import pathlib as _pathlib_h
_HANDLERS_BASE_DIR = str(_pathlib_h.Path(__file__).parent.resolve())

def _hdata_path(fname: str) -> str:
    """فایلى داتا لە هەمان فۆڵدەرى handlers.py"""
    if _pathlib_h.Path(fname).is_absolute():
        return fname
    return str(_pathlib_h.Path(_HANDLERS_BASE_DIR) / fname)



