# ── Pool-ی تایبەت بۆ وەرگێڕانی کتێب — جیا لە pool-ی گشتی ─────────────────
# quota-یان بە /gemini و /geminipro هاوبەش نابێت
# فۆرمات لە .env: GEMINI_TRANS_POOL=key1,key2,key3
_GEMINI_TRANS_POOL: list = [
    k.strip() for k in os.environ.get("GEMINI_TRANS_POOL", "").split(",") if k.strip()
]
_GEMINI_TRANS_COOLDOWN: dict = {}   # {key: epoch بەردەستبوون}

def _trans_pick_key(exclude: set | None = None) -> str | None:
    """کلیلی بەردەستی وەرگێڕان هەڵدەبژێرێت — سارد پشتگوێ دەخرێت."""
    import time as _t
    _now = _t.time()
    _ex  = exclude or set()
    for _k in _GEMINI_TRANS_POOL:
        if _k not in _ex and _now >= _GEMINI_TRANS_COOLDOWN.get(_k, 0):
            return _k
    return None

def _trans_mark_exhausted(key: str, seconds: float = 65.0) -> None:
    """کاتێک 429 گەشت، ئەو کلیلە بۆ ئەو ماوەیە سارد دەکات."""
    import time as _t
    _GEMINI_TRANS_COOLDOWN[key] = _t.time() + seconds
