_GEMINI_CLIENT_CACHE: dict = {}
_GEMINI_CLIENT_CACHE_LOCK = _th_gemini.Lock()

def _get_genai_client(api_key: str):
    """یەک client بۆ هەر API Key — کاشی و thread-safe.
    کاتێک key گۆڕدرا (/setgeminikey), کلایەنتی نوێ دروست دەبێت.
    """
    if api_key not in _GEMINI_CLIENT_CACHE:
        with _GEMINI_CLIENT_CACHE_LOCK:
            if api_key not in _GEMINI_CLIENT_CACHE:   # double-checked locking
                _GEMINI_CLIENT_CACHE[api_key] = _genai_lib.Client(api_key=api_key)
    return _GEMINI_CLIENT_CACHE[api_key]
# ── Gemini Key Pool — cooldown و هەڵبژاردن (thread-safe) ──────────────────
import time as _time_gemini

_GEMINI_KEY_COOLDOWN: dict = {}          # key → epoch کاتی بەردەستبوون
_GEMINI_KEY_COOLDOWN_LOCK = _th_gemini.Lock()

def _gemini_pick_key(exclude: set | None = None) -> str | None:
    """کلیلی بەردەستی هەڵدەبژێرێت — کلیلی سارد پشتگوێ دەخرێت.
    exclude: سێت بۆ کلیلەکانی تاوەکو نوێ هەوڵدراوە لەم ئەرکدا
    """
    _now = _time_gemini.time()
    _ex  = exclude or set()
    with _GEMINI_KEY_COOLDOWN_LOCK:
        for _k in _GEMINI_KEYS_POOL:
            if _k in _ex:
                continue
            if _now >= _GEMINI_KEY_COOLDOWN.get(_k, 0):
                return _k
    return None   # هەموو کلیلەکان سارد

def _gemini_mark_exhausted(key: str, seconds: float = 65.0) -> None:
    """کاتێک 429 یان quota گەشت، ئەو کلیلە بۆ ئەو ماوەیە پشتگوێ دەخرێت."""
    with _GEMINI_KEY_COOLDOWN_LOCK:
        _GEMINI_KEY_COOLDOWN[key] = _time_gemini.time() + seconds

