# ═══════════════════════════════════════════════════════════════════════════
# SambaNova HTTP Client — Professional Rate-Limit Handling
# ───────────────────────────────────────────────────────────────────────────
# تایبەتمەندییەکان:
#   • Key Rotation        — هەر ٥ کلیلەکە لە یەک pool، خۆکار rotate دەکرێن
#   • Retry-After Honor   — header و body ـی سێرڤەر دەخوێنرێتەوە
#   • Per-Key Cooldown    — کلیلێکی تەواوبوو بۆ ماوەیەک لاببرێ
#   • Exponential Backoff — بۆ ٥xx و timeout ـی شەبەکە
#   • Per-User Throttle   — هاوکاری بۆ flood-protection
# ═══════════════════════════════════════════════════════════════════════════

import time as _samba_time
import threading as _samba_threading
import random as _samba_random

# هەموو کلیلەکانی SambaNova لە یەک pool — load-balanced
# کلیلی بەتاڵ ("") فیلتەر دەکرێت بۆ ئەوەی pool پیت نەبێت
_SAMBA_API_KEYS_POOL: list = [k for k in [
    # کلیلە بنەڕەتییەکان (preferred بۆ هەر فەرمانێک)
    _SAMBA_API_KEY_Q,
    _SAMBA_API_KEY_JUNG,
    _SAMBA_API_KEY_FREUD,
    _SAMBA_API_KEY_NIETZSCHE,
    _SAMBA_API_KEY_SOCRATES,
    _SAMBA_API_KEY_BEEBE,
    _SAMBA_API_KEY_NARDI,
    _SAMBA_API_KEY_PIERCE,
    # کلیلە زیادکراوەکان (تەنها بۆ بارگەیی، نائاراستە)
    _SAMBA_API_KEY_POOL_1,
    _SAMBA_API_KEY_POOL_2,
    _SAMBA_API_KEY_POOL_3,
    _SAMBA_API_KEY_POOL_4,
    _SAMBA_API_KEY_POOL_5,
] if k]

# cooldown بۆ هەر کلیلێک: api_key → epoch ـی کاتی بەردەست‌بوونی
_SAMBA_KEY_COOLDOWN: dict = {}
_SAMBA_KEY_LOCK = _samba_threading.Lock()

# per-user throttle: "{uid}:{cmd}" → epoch ـی کاتی بەردەست‌بوون
_SAMBA_USER_THROTTLE: dict = {}
_SAMBA_USER_LOCK = _samba_threading.Lock()

# هەلومەرجەکانی سیستەم
_SAMBA_MAX_RETRIES         = 4       # کۆی هەوڵی re-try لە یەک داواکاریدا
_SAMBA_DEFAULT_RETRY_AFTER = 5.0     # ئەگەر سێرڤەر ڕێنواندنی نەکرد
_SAMBA_KEY_MAX_COOLDOWN    = 60.0    # سنووری بەرز بۆ cooldown ـی کلیل
_SAMBA_USER_MIN_INTERVAL   = 1.5     # فاصلەی کەمی نێوان دوو داواکاری
_SAMBA_BACKOFF_BASE        = 1.5     # base بۆ exponential backoff
_SAMBA_BACKOFF_CAP         = 6.0     # سنووری بەرزی backoff


class SambaRateLimitError(Exception):
    """
    هەموو کلیلەکانی pool لە cooldown دان.
    تێبینی: str(exc) "429" و "rate_limit" و "try again in Xs" ـی تێدایە بۆ
    هاوبیریی لەگەڵ exception handler ـی موجوود.
    """
    def __init__(self, wait_seconds: float, source: str = "pool"):
        self.wait_seconds = wait_seconds
        self.source = source
        super().__init__(
            f"SambaNova 429 rate_limit ({source}); try again in {wait_seconds:.1f}s"
        )


def _samba_pick_key(preferred=None):
    """
    کلیلێکی بەردەست هەڵبژێرە:
      ١) preferred ئەگەر بەردەست بێت (نە لە cooldown، نە blacklist)
      ٢) ئەگەر نا — random choice لە کلیلە بەردەستەکانی pool
    None دەگەڕێنێتەوە کاتێک هەموو کلیلەکان نائاراستن.
    """
    now = _samba_time.time()
    with _SAMBA_BLACKLIST_LOCK:
        blacklist = set(_SAMBA_KEY_BLACKLIST)  # کۆپی بۆ ئاسایش
    with _SAMBA_KEY_LOCK:
        # یەکەم: کلیلی preferred ـی بەردەست
        if (preferred
                and preferred not in blacklist
                and _SAMBA_KEY_COOLDOWN.get(preferred, 0) <= now):
            return preferred
        # دووەم: کلیلێکی هەڕەمەکی لە کلیلە بەردەستەکان
        candidates = [
            k for k in _SAMBA_API_KEYS_POOL
            if k != preferred
            and k not in blacklist
            and _SAMBA_KEY_COOLDOWN.get(k, 0) <= now
        ]
        if candidates:
            return _samba_random.choice(candidates)
        return None


def _samba_min_cooldown_remaining() -> float:
    """کەمترین کاتی چاوەڕوانی تا یەک کلیل بەردەست بێت."""
    now = _samba_time.time()
    with _SAMBA_KEY_LOCK:
        if not _SAMBA_KEY_COOLDOWN:
            return 0.0
        remaining = [v - now for v in _SAMBA_KEY_COOLDOWN.values() if v > now]
        return min(remaining) if remaining else 0.0


def _samba_mark_key_exhausted(api_key: str, retry_after: float) -> None:
    """کلیلێک ٤٢٩ وەرگرت — cooldown دانە بۆی."""
    cooldown = max(1.0, min(retry_after, _SAMBA_KEY_MAX_COOLDOWN))
    with _SAMBA_KEY_LOCK:
        _SAMBA_KEY_COOLDOWN[api_key] = _samba_time.time() + cooldown


# Blacklist بۆ کلیلە نادروستەکان (٤٠١ Unauthorized)
# ئەم کلیلانە هەتاهەتایی blacklist دەکرێن تاکو بۆتەکە restart بکرێتەوە.
# هۆکار: ئەگەر کلیلێک ٤٠١ وەربگرێت، یا ١) لاببردراوە، یا ٢) revoke بووە،
# یا ٣) فۆرماتەکەی هەڵەیە. هیچیان لە کاتدا چاک نابنەوە.
_SAMBA_KEY_BLACKLIST: set = set()
_SAMBA_BLACKLIST_LOCK = _samba_threading.Lock()


def _samba_blacklist_key(api_key: str, reason: str = "401 Unauthorized") -> None:
    """
    کلیلێک هەتاهەتایی blacklist بکە — ٤٠١ یعنی کلیلەکە نادروستە یان revoke بووە.
    تاکو بۆتەکە restart بکرێتەوە، ئەم کلیلە هەرگیز تاقی ناکرێتەوە.
    """
    with _SAMBA_BLACKLIST_LOCK:
        if api_key in _SAMBA_KEY_BLACKLIST:
            return  # پێشتر blacklist کرابوو
        _SAMBA_KEY_BLACKLIST.add(api_key)
        # شوینی پێداویستی — تەنها ٨ کاراکتەری سەرەتا و ٤ کاراکتەری کۆتایی
        masked = f"{api_key[:8]}...{api_key[-4:]}" if len(api_key) >= 12 else "***"
        active_count = len(_SAMBA_API_KEYS_POOL) - len(_SAMBA_KEY_BLACKLIST)
        logger.error(
            "<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> SambaNova KEY BLACKLISTED: %s (reason: %s) — "
            "کلیلە کارا ماون: %d/%d",
            masked, reason, active_count, len(_SAMBA_API_KEYS_POOL),
        )
        # ئاگادارکردنەوە کاتێک هەموو کلیلەکان لاببردرابن
        if active_count == 0:
            logger.critical(
                "<tg-emoji emoji-id=\"5422631223220540518\">⛔</tg-emoji> هەموو کلیلەکانی SambaNova blacklist کراون! "
                "تکایە کلیلە نوێ زیاد بکە بە بۆتەکە یان restart ـی بکە."
            )


def _samba_is_invalid_key_response(resp) -> bool:
    """
    دۆخی ٤٠١ شیکار بکە — ئایا کلیل بە ڕاستی نادروستە؟
    SambaNova ٤٠١ دەنێرێت بۆ:
      • Incorrect API key (نادروست)
      • invalid_api_key (revoke/typo)
      • authentication_error (هەڵەی fundamental)
    """
    if resp.status_code != 401:
        return False
    try:
        body = resp.json()
        err  = body.get("error") or {}
        code = (err.get("code") or "").lower()
        typ  = (err.get("type") or "").lower()
        msg  = (err.get("message") or "").lower()
        # هەر یەک لەمانە یعنی کلیل نادروستە
        if code in ("invalid_api_key", "invalid_request_error"):
            return True
        if typ in ("authentication_error", "invalid_request_error"):
            return True
        if "incorrect api key" in msg or "invalid api key" in msg:
            return True
    except Exception:
        pass
    return True   # ٤٠١ بەشیوەی default = کلیل نادروست


def _samba_parse_retry_after(resp) -> float:
    """Retry-After لە header یان body بهێنە (چرکە)."""
    # ١) HTTP header (مەرجی RFC)
    ra = resp.headers.get("Retry-After")
    if ra:
        try:
            return max(0.0, float(ra))
        except (ValueError, TypeError):
            pass
    # ٢) JSON body — SambaNova "try again in 12.5s" دەنووسێت
    try:
        body = resp.json()
        msg  = ((body.get("error") or {}).get("message") or "")
        import re as _re
        m = _re.search(r"try again in ([\d.]+)\s*s", msg, _re.I)
        if m:
            return float(m.group(1))
    except Exception:
        pass
    return _SAMBA_DEFAULT_RETRY_AFTER


def samba_user_throttle(throttle_key: str) -> float:
    """
    per-user throttle (سۆفت):
      ٠.٠  → ڕێگەپێدراوە، throttle بۆی نوێکرایەوە
      > ٠  → چەند چرکە بەکارهێنەر دەبێت چاوەڕوان بکات
    """
    now = _samba_time.time()
    with _SAMBA_USER_LOCK:
        nxt = _SAMBA_USER_THROTTLE.get(throttle_key, 0)
        if nxt > now:
            return nxt - now
        _SAMBA_USER_THROTTLE[throttle_key] = now + _SAMBA_USER_MIN_INTERVAL
        return 0.0


def _samba_request(*, system: str, history: list, user_text: str,
                   model: str, preferred_key: str,
                   temperature: float = 0.7, max_tokens: int = 2048):
    """
    هاوبەشی HTTP call بۆ SambaNova بە key rotation و retry-after و backoff.

    دەگەڕێتەوە: (reply_text: str, updated_history: list)

    دەهاوێژێت:
      • SambaRateLimitError — هەموو کلیلەکان exhausted
      • requests.HTTPError  — ٤xx ـی نا-٤٢٩
      • Exception           — هەڵەی شەبەکە یان نەشیکراو
    """
    import requests as _req

    new_history = history + [{"role": "user", "content": user_text}]
    messages    = [{"role": "system", "content": system}] + new_history
    payload = {
        "model":       model,
        "messages":    messages,
        "temperature": temperature,
        "max_tokens":  max_tokens,
    }

    last_retry_after = _SAMBA_DEFAULT_RETRY_AFTER
    last_exc = None
    tried_keys = set()

    for attempt in range(_SAMBA_MAX_RETRIES):
        api_key = _samba_pick_key(preferred_key)
        if api_key is None:
            wait = max(_samba_min_cooldown_remaining(), last_retry_after)
            raise SambaRateLimitError(wait, source="all-keys-exhausted")

        if api_key in tried_keys and len(tried_keys) >= len(_SAMBA_API_KEYS_POOL):
            raise SambaRateLimitError(last_retry_after, source="cycle-exhausted")
        tried_keys.add(api_key)

        try:
            resp = _req.post(
                _SAMBA_URL,
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type":  "application/json",
                },
                json=payload,
                timeout=60,
            )
        except (_req.Timeout, _req.ConnectionError) as exc:
            last_exc = exc
            sleep_s = min(_SAMBA_BACKOFF_BASE ** attempt, _SAMBA_BACKOFF_CAP)
            logger.warning(
                "SambaNova network error (attempt=%d/%d): %s — backoff %.1fs",
                attempt + 1, _SAMBA_MAX_RETRIES, exc, sleep_s,
            )
            _samba_time.sleep(sleep_s)
            continue

        # ✅ ٢٠٠ OK
        if resp.ok:
            try:
                data  = resp.json()
                reply = data["choices"][0]["message"]["content"]
            except (ValueError, KeyError, IndexError) as exc:
                logger.error(
                    "SambaNova malformed response: %s — body=%s",
                    exc, resp.text[:300],
                )
                raise RuntimeError("SambaNova returned malformed response") from exc
            updated = new_history + [{"role": "assistant", "content": reply}]
            return reply, updated

        # ⚡ ٤٢٩ — کلیل تەواو، rotate
        if resp.status_code == 429:
            ra = _samba_parse_retry_after(resp)
            last_retry_after = ra
            _samba_mark_key_exhausted(api_key, ra)
            logger.warning(
                "SambaNova 429 — کلیل تەواو، rotate (retry_after=%.1fs, model=%s, attempt=%d/%d)",
                ra, model, attempt + 1, _SAMBA_MAX_RETRIES,
            )
            continue

        # 🔄 ٥xx — backoff + retry
        if 500 <= resp.status_code < 600:
            last_exc = RuntimeError(f"HTTP {resp.status_code}: {resp.text[:200]}")
            sleep_s = min(_SAMBA_BACKOFF_BASE ** attempt, _SAMBA_BACKOFF_CAP)
            logger.warning(
                "SambaNova %s (attempt=%d/%d) — backoff %.1fs",
                resp.status_code, attempt + 1, _SAMBA_MAX_RETRIES, sleep_s,
            )
            _samba_time.sleep(sleep_s)
            continue

        # 🚫 ٤٠١ — کلیل نادروست، blacklist و rotate بکە
        # ئەمە یعنی کلیل revoke بووە، لاببردراوە، یان فۆرماتی هەڵەیە.
        # هیچ لە کاتدا چاک نابێت — هەتاهەتایی blacklist دەکرێت.
        if resp.status_code == 401 and _samba_is_invalid_key_response(resp):
            try:
                body = resp.json()
                reason = (body.get("error") or {}).get("message", "401 Unauthorized")[:100]
            except Exception:
                reason = "401 Unauthorized"
            _samba_blacklist_key(api_key, reason=reason)
            last_exc = RuntimeError(f"HTTP 401: invalid key blacklisted")
            continue   # ڕاستەوخۆ کلیلێکی تر تاقی بکەرەوە

        # ❌ ٤xx ـی تر — هەڵە، نە retry
        logger.error(
            "SambaNova [%s] REST error %s: %s",
            model, resp.status_code, resp.text[:500],
        )
        resp.raise_for_status()

    # هەموو هەوڵەکان شکستیان هێنا
    if last_exc:
        raise last_exc
    raise SambaRateLimitError(last_retry_after, source="max-retries")


@guarded
async def start(update: Update, context: CallbackContext):
    # خاوەن هەمیشە مۆڵەت هەیە — دیکەکان چەکی گرووپ دەکرێن
    user   = update.effective_user
    name = _html_escape(user.first_name or "بەکارهێنەر")
    ud     = get_user_data(user.id)
    level  = ud.get("level", 1)
    coins  = ud.get("coins", 0)
    streak = ud.get("streak", 0)
    rank   = get_user_rank(level)
    b      = _bank_get(user.id)
    total  = coins + b["balance"] + b["savings"]
    games_won = ud.get("games_won", 0)

    # ── ئەنیمەیشنی سڵاو بەپێی کاتی ڕۆژ ──
    hour = datetime.datetime.now().hour
    if 5 <= hour < 12:
        greet_emoji, greet_txt = "<tg-emoji emoji-id=\"5350304545186532529\">🌅</tg-emoji>", "بەیانی باش"
    elif 12 <= hour < 17:
        greet_emoji, greet_txt = "<tg-emoji emoji-id=\"5201827869361188827\">☀</tg-emoji>", "نیوەڕۆ باش"
    elif 17 <= hour < 21:
        greet_emoji, greet_txt = "🌇", "ئێوارە باش"
    else:
        greet_emoji, greet_txt = "<tg-emoji emoji-id=\"5415765090932641459\">🌙</tg-emoji>", "شەو باش"

    streak_txt = f"\n<tg-emoji emoji-id=\"5379636904075499661\">🔥</tg-emoji> بەردەوامی:  <b>{streak} ڕۆژ</b>" if streak > 0 else ""
    games_txt  = f"\n<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> بردنەوە:    <b>{games_won}</b>" if games_won > 0 else ""

    await update.message.reply_text(
        f"{greet_emoji} <b>{greet_txt}، {name}!</b>\n"
        f"⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> <b>{name}</b>  ·  <tg-emoji emoji-id=\"5789828777882162072\">🏅</tg-emoji> {rank}\n"
        f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئاست: <b>{level}</b>  ·  <tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> <b>{coins:,} {_TCN}</b>\n"
        f"{_TDM} کۆی سەرمایە: <b>{total:,} {_TCN}</b>"
        f"{streak_txt}{games_txt}\n"
        f"⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n"
        f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> بەشێک هەڵبژێرە لە خوارەوە",
        parse_mode="HTML",
        reply_markup=_main_menu_keyboard()
    )

