async def handle_debate_opinion(update: Update, context: CallbackContext) -> bool:
    """کۆنترۆڵکردنی تێکستی بیروڕای دیبەیت — یان دروستکردنی دیبەیتی تایبەت"""
    user_id = update.effective_user.id
    if user_id not in DEBATE_OPINION_WAITING:
        return False

    debate_id = DEBATE_OPINION_WAITING[user_id]
    opinion_text = update.message.text.strip()

    # ── CUSTOM_TOPIC: بابەتی نوێ دروست دەکرێت ──
    if debate_id == "CUSTOM_TOPIC":
        DEBATE_OPINION_WAITING.pop(user_id)
        if len(opinion_text) < 5:
            await update.message.reply_text(_TGX + " بابەتەکەت زۆر کورتە! لانیکەم ٥ پیت.", parse_mode="HTML")

            return True

        new_debate_id = f"d_{int(time.time())}"
        chat_id = update.effective_chat.id
        DEBATE_DATA[new_debate_id] = {
            "topic": opinion_text,
            "chat_id": chat_id,
            "votes_yes": [],
            "votes_no": [],
            "opinions": [],
            "created_at": datetime.datetime.now().isoformat(),
            "active": True,
            "creator": str(user_id)
        }
        _save_debate()

        keyboard = [
            [_ebtn("هاوڕام (0)", f"debate:yes:{new_debate_id}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
             _ebtn("هاوڕا نیم (0)", f"debate:no:{new_debate_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})],
            [_ebtn("بیروڕاکەت بنووسە", f"debate:opinion:{new_debate_id}", emoji_id="5303138782004924588", api_kwargs={"style": "primary"})],
            [_ebtn("ئەنجامەکان", f"debate:results:{new_debate_id}", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
             _ebtn("باشترین بیروڕا", f"debate:best:{new_debate_id}", emoji_id="5462927083132970373", api_kwargs={"style": "primary"})],
            [_ebtn("داخستنی مناقەشە", f"debate:close:{new_debate_id}", emoji_id="5231302159739395058", api_kwargs={"style": "primary"})],
        ]
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5438175921045545379\">🎙</tg-emoji> گفتوگۆی نوێ دروستکرا\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> بابەت: {opinion_text}\n\n"
            f"<tg-emoji emoji-id=\"5255934767844567828\">🗳</tg-emoji> دەنگ بدە و ڕای خۆت دەرببڕە!\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
        return True

    # ── بیروڕای ئاسایی ──
    DEBATE_OPINION_WAITING.pop(user_id)
    debate = DEBATE_DATA.get(debate_id)
    if not debate or not debate.get("active"):
        await update.message.reply_text(_TGX + " ئەم مناقەشەیە داخراوە یان نەدۆزرایەوە.", parse_mode="HTML")

        return True

    if len(opinion_text) < 3:
        await update.message.reply_text(_TGX + " بیروڕاکەت زۆر کورتە! لانیکەم دەبێت ٣ پیت بێت.", parse_mode="HTML")

        return True

    side = "yes" if str(user_id) in debate.get("votes_yes", []) else ("no" if str(user_id) in debate.get("votes_no", []) else "neutral")
    side_emoji = f"{_TCK}" if side == "yes" else (_TGX if side == "no" else "<tg-emoji emoji-id=\"5429482752619615220\">⚪</tg-emoji>")

    opinion_entry = {
        "user_id": user_id,
        "name": update.effective_user.first_name or str(user_id),
        "text": opinion_text[:300],
        "side": side,
        "likes": 0,
        "liked_by": [],
        "time": datetime.datetime.now().isoformat()
    }
    if "opinions" not in debate:
        debate["opinions"] = []
    debate["opinions"].append(opinion_entry)
    _save_debate()

    await update.message.reply_text(
        f"{_TCK} بیروڕاکەت تۆمار کرا!\n\n"
        f"{side_emoji} لایەنت: {'هاوڕا' if side == 'yes' else 'نەیار' if side == 'no' else 'بێ لایەن'}\n"
        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> {opinion_text[:100]}{'...' if len(opinion_text) > 100 else ''}",
        parse_mode="HTML"
    )
    return True


# ── گلۆبەل Rate Limit بۆ گرووپ ──
_GROUP_MSG_TIMES: dict = {}   # {user_id: [timestamps]}
_GROUP_RATE_MAX = 5           # زۆرترین نامە
_GROUP_RATE_WINDOW = 3        # لە X چرکەدا

def guarded_callback(func):
    """Decorator: rate limit + access check + هەڵەگرتن بۆ هەموو callbacks"""
    @functools.wraps(func)
    async def wrapper(update, context):
        # ── query بە شێوەی دروست دەستنیشان دەکرێت ──
        query = update.callback_query
        if not query:
            return
        user = update.effective_user or query.from_user
        chat = update.effective_chat
        if not user:
            return
        # ── بانی بۆت ──
        if _is_bot_banned(user.id):
            try: await query.answer()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return

        # ── Rate limit + Cleanup ──
        if not _check_callback_rate(user.id):
            try:
                await query.answer("⏳ زۆر خێرا کلیک دەکەیت!", show_alert=False)
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
            return

        # ── [ACCESS CONTROL] چیکی مۆڵەتی دەسترسی ──
        # پاسگەی ناوخۆیی — fake update بۆ یارییەکان
        if getattr(update, "_skip_access", False):
            try:
                await func(update, context)
            except Exception as _e:
                _em = str(_e).lower()
                _ok = ("not modified", "query is too old", "message to delete not found",
                       "bot was blocked", "message_id_invalid", "forbidden", "timed out")
                if any(p in _em for p in _ok):
                    logger.debug(f"callback ignore [{func.__name__}]: {_e}")
                    return
                logger.error(f"callback هەڵە [{func.__name__}]: {_e}", exc_info=True)
                try:
                    await query.answer("❌ هەڵەیەک ڕوویدا.", show_alert=True)
                except Exception:
                    pass
            else:
                try: await query.answer()
                except Exception: pass
            return

        # خاوەن: هەموو شوێنێک مۆڵەتدارە
        if user.id == OWNER_ID:
            try:
                await func(update, context)
            except Exception as _e:
                _em = str(_e).lower()
                _ok = ("not modified", "query is too old", "message to delete not found",
                       "bot was blocked", "message_id_invalid", "forbidden", "timed out")
                if any(p in _em for p in _ok):
                    logger.debug(f"callback ignore [{func.__name__}]: {_e}")
                else:
                    logger.error(f"callback هەڵە [{func.__name__}]: {_e}", exc_info=True)
            finally:
                try: await query.answer()
                except Exception: pass
            return

        # پڕایڤت چات: مۆڵەتدارە — دووگمەکانی بۆتەکە لە پڕایڤتیش کار دەکەن
        # (تێستەکان و فیچەرەکانی تایبەت دەبێت لە پڕایڤتیش کار بکەن)

        # گرووپ: چیک بکە ئایا لە لیستی مۆڵەتدارەکانداست
        if chat and chat.type != "private" and not is_group_allowed(chat.id, chat.type):
            try: await query.answer()
            except Exception: pass
            return

        # ── مۆڵەتدار — Run ──
        try:
            await func(update, context)
        except Exception as _e:
            _em = str(_e).lower()
            _ok = ("not modified", "query is too old", "message to delete not found",
                   "bot was blocked", "message_id_invalid", "forbidden", "timed out")
            if any(p in _em for p in _ok):
                logger.debug(f"callback ignore [{func.__name__}]: {_e}")
            else:
                logger.error(f"callback هەڵە [{func.__name__}]: {_e}", exc_info=True)
        finally:
            try: await query.answer()
            except Exception: pass
    return wrapper

