async def link_filter_cmd(update: Update, context: CallbackContext):
    """/linkfilter on|off — فیلتەری لینک"""
    if not await is_admin(update, context):
        await update.message.reply_text(_TGX + " تەنیا ئادمین!", parse_mode="HTML"); return

    chat_id = str(update.effective_chat.id)
    arg = (context.args[0].lower() if context.args else "")
    cfg = LINK_FILTER_DATA.setdefault(chat_id, {"enabled": False, "whitelist": []})
    if arg == "on":
        cfg["enabled"] = True
        _save_link_filter()
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> فیلتەری لینک <b>چالاک</b> کرا {_TCK}\n\nلینکی تازەکاران ئۆتۆماتیک دەسڕێتەوە.", parse_mode="HTML")
    elif arg == "of":
        cfg["enabled"] = False
        _save_link_filter()
        await update.message.reply_text("<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> فیلتەری لینک <b>ناچالاک</b> کرا <tg-emoji emoji-id=\"5422631223220540518\">⛔</tg-emoji>", parse_mode="HTML")
    else:
        status = f"{_TCK} چالاک" if cfg.get("enabled") else "<tg-emoji emoji-id=\"5422631223220540518\">⛔</tg-emoji> ناچالاک"
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> <b>فیلتەری لینک:</b> {status}\n\n"
            f"<code>/linkfilter on</code>  — چالاک بکە\n"
            f"<code>/linkfilter off</code> — ناچالاک بکە",
            parse_mode="HTML"
        )

async def _check_link_filter(update: Update, context: CallbackContext) -> bool:
    """True = پەیامەکە سڕایەوە"""
    msg = update.message
    if not msg or not msg.text:
        return False
    chat_id = str(update.effective_chat.id)
    cfg = LINK_FILTER_DATA.get(chat_id, {})
    if not cfg.get("enabled"):
        return False
    # ئادمینەکان پارێزراون
    try:
        member = await context.bot.get_chat_member(update.effective_chat.id, msg.from_user.id)
        if member.status in ("administrator", "creator"):
            return False
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    if _LINK_PATTERN.search(msg.text):
        try:
            await msg.delete()
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
        return True
    return False

async def _auto_delete(context: CallbackContext, chat_id: int, msg_id: int, delay: int):
    await asyncio.sleep(delay)
    try:
        await context.bot.delete_message(chat_id, msg_id)
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

