async def event_cmd(update: Update, context: CallbackContext):
    """/event ناوی ئیڤێنت — تێبینی"""
    if not await is_admin(update, context):
        await update.message.reply_text(_TGX + " تەنیا ئادمین!", parse_mode="HTML"); return

    if not context.args:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>شێواز:</b>\n"
            "<code>/event ناوی ئیڤێنت</code>\n\n"
            "نموونە:\n"
            "<code>/event یاری فوتبۆڵ ئێوارە ٨</code>",
            parse_mode="HTML"
        ); return
    title = " ".join(context.args)
    chat_id = str(update.effective_chat.id)
    event_id = str(int(time.time()))
    EVENT_DATA.setdefault(chat_id, {})[event_id] = {
        "title": title,
        "creator": update.message.from_user.id,
        "going": [],
        "not_going": [],
        "created": datetime.datetime.now().isoformat()
    }
    _save_event()
    kb = InlineKeyboardMarkup([
        [
            _ebtn(f"دێم ({0})", f"evt:go:{chat_id}:{event_id}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
            _ebtn(f"نا ({0})", f"evt:no:{chat_id}:{event_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
        ],
    [_ebtn("بینینی لیست", f"evt:list:{chat_id}:{event_id}", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})]
    ])
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>ئیڤێنتی نوێ!</b>\n\n"
        f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> <b>{title}</b>\n\n"
        f"دووگمە بکەرەوە بۆ بەشداری:",
        parse_mode="HTML"
    )

async def event_callback(update: Update, context: CallbackContext):
    """callback ی ئیڤێنت"""
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    if len(parts) < 4:
        return
    _, action, chat_id, event_id = parts[0], parts[1], parts[2], parts[3]
    ev = EVENT_DATA.get(chat_id, {}).get(event_id)
    if not ev:
        await answered("⚠️ ئیڤێنتەکە نەدۆزرایەوە!", show_alert=True); return
    user_id = query.from_user.id
    going = ev.setdefault("going", [])
    not_going = ev.setdefault("not_going", [])
    if action == "go":
        if user_id not in going:
            going.append(user_id)
            if user_id in not_going:
                not_going.remove(user_id)
        _save_event()
        await answered(f"<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> تۆمارکرایت بە دێم!", show_alert=False)
    elif action == "no":
        if user_id not in not_going:
            not_going.append(user_id)
            if user_id in going:
                going.remove(user_id)
        _save_event()
        await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji>" + " تۆمارکرایت بە نا!", show_alert=False)
    elif action == "list":
        await answered(
            f"<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> دێن: {len(going)} کەس\n<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> نا: {len(not_going)} کەس",
            show_alert=True
        )
        return
    # نوێکردنەوەی دووگمەکان
    kb = InlineKeyboardMarkup([
        [
            _ebtn(f"دێم ({len(going)})", f"evt:go:{chat_id}:{event_id}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
            _ebtn(f"نا ({len(not_going)})", f"evt:no:{chat_id}:{event_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
        ],
    [_ebtn("بینینی لیست", f"evt:list:{chat_id}:{event_id}", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})]
    ])
    try:
        await query.edit_message_reply_markup(reply_markup=kb)
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

async def _check_auto_reply(update, context) -> bool:
    """چەکی وەڵامی ئۆتۆماتیک — True گەڕاندەوە = وەڵام درا"""
    msg = update.message
    if not msg or not msg.text:
        return False
    cfg = AUTO_REPLY_DATA.get("settings", {})
    if not cfg.get("enabled", True):
        return False
    text = msg.text
    triggers = AUTO_REPLY_DATA.get("triggers", {})
    if not triggers:
        return False
    match_type    = cfg.get("match_type", "contains")
    case_sensitive = cfg.get("case_sensitive", False)
    chance        = int(cfg.get("chance", 100))
    for trigger, entry in triggers.items():
        if not _ar_match(trigger, text, match_type, case_sensitive):
            continue
        # ئەگەری
        if chance < 100:
            if random.randint(1, 100) > chance:
                continue
        responses = entry.get("responses", [])
        if not responses:
            continue
        reply_text = random.choice(responses)
        kb = None
        btns = entry.get("buttons", [])
        if btns:
            rows = []
            for row in btns:
                r = []
                for btn in row:
                    if btn.get("url"):
                        r.append(InlineKeyboardButton(btn["text"], url=btn["url"], api_kwargs={"style": "primary"}))
                    else:
                        r.append(_ebtn(btn["text"], btn.get("data", "ar_noop"), api_kwargs={"style": "primary"}))
                rows.append(r)
            kb = InlineKeyboardMarkup(rows)
        sent = False
        try:
            parse = entry.get("parse_mode", "HTML")
            await msg.reply_text(reply_text, parse_mode=parse, reply_markup=kb)
            sent = True
        except Exception:
            try:
                # هەوڵی دووەم بە بێ parse_mode
                await msg.reply_text(reply_text, reply_markup=kb, parse_mode='HTML')
                sent = True
            except Exception:
                try:
                    await context.bot.send_message(
                        chat_id=msg.chat.id,
                        text=reply_text,
                        reply_markup=kb,
                        parse_mode='HTML',
                    )
                    sent = True
                except Exception as _e:
                    logger.warning("auto_reply send failed: %s", _e)
        return sent
    return False

