async def unband_cmd(update: Update, context: CallbackContext):
    """/unband [ئایدی]  یان ڕیپڵ + /unband — لادانی بانی گرووپ"""
    chat = update.effective_chat
    user = update.effective_user
    is_owner = (user.id == OWNER_ID) if user else False
    is_group_chat = chat.type in ("group", "supergroup")

    is_linked_ch = await _is_linked_channel_admin(update)
    if not is_owner and not is_linked_ch:
        if not await is_admin(update, context):
            return
        if not is_group_chat:
            await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئەم فەرمانە تەنها لە گرووپدا کار دەکات.", parse_mode="HTML")
            return

    # ── تارگەت دیاریکردن ──
    target_id = None
    if update.message.reply_to_message:
        ru = update.message.reply_to_message.from_user
        if ru:
            target_id = ru.id
        else:
            rsc = getattr(update.message.reply_to_message, "sender_chat", None)
            if rsc:
                target_id = rsc.id
    elif context.args:
        try:
            target_id = int(context.args[0])
        except ValueError:
            await update.message.reply_text(
                _TGX + " ئایدی نادروستە!\n<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> <code>/unband [ئایدی]</code>", parse_mode="HTML")
            return

    if not target_id:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> شێواز: <code>/unband [ئایدی]</code>", parse_mode="HTML")
        return

    # بانی گرووپ لادەبەین (تەنها کاتێک لە گرووپدا)
    group_unban = False
    if is_group_chat:
        try:
            await context.bot.unban_chat_member(chat.id, target_id, only_if_banned=True)
            group_unban = True
        except Exception:
            group_unban = False

    # بانی بۆتیش لادەبەین ئەگەر هەبوو
    uid_str = str(target_id)
    bot_ban_removed = False
    if uid_str in BOT_BAN_DATA.get("banned", {}):
        del BOT_BAN_DATA["banned"][uid_str]
        _BOT_BAN_SET.discard(uid_str)
        _save_bot_ban()
        bot_ban_removed = True

    if group_unban or bot_ban_removed:
        parts = []
        if group_unban:     parts.append(f"{_TCK} بانی گرووپ لادرا")
        if bot_ban_removed: parts.append(f"{_TCK} بانی بۆت لادرا")
        await update.message.reply_text(
            f"{_TCK} <b>بانی لادرا!</b>\n\n"
            f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: <code>{target_id}</code>\n"
            + "\n".join(parts) +
            f"\n\nئەم کەسە دەتوانێت دووبارە بەشداری گرووپ بکات.", parse_mode="HTML")
    else:
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئەم کەسە بانکراو نییە.\n"
            f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: <code>{target_id}</code>", parse_mode="HTML")

