async def giftowner_cmd(update: Update, context: CallbackContext):
    """/giftowner [ئایدی] [ژمارە] [هۆکار]  یان ڕیپڵ + /giftowner [ژمارە]"""
    user = update.effective_user
    # ── مۆڵەت: خاوەن یان چەناڵی بەستراو ──
    msg = update.message
    sender_chat = getattr(msg, "sender_chat", None)
    is_linked_ch = (sender_chat and sender_chat.id == LINKED_CHANNEL_ID)
    if not is_linked_ch and (not user or user.id != OWNER_ID):
        await update.message.reply_text("<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> ئەم فەرمانە تەنها بۆ خاوەنی بۆتە.", parse_mode="HTML")
        return

    target_id, amount, reason = None, None, ""

    if update.message.reply_to_message:
        try:
            amount = int(context.args[0]) if context.args else None
        except (ValueError, IndexError):
            amount = None
        if not amount:
            await update.message.reply_text(
                _TGX + " ژمارە دیاری نەکراوە!\n<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> ڕیپڵ بکە + <code>/giftowner [ژمارە]</code>",
                parse_mode="HTML"); return
        rply = update.message.reply_to_message
        _ru = rply.from_user
        if _ru:
            target_id = _ru.id
        else:
            _rsc = getattr(rply, "sender_chat", None)
            if _rsc:
                target_id = _rsc.id
            else:
                await update.message.reply_text(_TGX + " ناتوانرێت تارگەت دیاری بکرێت!", parse_mode="HTML"); return

        reason    = " ".join(context.args[1:]) if len(context.args) > 1 else ""
    elif len(context.args) >= 2:
        try:
            target_id = int(context.args[0])
            amount    = int(context.args[1])
            reason    = " ".join(context.args[2:]) if len(context.args) > 2 else ""
        except ValueError:
            await update.message.reply_text(
                _TGX + " ئایدی یان ژمارە نادروستە!\n"
                "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> <code>/giftowner [ئایدی] [ژمارە]</code>", parse_mode="HTML"); return
    else:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5381873589899267194\">🎁</tg-emoji> <b>کۆین ببەخش</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> <b>شێوازەکان:</b>\n"
            "• <code>/giftowner [ئایدی] [ژمارە]</code>\n"
            "• <code>/giftowner [ئایدی] [ژمارە] [هۆکار]</code>\n"
            "• ڕیپڵ لەسەر پەیامی کەسێک: <code>/giftowner [ژمارە]</code>\n\n"
            "<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <b>نمونەکان:</b>\n"
            "<code>/giftowner 123456789 50000</code>\n"
            "<code>/giftowner 123456789 10000 خەڵاتی یاری</code>", parse_mode="HTML"); return

    if amount <= 0:
        await update.message.reply_text(_TGX + " ژمارەکە دەبێت گەورەتر لە ٠ بێت!", parse_mode="HTML"); return


    try:
        ci = await context.bot.get_chat(target_id)
        recv_name = _html_escape(ci.first_name or str(target_id))
    except Exception:
        recv_name = str(target_id)

    add_coins(target_id, amount)
    save_users(); save_coins()   # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: هەر دووکیان پاشەکەوت — crash-safe
    balance     = get_user_data(target_id).get("coins", 0)
    reason_line = f"\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هۆکار: {reason}" if reason else ""

    await update.message.reply_text(
        f"{_TCK} <b>کۆین بەخشین تەواو بوو!</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> وەرگر: <b>{recv_name}</b>\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: <code>{target_id}</code>\n"
        f"<tg-emoji emoji-id=\"5381873589899267194\">🎁</tg-emoji> بەخشراو: <b>{amount:,} {_TCN}</b>{reason_line}\n\n"
        f"{_TMN} بالانسی نوێ: <b>{balance:,} {_TCN}</b>", parse_mode="HTML")
    try:
        reason_msg = f"\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هۆکار: <b>{reason}</b>" if reason else ""
        await context.bot.send_message(
            target_id,
            f"<tg-emoji emoji-id=\"5381873589899267194\">🎁</tg-emoji> <b>کۆینت بەخشرا!</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"{_TMN} وەرتگرا: <b>{amount:,} {_TCN}</b>{reason_msg}\n"
            f"<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> لەلایەن خاوەنی بۆتەوە\n\n"
            f"{_TDM} بالانسی ئێستات: <b>{balance:,} {_TCN}</b>", parse_mode="HTML")
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored


