async def _check_media_trigger(update, context) -> bool:
    """لە ناو message handlerدا دەکرێتەوە — True = میدیا نێردرا"""
    msg  = update.message
    if not msg:
        return False
    text = (msg.text or msg.caption or "").strip()
    if not text or text.startswith("/"):
        return False
    triggers = MEDIA_TRIGGER_DATA.get("triggers", {})
    if not triggers:
        return False

    for key, entries in triggers.items():
        if key.lower() in text.lower() and entries:
            entry = random.choice(entries)
            fid, mtype, cap = entry["file_id"], entry["type"], entry.get("caption","")
            kw = {}
            try:
                if mtype == "sticker":
                    await msg.reply_sticker(fid); return True
                if mtype == "photo":
                    await msg.reply_photo(fid, caption=cap or None, parse_mode="HTML" if cap else None); return True
                if mtype == "animation":
                    await msg.reply_animation(fid, caption=cap or None, parse_mode="HTML" if cap else None); return True
                if mtype == "video":
                    await msg.reply_video(fid, caption=cap or None, parse_mode="HTML" if cap else None); return True
                if mtype == "voice":
                    await msg.reply_voice(fid); return True
                if mtype == "audio":
                    await msg.reply_audio(fid); return True
            except Exception as _e:
                logger.warning(f"media_trigger [{key}]: {_e}")
    return False

