async def _handle_media_trigger_upload(update: Update, context: CallbackContext):
    """group=10 — چاوەڕوانی میدیای ئاونەر بۆ تریگەر"""
    uid = update.effective_user.id if update.effective_user else None
    if not uid or uid not in _MEDIA_TRIGGER_WAIT:
        return
    trigger = _MEDIA_TRIGGER_WAIT[uid]["trigger"]
    msg     = update.message
    cap     = (msg.caption or "").strip()
    entry   = None

    if msg.sticker:
        entry = {"type": "sticker",   "file_id": msg.sticker.file_id,     "caption": ""}
    elif msg.photo:
        entry = {"type": "photo",     "file_id": msg.photo[-1].file_id,   "caption": cap}
    elif msg.animation:
        entry = {"type": "animation", "file_id": msg.animation.file_id,   "caption": cap}
    elif msg.video:
        entry = {"type": "video",     "file_id": msg.video.file_id,       "caption": cap}
    elif msg.voice:
        entry = {"type": "voice",     "file_id": msg.voice.file_id,       "caption": ""}
    elif msg.audio:
        entry = {"type": "audio",     "file_id": msg.audio.file_id,       "caption": ""}

    if not entry:
        return

    key = trigger.lower()
    MEDIA_TRIGGER_DATA["triggers"].setdefault(key, [])
    MEDIA_TRIGGER_DATA["triggers"][key].append(entry)
    _save_media_triggers()
    _MEDIA_TRIGGER_WAIT.pop(uid, None)

    _TE = {"sticker":"ستیکەر <tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji>","photo":"وێنە <tg-emoji emoji-id=\"5893232439110668588\">🖼</tg-emoji>","animation":"GIF 🎞","video":"ڤیدیۆ <tg-emoji emoji-id=\"6325351379388860506\">🎬</tg-emoji>","voice":"دەنگ <tg-emoji emoji-id=\"5438175921045545379\">🎙</tg-emoji>","audio":"موسیقا <tg-emoji emoji-id=\"5397756121261840824\">🎵</tg-emoji>"}
    count = len(MEDIA_TRIGGER_DATA["triggers"][key])
    await msg.reply_text(
        f"{_TCK} <b>زیادکرا!</b>\n\n"
        f"<tg-emoji emoji-id=\"5386701034355726526\">🔑</tg-emoji> وشە: <b>«{trigger}»</b>\n"
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> جۆر: {_TE.get(entry['type'], entry['type'])}\n"
        f"{_TCH} کۆی میدیای ئەم وشەیە: <b>{count}</b>\n\n"
        f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> دەتوانیت زیاتر زیاد بکەیت بە دووبارە کردنەوەی <code>/addtrigger {trigger}</code>",
        parse_mode="HTML")

async def deltrigger_cmd(update: Update, context: CallbackContext):
    """/deltrigger [وشە]"""
    if update.effective_user.id != OWNER_ID:
        await update.message.reply_text("<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> تەنها ئاونەر.", parse_mode="HTML"); return
