async def _handle_picture_vault_upload(update: Update, context: CallbackContext):
    """group=11 — چاوەڕوانی میدیای ئاونەر بۆ ئەرشیف"""
    uid = update.effective_user.id if update.effective_user else None
    if not uid or uid not in _PICTURE_VAULT_WAIT:
        return
    tag = _PICTURE_VAULT_WAIT[uid].get("tag", "")
    msg = update.message
    cap = (msg.caption or "").strip()
    entry = None

    if msg.photo:
        entry = {"type":"photo",     "file_id":msg.photo[-1].file_id, "caption":cap, "tag":tag}
    elif msg.animation:
        entry = {"type":"animation", "file_id":msg.animation.file_id, "caption":cap, "tag":tag}
    elif msg.video:
        entry = {"type":"video",     "file_id":msg.video.file_id,     "caption":cap, "tag":tag}
    elif msg.sticker:
        entry = {"type":"sticker",   "file_id":msg.sticker.file_id,   "caption":cap, "tag":tag}
    elif msg.voice:
        entry = {"type":"voice",     "file_id":msg.voice.file_id,     "caption":cap, "tag":tag}

    if not entry:
        return

    idx = len(PICTURE_VAULT_DATA["items"])
    PICTURE_VAULT_DATA["items"].append(entry)
    if tag:
        PICTURE_VAULT_DATA["tags"].setdefault(tag, [])
        PICTURE_VAULT_DATA["tags"][tag].append(idx)
    _save_picture_vault()
    _PICTURE_VAULT_WAIT.pop(uid, None)

    _TN = {"photo":"وێنە <tg-emoji emoji-id=\"5893232439110668588\">🖼</tg-emoji>","animation":"GIF 🎞","video":"ڤیدیۆ <tg-emoji emoji-id=\"6325351379388860506\">🎬</tg-emoji>","sticker":"ستیکەر <tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji>","voice":"دەنگ <tg-emoji emoji-id=\"5438175921045545379\">🎙</tg-emoji>"}
    cap_prev = f"\n<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> وتە: «{cap[:50]}{'...' if len(cap)>50 else ''}»" if cap else ""
    tag_line = f"\n<tg-emoji emoji-id=\"5395487321967596182\">🏷</tg-emoji> تاگ: <b>{tag}</b>" if tag else ""
    await msg.reply_text(
        f"{_TCK} <b>زیادکرا!</b>\n\n"
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> جۆر: {_TN.get(entry['type'],entry['type'])}"
        f"{cap_prev}{tag_line}\n"
        f"<tg-emoji emoji-id=\"5463172695132745432\">📦</tg-emoji> کۆی ئەرشیف: <b>{idx+1}</b> دانە", parse_mode="HTML")

async def picture_cmd(update: Update, context: CallbackContext):
    """/picture [تاگ]  یان  /picture کۆمەڵ — هم command هم callback"""
    # ── پشتگیری هەردوو command و callback context ──
    msg = update.effective_message
    chat = update.effective_chat

    async def _reply_text(text, **kw):
        try:
            await msg.reply_text(text, **kw, parse_mode='HTML')
        except Exception:
            try: await context.bot.send_message(chat.id, text, **kw, parse_mode='HTML')
            except Exception as e: logger.error("picture_reply_text")

    async def _reply_media(mtype, fid, cap):
        kw = {"caption": cap, "parse_mode": "HTML"} if cap else {}
        try:
            if   mtype == "photo":     await context.bot.send_photo(chat.id, fid, **kw)
            elif mtype == "animation": await context.bot.send_animation(chat.id, fid, **kw)
            elif mtype == "video":     await context.bot.send_video(chat.id, fid, **kw)
            elif mtype == "sticker":
                await context.bot.send_sticker(chat.id, fid)
                if cap: await context.bot.send_message(chat.id, cap, parse_mode="HTML")
            elif mtype == "voice":     await context.bot.send_voice(chat.id, fid, **kw)
            else: await _reply_text(cap or "<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji>", parse_mode="HTML")
        except Exception as _e:
            logger.error("picture_cmd media: %s", _e)
            await _reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> هەڵەیەک ڕووی دا لە ناردنی میدیاکەدا.", parse_mode="HTML")

    items = PICTURE_VAULT_DATA.get("items", [])
    if not items:
        await _reply_text(
            "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> ئەرشیفەکە خاوییە!\n"
            "ئاونەر بە <code>/addpicture</code> زیادیان بکات.", parse_mode="HTML")
        return

    arg = " ".join(context.args).strip() if context.args else ""

    # نیشاندانی تاگەکان
    if arg.lower() in ("کۆمەڵ", "tags", "لیست", "list"):
        tags = PICTURE_VAULT_DATA.get("tags", {})
        if not tags:
            await _reply_text("<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ تاگێک تۆمارنەکراوە.")
            return
        lines_t = [f"• <b>{t}</b> — {len(v)} دانە" for t, v in tags.items()]
        await _reply_text(
            "<tg-emoji emoji-id=\"5395487321967596182\">🏷</tg-emoji> <b>تاگەکانی ئەرشیف</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            + "\n".join(lines_t)
            + "\n\n<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> <code>/picture [تاگ]</code>", parse_mode="HTML")
        return

    # هەڵبژاردنی ئایتەم
    if arg:
        tags = PICTURE_VAULT_DATA.get("tags", {})
        idxs = [idx for t, v in tags.items()
                if arg.lower() in t.lower()
                for idx in v if 0 <= idx < len(items)]
        if not idxs:
            await _reply_text(
                f"{_TGX} تاگی «{arg}» نەدۆزرایەوە.\n"
                f"<code>/picture کۆمەڵ</code> بنووسە.", parse_mode="HTML")
            return
        item = items[random.choice(idxs)]
    else:
        item = random.choice(items)

    fid   = item["file_id"]
    mtype = item.get("type", "photo")
    cap   = (item.get("caption") or "").strip()
    await _reply_media(mtype, fid, cap)

