async def handle_word_chain_answer(update: Update, context: CallbackContext) -> bool:
    # زنجیرەی وشە لە گرووپ کار دەکات نەک بەپێی active_game
    # تەنها ئەگەر WORD_CHAIN_ACTIVE لە chat_id هەبوو
    chat_id = update.effective_chat.id
    if chat_id not in WORD_CHAIN_ACTIVE:
        # active_game ی word_chain بوون نییە بەڵام گرووپ چالاک نییە
        # پاکیکردنەوەی game
        user_id = update.effective_user.id
        remove_active_game(user_id)
        return False
    # گرووپ چالاکە — handle_word_chain_new ئەنجامی دەدات
    return await handle_word_chain_new(update, context)

