async def handle_emoji_puzzle_answer(update: Update, context: CallbackContext) -> bool:
    user_id = update.message.from_user.id
    active_game = get_active_game(user_id)
    
    if not active_game or active_game["type"] != "emoji_puzzle":
        return False

    try:
        user_answer = update.message.text.strip()
        correct_answer = active_game["data"]["answer"]
        
        game_data = active_game["data"]
        game_data["attempts"] += 1
        
        if user_answer.lower() == correct_answer.lower():
            xp_gain = 40 - (game_data["attempts"] * 5)
            xp_gain = max(20, xp_gain)
            
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> پیرۆزە! وەڵامەکەت دروستە: {correct_answer}\n\n"
                f"{_TCH} ژمارەی هەوڵەکان: {game_data['attempts']}\n"
                f"{_TMN} پاداشت: +{xp_gain} XP",
                parse_mode="HTML"
            )
            
            add_points(user_id, xp_gain)
            user_stats = get_user_data(user_id)
            user_stats["games_played"] = user_stats.get("games_played", 0) + 1
            user_stats["games_won"] = user_stats.get("games_won", 0) + 1
            user_stats["favorite_game"] = "مەتەڵی ئیمۆجی"
            save_users()
            remove_active_game(user_id)
        else:
            if game_data["attempts"] >= 3:
                await update.message.reply_text(
                    f"<tg-emoji emoji-id=\"5384348715127442215\">💥</tg-emoji> هەوڵەکانت تەواو بوون! وەڵامی ڕاست: {correct_answer}\n\n"
                    f"+10 XP بۆ ماندووبوونت!",
                    parse_mode='HTML',
                )
                add_points(user_id, 10)
                user_stats = get_user_data(user_id)
                user_stats["games_played"] = user_stats.get("games_played", 0) + 1
                user_stats["games_lost"] = user_stats.get("games_lost", 0) + 1
                save_users()
                remove_active_game(user_id)
            else:
                await update.message.reply_text(
                    f"{_TGX} وەڵامەکەت هەڵەیە! دووبارە هەوڵ بدەرەوە.\n\n"
                    f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> ڕێنمایی: {game_data['hint']}\n"
                    f"{_TCH} هەوڵی ماوە: {3 - game_data['attempts']}",
                    parse_mode="HTML"
                )
                update_game_data(user_id, game_data)
        
        return True
        
    except Exception as e:
        logger.error("هەڵە لە handle_emoji_puzzle_answer: %s", e)
        return False

