# ════════════════════════════════════════════════════════════════════
# 🚀 NASA Helpers — یارمەتیدەرە هاوبەشەکان بۆ هەموو بەشەکانی NASA
# ────────────────────────────────────────────────────────────────────
# ئەمانە بۆ پاراستن لە کێشەی "Wrong type of the web page content"
# بەکار دێن — کێشەیەک کە ڕوو دەدات کاتێک URL ـی NASA وێنە نییە
# (HTML, GIF, TIFF, BMP، یان فایلی زۆر گەورە).
# ════════════════════════════════════════════════════════════════════

async def _nasa_probe_content_type(url: str) -> tuple:
    """
    Content-Type و Content-Length ـی URL بهێنە بێ ئەوەی فایل دابەزێنیت.

    FIX #3 — دووگامی:
      ١. HEAD بکە (خێرا، بێ بار)
      ٢. ئەگەر HEAD شکستی هێنا یان ctype بەتاڵ گەڕایەوە (ناسا CDN ناپشتگیری دەکات):
         → GET بکە بەڵام تەنیا bytes=0-15 (١٦ بایت) — content-type ی header بهێنە
    دەگەڕێنێتەوە: (content_type: str, content_length: int)
    """
    _TIMEOUT      = 6
    _RANGE_HEADER = {"Range": "bytes=0-15"}

    def _parse_headers(headers) -> tuple:
        ctype = (headers.get("content-type") or "").split(";")[0].strip().lower()
        clen  = int(headers.get("content-length") or 0)
        return ctype, clen

    try:
        if httpx:
            async with httpx.AsyncClient(timeout=_TIMEOUT, follow_redirects=True) as c:
                # ── ① HEAD ──
                try:
                    r = await c.head(url)
                    if r.status_code < 400:
                        ctype, clen = _parse_headers(r.headers)
                        if ctype:                      # HEAD پاسخی درووستی گەڕاند
                            return ctype, clen
                except Exception:
                    pass
                # ── ② GET partial — HEAD شکستی هێنا یان ctype بەتاڵ بوو ──
                r2 = await c.get(url, headers=_RANGE_HEADER)
                return _parse_headers(r2.headers)
        else:
            loop = asyncio.get_running_loop()

            def _do_head():
                return requests.head(url, timeout=_TIMEOUT, allow_redirects=True)

            def _do_get_partial():
                return requests.get(url, timeout=_TIMEOUT, allow_redirects=True,
                                    headers=_RANGE_HEADER, stream=True)

            # ── ① HEAD ──
            try:
                r = await loop.run_in_executor(_THREAD_POOL, _do_head)
                ctype, clen = _parse_headers(r.headers)
                if ctype:
                    return ctype, clen
            except Exception:
                pass
            # ── ② GET partial ──
            r2 = await loop.run_in_executor(_THREAD_POOL, _do_get_partial)
            return _parse_headers(r2.headers)

    except Exception:
        return "", 0


async def _nasa_send_image_safe(
    context,
    chat_id: int,
    image_urls: list,   # ترتیبکراو: hd یەکەم
    caption: str,
    reply_markup,
    label: str = "NASA",
):
    """
    ناردنی پاراستوو بۆ هەر وێنەیەک:
      ١. هەر URL تاقی بکە (hd یەکەم)
      ٢. content-type چێک بکە
      ٣. ئەگەر GIF بوو → animation
      ٤. ئەگەر photo بوو و ≤ ٥MB → photo
      ٥. ئەگەر photo بوو و > ٥MB → URL ـی ئاسایی تاقی بکە
      ٦. ئەگەر هیچ نەکرا → fallback تێکست + لینک

    دەگەڕێنێتەوە: True ئەگەر سەرکەوت، False ئەگەر هەموو شت شکستی هێنا.
    """
    image_urls = [u for u in image_urls if u]  # سڕینەوەی پووچ
    if not image_urls:
        return False

    # سنووری Telegram بۆ photo: ١٠MB، بەڵام بۆ ئەمیناتر: ٥MB
    PHOTO_SIZE_LIMIT = 5 * 1024 * 1024

    last_err = None
    for img_url in image_urls:
        ctype, clen = await _nasa_probe_content_type(img_url)
        logger.debug("%s probe: ctype=%s clen=%s url=%s",
                     label, ctype, clen, img_url[:60])

        try:
            # GIF — animation
            if ctype == "image/gif":
                await context.bot.send_animation(
                    chat_id=chat_id, animation=img_url,
                    caption=caption, parse_mode="HTML", reply_markup=reply_markup,
                )
                return True

            # وێنەی ئاسایی
            if ctype.startswith("image/"):
                # فایلی گەورە بسپرە بۆ URL ـی دواتر
                if clen > 0 and clen > PHOTO_SIZE_LIMIT:
                    logger.warning("%s file too large: %d bytes — skip", label, clen)
                    continue

                await context.bot.send_photo(
                    chat_id=chat_id, photo=img_url,
                    caption=caption, parse_mode="HTML", reply_markup=reply_markup,
                )
                return True

            # نا-image (HTML, JSON, ...) — بڕۆ بۆ URL ـی دواتر
            logger.warning("%s URL is not image: ctype=%s", label, ctype)
            continue

        except Exception as _pe:
            last_err = _pe
            err_str = str(_pe).lower()
            logger.warning("%s send failed [%s...]: %s", label, img_url[:50], _pe)
            # ئەگەر کێشەی Telegram بوو لەسەر فایل، بڕۆ بۆ URL ـی دواتر
            if any(p in err_str for p in (
                "wrong type", "photo dimensions", "photo invalid",
                "wrong file identifier", "failed to get http url",
                "file is too big", "file too large",
            )):
                continue
            break

    # هیچ URL کاری نەکرد → False
    logger.warning("%s: all URLs failed. last=%s", label, last_err)
    return False


async def nasa_apod_from_query(query, context):
    """NASA APOD — Astronomy Picture of the Day"""
    _back_kb = InlineKeyboardMarkup([
        [_ebtn("ڕۆژێکی تر",  "nasa:apod",
               api_kwargs={"style": "primary"}),
         _ebtn("ناسا", "science:nasa_hub", emoji_id="5195033767969839232",
               api_kwargs={"style": "primary"})],
        [_ebtn("گەڕانەوە", "menu:science", emoji_id="5352759161945867747",
               api_kwargs={"style": "primary"})],
    ])

    _nasa_keys = [NASA_API_KEY, "DEMO_KEY"]
    data       = None
    last_err   = None

    import datetime as _dt
    _params_extra = {}
    if random.random() < 0.5:
        _start = _dt.date(2010, 1, 1)
        _end   = _dt.date.today()
        _days  = (_end - _start).days
        if _days > 0:
            _rand = _start + _dt.timedelta(days=random.randint(0, _days))
            _params_extra["date"] = _rand.isoformat()

    for _key in _nasa_keys:
        try:
            _url    = "https://api.nasa.gov/planetary/apod"
            _params = {"api_key": _key, **_params_extra}
            _resp   = (
                await _httpx_get(_url, params=_params, timeout=12)
                if httpx else
                await asyncio.get_running_loop().run_in_executor(
                    _THREAD_POOL, lambda: requests.get(_url, params=_params, timeout=12))
            )
            if _resp.status_code == 200:
                _d = _resp.json()
                if "url" in _d or "title" in _d:
                    data = _d
                    break
                last_err = f"API error: {str(_d)[:80]}"
            elif _resp.status_code == 429:
                last_err = f"Rate limited (429) key={_key[:8]}"
            else:
                last_err = f"HTTP {_resp.status_code}"
        except Exception as _e:
            last_err = f"{type(_e).__name__}: {_e}"
            logger.error("NASA APOD: %s", last_err)

    if data is None:
        await _safe_edit(
            query,
            "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji>"
            " هەڵە لە وەرگرتنی APOD. تکایە دواتر هەوڵ بدەوە.",
            reply_markup=_back_kb
        )
        return

    title_safe  = html.escape(data.get("title", "بێ ناونیشان"))
    expl_safe   = html.escape(data.get("explanation", "")[:500])
    media_type  = data.get("media_type", "image")
    apod_date   = data.get("date", "")
    copyright_  = html.escape(data.get("copyright", "").strip()) if data.get("copyright") else ""

    date_line   = f"\n<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>بەروار:</b> {apod_date}" if apod_date else ""
    copy_line   = f"\n<tg-emoji emoji-id=\"5438648530656860878\">📷</tg-emoji> <b>Copyright:</b> {copyright_}" if copyright_ else ""

    text = (
        "<tg-emoji emoji-id=\"5195033767969839232\">🚀</tg-emoji>"
        " <b>وێنەی گەردوونیی ڕۆژ — NASA APOD</b>\n"
        "⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n\n"
        f"<tg-emoji emoji-id=\"5217751293107381480\">🔭</tg-emoji> <b>ناونیشان:</b> {title_safe}"
        f"{date_line}{copy_line}\n\n"
        f"<tg-emoji emoji-id=\"5472411062412254753\">📖</tg-emoji>"
        f" <b>ڕوونکردنەوە:</b>\n{expl_safe}…"
    )

    if media_type == "video":
        vid_safe = html.escape(data.get("url", ""))
        await _safe_edit(
            query,
            text + f"\n\n<tg-emoji emoji-id=\"6325351379388860506\">🎬</tg-emoji> <a href='{vid_safe}'>سەیری ڤیدیۆکە بکە</a>",
            reply_markup=_back_kb
        )
        return

    # FIX #3b: media_type نا-image، نا-video (YouTube embed، iframe، هتد)
    # ناسا هەندێکجار media_type="other" دەگەڕێنێت — تەنیا لینک بنێرە
    if media_type not in ("image",):
        other_url  = data.get("url", "") or data.get("hdurl", "")
        other_safe = html.escape(other_url)
        await _safe_edit(
            query,
            text + (
                f"\n\n<tg-emoji emoji-id=\"6325351379388860506\">🎬</tg-emoji>"
                f" <a href='{other_safe}'>کردنەوەی ناوەڕۆک</a>"
            ),
            reply_markup=_back_kb
        )
        return

    # ──────────────────────────────────────────────────────────────────
    # 🚀 ناردنی وێنە بە بەکارهێنانی helper ـی هاوبەش
    # ──────────────────────────────────────────────────────────────────
    hd_url   = data.get("hdurl", "")
    main_url = data.get("url", "")
    image_urls = [hd_url, main_url]

    if not any(image_urls):
        await _safe_edit(query, text, reply_markup=_back_kb)
        return

    # سڕینەوەی پەیامی پێشوو
    try:
        await query.message.delete()
    except Exception as _e:
        logger.debug("APOD delete: %s", _e)

    # ناردنی پاراستوو
    success = await _nasa_send_image_safe(
        context=context,
        chat_id=query.message.chat.id,
        image_urls=image_urls,
        caption=text,
        reply_markup=_back_kb,
        label="APOD",
    )

    if success:
        return

    # هەموو URL شکستی هێنا → fallback بۆ تێکست + لینک
    fallback_url = next((u for u in image_urls if u), "")
    url_safe = html.escape(fallback_url)
    try:
        await context.bot.send_message(
            chat_id=query.message.chat.id,
            text=(
                text
                + f"\n\n<tg-emoji emoji-id=\"5893232439110668588\">🖼</tg-emoji> "
                f"<a href='{url_safe}'>کردنەوەی وێنەکە لە مرۆڤ‌ڤیووەر</a>"
            ),
            parse_mode="HTML",
            reply_markup=_back_kb,
            disable_web_page_preview=False,
        )
    except Exception as _e2:
        logger.error("APOD final fallback: %s", _e2)


