_BK_DB       = "books.db"
_BK_PER_PAGE = 6       # کتێب لە هەر لاپەڕەیەک
_BK_CHARS    = 3200    # کارەکتەری هەر پەڕەی کتێب

# ── ئایدی ئیمۆجییەکان (لە QURAN_EMOJI_IDS + بۆتەکەی خودەوە) ──
