_BK_E_NEXT   = "5379687326991555987"   # <tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji>️
_BK_E_BKMK   = "5379619938954679279"   # <tg-emoji emoji-id='5379619938954679279'>🔖</tg-emoji>
