_BK_E_STAR   = "5379553354076694057"   # <tg-emoji emoji-id='5379553354076694057'>⭐</tg-emoji>
_BK_E_MOSQUE = "5382295780889498241"   # <tg-emoji emoji-id='5382295780889498241'>🕌</tg-emoji>

# ── پیتە کوردییە تایبەتەکان — بۆ پشکنینی زمانی تێکست ──
_BK_WAIT: dict = {}      # {user_id: {"step": ..., "lang": ..., "title": ..., "_ts": float}}
_BK_WAIT_TTL  = 600.0   # ١٠ خولەک — پاشان state خۆکار پاک دەکرێتەوە
_BK_CANCEL_EV = __import__("threading").Event()  # SIGINT/shutdown → set() دەکرێت

# ── Chunk Processing — بۆ PDF ی گەورە (زیاتر لە TRIGGER پەڕە) ──────────────
_BK_CHUNK_STATE:   dict  = {}     # {uid: {book_id,file_id,next_idx,total_raw,chunk_num,lang,title,author,_ts}}
_BK_CHUNK_TTL     = 1800          # ٣٠ خولەک — پشوو لە نێوان دووگمەکان
_BK_CHUNK_TRIGGER = 400           # ئەگەر زیاتر لە ٤٠٠ پەڕە → chunk mode
_BK_CHUNK_PAGES   = 150           # ژمارەی پەڕەی هەر chunk (کەم بۆ پێشگیری لە SIGINT)

# ── وەرگێڕانی ئۆتۆماتیک لە کاتی خوێندنەوە ──────────────────────────────────
_BK_TRANS_CACHE: dict = {}   # {(book_id, page_num): "وەرگێڕاو"}  — memory cache
_BK_TRANS_ON:    dict = {}   # {uid: set_of_book_ids}  — بۆ کامیان چالاکە

# کۆتایی ڕستەی ڕاست: تەنها خاڵی تاک (نەک ...) و نیشانەکانی ئەرەبی/ئینگلیزی
# بە ئەمەوە هێڵی "سەرچاوە..." وەک بەردەوامی سەیر دەکرێت، نەک کۆتای پاراگراف
_BK_SENT_END = re.compile(r'(?<!\.)\.(?!\.)[)\]"»›”’]*\s*$|[؟!?…][)\]"»›”’]*\s*$')

# ── FIX [BUG-BK3]: Kurdish Legacy Font Encoding Normalizer ──────────────────
# زۆری PDF ی کوردی لە فۆنتی کۆن (Unikurd / IraqiW / AliWeb) نووسراوەن
# ئەم فۆنتانە پیتی کوردی لە پۆزیشنی عەرەبی خستووەتەوە → pypdf ئەمانەی دەردەکات
# ئەم فانکشنە ئەمانە دەگێڕێتەوە بۆ Unicode ی ڕاستەقینەی کوردی
_BK_LEGACY_PAIRS: list = [
    # ── تێکەڵی دیاکریتیک (Combined) — FIRST ────────────────────────────────
    ('يَ', 'ێ'),   # يَ (ya+fatha)  → ێ  (Kurdish ê,  U+06CE)
    ('لَ', 'ڵ'),   # لَ (lam+fatha) → ڵ  (Kurdish ll, U+06B5)
    ('رِ', 'ڕ'),   # رِ (ra+kasra)  → ڕ  (Kurdish rr, U+0695)
    # ── پیتی تاکەکان (Single) ───────────────────────────────────────────────
    ('ة', 'ە'),   # ة  → ە  (ta marbuta  → Kurdish ae)
    ('ث', 'پ'),   # ث  → پ  (tha         → p)
    ('ض', 'چ'),   # ض  → چ  (dad         → ch)
    ('ط', 'گ'),   # ط  → گ  (ta          → g)
    ('ظ', 'ڤ'),   # ظ  → ڤ  (zha         → v)
    ('ذ', 'ژ'),   # ذ  → ژ  (dhal        → zh)
    ('ؤ', 'ۆ'),   # ؤ  → ۆ  (waw+hamza   → Kurdish o)
    # ── یای عەرەبی → یای کوردی ─────────────────────────────────────────────
    # پێش combined diacritics (يَ) پشکنراو — ئەمجارە تاکەکانی دەگۆڕێت
    ('ي', 'ی'),   # U+064A Arabic Ya       → U+06CC Farsi/Kurdish Ya
    ('ى', 'ی'),   # U+0649 Alef Maqsura   → U+06CC Kurdish Ya (کۆتای وشە)
    ('ك', 'ک'),   # U+0643 Arabic Kaf     → U+06A9 Persian/Kurdish Kaf
]

def _bk_normalize_legacy_kurdish(text: str) -> str:
    """پیتی کوردی کۆن (Legacy Font — عەرەبی بنەما) دەگێڕێتەوە بۆ Unicode ی ڕاستەقینەی کوردی."""
    for _old, _new in _BK_LEGACY_PAIRS:
        text = text.replace(_old, _new)
    return text


def _bk_merge_lines(items: list) -> list:
    """
    هێڵە بڕاوەکانی PDF یەکدەکاتەوە بۆ پاراگرافی ڕاست.
    هێڵێک کە کۆتایی ڕستەی ڕاستی هەیە (. ؟ ! ?) → کۆتای پاراگراف + جیاکەر.
    هێڵی بەتاڵ → جیاکەری پاراگراف پاراستراوە.
    بەکاردەهێنرێت هەم لە کاتی ingest (PDF) هەم لە کاتی display.
    """
    result: list[str] = []
    buf = ""
    for item in items:
        if not item:
            if buf:
                result.append(buf)
                buf = ""
            result.append("")
            continue
        if not buf:
            buf = item
        elif _BK_SENT_END.search(buf):
            result.append(buf)
            result.append("")   # ← جیاکەری پاراگراف پاش کۆتایی ڕستە
            buf = item
        else:
            buf += " " + item
    if buf:
        result.append(buf)
    # سڕینەوەی خاڵەکانی بەتاڵی دووبارە
    deduped: list[str] = []
    for r in result:
        if r or not (deduped and deduped[-1] == ""):
            deduped.append(r)
    return deduped


def _bk_db() -> "_bk_sqlite.Connection":
    conn = _bk_sqlite.connect(_BK_DB, check_same_thread=False)
    conn.row_factory = _bk_sqlite.Row
    conn.execute("PRAGMA foreign_keys = ON")   # CASCADE چالاک دەکات
    conn.execute("PRAGMA journal_mode = WAL")  # خوێندن-نووسینی کاتەکی باشتر
    return conn


def _bk_init_db() -> None:
    with _bk_db() as c:
        c.executescript("""
            CREATE TABLE IF NOT EXISTS books (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                title       TEXT    NOT NULL,
                author      TEXT    NOT NULL DEFAULT '',
                language    TEXT    NOT NULL DEFAULT 'ar',
                total_pages INTEGER NOT NULL DEFAULT 0,
                added_by    INTEGER NOT NULL DEFAULT 0,
                added_at    TEXT    NOT NULL DEFAULT ''
            );
            CREATE TABLE IF NOT EXISTS book_pages (
                book_id  INTEGER NOT NULL,
                page_num INTEGER NOT NULL,
                text     TEXT    NOT NULL DEFAULT '',
                PRIMARY KEY (book_id, page_num),
                FOREIGN KEY (book_id) REFERENCES books(id) ON DELETE CASCADE
            );
            CREATE TABLE IF NOT EXISTS book_progress (
                user_id  INTEGER NOT NULL,
                book_id  INTEGER NOT NULL,
                page_num INTEGER NOT NULL DEFAULT 1,
                PRIMARY KEY (user_id, book_id),
                FOREIGN KEY (book_id) REFERENCES books(id) ON DELETE CASCADE
            );
        """)
        # ── مایگرەیشن: ئەگەر book_progress کۆن بوو (بێ FK) دووبارە دروست بکە ──
        fk_check = c.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' AND name='book_progress'"
        ).fetchone()
        if fk_check and "FOREIGN KEY" not in (fk_check[0] or ""):
            c.executescript("""
                ALTER TABLE book_progress RENAME TO book_progress_old;
                CREATE TABLE book_progress (
                    user_id  INTEGER NOT NULL,
                    book_id  INTEGER NOT NULL,
                    page_num INTEGER NOT NULL DEFAULT 1,
                    PRIMARY KEY (user_id, book_id),
                    FOREIGN KEY (book_id) REFERENCES books(id) ON DELETE CASCADE
                );
                INSERT INTO book_progress SELECT * FROM book_progress_old;
                DROP TABLE book_progress_old;
            """)


_bk_init_db()


def _bk_save_progress(user_id: int, book_id: int, page_num: int) -> None:
    with _bk_db() as c:
        c.execute("""
            INSERT INTO book_progress (user_id, book_id, page_num) VALUES (?,?,?)
            ON CONFLICT(user_id, book_id) DO UPDATE SET page_num=excluded.page_num
        """, (user_id, book_id, page_num))


def _bk_get_progress(user_id: int, book_id: int) -> int:
    with _bk_db() as c:
        row = c.execute(
            "SELECT page_num FROM book_progress WHERE user_id=? AND book_id=?",
            (user_id, book_id)
        ).fetchone()
    return row["page_num"] if row else 1


_BK_INDD      = re.compile(r'[\w\-]+\.indd\s+Page\s+\d+', re.IGNORECASE)
_BK_USERCODE  = re.compile(r'\buser-[a-z0-9]+\b', re.IGNORECASE)
_BK_FCODE     = re.compile(r'\bF-\d{3,}\b')
_BK_TIMESTAMP = re.compile(r'\b\d{1,2}/\d{1,2}/\d{2,4}\s+\d{1,2}:\d{2}\s+[AP]M\b')
_BK_PAGEONLY  = re.compile(r'^\s*[\d\s\-–—]+\s*$')


def _bk_clean_page(text: str) -> str:
    """
    artifact و شتی زیادە لە تێکستی PDF دەسڕێتەوە.
    هەروەها هێڵە بڕاوەکانی PDF یەکدەکاتەوە بۆ پاراگرافی ڕاست.

    دابەشی سڕینەوە:
      ① InDesign /.indd metadata — "ber38413_ch01.indd Page 8  16/11/12 ..."
      ② printer marks — "F-403", "user-f396"
      ③ هێڵی کورتی تەنیا ژمارە یان کۆدی ئەلفبا-ژمارەیی
      ④ خێرا دووبارەبوونەوەی هەمان هێڵ (artifact ی سکانەر)
      ⑤ هێڵە دووباراوەکانی PDF لە یەک پاراگرافدا یەکدەکاتەوە
    """
    lines = text.split("\n")
    cleaned: list[str] = []
    seen: dict[str, int] = {}

    for line in lines:
        s = line.strip()
        if not s:
            cleaned.append("")
            continue

        if _BK_INDD.search(s):      continue
        if _BK_USERCODE.search(s):  continue
        if _BK_FCODE.search(s) and len(s) < 15: continue
        if _BK_TIMESTAMP.search(s): continue
        if _BK_PAGEONLY.match(s) and len(s) < 10:
            continue

        key = s.lower()
        seen[key] = seen.get(key, 0) + 1
        if seen[key] > 1 and len(s) < 80:
            continue

        cleaned.append(s)

    # هێڵە بڕاوەکانی PDF → پاراگرافی ڕاست (dedup لە ناو helper)
    merged = _bk_merge_lines(cleaned)
    return "\n".join(merged).strip()


def _bk_split_text(raw: str) -> list:
    """تێکستی درێژ دابەشدەکات بە پەڕەی مەعقوول."""
    raw = _bk_clean_page(raw)
    paras = [p.strip() for p in re.split(r'\n{2,}', raw) if p.strip()]
    pages, cur = [], ""
    for p in paras:
        if len(cur) + len(p) + 2 > _BK_CHARS:
            if cur:
                pages.append(cur.strip())
                cur = ""
            while len(p) > _BK_CHARS:
                split_at = _BK_CHARS
                while split_at > 0 and p[split_at] not in ' \n':
                    split_at -= 1
                if split_at == 0:
                    split_at = _BK_CHARS
                pages.append(p[:split_at].strip())
                p = p[split_at:]
        cur += p + "\n\n"
    if cur.strip():
        pages.append(cur.strip())
    return pages or ["—"]


def _bk_extract_pdf(pdf_bytes: bytes) -> list:
    """[DEPRECATED] — بەکارهێنانی _bk_process_large_pdf باشترە."""
    if not _BK_PDF_OK:
        return []
    import io as _io
    pages = []
    try:
        reader = _BkPdfReader(_io.BytesIO(pdf_bytes))
        for pg in reader.pages:
            try:
                txt = (pg.extract_text() or "").strip()
                if txt:
                    pages.append(txt)
            except Exception:
                continue
    except Exception as _e:
        logger.error("_bk_extract_pdf: %s", _e)
    return pages


async def _bk_process_large_pdf(
    doc,
    msg,
    user_id: int,
    lang: str,
    title: str,
    author: str,
) -> "tuple[int, int] | tuple[None, None] | tuple[str, int]":
    """
    PDF پرۆسێس دەکات — بە دوو mode:
      • ئاسایی  (≤ TRIGGER پەڕە): یەکجار تەواو دەکرێت
      • Chunk   (> TRIGGER پەڕە): بەش بەش — دووگمەی بەردەوام بوون دەدرێت

    Returns:
      (book_id, total_lib_pages)  → تەواو بوو
      ("chunk", book_id)          → بەشی یەکەم تەواو بوو، بەردەوامبوون پێویستە
      (None, None)                → شکست
    """
    import io as _io2
    from datetime import datetime as _dtnl

    if not _BK_PDF_OK:
        await msg.edit_text(
            "<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji> pypdf دامەزراو نییە.\n<code>pip install pypdf</code>",
            parse_mode="HTML",
        )
        return None, None

    loop = asyncio.get_running_loop()

    # ── ١. داونلۆد ──────────────────────────────────────────────────────────
    try:
        await msg.edit_text(
            f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
            f' <tg-emoji emoji-id="5443127283898405358">⬇️</tg-emoji> <b>داونلۆد دەکرێت…</b>',
            parse_mode="HTML",
        )
        tg_file = await doc.get_file()
        _dl_buf = _io2.BytesIO()
        await tg_file.download_to_memory(_dl_buf)
        pdf_bytes = _dl_buf.getvalue()
        del _dl_buf
    except Exception as _dl_e:
        logger.error("_bk_process_large_pdf download: %s", _dl_e)
        await msg.edit_text(
            "<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji> داونلۆد شکستهێنا. تکایە دووبارە هەوڵ بدەرەوە."
        )
        return None, None

    # ── ٢. پشکنینی ژمارەی پەڕە + بڕیاری chunk mode ──────────────────────────
    def _count_pages() -> int:
        try:
            return len(_BkPdfReader(_io2.BytesIO(pdf_bytes)).pages)
        except Exception:
            return 0

    total_raw = await loop.run_in_executor(None, _count_pages)
    if total_raw == 0:
        await msg.edit_text(
            "<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji> PDF نەکرایەوە یان بەتاڵە.",
            parse_mode="HTML",
        )
        return None, None

    use_chunks = total_raw > _BK_CHUNK_TRIGGER
    end_idx    = _BK_CHUNK_PAGES if use_chunks else total_raw
    total_chunks = (total_raw + _BK_CHUNK_PAGES - 1) // _BK_CHUNK_PAGES if use_chunks else 1

    if use_chunks:
        try:
            await msg.edit_text(
                f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
                f' <b>PDF گەورەیە — {total_raw} پەڕە</b>\n'
                f'<tg-emoji emoji-id="5454415424319931791">⏳</tg-emoji> '
                f'بەش بەش پرۆسێس دەکرێت ({total_chunks} بەش × {_BK_CHUNK_PAGES} پەڕە)\n'
                f'<b>بەش ١ لە {total_chunks} دەستپێدەکات…</b>',
                parse_mode="HTML",
            )
        except Exception:
            pass

    # ── ٣. استخراج لە thread + progress ────────────────────────────────────
    _prog: dict = {"done": 0, "total": 0, "pages": [], "err": None, "ok": False}

    def _thread_extract_range() -> None:
        try:
            reader = _BkPdfReader(_io2.BytesIO(pdf_bytes))
            _prog["total"] = min(end_idx, len(reader.pages))
            raw: list = []
            for _i in range(0, min(end_idx, len(reader.pages))):
                if _i % 50 == 0 and _BK_CANCEL_EV.is_set():
                    # ✅ FIX: پەڕەی کەمکراوەکان پاشەکەوت بکە پێش وەستان
                    _prog["err"]      = "RESTART"
                    _prog["pages"]    = raw
                    _prog["done_idx"] = _i      # کاتی ئەو پەڕەیەی بوومانەوە
                    return
                try:
                    _txt = (reader.pages[_i].extract_text() or "").strip()
                except Exception:
                    _txt = ""
                if _txt:
                    raw.append(_txt)
                _prog["done"] = _i + 1
            _prog["pages"] = raw
            _prog["ok"] = True
        except Exception as _exc:
            _prog["err"] = str(_exc)
            logger.error("_thread_extract_range: %s", _exc)

    fut = loop.run_in_executor(None, _thread_extract_range)

    _last_bar = ""
    _elapsed  = 0
    _TIMEOUT_S = 480
    while not fut.done():
        await asyncio.sleep(3)
        _elapsed += 3
        if _elapsed >= _TIMEOUT_S:
            _BK_CANCEL_EV.set()
            try:
                await msg.edit_text(
                    "<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji>"
                    f" <b>کات تەواو بوو ({_TIMEOUT_S//60} خولەک)</b>\n"
                    "PDF زۆر گەورەیە. تکایە PDF بچووکتر بنێرە.",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            _BK_CANCEL_EV.clear()
            return None, None
        if _BK_CANCEL_EV.is_set():
            # ✅ FIX: ئەگەر پەڕەی کەمکراوە هەیە → بخاتە DB و بەردەوام بوون پیشان بدە
            partial_pages = _prog.get("pages", [])
            done_idx      = _prog.get("done_idx", _prog.get("done", 0))
            if partial_pages:
                _partial: list = []
                for _rp in partial_pages:
                    _partial.extend(_bk_split_text(_rp))
                if lang == "ku":
                    _partial = [_bk_normalize_legacy_kurdish(_p) for _p in _partial]
                from datetime import datetime as _dtnl_p
                def _do_partial_insert():
                    _CH = 200
                    with _bk_db() as _c:
                        _cur = _c.execute(
                            "INSERT INTO books (title,author,language,total_pages,added_by,added_at)"
                            " VALUES (?,?,?,?,?,?)",
                            (title, author, lang, len(_partial), user_id, _dtnl_p.now().isoformat()),
                        )
                        _bid = _cur.lastrowid
                        for _off in range(0, len(_partial), _CH):
                            _c.executemany(
                                "INSERT INTO book_pages (book_id,page_num,text) VALUES (?,?,?)",
                                [(_bid, _off+_x+1, _p)
                                 for _x, _p in enumerate(_partial[_off:_off+_CH])],
                            )
                    return _bid
                import time as _bk_t_p
                p_book_id = await loop.run_in_executor(None, _do_partial_insert)
                _BK_CHUNK_STATE[user_id] = {
                    "book_id": p_book_id, "file_id": getattr(doc, "file_id", None),
                    "next_idx": done_idx, "total_raw": total_raw, "chunk_num": 1,
                    "lang": lang, "title": title, "author": author,
                    "_ts": _bk_t_p.monotonic(),
                }
                remaining_r  = total_raw - done_idx
                next_p       = min(_BK_CHUNK_PAGES, remaining_r)
                total_chunks_r = (total_raw + _BK_CHUNK_PAGES - 1) // _BK_CHUNK_PAGES
                kb_p = InlineKeyboardMarkup([[_ebtn(
                    f"بەردەوام بوون ► ({next_p} پەڕەی تر)",
                    f"bk_chunk:{user_id}",
                    emoji_id=_BK_E_BOOK, api_kwargs={"style": "success"},
                )]])
                try:
                    await msg.edit_text(
                        f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
                        f' <tg-emoji emoji-id="5866334493454897274">⏰</tg-emoji>'
                        f' <b>بۆت ریستارت بوو لەناوی پرۆسێس</b>\n\n'
                        f'<tg-emoji emoji-id="5857044938755149915">✅</tg-emoji>'
                        f' <b>{len(_partial)}</b> پەڕەی پاشەکەوتکراوە\n'
                        f'ماوەتەوە: <b>{remaining_r}</b> پەڕە لە <b>{total_raw}</b>\n\n'
                        f'دووگمەکە بەست بۆ بەردەوام بوون:',
                        parse_mode="HTML", reply_markup=kb_p,
                    )
                except Exception:
                    pass
                return "chunk", p_book_id
            else:
                try:
                    await msg.edit_text(
                        "<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji>"
                        " بۆت ریستارت بوو پێش دەستپێکردنی پرۆسێس.\n"
                        "تکایە دووبارە PDF بنێرە.",
                        parse_mode="HTML",
                    )
                except Exception:
                    pass
                return None, None
        _done  = _prog["done"]
        _total = _prog["total"]
        if _total > 0:
            _pct    = int(_done / _total * 100)
            _filled = _pct // 10
            _bar    = "█" * _filled + "░" * (10 - _filled)
            _chunk_label = f" (بەش ١/{total_chunks})" if use_chunks else ""
            _line   = (
                f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
                f' <tg-emoji emoji-id="5454415424319931791">⏳</tg-emoji>'
                f' <b>تێکست دەردەکرێت{_chunk_label}…</b>\n'
                f'<code>[{_bar}] {_pct}%</code>\n'
                f'پەڕە: <b>{_done}</b> / <b>{_total}</b>'
            )
            if _bar != _last_bar:
                try:
                    await msg.edit_text(_line, parse_mode="HTML")
                    _last_bar = _bar
                except Exception as _pe:
                    logger.debug("_bk progress edit skip: %s", _pe)

    try:
        await fut
    except Exception as _fe:
        logger.error("_bk_process_large_pdf fut: %s", _fe)

    if not _prog["ok"] or not _prog["pages"]:
        _err_hint = _prog.get("err") or "تێکستێک نەدۆزرایەوە"
        await msg.edit_text(
            f"<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji> <b>شکستهێنا:</b> {_err_hint[:200]}\n"
            "شاید PDF سکانکراوەیە (image-only) یان خراپ بێت.",
            parse_mode="HTML",
        )
        return None, None

    # ── ٤. سپلیت + نۆرمالایز ───────────────────────────────────────────────
    all_pages: list = []
    for _rp in _prog["pages"]:
        all_pages.extend(_bk_split_text(_rp))
    del _prog, pdf_bytes

    if lang == "ku":
        all_pages = [_bk_normalize_legacy_kurdish(_p) for _p in all_pages]

    # ── ٥. DB insert ────────────────────────────────────────────────────────
    def _do_insert() -> int:
        _CHUNK = 200
        with _bk_db() as _c:
            _cur = _c.execute(
                "INSERT INTO books (title, author, language, total_pages, added_by, added_at) "
                "VALUES (?,?,?,?,?,?)",
                (title, author, lang, len(all_pages), user_id, _dtnl.now().isoformat()),
            )
            _bk_id = _cur.lastrowid
            for _off in range(0, len(all_pages), _CHUNK):
                _c.executemany(
                    "INSERT INTO book_pages (book_id, page_num, text) VALUES (?,?,?)",
                    [(_bk_id, _off + _idx + 1, _p)
                     for _idx, _p in enumerate(all_pages[_off: _off + _CHUNK])],
                )
        return _bk_id

    book_id = await loop.run_in_executor(None, _do_insert)

    # ── ٦. ئەگەر chunk mode — state تۆمار بکە + دووگمەی بەردەوام ────────────
    if use_chunks:
        import time as _bk_t
        _BK_CHUNK_STATE[user_id] = {
            "book_id":   book_id,
            "file_id":   getattr(doc, "file_id", None) or getattr(doc, "_file_id", None),
            "next_idx":  end_idx,
            "total_raw": total_raw,
            "chunk_num": 1,
            "lang":      lang,
            "title":     title,
            "author":    author,
            "_ts":       _bk_t.monotonic(),
        }
        remaining = total_raw - end_idx
        next_chunk_pages = min(_BK_CHUNK_PAGES, remaining)
        kb_chunk = InlineKeyboardMarkup([[
            _ebtn(
                f"بەردەوام بوون ► بەش ٢/{total_chunks} ({next_chunk_pages} پەڕە)",
                f"bk_chunk:{user_id}",
                emoji_id=_BK_E_BOOK,
                api_kwargs={"style": "success"},
            ),
        ]])
        try:
            await msg.edit_text(
                f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
                f' <tg-emoji emoji-id="5857044938755149915">✅</tg-emoji>'
                f' <b>بەش ١ لە {total_chunks} تەواو بوو!</b>\n\n'
                f'<b>{html.escape(title)}</b>\n'
                f'پەڕەی زیادکراو: <b>{len(all_pages)}</b> لە <b>{total_raw}</b>\n\n'
                f'<tg-emoji emoji-id="5454415424319931791">⏳</tg-emoji>'
                f' <b>{remaining}</b> پەڕەی تر ماوەتەوە\n'
                f'دووگمەکە بەست بۆ بەردەوام بوون:',
                parse_mode="HTML",
                reply_markup=kb_chunk,
            )
        except Exception as _ce:
            logger.debug("chunk msg edit: %s", _ce)
        return "chunk", book_id

    return book_id, len(all_pages)


async def _bk_chunk_continue_callback(query, context) -> None:
    """
    دووگمەی 'بەردەوام بوون' — بەشی داهاتووی PDF لە Telegram re-download دەکات
    و پرۆسێس دەکات، پاشان بە هەمان book_id ئەپێند دەکات.
    """
    import io   as _io3
    import time as _bk_t2
    from datetime import datetime as _dtnl2

    uid = query.from_user.id
    state = _BK_CHUNK_STATE.get(uid)

    if not state:
        await query.answer("⏰ کاتی بەردەوامبوون بەسەرچووە. PDF دووبارە بنێرە.", show_alert=True)
        return
    if _bk_t2.monotonic() - state.get("_ts", 0) > _BK_CHUNK_TTL:
        _BK_CHUNK_STATE.pop(uid, None)
        await query.answer("⏰ کاتی بەردەوامبوون بەسەرچووە. PDF دووبارە بنێرە.", show_alert=True)
        return

    await query.answer()

    book_id     = state["book_id"]
    file_id     = state["file_id"]
    start_idx   = state["next_idx"]
    total_raw   = state["total_raw"]
    chunk_num   = state["chunk_num"]
    lang        = state["lang"]
    title       = state["title"]
    author      = state["author"]
    end_idx     = min(start_idx + _BK_CHUNK_PAGES, total_raw)
    total_chunks = (total_raw + _BK_CHUNK_PAGES - 1) // _BK_CHUNK_PAGES
    is_last     = end_idx >= total_raw

    # ── پیامی شروع ──────────────────────────────────────────────────────────
    try:
        await query.edit_message_text(
            f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
            f' <tg-emoji emoji-id="5443127283898405358">⬇️</tg-emoji>'
            f' <b>بەش {chunk_num+1}/{total_chunks} داونلۆد دەکرێت…</b>',
            parse_mode="HTML",
        )
    except Exception:
        pass

    loop = asyncio.get_running_loop()

    # ── ١. Re-download ───────────────────────────────────────────────────────
    try:
        tg_file  = await context.bot.get_file(file_id)
        _dl_buf2 = _io3.BytesIO()
        await tg_file.download_to_memory(_dl_buf2)
        pdf_bytes2 = _dl_buf2.getvalue()
        del _dl_buf2
    except Exception as _dl_e:
        logger.error("_bk_chunk_continue download: %s", _dl_e)
        try:
            await query.edit_message_text(
                "<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji>"
                " داونلۆد شکستهێنا. تکایە دووبارە دووگمەکە بەست."
            )
        except Exception:
            pass
        return

    # ── ٢. استخراج لە thread ────────────────────────────────────────────────
    _prog2: dict = {"done": 0, "total": 0, "pages": [], "err": None, "ok": False}

    def _thread_extract_chunk() -> None:
        try:
            reader = _BkPdfReader(_io3.BytesIO(pdf_bytes2))
            _prog2["total"] = end_idx - start_idx
            raw: list = []
            for _i in range(start_idx, min(end_idx, len(reader.pages))):
                if (_i - start_idx) % 50 == 0 and _BK_CANCEL_EV.is_set():
                    _prog2["err"]      = "RESTART"
                    _prog2["pages"]    = raw
                    _prog2["done_idx"] = _i
                    return
                try:
                    _txt = (reader.pages[_i].extract_text() or "").strip()
                except Exception:
                    _txt = ""
                if _txt:
                    raw.append(_txt)
                _prog2["done"] = _i - start_idx + 1
            _prog2["pages"] = raw
            _prog2["ok"] = True
        except Exception as _exc:
            _prog2["err"] = str(_exc)
            logger.error("_thread_extract_chunk: %s", _exc)

    fut2 = loop.run_in_executor(None, _thread_extract_chunk)

    # ── ٣. progress ──────────────────────────────────────────────────────────
    _last_bar2 = ""
    _elapsed2  = 0
    while not fut2.done():
        await asyncio.sleep(3)
        _elapsed2 += 3
        if _elapsed2 >= 480:
            _BK_CANCEL_EV.set()
            try:
                await query.edit_message_text(
                    "<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji> کات تەواو بوو.",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            _BK_CANCEL_EV.clear()
            return
        _done2  = _prog2["done"]
        _total2 = _prog2["total"]
        if _total2 > 0:
            _pct2    = int(_done2 / _total2 * 100)
            _filled2 = _pct2 // 10
            _bar2    = "█" * _filled2 + "░" * (10 - _filled2)
            _line2   = (
                f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
                f' <tg-emoji emoji-id="5454415424319931791">⏳</tg-emoji>'
                f' <b>بەش {chunk_num+1}/{total_chunks} دەردەکرێت…</b>\n'
                f'<code>[{_bar2}] {_pct2}%</code>\n'
                f'پەڕە: <b>{start_idx + _done2}</b> / <b>{total_raw}</b>'
            )
            if _bar2 != _last_bar2:
                try:
                    await query.edit_message_text(_line2, parse_mode="HTML")
                    _last_bar2 = _bar2
                except Exception:
                    pass

    try:
        await fut2
    except Exception as _fe2:
        logger.error("_bk_chunk_continue fut: %s", _fe2)

    del pdf_bytes2

    if not _prog2["ok"] or not _prog2["pages"]:
        # ✅ FIX: ئەگەر RESTART و پەڕەی کەمکراوە هەیە → ئەپێند و بەردەوام بوون
        partial2 = _prog2.get("pages", [])
        done_idx2 = _prog2.get("done_idx", start_idx + _prog2.get("done", 0))
        if _prog2.get("err") == "RESTART" and partial2:
            _p2: list = []
            for _rp in partial2:
                _p2.extend(_bk_split_text(_rp))
            if lang == "ku":
                _p2 = [_bk_normalize_legacy_kurdish(_x) for _x in _p2]

            def _do_append_partial():
                _CH2 = 200
                with _bk_db() as _c:
                    _lr = _c.execute(
                        "SELECT COALESCE(MAX(page_num),0) FROM book_pages WHERE book_id=?",
                        (book_id,)
                    ).fetchone()[0]
                    for _off in range(0, len(_p2), _CH2):
                        _c.executemany(
                            "INSERT INTO book_pages (book_id,page_num,text) VALUES (?,?,?)",
                            [(book_id, _lr+_off+_x+1, _pg)
                             for _x, _pg in enumerate(_p2[_off:_off+_CH2])],
                        )
                    _nt = _c.execute(
                        "SELECT COUNT(*) FROM book_pages WHERE book_id=?", (book_id,)
                    ).fetchone()[0]
                    _c.execute("UPDATE books SET total_pages=? WHERE id=?", (_nt, book_id))
                return _nt

            new_total_p = await loop.run_in_executor(None, _do_append_partial)
            _BK_CHUNK_STATE[uid] = {
                **state,
                "next_idx":  done_idx2,
                "chunk_num": chunk_num + 1,
                "_ts":       _bk_t2.monotonic(),
            }
            remaining_p  = total_raw - done_idx2
            next_p2      = min(_BK_CHUNK_PAGES, remaining_p)
            kb_p2 = InlineKeyboardMarkup([[_ebtn(
                f"بەردەوام بوون ► ({next_p2} پەڕەی تر)",
                f"bk_chunk:{uid}",
                emoji_id=_BK_E_BOOK, api_kwargs={"style": "success"},
            )]])
            try:
                await query.edit_message_text(
                    f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
                    f' <tg-emoji emoji-id="5866334493454897274">⏰</tg-emoji>'
                    f' <b>بۆت ریستارت بوو لەناوی پرۆسێس</b>\n\n'
                    f'<tg-emoji emoji-id="5857044938755149915">✅</tg-emoji>'
                    f' کۆی پەڕەی ذخیرەکراو: <b>{new_total_p}</b>\n'
                    f'ماوەتەوە: <b>{remaining_p}</b> پەڕە\n\n'
                    f'دووگمەکە بەست بۆ بەردەوام بوون:',
                    parse_mode="HTML", reply_markup=kb_p2,
                )
            except Exception:
                pass
            return
        # هیچ پەڕەیەک نەکرایەوە
        try:
            await query.edit_message_text(
                f"<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji>"
                f" بەش {chunk_num+1} شکستهێنا — شاید PDF سکانکراوەیە.",
                parse_mode="HTML",
            )
        except Exception:
            pass
        _BK_CHUNK_STATE.pop(uid, None)
        return

    # ── ٤. سپلیت + نۆرمالایز ───────────────────────────────────────────────
    new_pages: list = []
    for _rp in _prog2["pages"]:
        new_pages.extend(_bk_split_text(_rp))
    del _prog2

    if lang == "ku":
        new_pages = [_bk_normalize_legacy_kurdish(_p) for _p in new_pages]

    # ── ٥. ئەپێند بۆ DB ─────────────────────────────────────────────────────
    def _do_append() -> int:
        _CHUNK = 200
        with _bk_db() as _c:
            # ئەوەی ئێستا هەیە بزانە
            _last_row = _c.execute(
                "SELECT COALESCE(MAX(page_num), 0) FROM book_pages WHERE book_id=?",
                (book_id,)
            ).fetchone()[0]
            # پەڕەی نوێ ئەپێند بکە
            for _off in range(0, len(new_pages), _CHUNK):
                _c.executemany(
                    "INSERT INTO book_pages (book_id, page_num, text) VALUES (?,?,?)",
                    [
                        (book_id, _last_row + _off + _idx + 1, _p)
                        for _idx, _p in enumerate(new_pages[_off: _off + _CHUNK])
                    ],
                )
            # total_pages نوێ بکەرەوە
            _new_total = _c.execute(
                "SELECT COUNT(*) FROM book_pages WHERE book_id=?", (book_id,)
            ).fetchone()[0]
            _c.execute(
                "UPDATE books SET total_pages=? WHERE id=?", (_new_total, book_id)
            )
            return _new_total

    new_total = await loop.run_in_executor(None, _do_append)

    # ── ٦. بەردەوام یان تەواو ───────────────────────────────────────────────
    if is_last:
        _BK_CHUNK_STATE.pop(uid, None)
        kb_done = InlineKeyboardMarkup([[
            _ebtn("بخوێنە", f"bk_read:{book_id}:1",
                  emoji_id=_BK_E_BOOK, api_kwargs={"style": "success"}),
            _ebtn("لیستی کتێب", "bk_list:0",
                  emoji_id=_BK_E_LIST, api_kwargs={"style": "primary"}),
        ]])
        flag = "<tg-emoji emoji-id='5231070734016607712'>🌙</tg-emoji>" if lang == "ar" else ("<tg-emoji emoji-id='5472411062412254753'>📖</tg-emoji>" if lang == "ku" else "<tg-emoji emoji-id='5399898266265475100'>🌍</tg-emoji>")
        try:
            await query.edit_message_text(
                f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
                f' <tg-emoji emoji-id="5857044938755149915">✅</tg-emoji>'
                f' <b>کتێبەکە تەواو زیادکرا!</b>\n\n'
                f'{flag} <b>{html.escape(title)}</b>\n'
                f'نووسەر: {html.escape(author)}\n'
                f'کۆی پەڕە: <b>{new_total}</b>',
                parse_mode="HTML",
                reply_markup=kb_done,
            )
        except Exception as _fe:
            logger.debug("chunk done edit: %s", _fe)
    else:
        # state نوێ بکەرەوە
        _BK_CHUNK_STATE[uid] = {
            **state,
            "next_idx":  end_idx,
            "chunk_num": chunk_num + 1,
            "_ts":       _bk_t2.monotonic(),
        }
        remaining2    = total_raw - end_idx
        next_ch_pages = min(_BK_CHUNK_PAGES, remaining2)
        kb_next = InlineKeyboardMarkup([[
            _ebtn(
                f"بەردەوام بوون ► بەش {chunk_num+2}/{total_chunks} ({next_ch_pages} پەڕە)",
                f"bk_chunk:{uid}",
                emoji_id=_BK_E_BOOK,
                api_kwargs={"style": "success"},
            ),
        ]])
        try:
            await query.edit_message_text(
                f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji>'
                f' <tg-emoji emoji-id="5857044938755149915">✅</tg-emoji>'
                f' <b>بەش {chunk_num+1}/{total_chunks} تەواو بوو!</b>\n\n'
                f'پەڕەی زیادکراو تاکوو ئێستا: <b>{new_total}</b> لە <b>{total_raw}</b>\n'
                f'ماوەتەوە: <b>{remaining2}</b> پەڕە\n\n'
                f'دووگمەکە بەست بۆ بەردەوام بوون:',
                parse_mode="HTML",
                reply_markup=kb_next,
            )
        except Exception as _fe:
            logger.debug("chunk continue edit: %s", _fe)


async def _bk_translate_page(book_id: int, page_num: int, text: str,
                              src_lang: str = "en") -> str:
    """
    تێکستی هەر زمانێک وەرگێڕدەکات بۆ کوردی سۆرانی.
    ئەستراتیژی: Gemini (کوالیتی بەرز) → Google Translate (fallback)
    ئەنجامەکە cache دەکرێت بۆ ئەوەی پەڕەی هەمان کتێب دووبارە وەرگێڕدرێت.
    Returns: وەرگێڕاوی تەواو  یان  "" بۆ شکستی تەواو
    """
    import re as _re_bk
    import urllib.parse as _up

    cache_key = (book_id, page_num, src_lang)
    if cache_key in _BK_TRANS_CACHE:
        return _BK_TRANS_CACHE[cache_key]

    # ── ناوەکانی زمان بۆ prompt ──────────────────────────────────────────────
    _LANG_NAMES = {
        "en": "English", "ar": "Arabic", "fa": "Persian (Farsi)",
        "tr": "Turkish",  "ur": "Urdu",   "id": "Indonesian",
        "fr": "French",   "de": "German", "ru": "Russian",
        "zh": "Chinese",  "es": "Spanish","it": "Italian",
        "pt": "Portuguese","ja": "Japanese","ko": "Korean",
        "hi": "Hindi",    "bn": "Bengali", "nl": "Dutch",
        "pl": "Polish",   "sv": "Swedish", "no": "Norwegian",
    }
    _src_name = _LANG_NAMES.get(src_lang, src_lang.upper())

    # ── داڕشتنی chunk بۆ نێردن ──────────────────────────────────────────────
    MAX_CHUNK = 3000

    def _split(t: str) -> list:
        if len(t) <= MAX_CHUNK:
            return [t]
        parts, cur = [], ""
        for para in t.split("\n\n"):
            if len(cur) + len(para) + 2 <= MAX_CHUNK:
                cur += ("\n\n" if cur else "") + para
            else:
                if cur:
                    parts.append(cur)
                cur = para if len(para) <= MAX_CHUNK else ""
                if len(para) > MAX_CHUNK:
                    for i in range(0, len(para), MAX_CHUNK):
                        parts.append(para[i: i + MAX_CHUNK])
        if cur:
            parts.append(cur)
        return parts or [t]

    # ── پاکسازی: تەنها ساتری کوردی/عەرەبی بهێڵێتەوە ─────────────────────────
    def _kurdish_only(raw: str) -> str:
        _clean_lines = []
        for _line in raw.split("\n"):
            _s = _line.strip()
            if not _s:
                _clean_lines.append("")
                continue
            _latin  = sum(1 for c in _s if "A" <= c <= "z")
            _arabic = sum(1 for c in _s if "\u0600" <= c <= "\u06ff" or "\u0750" <= c <= "\u077f")
            _total  = len(_s.replace(" ", "")) or 1
            # ساتر لابدە ئەگەر: Latin > ٥٠٪ و Arabic < ٣٠٪
            if (_latin / _total) > 0.50 and (_arabic / _total) < 0.30:
                continue
            _clean_lines.append(_line)
        _out = "\n".join(_clean_lines)
        return _re_bk.sub(r"\n{3,}", "\n\n", _out).strip()

    # ════════════════════════════════════════════════════════════════════════
    # ── ١. Gemini — وەرگێڕانی پێشکەوتوو بە LLM ─────────────────────────────
    # ════════════════════════════════════════════════════════════════════════
    async def _gemini_translate_chunk(chunk: str) -> str:
        """یەک chunk بە Gemini وەردەگێڕێت — pool-ی تایبەتی وەرگێڕان بەکاردەهێنێت"""
        _prompt = (
            f"You are a professional literary translator. "
            f"Translate the following {_src_name} text into Kurdish Sorani (کوردی سۆرانی).\n\n"
            "CRITICAL RULES — follow every one exactly:\n"
            "1. Output ONLY the Kurdish Sorani translation. No original text. No notes. No explanations.\n"
            "2. Every single sentence must be translated. Never skip, summarize, or omit anything.\n"
            "3. Do NOT leave any word in the source language or in English.\n"
            "4. Use natural, fluent Kurdish Sorani as spoken in the Kurdistan Region of Iraq.\n"
            "5. Preserve all paragraph breaks and line structure exactly as in the source.\n"
            "6. Literary style: elegant and readable — not word-for-word mechanical translation.\n"
            "7. Proper nouns (names of people, places, organizations): transliterate into Kurdish script.\n\n"
            f"TEXT:\n{chunk}"
        )
        # ── pool-ی تایبەتی وەرگێڕان بەکاربێنە — quota-ی /gemini و /geminipro نابات ──
        _tried: set = set()
        while True:
            _key = _trans_pick_key(exclude=_tried)
            if not _key:
                break   # هەموو کلیلەکان سارد
            _tried.add(_key)
            try:
                _client = _get_genai_client(_key)
                _types  = _genai_types_lib
                _resp   = _client.models.generate_content(
                    model=_GEMINI_MODEL,
                    contents=[_types.Content(
                        role="user",
                        parts=[_types.Part(text=_prompt)]
                    )],
                    config=_types.GenerateContentConfig(
                        max_output_tokens=4000,
                        temperature=0.2,
                        thinking_config=_types.ThinkingConfig(thinking_budget=0),
                    ),
                )
                _trans_result = (_resp.text or "").strip()
                logger.info(
                    "<tg-emoji emoji-id=\"5271715383928172373\">📖</tg-emoji> وەرگێڕان [Gemini <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji>] زمان=%s key=%s... چارخ=%d دەرۆکت=%d char",
                    src_lang, _key[:8], len(chunk), len(_trans_result)
                )
                return _trans_result
            except Exception as _ge:
                _s = str(_ge)
                if ("429" in _s or "RESOURCE_EXHAUSTED" in _s.upper()
                        or "quota" in _s.lower()):
                    _trans_mark_exhausted(_key, seconds=65.0)
                    continue   # کلیلی دیکە هەوڵ بدە
                logger.debug("_bk_translate Gemini: %s", _ge)
                break   # هەڵەی تر → fallback
        return ""

    # ════════════════════════════════════════════════════════════════════════
    # ── ٢. Google Translate — fallback بۆ کاتی شکستی Gemini ────────────────
    # ════════════════════════════════════════════════════════════════════════
    async def _gtrans_chunk(chunk: str) -> str:
        """Google Translate fallback — "" بۆ شکست"""
        try:
            async with __import__("httpx").AsyncClient(timeout=15) as _hc:
                url = (
                    "https://translate.googleapis.com/translate_a/single"
                    f"?client=gtx&sl={src_lang}&tl=ckb&dt=t&q={_up.quote(chunk)}"
                )
                resp = await _hc.get(url, headers={"User-Agent": "Mozilla/5.0"})
                data = resp.json()
                _gt_result = "".join(s[0] for s in data[0] if s[0])
                logger.info(
                    "<tg-emoji emoji-id=\"5271715383928172373\">📖</tg-emoji> وەرگێڕان [Google Translate <tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji>] زمان=%s دەرۆکت=%d char",
                    src_lang, len(_gt_result)
                )
                return _gt_result
        except Exception as _gte:
            logger.debug("_bk_translate GTrans: %s", _gte)
            return ""

    # ════════════════════════════════════════════════════════════════════════
    # ── ئەنجامدانی وەرگێڕان ─────────────────────────────────────────────────
    # ════════════════════════════════════════════════════════════════════════
    chunks = _split(text)
    parts  = []

    for _chunk in chunks:
        # ١. Gemini هەوڵ بدە
        _result = await _gemini_translate_chunk(_chunk)

        # ٢. ئەگەر Gemini شکستی هێنا → Google Translate
        if not _result:
            logger.debug("_bk_translate: Gemini شکست → Google Translate fallback")
            _result = await _gtrans_chunk(_chunk)

        # ٣. ئەگەر هەردووکیان شکستیان هێنا → chunk-ی سەرەوە بهێڵەرەوە
        parts.append(_result or _chunk)

    raw    = "\n\n".join(parts)
    result = _kurdish_only(raw)

    if result:
        _BK_TRANS_CACHE[cache_key] = result
    return result


def _bk_build_list(page: int, user_id: int) -> tuple:
    """لیستی کتێبەکان دروست دەکات."""
    page = max(0, page)   # نێگەتیڤ OFFSET پارێزراوە
    with _bk_db() as c:
        total = c.execute("SELECT COUNT(*) FROM books").fetchone()[0]
        rows  = c.execute(
            "SELECT id, title, author, language, total_pages FROM books "
            "ORDER BY id DESC LIMIT ? OFFSET ?",
            (_BK_PER_PAGE, page * _BK_PER_PAGE)
        ).fetchall()

        # ✅ FIX: یەک کوئێری بۆ هەموو progress — جێگری N+1 کوئێری
        book_ids = [b["id"] for b in rows]
        if book_ids:
            placeholders = ",".join("?" * len(book_ids))
            prog_rows = c.execute(
                f"SELECT book_id, page_num FROM book_progress "
                f"WHERE user_id=? AND book_id IN ({placeholders})",
                [user_id] + book_ids
            ).fetchall()
            prog_map = {r["book_id"]: r["page_num"] for r in prog_rows}
        else:
            prog_map = {}

    total_pages = max(1, (total + _BK_PER_PAGE - 1) // _BK_PER_PAGE)

    text = (
        f'<tg-emoji emoji-id="{_BK_E_LIST}">📋</tg-emoji> <b>کتێبخانە</b>\n'
        f'⊱━━━━━<tg-emoji emoji-id="{_BK_E_STAR}">⭐</tg-emoji>━━━━━⊰\n\n'
        f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji> کۆی کتێب: <b>{total}</b>  ·  '
        f'لاپەڕەی <b>{page+1}/{total_pages}</b>\n\n'
    )

    btns = []
    if not rows:
        text += "<tg-emoji emoji-id='5352896944496728039'>📭</tg-emoji> هیچ کتێبێک تۆمار نەکراوە."
    else:
        for i, b in enumerate(rows):
            flag = "<tg-emoji emoji-id='5231070734016607712'>🌙</tg-emoji>" if b["language"] == "ar" else ("<tg-emoji emoji-id='5472411062412254753'>📖</tg-emoji>" if b["language"] == "ku" else "<tg-emoji emoji-id='5399898266265475100'>🌍</tg-emoji>")
            prog = prog_map.get(b["id"], 1)   # <tg-emoji emoji-id='5857044938755149915'>✅</tg-emoji> لە map — بەبێ کوئێری زیادە
            lbl  = f"{flag} {b['title']}"
            if b["total_pages"] > 1:
                lbl += f"  ·  پ {prog}/{b['total_pages']}"
            btn = _ebtn(lbl, f"bk_read:{b['id']}:{prog}", emoji_id=_BK_E_BOOK,
                        api_kwargs={"style": "primary"})
            if i % 2 == 0:
                btns.append([btn])
            else:
                btns[-1].append(btn)

    # ناڤیگەیشن
    nav = []
    if page > 0:
        nav.append(_ebtn("پێشتر", f"bk_list:{page-1}", emoji_id=_BK_E_PREV,
                         api_kwargs={"style": "primary"}))
    if page < total_pages - 1:
        nav.append(_ebtn("دواتر", f"bk_list:{page+1}", emoji_id=_BK_E_NEXT,
                         api_kwargs={"style": "primary"}))
    if nav:
        btns.append(nav)

    # هەموو میمبەرەکان دەتوانن کتێب زیاد بکەن
    btns.append([_ebtn("زیادکردنی کتێب", "bk_add", emoji_id=_BK_E_ADD,
                       api_kwargs={"style": "success"})])

    btns.append([_ebtn("گەڕانەوە", "menu:islamic", emoji_id=_BK_E_BACK,
                       api_kwargs={"style": "primary"})])
    return text, InlineKeyboardMarkup(btns)


def _bk_fmt_display(txt: str) -> str:
    """
    تێکستی پاشەکەوتراو (کتێبی کۆن یان نوێ) پێش پیشاندان فۆرمات دەکات.
    هێڵە بڕاوەکانی PDF یەکدەکاتەوە — پاراگرافی ڕووناک و خوێندنەوەی ئاسانتر.
    """
    # هەر block ی جیاکراو بە \n\n → هێڵەکانی ناوەکەی یەکدەکاتەوە بە _bk_merge_lines
    all_lines: list[str] = []
    for block in re.split(r'\n{2,}', txt.strip()):
        block_lines = [l.strip() for l in block.split('\n') if l.strip()]
        if not block_lines:
            continue
        merged = _bk_merge_lines(block_lines)
        all_lines.extend(merged)
        all_lines.append("")   # جیاکەری پاراگراف

    paras = [l for l in all_lines if l]
    return "\n\n".join(paras) if paras else txt.strip()


def _bk_build_reader(book_id: int, page_num: int, user_id: int,
                     trans_text: str = "", trans_on: bool = False) -> tuple:
    """پەڕەی خوێندنەوە دروست دەکات."""
    with _bk_db() as c:
        book = c.execute(
            "SELECT title, author, language, total_pages FROM books WHERE id=?",
            (book_id,)
        ).fetchone()

    if not book:
        return "<tg-emoji emoji-id='6271611232457855630'>❌</tg-emoji> کتێبەکە نەدۆزرایەوە.", InlineKeyboardMarkup([])

    total    = book["total_pages"]
    page_num = max(1, min(page_num, total))

    with _bk_db() as c:
        pg_row = c.execute(
            "SELECT text FROM book_pages WHERE book_id=? AND page_num=?",
            (book_id, page_num)
        ).fetchone()
    txt     = pg_row["text"] if pg_row else "—"
    txt     = _bk_fmt_display(txt)   # ← فۆرماتی جوانتر بۆ هەم کتێبی کۆن هەم نوێ
    flag    = "<tg-emoji emoji-id='5231070734016607712'>🌙</tg-emoji>" if book["language"] == "ar" else ("<tg-emoji emoji-id='5472411062412254753'>📖</tg-emoji>" if book["language"] == "ku" else "<tg-emoji emoji-id='5399898266265475100'>🌍</tg-emoji>")
    title_s = (book["title"][:28] + "…") if len(book["title"]) > 30 else book["title"]
    auth_s  = (book["author"][:20] + "…") if len(book["author"]) > 22 else book["author"]

    body = ("\u200F" if book["language"] in ("ar", "ku") else "") + html.escape(txt)

    # ✅ FIX: کاتێک وەرگێڕان چالاکە — تەنها کوردیەکە نیشان بدە، تێکستی سەرەوە بشارەوە
    if trans_text and trans_on:
        text_msg = (
            f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji> {flag} '
            f'<b>{html.escape(title_s)}</b>\n'
            f'<i>{html.escape(auth_s)}</i>  ·  '
            f'پەڕەی <b>{page_num}</b> لە <b>{total}</b>\n'
            f'⊱━━━━━<tg-emoji emoji-id="{_BK_E_STAR}">⭐</tg-emoji>━━━━━⊰\n\n'
            f'\u200F{html.escape(trans_text)}\n\n'
            f'⊱━━━━━<tg-emoji emoji-id="{_BK_E_STAR}">⭐</tg-emoji>━━━━━⊰'
        )
    else:
        text_msg = (
            f'<tg-emoji emoji-id="{_BK_E_BOOK}">📖</tg-emoji> {flag} '
            f'<b>{html.escape(title_s)}</b>\n'
            f'<i>{html.escape(auth_s)}</i>  ·  '
            f'پەڕەی <b>{page_num}</b> لە <b>{total}</b>\n'
            f'⊱━━━━━<tg-emoji emoji-id="{_BK_E_STAR}">⭐</tg-emoji>━━━━━⊰\n\n'
            f'{body}\n\n'
            f'⊱━━━━━<tg-emoji emoji-id="{_BK_E_STAR}">⭐</tg-emoji>━━━━━⊰'
        )

    # ناڤیگەیشن
    nav = []
    if page_num > 1:
        nav.append(_ebtn("پێشتر", f"bk_read:{book_id}:{page_num-1}",
                         emoji_id=_BK_E_PREV, api_kwargs={"style": "primary"}))
    nav.append(_ebtn(f"{page_num}/{total}", "bk_noop",
                     emoji_id=_BK_E_BKMK, api_kwargs={"style": "primary"}))
    if page_num < total:
        nav.append(_ebtn("دواتر", f"bk_read:{book_id}:{page_num+1}",
                         emoji_id=_BK_E_NEXT, api_kwargs={"style": "primary"}))

    jump = []
    if page_num > 1:
        jump.append(_ebtn("⏮ یەکەم", f"bk_read:{book_id}:1",
                          emoji_id=_BK_E_PREV, api_kwargs={"style": "primary"}))
    if page_num < total:
        jump.append(_ebtn("⏭ کۆتا", f"bk_read:{book_id}:{total}",
                          emoji_id=_BK_E_NEXT, api_kwargs={"style": "primary"}))

    rows = [nav]
    if jump:
        rows.append(jump)

    # ── دووگمەی وەرگێڕان — بۆ هەر زمانێک جگە لە کوردی ─────────────────────
    if book["language"] not in ("ku", "ckb"):
        _trans_lbl_on  = "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> کوژاندنەوەی وەرگێڕان"
        _TRANS_NAMES = {
            "ar": "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> وەرگێڕانی کوردی (عەرەبی)",
            "en": "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> وەرگێڕانی کوردی (ئینگلیزی)",
            "fa": "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> وەرگێڕانی کوردی (فارسی)",
            "tr": "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> وەرگێڕانی کوردی (تورکی)",
            "ur": "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> وەرگێڕانی کوردی (ئوردو)",
        }
        _trans_lbl_off = _TRANS_NAMES.get(
            book["language"],
            f"<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> وەرگێڕانی کوردی ({book['language'].upper()})"
        )
        if trans_on:
            rows.append([_ebtn(
                _trans_lbl_on,
                f"bk_trans:off:{book_id}:{page_num}",
                emoji_id="5395758123950576680",
                api_kwargs={"style": "primary"},
            )])
        else:
            rows.append([_ebtn(
                _trans_lbl_off,
                f"bk_trans:on:{book_id}:{page_num}",
                emoji_id="5395758123950576680",
                api_kwargs={"style": "success"},
            )])

    bottom = [_ebtn("لیستی کتێب", "bk_list:0", emoji_id=_BK_E_LIST,
                    api_kwargs={"style": "primary"})]
    if user_id == OWNER_ID:
        bottom.append(_ebtn("سڕینەوە", f"bk_del_confirm:{book_id}",
                            emoji_id=_BK_E_DEL, api_kwargs={"style": "danger"}))
    rows.append(bottom)
    return text_msg, InlineKeyboardMarkup(rows)


async def _bk_list_callback(query, context):
    """نیشاندانی لیستی کتێبەکان."""
    parts = query.data.split(":")
    # FIX [BUG-BK2]: کاتێک لە islamic:books دەیخوێنرێتەوە parts[1]="books" دەبێت
    # int("books") crash دەکات → try/except پارێزراوە
    try:
        page = int(parts[1]) if len(parts) > 1 else 0
    except (ValueError, IndexError):
        page = 0
    user_id = query.from_user.id
    loop    = asyncio.get_running_loop()
    # ✅ FIX: sync SQLite blocking لە executor دەکرێت
    text, kb = await loop.run_in_executor(None, _bk_build_list, page, user_id)
    await _safe_edit(query, text, reply_markup=kb)


async def _bk_read_callback(query, context):
    """نیشاندانی پەڕەی کتێب."""
    parts = query.data.split(":")
    if len(parts) != 3:
        await query.answer("⚠️ داتای خراپ", show_alert=True)
        return
    try:
        book_id, page_num = int(parts[1]), int(parts[2])
    except ValueError:
        await query.answer("⚠️ ژمارەی خراپ", show_alert=True)
        return
    user_id = query.from_user.id
    loop    = asyncio.get_running_loop()
    await loop.run_in_executor(None, _bk_save_progress, user_id, book_id, page_num)

    # ── وەرگێڕان چالاکە؟ ──
    trans_on  = book_id in _BK_TRANS_ON.get(user_id, set())
    trans_text = ""
    if trans_on:
        # cache بپشکنە — ئەگەر نەبوو وەرگێڕ
        cache_key = (book_id, page_num)
        if cache_key in _BK_TRANS_CACHE:
            trans_text = _BK_TRANS_CACHE[cache_key]
        else:
            # پیامی چاوەڕوانی بنێرە
            try:
                await query.answer(
                    "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> وەرگێڕان دەکرێت…", show_alert=False
                )
            except Exception:
                pass
            # تێکستی پەڕە بخوێنەوە (sync)
            def _get_page_text():
                with _bk_db() as c:
                    row = c.execute(
                        "SELECT text FROM book_pages WHERE book_id=? AND page_num=?",
                        (book_id, page_num)
                    ).fetchone()
                return row["text"] if row else ""
            raw_text = await loop.run_in_executor(None, _get_page_text)
            if raw_text:
                # زمانی کتێب دۆزە بکەوە بۆ وەرگێڕانی ڕاست
                def _get_book_lang():
                    with _bk_db() as _c:
                        _r = _c.execute(
                            "SELECT language FROM books WHERE id=?", (book_id,)
                        ).fetchone()
                    return _r["language"] if _r else "en"
                _bk_src_lang = await loop.run_in_executor(None, _get_book_lang)
                trans_text = await _bk_translate_page(
                    book_id, page_num, raw_text, src_lang=_bk_src_lang
                )

    text, kb = await loop.run_in_executor(
        None, _bk_build_reader, book_id, page_num, user_id, trans_text, trans_on
    )
    await _safe_edit(query, text, reply_markup=kb)


async def _bk_trans_callback(query, context):
    """
    دووگمەی وەرگێڕانی کوردی — چالاک/ناچالاک کردن.
    data: bk_trans:on:{book_id}:{page_num}  یان  bk_trans:off:{book_id}:{page_num}
    """
    parts = query.data.split(":")
    if len(parts) != 4:
        await query.answer("⚠️ داتای خراپ", show_alert=True)
        return
    try:
        action   = parts[1]                  # "on" یان "off"
        book_id  = int(parts[2])
        page_num = int(parts[3])
    except (ValueError, IndexError):
        await query.answer("⚠️ داتای خراپ", show_alert=True)
        return

    user_id = query.from_user.id
    loop    = asyncio.get_running_loop()

    if user_id not in _BK_TRANS_ON:
        _BK_TRANS_ON[user_id] = set()

    if action == "on":
        _BK_TRANS_ON[user_id].add(book_id)
        # وەرگێڕان فەوری بکە — پیامی چاوەڕوانی
        try:
            await query.answer("🌐 وەرگێڕان دەکرێت…", show_alert=False)
        except Exception:
            pass
        # پەڕەی ئێستا وەرگێڕ
        cache_key = (book_id, page_num)
        if cache_key not in _BK_TRANS_CACHE:
            def _get_txt():
                with _bk_db() as _c2:
                    r = _c2.execute(
                        "SELECT text FROM book_pages WHERE book_id=? AND page_num=?",
                        (book_id, page_num)
                    ).fetchone()
                return r["text"] if r else ""
            def _get_lang():
                with _bk_db() as _c3:
                    _rl = _c3.execute(
                        "SELECT language FROM books WHERE id=?", (book_id,)
                    ).fetchone()
                return _rl["language"] if _rl else "en"
            raw  = await loop.run_in_executor(None, _get_txt)
            _sl  = await loop.run_in_executor(None, _get_lang)
            if raw:
                await _bk_translate_page(book_id, page_num, raw, src_lang=_sl)
        trans_text = _BK_TRANS_CACHE.get(cache_key, "")
    else:
        _BK_TRANS_ON[user_id].discard(book_id)
        trans_text = ""

    await loop.run_in_executor(None, _bk_save_progress, user_id, book_id, page_num)
    text, kb = await loop.run_in_executor(
        None, _bk_build_reader, book_id, page_num, user_id, trans_text, action == "on"
    )
    await _safe_edit(query, text, reply_markup=kb)


