async def _nasa_mars_callback(query, context):
    """دوایین وێنەکانی رۆڤەرەکانی مریخ — v2: چەندین فۆڵبەک + safe JSON"""
    _back_kb = InlineKeyboardMarkup([
        [_ebtn("وێنەیەکی تر",  "nasa:mars",
               api_kwargs={"style": "primary"}),
         _ebtn("ناسا", "science:nasa_hub", emoji_id="5195033767969839232",
               api_kwargs={"style": "primary"})],
        [_ebtn("گەڕانەوە", "menu:science", emoji_id="5352759161945867747",
               api_kwargs={"style": "primary"})],
    ])

    # ── رۆڤەر و sol ی دانراو ─── ⋆⋅☆⋅⋆ ───
    # (rover, sol_min, sol_max) — sol ی دانراوی زیاتر وێنەی دروستیان هەیە
    _ROVER_RANGES = [
        ("curiosity",     500, 3000),
        ("perseverance",  100, 1200),
        ("curiosity",     100,  499),   # فۆڵبەک ١
        ("perseverance",   10,   99),   # فۆڵبەک ٢
    ]
    _API_KEYS = [NASA_API_KEY, "DEMO_KEY"]

    async def _fetch_mars_photos(rover: str, sol: int, api_key: str):
        """وەرگرتنی وێنەکان — safe JSON parse + status check"""
        _url    = f"https://api.nasa.gov/mars-photos/api/v1/rovers/{rover}/photos"
        _params = {"sol": sol, "api_key": api_key, "page": 1}
        try:
            _resp = (
                await _httpx_get(_url, params=_params, timeout=14)
                if httpx else
                await asyncio.get_running_loop().run_in_executor(
                    _THREAD_POOL, lambda: requests.get(_url, params=_params, timeout=14))
            )
            if _resp.status_code == 429:
                logger.warning("NASA Mars rate-limited (429) key=%s", api_key[:8])
                return []
            if _resp.status_code != 200:
                logger.warning("NASA Mars HTTP %s rover=%s sol=%s", _resp.status_code, rover, sol)
                return []
            # safe JSON — هۆکاری سەرەکی کێشەی کۆنەکە
            _raw = _resp.text.strip() if hasattr(_resp, "text") else _resp.content.decode("utf-8", errors="replace").strip()
            if not _raw:
                logger.warning("NASA Mars empty body rover=%s sol=%s key=%s", rover, sol, api_key[:8])
                return []
            try:
                _data = json.loads(_raw)
            except Exception as _je:
                logger.warning("NASA Mars JSON parse fail: %s | body[:80]=%s", _je, _raw[:80])
                return []
            return _data.get("photos", [])
        except Exception as _e:
            logger.warning("NASA Mars fetch error rover=%s sol=%s: %s", rover, sol, _e)
            return []

    # ── هەوڵدانی پلەبەپلە ─── ⋆⋅☆⋅⋆ ───
    _photos = []
    for _rover, _smin, _smax in _ROVER_RANGES:
        if _photos:
            break
        _sol = random.randint(_smin, _smax)
        for _key in _API_KEYS:
            _photos = await _fetch_mars_photos(_rover, _sol, _key)
            if _photos:
                break

    if not _photos:
        await _safe_edit(query,
            "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji>"
            " هیچ وێنەیەک نەدۆزرایەوە. تکایە چەند خولەکێک دواتر هەوڵ بدەوە.",
            reply_markup=_back_kb)
        return

    # ── پیشاندانی وێنە ─── ⋆⋅☆⋅⋆ ───
    try:
        _photo      = random.choice(_photos[:25])
        _img_url    = _photo.get("img_src", "")
        _camera     = _photo.get("camera", {}).get("full_name", "نەزانراو")
        _earth_date = _photo.get("earth_date", "")
        _sol_used   = _photo.get("sol", _sol)
        _rover_name = _photo.get("rover", {}).get("name", _rover.capitalize())

        _txt = (
            "<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> <b>وێنەی مریخ — NASA Mars Rover</b>\n"
            "⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n\n"
            f"<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> <b>رۆڤەر:</b> {html.escape(_rover_name)}\n"
            f"<tg-emoji emoji-id=\"5438648530656860878\">📷</tg-emoji> <b>کامێرا:</b> {html.escape(_camera)}\n"
            f"<tg-emoji emoji-id=\"6032875887626556562\">🪐</tg-emoji> <b>سۆل:</b> {_sol_used}  |  "
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>بەروار:</b> {_earth_date}"
        )
        try:
            await query.message.delete()
        except Exception:
            pass

        # ⚡ ناردنی پاراستوو بە helper ـی هاوبەش
        success = await _nasa_send_image_safe(
            context=context,
            chat_id=query.message.chat.id,
            image_urls=[_img_url],
            caption=_txt,
            reply_markup=_back_kb,
            label="Mars",
        )

        if not success:
            # fallback بۆ تێکست + لینک
            await context.bot.send_message(
                chat_id=query.message.chat.id,
                text=_txt + f"\n\n<tg-emoji emoji-id=\"5893232439110668588\">🖼</tg-emoji> <a href='{html.escape(_img_url)}'>کردنەوەی وێنەکە</a>",
                parse_mode="HTML",
                reply_markup=_back_kb,
                disable_web_page_preview=False,
            )
    except Exception as _e:
        logger.error("NASA Mars display: %s", _e)
        await _safe_edit(query,
            "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji>"
            " هەڵەیەک ڕوویدا لە پیشاندانی وێنەی مریخ.",
            reply_markup=_back_kb)


async def _nasa_epic_callback(query, context):
    """وێنەی زەوی لە EPIC satellite"""
    _back_kb = InlineKeyboardMarkup([
        [_ebtn("وێنەیەکی تر",  "nasa:epic",
               api_kwargs={"style": "primary"}),
         _ebtn("ناسا", "science:nasa_hub", emoji_id="5195033767969839232",
               api_kwargs={"style": "primary"})],
        [_ebtn("گەڕانەوە", "menu:science", emoji_id="5352759161945867747",
               api_kwargs={"style": "primary"})],
    ])
    try:
        _resp = (
            await _httpx_get("https://api.nasa.gov/EPIC/api/natural",
                             params={"api_key": NASA_API_KEY}, timeout=12)
            if httpx else
            await asyncio.get_running_loop().run_in_executor(
                _THREAD_POOL,
                lambda: requests.get("https://api.nasa.gov/EPIC/api/natural",
                                     params={"api_key": NASA_API_KEY}, timeout=12))
        )
        _items = _resp.json()
        if not _items or not isinstance(_items, list):
            raise ValueError("بۆ داتای EPIC")

        _item     = random.choice(_items[:10])
        _img_name = _item.get("image", "")
        _caption_ = _item.get("caption", "")
        _date_str = _item.get("date", "")[:10]
        _year, _month, _day = (_date_str.split("-") + ["","",""])[:3]
        _img_url  = (
            f"https://epic.gsfc.nasa.gov/archive/natural"
            f"/{_year}/{_month}/{_day}/png/{_img_name}.png"
        )
        _txt = (
            "<tg-emoji emoji-id=\"5399898266265475100\">🌍</tg-emoji> <b>زەوی لە چاوی EPIC — NASA DSCOVR</b>\n"
            "⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n\n"
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>بەروار:</b> {_date_str}\n"
            f"<tg-emoji emoji-id=\"5472411062412254753\">📖</tg-emoji>"
            f" {html.escape(_caption_[:300])}"
        )
        try:
            await query.message.delete()
        except Exception:
            pass

        # ⚡ ناردنی پاراستوو
        success = await _nasa_send_image_safe(
            context=context,
            chat_id=query.message.chat.id,
            image_urls=[_img_url],
            caption=_txt,
            reply_markup=_back_kb,
            label="EPIC",
        )

        if not success:
            await context.bot.send_message(
                chat_id=query.message.chat.id,
                text=_txt + f"\n\n<tg-emoji emoji-id=\"5893232439110668588\">🖼</tg-emoji> <a href='{html.escape(_img_url)}'>کردنەوەی وێنەکە</a>",
                parse_mode="HTML",
                reply_markup=_back_kb,
                disable_web_page_preview=False,
            )
    except Exception as _e:
        logger.error("NASA EPIC: %s", _e)
        await _safe_edit(query,
            "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji>"
            " هەڵەیەک ڕوویدا لە وەرگرتنی وێنەی EPIC.",
            reply_markup=_back_kb)


async def _nasa_neo_callback(query, context):
    """ئەستیرۆیدەکانی نزیک بە زەوی — NASA Near-Earth Objects"""
    _back_kb = InlineKeyboardMarkup([
        [_ebtn("نوێکردنەوە", "nasa:neo",
               emoji_id="5353025084845994828",
               api_kwargs={"style": "primary"}),
         _ebtn("ناسا", "science:nasa_hub", emoji_id="5195033767969839232",
               api_kwargs={"style": "primary"})],
        [_ebtn("گەڕانەوە", "menu:science", emoji_id="5352759161945867747",
               api_kwargs={"style": "primary"})],
    ])
    try:
        import datetime as _dt
        _today  = _dt.date.today().isoformat()
        _params = {"start_date": _today, "end_date": _today, "api_key": NASA_API_KEY}
        _resp = (
            await _httpx_get("https://api.nasa.gov/neo/rest/v1/feed",
                             params=_params, timeout=15)
            if httpx else
            await asyncio.get_running_loop().run_in_executor(
                _THREAD_POOL,
                lambda: requests.get("https://api.nasa.gov/neo/rest/v1/feed",
                                     params=_params, timeout=15))
        )
        _data = _resp.json()
        _neos = _data.get("near_earth_objects", {}).get(_today, [])

        if not _neos:
            await _safe_edit(query,
                "<tg-emoji emoji-id=\"5940434198413184876\">☄️</tg-emoji> هیچ ئەستیرۆیدێکی تۆمارکراو نییە بۆ ئەمڕۆ. دواتر هەوڵ بدەوە.",
                reply_markup=_back_kb)
            return

        _sorted = sorted(
            _neos,
            key=lambda x: float(
                x.get("close_approach_data", [{}])[0]
                 .get("miss_distance", {}).get("kilometers", "1e20")
            )
        )
        _total = _data.get("element_count", len(_neos))
        _txt = (
            "<tg-emoji emoji-id=\"5940434198413184876\">☄️</tg-emoji> <b>ئەستیرۆیدەکانی نزیک بە زەوی — ئەمڕۆ</b>\n"
            "⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n"
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>بەروار:</b> {_today}  |  "
            f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji>"
            f" <b>کۆی گشتی:</b> {_total} ئەستیرۆید\n\n"
        )
        for _i, _neo in enumerate(_sorted[:6], 1):
            _name     = html.escape(_neo.get("name", "نەزانراو"))
            _haz      = _neo.get("is_potentially_hazardous_asteroid", False)
            _haz_icon = "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> خەتەرناک" if _haz else "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> بێزیان"
            _diam     = _neo.get("estimated_diameter", {}).get("meters", {})
            _d_min    = _diam.get("estimated_diameter_min", 0)
            _d_max    = _diam.get("estimated_diameter_max", 0)
            _approach = _neo.get("close_approach_data", [{}])[0]
            _miss_km  = float(_approach.get("miss_distance", {}).get("kilometers", 0))
            _vel_kph  = float(_approach.get("relative_velocity", {}).get("kilometers_per_hour", 0))
            _txt += (
                f"<b>{_i}. {_name}</b>  {_haz_icon}\n"
                f"   <tg-emoji emoji-id=\"5438569421654234414\">📐</tg-emoji> قەبارە: {_d_min:.0f} – {_d_max:.0f} m\n"
                f"   <tg-emoji emoji-id=\"5375510007439711210\">📏</tg-emoji> دووری نزیکترین: {_miss_km:,.0f} km\n"
                f"   <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> خێرایی: {_vel_kph:,.0f} km/h\n\n"
            )
        await _safe_edit(query, _txt.rstrip(), reply_markup=_back_kb)
    except Exception as _e:
        logger.error("NASA NEO: %s", _e)
        await _safe_edit(query,
            "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji>"
            " هەڵەیەک ڕوویدا لە وەرگرتنی زانیارییەکانی ئەستیرۆید.",
            reply_markup=_back_kb)


async def _iss_quick_callback(query, context):
    """شوێن و زانیاری ISS"""
    _back_kb = InlineKeyboardMarkup([
        [_ebtn("نوێکردنەوە", "nasa:iss_quick",
               emoji_id="5353025084845994828",
               api_kwargs={"style": "primary"}),
         _ebtn("ناسا", "science:nasa_hub", emoji_id="5195033767969839232",
               api_kwargs={"style": "primary"})],
        [_ebtn("گەڕانەوە", "menu:science", emoji_id="5352759161945867747",
               api_kwargs={"style": "primary"})],
    ])
    try:
        _loc_resp = (
            await _httpx_get("http://api.open-notify.org/iss-now.json", timeout=8)
            if httpx else
            await asyncio.get_running_loop().run_in_executor(
                _THREAD_POOL,
                lambda: requests.get("http://api.open-notify.org/iss-now.json", timeout=8))
        )
        _loc  = _loc_resp.json()
        _lat  = float(_loc["iss_position"]["latitude"])
        _lon  = float(_loc["iss_position"]["longitude"])

        _crew_resp = (
            await _httpx_get("http://api.open-notify.org/astros.json", timeout=8)
            if httpx else
            await asyncio.get_running_loop().run_in_executor(
                _THREAD_POOL,
                lambda: requests.get("http://api.open-notify.org/astros.json", timeout=8))
        )
        _iss_crew = [
            p["name"] for p in _crew_resp.json().get("people", [])
            if p.get("craft") == "ISS"
        ]

        _lat_dir  = "N" if _lat >= 0 else "S"
        _lon_dir  = "E" if _lon >= 0 else "W"
        _crew_txt = "\n".join(f"   • {html.escape(n)}" for n in _iss_crew)                     if _iss_crew else "   زانیاری نییە"

        _txt = (
            "<tg-emoji emoji-id=\"5379712035938407997\">🛸</tg-emoji> <b>ئیستگای فەزایی نێودەوڵەتی — ISS Tracker</b>\n"
            "⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n\n"
            f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> <b>شوێنی ئێستا:</b>\n"
            f"   <tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> Lat: {abs(_lat):.4f}° {_lat_dir}  |  "
            f"Lon: {abs(_lon):.4f}° {_lon_dir}\n\n"
            f"<tg-emoji emoji-id=\"5355115844860931955\">🏔</tg-emoji> <b>بەرزی:</b> ~408 km  |  <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> <b>خێرایی:</b> ~27,600 km/h\n"
            f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> <b>دووری دەوری:</b> هەر 92 خولەک\n\n"
            f"👨‍<tg-emoji emoji-id=\"5195033767969839232\">🚀</tg-emoji> <b>خەڵکی ئێستای ISS</b> ({len(_iss_crew)} کەس):\n"
            f"{_crew_txt}\n\n"
            f"<tg-emoji emoji-id=\"5231263977480144467\">🗺</tg-emoji>️ <a href='https://www.google.com/maps?q={_lat},{_lon}&z=3'>"
            "سەیری شوێن لە نەخشەدا بکە</a>"
        )
        await _safe_edit(query, _txt, reply_markup=_back_kb)
    except Exception as _e:
        logger.error("ISS Tracker: %s", _e)
        _txt_fb = (
            "<tg-emoji emoji-id=\"5379712035938407997\">🛸</tg-emoji> <b>ISS — زانیاری بنەڕەتی</b>\n⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n\n"
            "<tg-emoji emoji-id=\"5355115844860931955\">🏔</tg-emoji> بەرزی: ~408 km  |  <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> خێرایی: ~27,600 km/h\n"
            "<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> هەر 92 خولەک یەک دووری دەوری زەوی\n"
            "<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> دامەزراندن: نۆڤەمبەر 1998\n"
            "<i>(سێرڤەری شوێننیشاندەر ئێستا بەردەست نییە)</i>"
        )
        await _safe_edit(query, _txt_fb, reply_markup=_back_kb)


