def _planet_prev(pname: str) -> str:
    _order = ["mercury","venus","earth","mars","jupiter","saturn","uranus","neptune"]
    _i = _order.index(pname) if pname in _order else 0
    return _order[(_i - 1) % len(_order)]


def _planet_next(pname: str) -> str:
    _order = ["mercury","venus","earth","mars","jupiter","saturn","uranus","neptune"]
    _i = _order.index(pname) if pname in _order else 0
    return _order[(_i + 1) % len(_order)]


async def planet_detail_callback(update: Update, context: CallbackContext):
    """زانیاری تەواوی گەرەیرە — planet:<n>"""
    query    = update.callback_query
    answered = _make_answerer(query)
    await answered()

    _pname = query.data.split(":", 1)[1] if ":" in query.data else "mars"
    _pdata = PLANET_DATA_V2.get(_pname, PLANET_DATA_V2["mars"])

    _kb = [
        [_ebtn("گەرەیرەی پێشتر", f"planet:{_planet_prev(_pname)}",
               emoji_id="5456187398977247949", api_kwargs={"style": "primary"}),
         _ebtn("گەرەیرەی دواتر", f"planet:{_planet_next(_pname)}",
               api_kwargs={"style": "primary", "icon_custom_emoji_id": "5341583133055669788"})],
        [_ebtn("لیستی گەرەیرەکان", "science:planets",
               api_kwargs={"style": "primary"})],
        [_ebtn("گەڕانەوە", "menu:science", emoji_id="5352759161945867747",
               api_kwargs={"style": "primary"})],
    ]

    _labels_map = {
        "distance_sun_km": "<tg-emoji emoji-id=\"5201827869361188827\">☀</tg-emoji>️ دووری لە خۆر",
        "diameter_km":     "<tg-emoji emoji-id=\"5438569421654234414\">📐</tg-emoji> قەبارە (دایامیتر)",
        "moons":           "<tg-emoji emoji-id=\"5415765090932641459\">🌙</tg-emoji> ژمارەی مانگ",
        "orbital_period":  "<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> سالانی دووری",
        "day_length":      "<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji>️ درێژایی ڕۆژ",
        "gravity":         "<tg-emoji emoji-id=\"5400250414929041085\">⚖️</tg-emoji> گرانی",
        "temp_max":        "<tg-emoji emoji-id=\"5395463497783983254\">🌡</tg-emoji>️ گەرمای زیاترین",
        "temp_min":        "<tg-emoji emoji-id=\"5395463497783983254\">🌡</tg-emoji>️ گەرمای کەمترین",
        "temp_avg":        "<tg-emoji emoji-id=\"5395463497783983254\">🌡</tg-emoji>️ گەرمای مامناوەند",
        "atmo":            "<tg-emoji emoji-id=\"5379686360623913052\">💨</tg-emoji> هوای ئازمێن",
    }
    _extras = ""
    for _k, _v in _pdata.items():
        if _k in ("ku_name","order","facts","type"):
            continue
        _lbl = _labels_map.get(_k, _k)
        _extras += f"{_lbl}: <b>{html.escape(str(_v))}</b>\n"

    _facts_txt = "\n".join(f"   • {f}" for f in _pdata["facts"])
    _txt = (
        f"<tg-emoji emoji-id=\"6032875887626556562\">🪐</tg-emoji> <b>{_pdata['ku_name']}</b>\n"   # FIX v42: html.escape() دەسڕێنرێوە — ku_name خۆی HTML پێشکەش دەکات
        f"<i>({html.escape(_pdata['type'])}  |  هەمار {_pdata['order']} لە سیستەمی خۆردا)</i>\n"
        "⊱━━━━━<tg-emoji emoji-id=\"5379553354076694057\">⭐</tg-emoji>━━━━━⊰\n\n"
        f"{_extras}\n"
        f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> <b>تایبەتمەندییە گرنگەکان:</b>\n{_facts_txt}"
    )
    await _safe_edit(query, _txt, reply_markup=InlineKeyboardMarkup(_kb))


