async def _handle_submenu_house_buy(query, action, context, answered):
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: مامەڵەکردنی کڕینی خانوو لە economy:house کلیک
    HOUSES = {
        "house_basic":   ("<tg-emoji emoji-id=\"5228909012552000246\">🏠</tg-emoji> خانووی سادە",  1000,  5),
        "house_mid":     ("<tg-emoji emoji-id=\"5197708768091061888\">🏡</tg-emoji> خانووی ناوەند", 5000,  10),
        "house_castle":  ("<tg-emoji emoji-id=\"5330116450843636190\">🏰</tg-emoji> کۆشک",         15000, 20),
    }
    h_id   = action
    h_info = HOUSES.get(h_id)
    uid    = query.from_user.id
    ud     = get_user_data(uid)
    if not h_info:
        await answered("❌" + " خانووەکە نەدۆزرایەوە!", show_alert=True); return
    h_name, h_price, h_xp = h_info
    if ud.get("house") == h_id:
        await answered("✅ ئەم خانووە پێشتر هەیتە!", show_alert=True); return
    coins = ud.get("coins", 0)
    if coins < h_price:
        await answered(f"❌ کۆینت بەس نییە! پێویستت بە {h_price:,}🪙، بەڵام تەنها {coins:,}🪙ت هەیە.", show_alert=True); return
    add_coins(uid, -h_price, "house", h_name)
    ud["house"] = h_id
    save_users()
    await answered(f"✅ {h_name}ت کڕی! +{h_xp}٪ XP Bonus چالاک بوو!", show_alert=True)
    try:
        await house_callback(query, context)
    except Exception as _exc:
        logger.debug("Suppressed Exception: %s", _exc)

