# ── _SUBMENU_DISPATCH: router بۆ هەموو submenu handler فانکشنەکان ──
_SUBMENU_DISPATCH: dict = {
    "weather":    _handle_submenu_weather,
    "news":       _handle_submenu_news,
    "profile":    _handle_submenu_profile,
    "tools":      _handle_submenu_tools,
    "islamic":    _handle_submenu_islamic,
    "nasa":       _handle_submenu_nasa,
    "science":    _handle_submenu_science,
    "economy":    _handle_submenu_economy,
    "house_buy":  _handle_submenu_house_buy,
    "game":       _handle_submenu_game,
    "debate":     _handle_submenu_debate,
    "ai":         _handle_submenu_ai,
    "admin":      _handle_submenu_admin,
}

async def submenu_callback(update: Update, context: CallbackContext):
    """
    <tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> Submenu dispatcher — هەر menu_type بۆ handler فانکشنی تایبەتی خۆی دەنێردرێت.
    بشکێنراوە لە 11 handler فانکشن بۆ نگەداشتی ئاسانتر.
    """
    try:
        query = update.callback_query
        answered = _make_answerer(query)

        data  = query.data
        parts = data.split(":")
        menu_type = parts[0]
        action    = parts[1] if len(parts) > 1 else ""

        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> O(1) dispatch — dispatch table پێش if/elif
        _simple = _SUBMENU_SIMPLE.get((menu_type, action))
        if _simple is not None:
            await answered()
            await _dismiss_menu(query)
            await _simple(query, context)
            return

        # debate/ai/admin پەیامەکەی خۆی بەرێوەدەبات (_safe_edit) — _dismiss_menu نەخوێنێتەوە
        await answered()
        if menu_type not in ("debate", "ai", "admin"):
            await _dismiss_menu(query)

        # ── Dispatch بۆ handler فانکشنی تایبەت ──
        _handler = _SUBMENU_DISPATCH.get(menu_type)
        if _handler is not None:
            await _handler(query, action, context, answered)
        else:
            logger.debug(f"submenu_callback: menu_type نەزانراو: {menu_type!r}")

    except Exception as e:
        logger.error(f"Error in submenu_callback: {e}")
        try:
            if hasattr(query, "answer"):
                await query.answer()
        except Exception as _qa_e:
            logger.debug("query.answer() suppressed (intentional): %s", _qa_e)

