async def note(update: Update, context: CallbackContext):
    user_id = update.message.from_user.id
    text = " ".join(context.args)
    
    if not text:
        await update.message.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> شێواز: <code>/note [تێبینییەکەت لێرە بنووسە]</code>", parse_mode="HTML")
        return
    
    chat_id = str(update.effective_chat.id)
    if chat_id not in NOTES:
        NOTES[chat_id] = {}
    
    note_id = len(NOTES[chat_id].get(str(user_id), [])) + 1
    NOTES[chat_id].setdefault(str(user_id), []).append({
        "id": note_id,
        "text": text,
        "timestamp": datetime.datetime.now().isoformat()
    })
    save_notes()
    await update.message.reply_text(f"{_TCK} تێبینییەکەت بە سەرکەوتوویی پاشەکەوت کرا.", parse_mode="HTML")

