async def get_weather(update, context, city: str, edit: bool = False):
    data = await _fetch_weather(city)
    if data is None:
        err = _TGX + " ببورە، کێشەیەک لە وەرگرتنی داتا هەیە."
        if edit:
            try: await update.edit_message_text(err, parse_mode='HTML')  # {_TCK} FIX: wrapped
            except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc, parse_mode="HTML")
        elif hasattr(update, "message") and update.message:
            await update.message.reply_text(err, parse_mode='HTML')
        else:
            try: await update.edit_message_text(err, parse_mode='HTML')  # {_TCK} FIX: wrapped
            except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc, parse_mode="HTML")
        return

    city_safe = city[:48]   # ── FIX #1: بڕکردنی city — "wx:forecast:" (12) + 48 = 60 < 64 limit ──
    text = _build_current(data, city_safe)
    kb   = _wx_kb(city_safe)
    try:
        if edit:
            await update.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        elif hasattr(update, "message") and update.message:
            await update.message.reply_text(text, parse_mode="HTML", reply_markup=kb)
        else:
            await update.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
    except Exception as e:
        logger.error("Weather display error: %s", e)
        # ── FIX v22: Fallback بەبێ HTML — ئەگەر parse_mode هەڵە دا ──
        try:
            import re as _re
            plain = _re.sub(r'<[^>]+>', '', text)
            if hasattr(update, "message") and update.message:
                await update.message.reply_text(plain)
            else:
                await update.edit_message_text(plain)
        except Exception as e2:
            logger.error("Weather fallback error: %s", e2)

