        mbtif_line = f"<tg-emoji emoji-id=\"5341715473882955310\">⚙️</tg-emoji> فەنکشن: <b>{_tr('mbtifunc','top_func')}</b>" if tr.get("mbtifunc") else ""
        # Enneagram
        ennea_line = f"<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> Enneagram: <b>{_tr('enneagram','type')}w{_tr('enneagram','wing')}</b> {_tr('enneagram','emoji','')}" if tr.get("enneagram") else ""
