        # ── لێڤڵ ئیمۆجی ──
        _lv = stats['level']
        if _lv >= 100: _lv_icon = "🔱"
        elif _lv >= 50: _lv_icon = f"{_TDM}"
        elif _lv >= 25: _lv_icon = "<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji>"
        elif _lv >= 10: _lv_icon = "<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>"
        else: _lv_icon = "✦"

        # ── ئانلاین ستاتس ──
        if days_since_active == 0: _status = "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> ئۆنلاین"
        elif days_since_active <= 1: _status = "<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> دوێنێ"
        elif days_since_active <= 7: _status = "<tg-emoji emoji-id=\"5431855765000331501\">🟠</tg-emoji> ئەم هەفتەیە"
        else: _status = f"<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> {days_since_active} ڕۆژ"

