async def leaderboard_from_update(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> Leaderboard — یەک نامە، ٤ دووگمەی تاب — <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> top10 cached"""
    uid = update.effective_user.id
