# ── lookup خێرا ──
_QR_AR  = {s[0]: s[1] for s in SURAH_DB}
_QR_KU  = {s[0]: s[2] for s in SURAH_DB}
_QR_AYC = {s[0]: s[3] for s in SURAH_DB}

# ── ژمارەی کوردی ──
_QR_KU_NUMS = "٠١٢٣٤٥٦٧٨٩"
def _qr_to_ku(n: int) -> str:
    return "".join(_QR_KU_NUMS[int(d)] for d in str(n))


def _qr_emoji(key: str, fallback: str) -> str:
    """
    وەرگرتنی Custom Emoji ID لە QURAN_EMOJI_IDS داتابەیس.
    ئەگەر کی نەبوو، fallback دەگەڕێنێتەوە.
    """
    return QURAN_EMOJI_IDS.get(key, fallback)


# ── fetch بە کاشینگ ──
async def _qr_fetch_surah(surah_num: int):
    """داگرتنی سوورەتێک لە API بە کاشینگ. دەگەڕێنێتەوە dict یان None."""
    now = time.time()
    cached = _SURAH_CACHE.get(surah_num)
    if cached and (now - cached["ts"]) < _SURAH_CACHE_TTL:
        return cached

    url = _QURAN_API.format(n=surah_num)
    data = None

    try:
        import httpx as _hx
        async with _hx.AsyncClient(timeout=_QURAN_API_TIMEOUT) as cl:
            r = await cl.get(url)
            if r.status_code == 200:
                data = r.json()
    except Exception:
        pass

    if data is None:
        try:
            import requests as _rq
            loop = asyncio.get_running_loop()
            resp = await loop.run_in_executor(
                None, lambda: _rq.get(url, timeout=_QURAN_API_TIMEOUT))
            if resp.status_code == 200:
                data = resp.json()
        except Exception as _e:
            logger.warning("quran api fetch: %s", _e)

    if not data or data.get("code") != 200:
        return None

    editions = data.get("data", [])
    if not editions:
        return None

    ar_ayahs = [a["text"] for a in editions[0].get("ayahs", [])]
    ku_ayahs = [a["text"] for a in editions[1].get("ayahs", [])] if len(editions) >= 2 else []

    # FIX: quran-uthmani بۆ سوورەتی نەک-١ و نەک-٩، Basmalah دەخاتە سەرەتای ئایەت ١
    # سوورە ١ (فاتیحە): ئایەت ١ = Basmalah بە خۆی، نابێت لادەبرێت
    # سوورە ٩ (تەوبە): Basmalah نییە
    if surah_num not in (1, 9) and ar_ayahs:
        ar_ayahs[0] = _qr_strip_basmalah(ar_ayahs[0])
        if ku_ayahs:
            ku_ayahs[0] = _qr_strip_basmalah(ku_ayahs[0])

    result = {"ar": ar_ayahs, "ku": ku_ayahs, "ts": now}
    _SURAH_CACHE[surah_num] = result
    return result


# ── داتای قورئانی بەکارهێنەر ──
def _qr_get_data(user_id: int) -> dict:
    ud = get_user_data(user_id)
    if "quran" not in ud:
        ud["quran"] = {
            "bookmark":        {"surah": 1, "page": 0},
            "reminder_hour":   None,
            "reminder_chat":   None,
            "last_read":       None,
            "total_pages_read": 0,
        }
    return ud["quran"]


def _qr_save(user_id: int):
    try:
        _debounced_save(USERS, USERS_FILE)
    except Exception:
        pass


