def _qr_build_surah_list(page: int):
    e_prev = _qr_emoji("prev", "5352759161945867747")
    e_next = _qr_emoji("next", "5379687326991555987")
    e_home = _qr_emoji("star", "5379553354076694057")

    total = len(SURAH_DB)
    total_pages = (total + _SURAHS_PER_PAGE - 1) // _SURAHS_PER_PAGE
    page = max(0, min(page, total_pages - 1))
    start = page * _SURAHS_PER_PAGE
    chunk = SURAH_DB[start: start + _SURAHS_PER_PAGE]

    text = (
        f'<tg-emoji emoji-id="{_qr_emoji("book","5472411062412254753")}">📖</tg-emoji>'
        f" <b>لیستی سوورەتەکان</b>  "
        f"<i>[ پەڕە {_qr_to_ku(page+1)} / {_qr_to_ku(total_pages)} ]</i>\n"
        f'⊱━━━━━<tg-emoji emoji-id="{e_home}">⭐</tg-emoji>━━━━━⊰\n\n'
        "<i>سوڕەتێک هەڵبژێرە یان بووکماڕکت بکەوە ئەو سوڕەتەی کە تێیدایت!</i>\n"
        "<i>بەهیوام بەردەوام بیت، خوایگەورە نیعمەتە ئەیبەخشێت بۆیە گەر خواستی بەردەوامیت هەبێت دیارە تۆ شایەنی ئەو نیعمەتەی.</i>"
    )

    rows = []
    for i in range(0, len(chunk), 2):
        row = []
        for s in chunk[i:i+2]:
            label = f"{_qr_to_ku(s[0])}· {s[1]}"
            row.append(_ebtn(label, f"qr_read:{s[0]}:0", api_kwargs={"style": "primary"}))
        rows.append(row)

    nav = []
    if page > 0:
        nav.append(_ebtn("پێشتر", f"qr_list:{page-1}", emoji_id=e_prev, api_kwargs={"style": "primary"}))
    nav.append(_ebtn("سەرەکی", "qr_menu", emoji_id=e_home, api_kwargs={"style": "primary"}))
    if page < total_pages - 1:
        nav.append(_ebtn("دواتر", f"qr_list:{page+1}", emoji_id=e_next, api_kwargs={"style": "primary"}))
    rows.append(nav)
    return text, InlineKeyboardMarkup(rows)


def _qr_texts_differ(ar: str, ku: str) -> bool:
    """
    True ئەگەر ku_raw وەرگێڕانێکی کوردی راستەقینەیە.

    FIX v9 — ROOT CAUSE FIX:
    نۆرمالایزکردنی Uthmani↔عەرەبی ستاندارد (FIX v1-v8) بۆ دوو هۆکار
    شکستی دەهێنا بۆ ئایەتی درێژ:
      ١) ىٰ (عَلَىٰ) → ا دەبوو بەجیاتی ي  → علا ≠ علي  → similarity < 0.97
      ٢) هَٰذَا → هاذا دەبوو بەجیاتی هذا  → زیادی ئەلیف → similarity < 0.97

    چارەسەری ڕادیکاڵ: ku.amed ئەگەر عەرەبی ستاندارد گەڕاندەوە
    (نەک وەرگێڕانی کوردی)، ئەو تێکستە هیچ پیتێکی کوردی تایبەت
    تێدا نییە. وەرگێڕانی راستەقینەی کوردی هەمیشە لانیکەم یەک
    پیتی کوردی تایبەت تێدایە:
      ۆ U+06C6  ێ U+06CE  ڕ U+0695  ە U+06D5
      گ U+06AF  چ U+0686  ژ U+0698  پ U+067E  ڤ U+06A4

    ئەم پیتانە هەرگیز لە عەرەبیی قورئانی دانەمەزرون.
    """
    if not ku:
        return False
    _KU_SPECIFIC = re.compile(
        r'[\u06C6\u06CE\u0695\u06D5\u06AF\u0686\u0698\u067E\u06A4]'
    )
    return bool(_KU_SPECIFIC.search(ku))


# ── Basmalah بۆ لابردن لە سەرەتای ئایەت ١ ──
# quran-uthmani بۆ هەموو سوورەتێک (جگە لە ١ و ٩)، Basmalah دەخاتە سەرەتای ئایەت ١
_BASMALA_FORMS = (
    "بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ",   # Uthmani
    "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ",    # Hafs
    "بسم الله الرحمن الرحيم",                      # ساکەت
)

def _qr_strip_basmalah(text: str) -> str:
    """
    لابردنی Basmalah لە سەرەتای ئایەت ١ بۆ سوورەتی نەک-١ و نەک-٩.
    FIX: بِسْمِ...ٱلرَّحِيمِ + سوورەت → تەنیا سوورەت دەگەڕێتەوە.
    """
    for basm in _BASMALA_FORMS:
        if text.startswith(basm):
            return text[len(basm):].lstrip()
    return text


def _qr_build_reader(surah_num: int, page: int, ar_ayahs: list, ku_ayahs: list):
    e_book = _qr_emoji("book",     "5472411062412254753")
    e_prev = _qr_emoji("prev",     "5352759161945867747")
    e_next = _qr_emoji("next",     "5379687326991555987")
    e_bkmk = _qr_emoji("bookmark", "5379619938954679279")
    e_list = _qr_emoji("list",     "5264986544564892162")
    e_home = _qr_emoji("star",     "5379553354076694057")

    total_ayahs = len(ar_ayahs)
    total_pages = max(1, (total_ayahs + _AYAHS_PER_PAGE - 1) // _AYAHS_PER_PAGE)
    page = max(0, min(page, total_pages - 1))
    start = page * _AYAHS_PER_PAGE
    end   = min(start + _AYAHS_PER_PAGE, total_ayahs)

    ar_name = _QR_AR.get(surah_num, "")
    ku_name = _QR_KU.get(surah_num, "")

    lines = [
        f'<tg-emoji emoji-id="{e_book}">📖</tg-emoji>'
        f" <b>سورة {html.escape(ar_name)}</b>  ·  <b>{html.escape(ku_name)}</b>",
        f"<i>ژمارەی سوورەت: {_qr_to_ku(surah_num)}  ·  "
        f"ئایەت: {_qr_to_ku(total_ayahs)}  ·  "
        f"پەڕە {_qr_to_ku(page+1)}/{_qr_to_ku(total_pages)}</i>",
        f'⊱━━━━━<tg-emoji emoji-id="{e_home}">⭐</tg-emoji>━━━━━⊰',
        "",
    ]

    # FIX: Basmalah لابرا — quran-uthmani خۆی ئایەت ١ی هەر سوورەت Basmalah دەگەڕێنێتەوە،
    # بۆیە زیادکردنی دەستی دووبارەبوون دروست دەکرد.

    for i in range(start, end):
        ayah_num = i + 1
        ar_raw   = ar_ayahs[i] if i < len(ar_ayahs) else ""
        ar_text  = html.escape(ar_raw)
        lines.append(f"﴿ {ar_text} ﴾")
        lines.append(f"<code>({_qr_to_ku(ayah_num)})</code>")
        lines.append("")

    lines.append(f'⊱━━━━━<tg-emoji emoji-id="{e_home}">⭐</tg-emoji>━━━━━⊰')
    text = "\n".join(lines)

    # ئەگەر زۆر درێژ بوو — ئایەتی کەمتر
    if len(text) > 3800:
        lines2 = lines[:4]
        for i in range(start, min(start + 3, end)):
            ayah_num = i + 1
            ar_raw   = ar_ayahs[i] if i < len(ar_ayahs) else ""
            ar_text  = html.escape(ar_raw)
            lines2.append(f"﴿ {ar_text} ﴾")
            lines2.append(f"<code>({_qr_to_ku(ayah_num)})</code>")
            lines2.append("")
        lines2.append(f'⊱━━━━━<tg-emoji emoji-id="{e_home}">⭐</tg-emoji>━━━━━⊰')
        text = "\n".join(lines2)

    rows = []
    nav_page = []
    if page > 0:
        nav_page.append(_ebtn("پێشتر", f"qr_read:{surah_num}:{page-1}", emoji_id=e_prev, api_kwargs={"style": "primary"}))
    nav_page.append(_ebtn(f"{_qr_to_ku(page+1)}/{_qr_to_ku(total_pages)}", "qr_noop", emoji_id=e_book, api_kwargs={"style": "primary"}))
    if page < total_pages - 1:
        nav_page.append(_ebtn("دواتر", f"qr_read:{surah_num}:{page+1}", emoji_id=e_next, api_kwargs={"style": "primary"}))
    rows.append(nav_page)

    nav_surah = []
    if surah_num > 1:
        nav_surah.append(_ebtn(f"{_QR_AR.get(surah_num-1,'')}", f"qr_read:{surah_num-1}:0", emoji_id=e_prev, api_kwargs={"style": "primary"}))
    if surah_num < 114:
        nav_surah.append(_ebtn(f"{_QR_AR.get(surah_num+1,'')}", f"qr_read:{surah_num+1}:0", emoji_id=e_next, api_kwargs={"style": "primary"}))
    if nav_surah:
        rows.append(nav_surah)

    rows.append([
        _ebtn("بوکمارک", f"qr_bmark_set:{surah_num}:{page}", emoji_id=e_bkmk, api_kwargs={"style": "success"}),
        _ebtn("لیست",    "qr_list:0",                          emoji_id=e_list, api_kwargs={"style": "primary"}),
        _ebtn("سەرەکی",  "qr_menu",                            emoji_id=e_home, api_kwargs={"style": "primary"}),
    ])
    return text, InlineKeyboardMarkup(rows)


def _qr_build_reminder_menu(user_id: int):
    e_bell      = _qr_emoji("bell",      "5274055917766202507")
