# ── safe edit ──
async def _qr_safe_edit(query, text: str, kb: InlineKeyboardMarkup):
    try:
        await query.edit_message_text(text, reply_markup=kb, parse_mode="HTML")
    except Exception as _e:
        if "message is not modified" not in str(_e).lower():
            logger.warning("quran safe_edit: %s", _e)


# ── لابردنی job ──
def _qr_remove_job(job_queue, user_id: int):
    name = f"qr_rem_{user_id}"
    for job in job_queue.get_jobs_by_name(name):
        job.schedule_removal()


# ── دووبارە دامەزراندنەوەی یادکردنەوەکان ──
def restore_reminders(application) -> int:
    """
    پاش restart، یادکردنەوەکانی هەموو بەکارهێنەران دووبارە دامەزرێنرێن.
    دەگەڕێنێتەوە ژمارەی یادکردنەوەی دامەزرێنراو.
    """
    count = 0
    jq = application.job_queue
    if not jq:
        return 0
    for uid_str, ud in USERS.items():
        qd = ud.get("quran")
        if not qd:
            continue
        hour = qd.get("reminder_hour")
        chat = qd.get("reminder_chat")
        if hour is None or chat is None:
            continue
        try:
            t = datetime.time(hour=int(hour), minute=0, tzinfo=datetime.timezone.utc)
            jq.run_daily(
                quran_reminder_job,
                time=t,
                chat_id=int(chat),
                name=f"qr_rem_{uid_str}",
                data={"user_id": uid_str},
            )
            count += 1
        except Exception as _e:
            logger.warning("restore_reminders uid=%s: %s", uid_str, _e)
    logger.info("📖 Quran: %d یادکردنەوە دووبارە دامەزرێنران", count)
    return count


