async def quran_command(update: Update, context: CallbackContext):
    """/quran — کردنەوەی سیستەمی خوێندنی قورئانی پیرۆز."""
    text, kb = _qr_build_main_menu()
    await update.message.reply_text(text, reply_markup=kb, parse_mode="HTML")


async def quran_callback(update: Update, context: CallbackContext):
    """CallbackQueryHandler بۆ ^qr_ — خوێندنەوەی قورئان."""
    query = update.callback_query
    await query.answer()

    data  = query.data or ""
    parts = data.split(":")
    cmd   = parts[0]
    uid   = query.from_user.id

    if cmd == "qr_menu":
        text, kb = _qr_build_main_menu()
        await _qr_safe_edit(query, text, kb)
        return

    if cmd == "qr_list":
        page = int(parts[1]) if len(parts) > 1 else 0
        text, kb = _qr_build_surah_list(page)
        await _qr_safe_edit(query, text, kb)
        return

    if cmd == "qr_read":
        surah_num = max(1, min(int(parts[1]) if len(parts) > 1 else 1, 114))
        page      = int(parts[2]) if len(parts) > 2 else 0
        e_book    = _qr_emoji("book", "5472411062412254753")
        await query.edit_message_text(
            f'<tg-emoji emoji-id="{e_book}">📖</tg-emoji>'
            f" <b>{_QR_KU.get(surah_num,'')} — {_QR_AR.get(surah_num,'')}</b>\n\n"
            "<i>چاوەڕوان بکە، داتای سوورەت داگیرا دێت…</i>",
            parse_mode="HTML",
        )
        surah_data = await _qr_fetch_surah(surah_num)
        if not surah_data:
            await query.edit_message_text(
                "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ببورە، ئێستا پەیوەندی بە سێرڤەرەوە نابەستین.\n"
                "تکایە کەمێک لەتۆ ماوەیەک دواتر هەوڵ بدەوە.",
                parse_mode="HTML",
            )
            return
        qd = _qr_get_data(uid)
        qd["last_read"] = {"surah": surah_num, "page": page}
        qd["total_pages_read"] = qd.get("total_pages_read", 0) + 1
        _qr_save(uid)
        text, kb = _qr_build_reader(surah_num, page, surah_data["ar"], surah_data["ku"])
        await _qr_safe_edit(query, text, kb)
        return

    if cmd == "qr_bmark_set":
        surah = int(parts[1]) if len(parts) > 1 else 1
        pg    = int(parts[2]) if len(parts) > 2 else 0
        qd = _qr_get_data(uid)
        qd["bookmark"] = {"surah": surah, "page": pg}
        _qr_save(uid)
        await query.answer(
            f"<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> بوکمارک خەزەن کرا — {_QR_KU.get(surah,'')} پەڕە {pg+1}",
            show_alert=True,
        )
        return

    if cmd == "qr_bmark_go":
        qd    = _qr_get_data(uid)
        bmark = qd.get("bookmark", {"surah": 1, "page": 0})
        surah = bmark.get("surah", 1)
        pg    = bmark.get("page", 0)
        e_book = _qr_emoji("book", "5472411062412254753")
        await query.edit_message_text(
            f'<tg-emoji emoji-id="{e_book}">📖</tg-emoji>'
            f" <b>بوکمارک: {_QR_KU.get(surah,'')} · پەڕە {_qr_to_ku(pg+1)}</b>\n\n"
            "<i>داگیرکردنی سوورەت…</i>",
            parse_mode="HTML",
        )
        surah_data = await _qr_fetch_surah(surah)
        if not surah_data:
            await query.edit_message_text(
                "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئێستا پەیوەندی نییە. دواتر هەوڵ بدەوە.",
                parse_mode="HTML",
            )
            return
        text, kb = _qr_build_reader(surah, pg, surah_data["ar"], surah_data["ku"])
        await _qr_safe_edit(query, text, kb)
        return

    if cmd == "qr_random":
        surah_num = random.randint(1, 114)
        e_book = _qr_emoji("book", "5472411062412254753")
        await query.edit_message_text(
            f'<tg-emoji emoji-id="{e_book}">📖</tg-emoji>'
            " <b>ئایەتی هەڵکەوت داگیردێت…</b>",
            parse_mode="HTML",
        )
        surah_data = await _qr_fetch_surah(surah_num)
        if not surah_data:
            await query.edit_message_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> هەڵە. دواتر هەوڵ بدەوە.", parse_mode="HTML")
            return
        text, kb = _qr_build_reader(surah_num, 0, surah_data["ar"], surah_data["ku"])
        await _qr_safe_edit(query, text, kb)
        return

    if cmd == "qr_noop":
        return


async def quran_reminder_callback(update: Update, context: CallbackContext):
    """CallbackQueryHandler بۆ ^qrr_ — یادکردنەوەکانی قورئان."""
    query = update.callback_query
    await query.answer()

    data  = query.data or ""
    parts = data.split(":")
    cmd   = parts[0]
    uid   = query.from_user.id
    chat_id = query.message.chat_id

    if cmd == "qrr_menu":
        text, kb = _qr_build_reminder_menu(uid)
        await _qr_safe_edit(query, text, kb)
        return

    if cmd == "qrr_set":
        hour = max(0, min(23, int(parts[1]) if len(parts) > 1 else 8))
        qd = _qr_get_data(uid)
        qd["reminder_hour"] = hour
        qd["reminder_chat"] = chat_id
        _qr_save(uid)
        try:
            jq = context.job_queue
            if jq:
                _qr_remove_job(jq, uid)
                t = datetime.time(hour=hour, minute=0, tzinfo=datetime.timezone.utc)
                jq.run_daily(
                    quran_reminder_job,
                    time=t,
                    chat_id=chat_id,
                    name=f"qr_rem_{uid}",
                    data={"user_id": uid},
                )
        except Exception as _e:
            logger.warning("quran reminder job: %s", _e)
        text, kb = _qr_build_reminder_menu(uid)
        await _qr_safe_edit(query, text, kb)
        await query.answer(f"✅ یادکردنەوە دانرا بۆ {_qr_to_ku(hour)}:٠٠ UTC", show_alert=True)
        return

    if cmd == "qrr_off":
        qd = _qr_get_data(uid)
        qd["reminder_hour"] = None
        _qr_save(uid)
        try:
            jq = context.job_queue
            if jq:
                _qr_remove_job(jq, uid)
        except Exception:
            pass
        text, kb = _qr_build_reminder_menu(uid)
        await _qr_safe_edit(query, text, kb)
        await query.answer("🚫 یادکردنەوە کوژاندرایەوە", show_alert=True)
        return


async def quran_reminder_job(context: CallbackContext) -> None:
    """jobی ڕۆژانەی یادکردنەوەی قورئان."""
    chat_id = context.job.chat_id
    if not chat_id:
        return
    surah_num  = random.randint(1, 114)
    surah_data = await _qr_fetch_surah(surah_num)
    ku_name    = _QR_KU.get(surah_num, "")
    ar_name    = _QR_AR.get(surah_num, "")
    e_book     = _qr_emoji("book", "5472411062412254753")
    e_list     = _qr_emoji("list", "5264986544564892162")
    e_star_id  = _qr_emoji("star", "5379553354076694057")

    header = (
        f'<tg-emoji emoji-id="{e_book}">📖</tg-emoji>'
        " <b>یادکردنەوەی قورئانی پیرۆز</b>\n"
        f'⊱━━━━━<tg-emoji emoji-id="{e_star_id}">⭐</tg-emoji>━━━━━⊰\n\n'
    )

    if surah_data and surah_data["ar"]:
        ayah_idx = random.randint(0, len(surah_data["ar"]) - 1)
        ar_text  = html.escape(surah_data["ar"][ayah_idx])
        ku_text  = html.escape(surah_data["ku"][ayah_idx]) if surah_data["ku"] else ""
        ayah_num = _qr_to_ku(ayah_idx + 1)
        body = (
            f"<b>سورة {html.escape(ar_name)}  ·  {html.escape(ku_name)}</b>  "
            f"[{_qr_to_ku(surah_num)}:{ayah_num}]\n\n"
            f"﴿ {ar_text} ﴾\n"
        )
        if ku_text:
            body += f"\n<i>{ku_text}</i>\n"
    else:
        body = (
            f"<b>سورة {html.escape(ar_name)}  ·  {html.escape(ku_name)}</b>\n\n"
            "﴿ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ ﴾\n"
            "<i>تەنها بە یادی خودا دڵەکان ئارام دەبنەوە.</i>\n"
        )

    kb = InlineKeyboardMarkup([[
        _ebtn("بخوێنە", f"qr_read:{surah_num}:0", emoji_id=e_book, api_kwargs={"style": "primary"}),
        _ebtn("لیست",   "qr_list:0",               emoji_id=e_list, api_kwargs={"style": "primary"}),
    ]])
    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=header + body,
            parse_mode="HTML",
            reply_markup=kb,
        )
    except Exception as _e:
        logger.warning("quran reminder send: %s", _e)


# ═══════════════════════════════════════════════════════════════════════
# 📖 سیستەمی تەفسیری قورئانی کوردی سۆرانی — نوسخەی ١.٠
#    API: quranenc.com — وەرگێڕانی محمد صالح بامۆکی + تێبینییەکان (تەفسیر)
#    عەرەبی: alquran.cloud (quran-uthmani) — هاوبەشکردن بە _qr_fetch_surah
# ═══════════════════════════════════════════════════════════════════════

_TF_CACHE:     dict  = {}          # {surah_num: {"ayahs": [...], "ts": float}}
_TF_CACHE_TTL: float = 7200.0      # ٢ کاتژمێر
_TF_API       = "https://quranenc.com/api/v1/translation/sura/kurdish_bamoki/{n}"
_TF_TIMEOUT   = 15.0

# ── ئایەتی هەڵکەوتی ڕۆژانە — بۆ reminder ──
_TF_DAILY_VERSES = [
    (2, 286), (3, 200), (2, 255), (55, 13), (93, 11),
    (94, 6),  (65, 3),  (2, 153), (3, 139), (39, 53),
]

# ─────────────────────────────────────────────
# داگرتنی داتا
# ─────────────────────────────────────────────
async def _tf_fetch_surah(surah_num: int) -> list | None:
    """
    دەگەڕێنێتەوە لیستێک لە dict:
      [{"aya": int, "ku": str, "fn": str}, ...]
    یان None ئەگەر هەڵەیەک ڕووی دا.
    """
    now    = time.time()
    cached = _TF_CACHE.get(surah_num)
    if cached and (now - cached["ts"]) < _TF_CACHE_TTL:
        return cached["ayahs"]

    url  = _TF_API.format(n=surah_num)
    data = None

    try:
        import httpx as _hx
        async with _hx.AsyncClient(timeout=_TF_TIMEOUT) as cl:
            r = await cl.get(url)
            if r.status_code == 200:
                data = r.json()
    except Exception:
        pass

    if data is None:
        try:
            import requests as _rq
            loop = asyncio.get_running_loop()
            resp = await loop.run_in_executor(
                None, lambda: _rq.get(url, timeout=_TF_TIMEOUT))
            if resp.status_code == 200:
                data = resp.json()
        except Exception as _e:
            logger.warning("tf_fetch: %s", _e)

    if not data:
        return None

    result_raw = data.get("result") or data.get("data") or []
    if not result_raw:
        return None

    ayahs = []
    for item in result_raw:
        ayahs.append({
            "aya": int(item.get("aya", 0)),
            "ku":  (item.get("translation") or "").strip(),
            "fn":  (item.get("footnotes")  or "").strip(),
        })

    _TF_CACHE[surah_num] = {"ayahs": ayahs, "ts": now}
    return ayahs


