def _tf_build_surah_list(page: int) -> tuple:
    e_st = _TF_E_STAR; e_pv = _TF_E_PREV; e_nx = _TF_E_NEXT
    total_pages = (len(SURAH_DB) + 9) // 10
    page = max(0, min(page, total_pages - 1))
    chunk = SURAH_DB[page * 10: page * 10 + 10]

    text = (
        f'<tg-emoji emoji-id="{_TF_E_BOOK}">📖</tg-emoji>'
        f" <b>لیستی سوورەتەکان</b>"
        f"  <i>[ پەڕە {_qr_to_ku(page+1)}/{_qr_to_ku(total_pages)} ]</i>\n"
        f'⊱━━━<tg-emoji emoji-id="{e_st}">⭐</tg-emoji>━━━⊰\n\n'
        "<i>سوورەتێک هەڵبژێرە بۆ خوێندن و تەفسیر:</i>"
    )
    rows = []
    for i in range(0, len(chunk), 2):
        row = []
        for s in chunk[i:i+2]:
            label = f"{_qr_to_ku(s[0])}· {s[1]}"
            row.append(_ebtn(label, f"tf_read:{s[0]}:0", api_kwargs={"style": "primary"}))
        rows.append(row)

    nav = []
    if page > 0:
        nav.append(_ebtn("پێشتر", f"tf_list:{page-1}", emoji_id=e_pv, api_kwargs={"style": "primary"}))
    nav.append(_ebtn("سەرەکی", "tf_menu", emoji_id=e_st, api_kwargs={"style": "primary"}))
    if page < total_pages - 1:
        nav.append(_ebtn("دواتر", f"tf_list:{page+1}", emoji_id=e_nx, api_kwargs={"style": "primary"}))
    rows.append(nav)
    return text, InlineKeyboardMarkup(rows)


def _tf_build_ayah_view(
    surah_num: int,
    ayah_idx:  int,
    ar_ayahs:  list,
    tf_ayahs:  list,
    show_fn:   bool = False,
) -> tuple:
    """یەک ئایەت — عەرەبی + کوردی سۆرانی + تەفسیر (ئەگەر show_fn=True)."""
    e_bk = _TF_E_BOOK; e_st = _TF_E_STAR
    e_pv = _TF_E_PREV; e_nx = _TF_E_NEXT
    e_ls = _TF_E_LIST; e_nt = _TF_E_NOTE

    total    = len(ar_ayahs)
    ayah_idx = max(0, min(ayah_idx, total - 1))
    ayah_num = ayah_idx + 1

    ar_name = _QR_AR.get(surah_num, "")
    ku_name = _QR_KU.get(surah_num, "")
    ar_raw  = ar_ayahs[ayah_idx] if ayah_idx < len(ar_ayahs) else ""
    tf_item = tf_ayahs[ayah_idx] if ayah_idx < len(tf_ayahs) else {}
    ku_text = tf_item.get("ku", "")
    fn_text = tf_item.get("fn", "")

    # ─ Header ─
    lines = [
        f'<tg-emoji emoji-id="{e_bk}">📖</tg-emoji>'
        f" <b>سورة {html.escape(ar_name)}  ·  {html.escape(ku_name)}</b>",
        f"<i>ئایەت {_qr_to_ku(ayah_num)} / {_qr_to_ku(total)}"
        f"  ·  سوورەت {_qr_to_ku(surah_num)}</i>",
        f'⊱━━━<tg-emoji emoji-id="{e_st}">⭐</tg-emoji>━━━⊰',
        "",
        f"﴿ {html.escape(ar_raw)} ﴾",
        "",
    ]
    if ku_text:
        lines += [
            f'<tg-emoji emoji-id="{e_nt}">📝</tg-emoji> <b>وەرگێڕانی کوردی:</b>',
            f"<i>{html.escape(ku_text)}</i>",
            "",
        ]
    if show_fn and fn_text:
        lines += [
            f'<tg-emoji emoji-id="{e_nt}">📝</tg-emoji> <b>تەفسیر / تێبینی:</b>',
            f"{html.escape(fn_text)}",
            "",
        ]
    lines.append(f'⊱━━━<tg-emoji emoji-id="{e_st}">⭐</tg-emoji>━━━⊰')
    text = "\n".join(lines)

    # ─ بریکردن ئەگەر زۆر درێژ بوو ─
    if len(text) > 3900 and show_fn and fn_text:
        fn_cut = fn_text[:600] + "…"
        lines2 = lines[:-1]
        for i, l in enumerate(lines2):
            if l.startswith(html.escape(fn_text)[:20]) and len(l) > 600:
                lines2[i] = html.escape(fn_cut)
        lines2.append(f'⊱━━━<tg-emoji emoji-id="{e_st}">⭐</tg-emoji>━━━⊰')
        text = "\n".join(lines2)

    # ─ Keyboard ─
    fn_flag   = "1" if show_fn else "0"
    fn_toggle = "0" if show_fn else "1"

    rows = []

    # ناڤیگەیشنی ئایەت
    nav_ayah = []
    if ayah_idx > 0:
        nav_ayah.append(_ebtn(
            "<tg-emoji emoji-id=\"5255703720078879038\">◀</tg-emoji> پێشوو", f"tf_read:{surah_num}:{ayah_idx-1}:{fn_flag}",
            emoji_id=e_pv, api_kwargs={"style": "primary"}))
    nav_ayah.append(_ebtn(
        f"{_qr_to_ku(ayah_num)}/{_qr_to_ku(total)}",
        "tf_noop", emoji_id=e_bk, api_kwargs={"style": "primary"}))
    if ayah_idx < total - 1:
        nav_ayah.append(_ebtn(
            "دوواتر <tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji>", f"tf_read:{surah_num}:{ayah_idx+1}:{fn_flag}",
            emoji_id=e_nx, api_kwargs={"style": "primary"}))
    rows.append(nav_ayah)

    # تەفسیر toggle + سوورەتی تر
    row2 = []
    if fn_text:
        lbl = "🙈 شاردنەوەی تەفسیر" if show_fn else "<tg-emoji emoji-id=\"5271715383928172373\">📖</tg-emoji> نیشاندانی تەفسیر"
        row2.append(_ebtn(
            lbl, f"tf_read:{surah_num}:{ayah_idx}:{fn_toggle}",
            emoji_id=e_nt, api_kwargs={"style": "success" if not show_fn else "danger"}))
    rows.append(row2) if row2 else None

    # ناڤیگەیشنی سوورەت + لیست
    nav_bot = []
    if surah_num > 1:
        nav_bot.append(_ebtn(
            f"<tg-emoji emoji-id=\"5255703720078879038\">◀</tg-emoji> {_QR_AR.get(surah_num-1,'')}",
            f"tf_read:{surah_num-1}:0:{fn_flag}",
            emoji_id=e_pv, api_kwargs={"style": "primary"}))
    nav_bot.append(_ebtn(
        "لیست", "tf_list:0",
        emoji_id=e_ls, api_kwargs={"style": "primary"}))
    if surah_num < 114:
        nav_bot.append(_ebtn(
            f"{_QR_AR.get(surah_num+1,'')} <tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji>",
            f"tf_read:{surah_num+1}:0:{fn_flag}",
            emoji_id=e_nx, api_kwargs={"style": "primary"}))
    rows.append(nav_bot)

    return text, InlineKeyboardMarkup(rows)


# ─────────────────────────────────────────────
# فەرمانەکان
# ─────────────────────────────────────────────
@guarded
async def tafsir_cmd(update: Update, context: CallbackContext):
    """/tafsir — کردنەوەی سیستەمی تەفسیری قورئانی کوردی سۆرانی."""
    text, kb = _tf_build_main_menu()
    await update.message.reply_text(text, reply_markup=kb, parse_mode="HTML")


async def tafsir_callback(update: Update, context: CallbackContext):
    """CallbackQueryHandler بۆ ^tf_ — تەفسیری قورئان."""
    query = update.callback_query
    await query.answer()

    data  = query.data or ""
    parts = data.split(":")
    cmd   = parts[0]

    # ── سەرەکی ──
    if cmd == "tf_menu":
        text, kb = _tf_build_main_menu()
        try:
            await query.edit_message_text(text, reply_markup=kb, parse_mode="HTML")
        except Exception as _e:
            if "not modified" not in str(_e).lower():
                logger.warning("tf_menu: %s", _e)
        return

    # ── لیستی سوورەتەکان ──
    if cmd == "tf_list":
        page = int(parts[1]) if len(parts) > 1 else 0
        text, kb = _tf_build_surah_list(page)
        try:
            await query.edit_message_text(text, reply_markup=kb, parse_mode="HTML")
        except Exception as _e:
            if "not modified" not in str(_e).lower():
                logger.warning("tf_list: %s", _e)
        return

    # ── خوێندنەوەی ئایەت ──
    if cmd == "tf_read":
        surah_num = max(1, min(int(parts[1]) if len(parts) > 1 else 1, 114))
        ayah_idx  = max(0, int(parts[2]) if len(parts) > 2 else 0)
        show_fn   = (parts[3] == "1") if len(parts) > 3 else False

        e_bk = _TF_E_BOOK; e_st = _TF_E_STAR
        # ── loading ──
        try:
            await query.edit_message_text(
                f'<tg-emoji emoji-id="{e_bk}">📖</tg-emoji>'
                f" <b>{html.escape(_QR_KU.get(surah_num, ''))} — {html.escape(_QR_AR.get(surah_num, ''))}</b>\n"
                f'⊱━━━<tg-emoji emoji-id="{e_st}">⭐</tg-emoji>━━━⊰\n\n'
                "<i><tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> داگیرکردنی داتا…</i>",
                parse_mode="HTML",
            )
        except Exception:
            pass

        # ── هاوکاتی داگرتنی Arabic + Tafsir ──
        ar_task = asyncio.ensure_future(_qr_fetch_surah(surah_num))
        tf_task = asyncio.ensure_future(_tf_fetch_surah(surah_num))
        ar_data, tf_data = await asyncio.gather(ar_task, tf_task, return_exceptions=True)

        if isinstance(ar_data, Exception) or not ar_data:
            ar_data = None
        if isinstance(tf_data, Exception):
            tf_data = None

        if not ar_data and not tf_data:
            try:
                await query.edit_message_text(
                    "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ببورە، ئێستا پەیوەندی بە سێرڤەرەوە نابەستین.\n"
                    "تکایە کەمێک لەتۆ ماوەیەک دواتر هەوڵ بدەوە.",
                    parse_mode="HTML",
                )
            except Exception:
                pass
            return

        ar_ayahs = ar_data["ar"] if ar_data else []
        tf_ayahs = tf_data or []

        # ئەگەر یەکێک نەبوو — Array ی بەتال بەکاربهێنە
        max_len = max(len(ar_ayahs), len(tf_ayahs))
        ayah_idx = max(0, min(ayah_idx, max_len - 1))

        # عەرەبی ئەگەر نەبوو placeholder بەکاربهێنە
        if not ar_ayahs:
            ar_ayahs = ["" for _ in range(len(tf_ayahs))]

        text, kb = _tf_build_ayah_view(surah_num, ayah_idx, ar_ayahs, tf_ayahs, show_fn)
        try:
            await query.edit_message_text(text, reply_markup=kb, parse_mode="HTML")
        except Exception as _e:
            if "not modified" not in str(_e).lower():
                logger.warning("tf_read edit: %s", _e)
        return

    # ── ئایەتی هەڵکەوت ──
    if cmd == "tf_random":
        surah_num = random.randint(1, 114)
        e_bk = _TF_E_BOOK; e_st = _TF_E_STAR
        try:
            await query.edit_message_text(
                f'<tg-emoji emoji-id="{e_bk}">📖</tg-emoji>'
                " <b>ئایەتی هەڵکەوت داگیردێت…</b>",
                parse_mode="HTML",
            )
        except Exception:
            pass

        ar_data = await _qr_fetch_surah(surah_num)
        tf_data = await _tf_fetch_surah(surah_num)
        ar_ayahs = ar_data["ar"] if ar_data else []
        tf_ayahs = tf_data or []

        if not ar_ayahs and not tf_ayahs:
            try:
                await query.edit_message_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> هەڵە. دواتر هەوڵ بدەوە.", parse_mode="HTML")
            except Exception:
                pass
            return

        max_len  = max(len(ar_ayahs), len(tf_ayahs), 1)
        rand_idx = random.randint(0, max_len - 1)
        if not ar_ayahs:
            ar_ayahs = ["" for _ in range(len(tf_ayahs))]

        text, kb = _tf_build_ayah_view(surah_num, rand_idx, ar_ayahs, tf_ayahs, False)
        try:
            await query.edit_message_text(text, reply_markup=kb, parse_mode="HTML")
        except Exception as _e:
            if "not modified" not in str(_e).lower():
                logger.warning("tf_random edit: %s", _e)
        return

    if cmd == "tf_noop":
        return


# ─────────────────────────────────────────────
# بوتنی مێنیوی سەرەکی (run:tafsir → tafsir_cmd)
# ─────────────────────────────────────────────


