async def science_fact(update: Update, context: CallbackContext):
    """/sciencefact — فاکتی زانستی هەڵکەوت لە ١٢٠+ فاکت"""
    _all_facts = []
    for _cat_data in SCIENCE_FACTS_V2.values():
        _all_facts.extend(_cat_data["facts"])
    _fact = random.choice(_all_facts)
    await update.message.reply_text(
        "<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji>"
        f" <b>فاکتی زانستی:</b>\n\n{_fact}",
        parse_mode="HTML"
    )
# ----------------- Tech News -----------------

async def tech_news(update: Update, context: CallbackContext):
    """فەرمانی /technews — ڕاستەوخۆ هەواڵی تەکنەلۆژیا نیشاندەدات"""
    articles = await _fetch_news_articles("technology")
