async def addgroup_cmd(update: Update, context: CallbackContext):
    """
    /addgroup — زیادکردنی گرووپ بۆ لیستی مۆڵەتدار
    بەکارهێنان: لە ناو گرووپەکەدا بنووسە /addgroup
    یان: /addgroup [ئایدی گرووپ]
    """
    user_id = update.effective_user.id
    if user_id != OWNER_ID:
        return

    # ئەگەر ئایدی داراوە
    if context.args:
        try:
            gid = int(context.args[0])
        except ValueError:
            await update.message.reply_text(_TGX + " ئایدی دروست نییە. تەنها ژمارە بنووسە.", parse_mode="HTML")

            return
    else:
        # ئایدی گرووپی ئێستا
        chat = update.effective_chat
        if chat.type == "private":
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> بەکارهێنان:\n"
                "دوو ڕێگە هەیە:\n\n"
                "١. لە ناو گرووپەکەدا بنووسە: <code>/addgroup</code>\n"
                "٢. ئایدی بنووسە: <code>/addgroup -1001234567890</code>\n\n"
                "بۆ دۆزینەوەی ئایدی گرووپ، بۆت زیاد بکە و <code>/id</code> بنووسە.",
                parse_mode="HTML"
            )
            return
        gid = chat.id

    groups = ALLOWED_GROUPS_DATA.get("groups", [])
    if gid in groups:
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> گرووپی `{gid}` پێشتر لە لیستدایە.", parse_mode="HTML"
        )
        return

    groups.append(gid)
    ALLOWED_GROUPS_DATA["groups"] = groups
    _save_allowed_groups(ALLOWED_GROUPS_DATA)
    # ── cache پاک بکەرەوە بۆ ئەو گرووپە ──
    _GROUP_ACCESS_CACHE.pop(gid, None)
    audit_log("ADD_GROUP", user_id, target_id=0, chat_id=gid,
              details=f"Added group {gid} to allowed list (total: {len(groups)})")
    await update.message.reply_text(
        f"{_TCK} زیادکرا!\n\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی گرووپ: `{gid}`\n"
        f"{_TCH} کۆی گرووپە مۆڵەتدارەکان: {len(groups)}",
        parse_mode="HTML"
    )

async def removegroup_cmd(update: Update, context: CallbackContext):
    """
    /removegroup [ئایدی] — سڕینەوەی گرووپ لە لیستی مۆڵەتدار
    """
    user_id = update.effective_user.id
    if user_id != OWNER_ID:
        return

    groups = ALLOWED_GROUPS_DATA.get("groups", [])
    if not context.args:
        if not groups:
            list_text = "— هیچ گرووپێک نییە —"
        else:
            list_text = "\n".join([f"• `{g}`" for g in groups])
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> لیستی گرووپە مۆڵەتدارەکان ({len(groups)})：\n\n"
            f"{list_text}\n\n"
            f"بۆ سڕینەوە: <code>/removegroup [ئایدی]</code>",
            parse_mode="HTML"
        )
        return

    try:
        gid = int(context.args[0])
    except ValueError:
        await update.message.reply_text(_TGX + " ئایدی دروست نییە.", parse_mode="HTML")

        return

    if gid not in groups:
        await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> گرووپی `{gid}` لە لیستدا نییە.", parse_mode="HTML")
        return

    groups.remove(gid)
    ALLOWED_GROUPS_DATA["groups"] = groups
    _save_allowed_groups(ALLOWED_GROUPS_DATA)
    # ── cache پاک بکەرەوە ──
    _GROUP_ACCESS_CACHE.pop(gid, None)
    audit_log("REMOVE_GROUP", user_id, target_id=0, chat_id=gid,
              details=f"Removed group {gid} from allowed list (remaining: {len(groups)})",
              severity="WARN")
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> سڕایەوە!\n\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی گرووپ: `{gid}`\n"
        f"{_TCH} کۆی گرووپە مۆڵەتدارەکان: {len(groups)}",
        parse_mode="HTML"
    )

async def listgroups_cmd(update: Update, context: CallbackContext):
    """
    /listgroups — بینینی هەموو گرووپە مۆڵەتدارەکان
    """
    user_id = update.effective_user.id
    if user_id != OWNER_ID:
        return

    groups = ALLOWED_GROUPS_DATA.get("groups", [])
    if not groups:
        list_text = "— هیچ گرووپێک زیادنەکراوە —"
    else:
        list_text = "\n".join([f"{i+1}. `{g}`" for i, g in enumerate(groups)])

    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5870972873450984431\">🔐</tg-emoji> گرووپە مۆڵەتدارەکان\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"{list_text}\n\n"
        f"{_TCH} کۆی گشتی: {len(groups)} گرووپ\n\n"
        f"<tg-emoji emoji-id=\"5230940806960919610\">➕</tg-emoji> زیادکردن: <code>/addgroup [ئایدی]</code>\n"
        f"<tg-emoji emoji-id=\"5231265631042548053\">➖</tg-emoji> سڕینەوە: <code>/removegroup [ئایدی]</code>",
        parse_mode="HTML"
    )


