async def mbtifunc_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    clicker_uid = query.from_user.id
    parts = query.data.split(":", 3)
    action = parts[1] if len(parts) > 1 else ""

    cb_uid = None
    if len(parts) >= 3:
        try:
            cb_uid = int(parts[-1])
        except (ValueError, IndexError):
            cb_uid = None

    uid = cb_uid if cb_uid else clicker_uid

    # ── چەکی خاوەنداری + query.answer یەک جار ──
    if cb_uid and clicker_uid != cb_uid:
        try: await answered("🔒 ئەم تێستە هی تۆ نییە! تێستی خۆت بکە /mbtifunc", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action not in ("start", "back", "view", "cancel", "confirmcancel", "prev", "ans"):
        sess = MBTI_FUNC_USER_SESSIONS.get(str(uid))
        if not sess:
            if not _is_func_allowed(uid):
                try: await answered("🔒 ئەم تێستە Premium ە — ڕێگەت پێنەدراوە!", show_alert=True)
                except Exception as _exc:
                    logger.debug("Suppressed Exception: %s", _exc)
                return
            MBTI_FUNC_USER_SESSIONS[str(uid)] = {
                "q_idx": 0,
                "scores": {fn: 0 for fn in MBTI_FUNC_INFO.keys()},
                "owner_id": uid
            }
            _save_mbti_func_sessions()
            await _mbtifunc_show_q(query, uid)
            return

    if action == "start":
        # چەکی Premium لە کاتی دەستپێکردنی تێستەکەدا
        if not _is_func_allowed(uid):
            await answered("🔒 ئەم تێستە Premium ە — ڕێگەت پێنەدراوە!", show_alert=True)
            return
        MBTI_FUNC_USER_SESSIONS[str(uid)] = {
            "q_idx": 0,
            "scores": {fn: 0 for fn in MBTI_FUNC_INFO.keys()},
            "owner_id": uid
        }
        _save_mbti_func_sessions()
        await _mbtifunc_show_q(query, uid)

    elif action == "ans":
        ans = parts[2] if len(parts) > 2 else "3"
        sess = MBTI_FUNC_USER_SESSIONS.get(str(uid))
        if not sess:
            await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کات بەسەرچوو! تکایە /mbtifunc بنووسە.")
            return
        q_idx = sess["q_idx"]
        if q_idx < len(MBTI_FUNC_QUESTIONS):
            q = MBTI_FUNC_QUESTIONS[q_idx]
            fn = q["fn"]
            try:
                raw_val = int(ans)
                # 5=زۆر بە توندی ڕازیم (5 خاڵ), 1=بە توندی ڕازی نیم (1 خاڵ)
                score_val = raw_val
            except ValueError:
                score_val = 3
            sess["scores"][fn] = sess["scores"].get(fn, 0) + score_val
            sess.setdefault("ans_log", []).append({"t": fn, "val": score_val})
        sess["q_idx"] += 1
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]
        if sess["q_idx"] >= len(MBTI_FUNC_QUESTIONS):
            scores = sess["scores"]
            del MBTI_FUNC_USER_SESSIONS[str(uid)]
            _save_mbti_func_sessions()
            _MBTIFUNC_KB_CACHE.pop(uid, None)
            await _show_mbtifunc_result(query, scores)
        else:
            await _mbtifunc_show_q(query, uid)

    elif action == "view":
        fn = parts[2] if len(parts) > 2 else "Te"
        await _show_mbtifunc_info(query, fn, uid=clicker_uid)

    elif action == "back":
        keyboard = [
            [_ebtn("دەستپێکردنی تاقیکردنەوە", f"mbtifunc:start:{clicker_uid}", emoji_id="5381961872952038862", api_kwargs={"style": "success"})],
            [
                _ebtn("Te", "mbtifunc:view:Te", api_kwargs={"icon_custom_emoji_id": "5341715473882955310", "style": "primary"}),
                _ebtn("Ti", "mbtifunc:view:Ti", api_kwargs={"style": "primary", "icon_custom_emoji_id": "5382021607357162402"}),
                _ebtn("Fe", "mbtifunc:view:Fe", api_kwargs={"icon_custom_emoji_id": "5420631872994553493", "style": "primary"}),
                _ebtn("Fi", "mbtifunc:view:Fi", api_kwargs={"icon_custom_emoji_id": "5357584845465730934", "style": "primary"}),
            ],
            [
                _ebtn("Ne", "mbtifunc:view:Ne", emoji_id="5472411062412254753", api_kwargs={"style": "primary"}),
                _ebtn("Ni", "mbtifunc:view:Ni", api_kwargs={"icon_custom_emoji_id": "5782680182775092318", "style": "primary"}),
                _ebtn(f"Se", "mbtifunc:view:Se", emoji_id="5220195537520711716", api_kwargs={"style": "primary"}),
                _ebtn("Si", "mbtifunc:view:Si", emoji_id="5454006698052184265", api_kwargs={"style": "primary"}),
            ],
        ]
        await _safe_edit(query, "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> تاقیکردنەوەی فەنکشنی کۆگنیتیڤی MBTI\n\nفەنکشنێک هەڵبژێرە:", reply_markup=InlineKeyboardMarkup(keyboard))

    elif action == "prev":
        # <tg-emoji emoji-id=\"5456187398977247949\">⬅️</tg-emoji> گەڕانەوەی هێڵ — سکۆری دواین وەڵام کەم دەکات
        sess = MBTI_FUNC_USER_SESSIONS.get(str(uid))
        if not sess or sess.get("q_idx", 0) == 0:
            await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            fn = last.get("t")
            val = last.get("val", 0)
            if fn and fn in sess.get("scores", {}):
                sess["scores"][fn] = max(0, sess["scores"].get(fn, 0) - val)
            sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _MBTIFUNC_KB_CACHE.clear()
        _save_mbti_func_sessions()
        await _mbtifunc_show_q(query, uid)

    elif action == "confirmcancel":
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەکە؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"mbtifunc:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"mbtifunc:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))

    elif action == "resume":
        if str(uid) in MBTI_FUNC_USER_SESSIONS:
            await _mbtifunc_show_q(query, uid)
        else:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ تاقیکردنەوەیەکی چالاکت نییە.")
        return

    elif action == "cancel":
        if str(uid) in MBTI_FUNC_USER_SESSIONS:
            del MBTI_FUNC_USER_SESSIONS[str(uid)]
            _save_mbti_func_sessions()
            _MBTIFUNC_KB_CACHE.clear()
        await _safe_edit(query, _TGX + " تاقیکردنەوەکە هەڵوەشایەوە. بۆ دەستپێکردنەوە /mbtifunc بنووسە.")


