async def ennea_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    clicker_uid = query.from_user.id
    parts = query.data.split(":", 3)
    action = parts[1]

    cb_uid = None
    if len(parts) >= 3:
        try:
            cb_uid = int(parts[-1])
        except (ValueError, IndexError):
            cb_uid = None

    uid = cb_uid if cb_uid else clicker_uid

    # ── چەکی خاوەنداری بۆ هەموو actionەکان جگە لە view ──
    if action not in ("view", "back") and cb_uid and str(clicker_uid) != str(cb_uid):
        try: await answered("🔒 ئەم تێستە هی تۆ نییە! تێستی خۆت بکە /ennea", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action not in ("start", "back", "view", "prev", "ans", "cancel", "confirmcancel"):
        sess = ENNEA_USER_SESSIONS.get(str(uid))
        if not sess:
            ENNEA_USER_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {i: 0 for i in range(1, 10)}, "owner_id": uid}
            _save_ennea_sessions()
            await _ennea_show_q(query, uid)
            return

    # ── دەستپێکردن ──
    if action == "start":
        ENNEA_USER_SESSIONS[str(uid)] = {
            "q_idx": 0,
            "scores": {i: 0 for i in range(1, 10)},
            "owner_id": uid
        }
        _save_ennea_sessions()
        await _ennea_show_q(query, uid)

    # ── وەڵامدان ──
    elif action == "ans":
        ans = parts[2] if len(parts) > 2 else "no"
        sess = ENNEA_USER_SESSIONS.get(str(uid))
        if not sess:
            await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کات بەسەرچوو! تکایە /ennea بنووسە.")
            return
        q_idx = sess["q_idx"]
        score_map = {"5": 5, "4": 4, "3": 3, "2": 2, "1": 1, "yes": 5, "no": 1}
        if q_idx < len(ENNEA_QUESTIONS):
            q = ENNEA_QUESTIONS[q_idx]
            score_val = score_map.get(ans, 0)
            if score_val > 0:
                sess["scores"][q["t"]] = sess["scores"].get(q["t"], 0) + score_val
            sess.setdefault("ans_log", []).append({"t": q["t"], "val": score_val})
            sess["q_idx"] += 1
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]
        if sess["q_idx"] >= len(ENNEA_QUESTIONS):
            result = _calc_ennea(sess["scores"])
            scores = dict(sess["scores"])
            del ENNEA_USER_SESSIONS[str(uid)]; _save_ennea_sessions(); _ENNEA_KB_CACHE.pop(uid, None)
            await _ennea_show_result(query, result, scores)
        else:
            await _ennea_show_q(query, uid)

    # ── بینینی جۆرێک ──
    elif action == "view":
        t = int(parts[2]) if len(parts) > 2 else 1
        await _ennea_show_type(query, t)

    # ── گەڕانەوە ──
    elif action == "back":
        keyboard = [
            [_ebtn("دەستپێکردنی تاقیکردنەوەی کامڵ (١٨٠ پرسیار)", "ennea:start", emoji_id="5381961872952038862", api_kwargs={"style": "success"})],
            [
                _ebtn("١ ", "ennea:view:1", emoji_id="5400250414929041085", api_kwargs={"style": "primary"}),
                _ebtn("٢", "ennea:view:2", api_kwargs={"icon_custom_emoji_id": "5420631872994553493", "style": "primary"}),
                _ebtn("٣", "ennea:view:3", emoji_id="5462927083132970373", api_kwargs={"style": "primary"}),
            ],
            [
                _ebtn("٤ ", "ennea:view:4", emoji_id="5380041425570275675", api_kwargs={"style": "primary"}),
                _ebtn("٥", "ennea:view:5", api_kwargs={"icon_custom_emoji_id": "5217751293107381480", "style": "primary"}),
                _ebtn("٦", "ennea:view:6", emoji_id="5454006698052184265", api_kwargs={"style": "primary"}),
            ],
            [
 _ebtn("٧", "ennea:view:7", emoji_id="5787166284705699232", api_kwargs={"style": "primary"}),
                _ebtn("٨", "ennea:view:8", emoji_id="5471936197943106990", api_kwargs={"style": "primary"}),
                _ebtn("٩","ennea:view:9", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5438652692480169323"),
            ],
        ]
        await _safe_edit(query, "<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> تاقیکردنەوەی ئێنیاگرام\n\nجۆرێک هەڵبژێرە بۆ بینینی زانیارییەکان:", reply_markup=InlineKeyboardMarkup(keyboard))

    elif action == "prev":
        # <tg-emoji emoji-id=\"5456187398977247949\">⬅️</tg-emoji> گەڕانەوەی هێڵ
        sess = ENNEA_USER_SESSIONS.get(str(uid))
        if not sess or sess.get("q_idx", 0) == 0:
            await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True); return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            t = last.get("t"); val = last.get("val", 0)
            if t in sess.get("scores", {}):
                sess["scores"][t] = max(0, sess["scores"].get(t, 0) - val)
            sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _ENNEA_KB_CACHE.clear()
        _save_ennea_sessions()
        await _ennea_show_q(query, uid)

    # ── دڵنیابوونەوە پێش هەڵوەشاندنەوە ──
    elif action == "confirmcancel":
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی ئێنیاگرام؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"ennea:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"ennea:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))

    # ── هەڵوەشاندنەوە ──
    elif action == "resume":
        if str(uid) in ENNEA_USER_SESSIONS:
            await _ennea_show_q(query, uid)
        else:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ تاقیکردنەوەیەکی چالاکت نییە.")
        return

    elif action == "cancel":
        if str(uid) in ENNEA_USER_SESSIONS:
            del ENNEA_USER_SESSIONS[str(uid)]; _save_ennea_sessions(); _ENNEA_KB_CACHE.clear()
        await _safe_edit(query, _TGX + " تاقیکردنەوەکە هەڵوەشایەوە. بۆ دەستپێکردنەوە /ennea بنووسە.")


# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Cached keyboard بۆ ennea
# FIX [BUG-2]: _ENNEA_KB_CACHE ئێستا لە main.py دادەنرێت — دوبارەکردنەوە لابرا

async def _ennea_show_q(query, uid: int):
    sess = ENNEA_USER_SESSIONS.get(str(uid))
    if not sess:
        try: await query.edit_message_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کێشەیەک ڕوویدا. /ennea بنووسە.", parse_mode="HTML")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    q_idx = sess["q_idx"]
    total = len(ENNEA_QUESTIONS)
    if q_idx >= total:
        return
    q = ENNEA_QUESTIONS[q_idx]
    pct = int((q_idx / total) * 100)
    progress_bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
    text = (
        f"<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> تاقیکردنەوەی ئێنیاگرام\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TCH} پرۆسێس: [{progress_bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> پرسیاری {q_idx+1} لە {total}\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{q['q']}</b>"
    )
    try:
        await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup(_ennea_kb(uid, q_idx)))
    except Exception as e:
        if "not modified" not in str(e).lower():
            raise

async def _ennea_show_type(query, t: int):
    info = ENNEA_TYPES.get(t, ENNEA_TYPES[1])
    # جۆرە پەیوەندیدارەکان
    prev_t = (t - 2) % 9 + 1
    next_t = t % 9 + 1
    keyboard = [
        [
            _ebtn(f"جۆری {prev_t}", f"ennea:view:{prev_t}", emoji_id="5255703720078879038", api_kwargs={"style": "primary"}),
            _ebtn(f"جۆری {next_t}", f"ennea:view:{next_t}", emoji_id="6282822561684263060", api_kwargs={"style": "primary"}),
        ],
        [_ebtn("گەڕانەوە", "ennea:back", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})],
    ]
    text = (
        f"{info['color']} جۆری {t}: {info['name']} {info['emoji']}\n"
        f"_{info['en']}_\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5442679189960431377\">😨</tg-emoji> ترسی سەرەکی: {info['core_fear']}\n"
        f"<tg-emoji emoji-id=\"5938293140036259040\">💫</tg-emoji> ئارەزووی سەرەکی: {info['core_desire']}\n\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> وەسف:\n{info['desc']}\n\n"
        f"{_TCK} خاڵە بەهێزەکان: {info['strengths']}\n"
        f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> خاڵە لاوازەکان: {info['weakness']}\n"
        f"🪽 بالەکانت: {info['wings']}\n"
        f"<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> کاتی گەشەپێدان: {info['growth']}\n"
        f"<tg-emoji emoji-id=\"5393589131106359852\">📉</tg-emoji> کاتی سترێس: {info['stress']}\n"
        f"<tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji> کارەکانی گونجاو: {info['career']}\n"
        f"💕 لە پەیوەندیدا: {info['love']}\n"
        f"<tg-emoji emoji-id=\"5399898266265475100\">🌍</tg-emoji> لە جیهاندا: {info['percent']} لە مرۆڤەکان\n"
        f"<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> کەسانی ناسراو: {info['famous']}\n"
        f"🎌 هاوشێوە لە ئەنیمێ: _{info['anime_char']}_"
    )
    await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup(keyboard))


