async def ichazo_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    clicker_uid = query.from_user.id
    parts = query.data.split(":", 3)
    action = parts[1]

    cb_uid = None
    if len(parts) >= 3:
        try:
            cb_uid = int(parts[-1])
        except (ValueError, IndexError):
            cb_uid = None

    uid = cb_uid if cb_uid else clicker_uid

    # چەکی مۆڵەتی پریمیوم
    if action == "start" and not _is_adv_allowed(clicker_uid, "ichazo"):
        await answered(_adv_premium_alert("Ichazo Enneagram", "🔯"), show_alert=True)
        return

    if action not in ("view", "back") and cb_uid and str(clicker_uid) != str(cb_uid):
        await answered("🔒 ئەم تێستە هی تۆ نییە! تێستی خۆت بکە /ichazo", show_alert=True)
        return

    if action == "start":
        ICHAZO_USER_SESSIONS[str(uid)] = {
            "q_idx": 0,
            "scores": {i: 0 for i in range(1, 10)},
            "owner_id": uid
        }
        _save_ichazo_sessions()
        await _ichazo_show_q(query, uid)

    elif action == "ans":
        ans = parts[2] if len(parts) > 2 else "no"
        sess = ICHAZO_USER_SESSIONS.get(str(uid))
        if not sess:
            await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کات بەسەرچوو! تکایە /ichazo بنووسە.")
            return
        q_idx = sess["q_idx"]
        score_map = {"5": 5, "4": 4, "3": 3, "2": 2, "1": 1}
        if q_idx < len(ICHAZO_QUESTIONS):
            q = ICHAZO_QUESTIONS[q_idx]
            score_val = score_map.get(ans, 0)
            sess["scores"][q["t"]] = sess["scores"].get(q["t"], 0) + score_val
            sess.setdefault("ans_log", []).append({"t": q["t"], "val": score_val})
            sess["q_idx"] += 1
        if sess["q_idx"] >= len(ICHAZO_QUESTIONS):
            result = _calc_ichazo(sess["scores"])
            scores = dict(sess["scores"])
            del ICHAZO_USER_SESSIONS[str(uid)]
            _save_ichazo_sessions()
            [_ICHAZO_KB_CACHE.pop(k, None) for k in [(uid, True), (uid, False)]]
            await _ichazo_show_result(query, result, scores)
        else:
            await _ichazo_show_q(query, uid)

    elif action == "view":
        t = int(parts[2]) if len(parts) > 2 else 1
        await _ichazo_show_type(query, t)

    elif action == "back":
        keyboard = [
            [_ebtn("Ichazo Enneagram (400 Q)", "icz:start", emoji_id="5463289097336405244", api_kwargs={"style": "success"})],
            [
                _ebtn("١ ", "icz:view:1", emoji_id="5400250414929041085", api_kwargs={"style": "primary"}),
                _ebtn("٢", "icz:view:2", api_kwargs={"icon_custom_emoji_id": "5420631872994553493", "style": "primary"}),
                _ebtn("٣", "icz:view:3", emoji_id="5462927083132970373", api_kwargs={"style": "primary"}),
            ],
            [
                _ebtn("٤ ", "icz:view:4", emoji_id="5380041425570275675", api_kwargs={"style": "primary"}),
                _ebtn("٥", "icz:view:5", api_kwargs={"icon_custom_emoji_id": "5217751293107381480", "style": "primary"}),
                _ebtn("٦", "icz:view:6", emoji_id="5454006698052184265", api_kwargs={"style": "primary"}),
            ],
            [
 _ebtn("٧", "icz:view:7", emoji_id="5787166284705699232", api_kwargs={"style": "primary"}),
                _ebtn("٨", "icz:view:8", emoji_id="5471936197943106990", api_kwargs={"style": "primary"}),
                _ebtn("٩","icz:view:9", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5438652692480169323"),
            ],
        ]
        await _safe_edit(query, "<tg-emoji emoji-id=\"5463289097336405244\">🔯</tg-emoji> ئینیاگرامی ئیچازۆ\n\nجۆرێک هەڵبژێرە بۆ بینینی زانیارییەکان:", reply_markup=InlineKeyboardMarkup(keyboard))

    elif action == "prev":
        sess = ICHAZO_USER_SESSIONS.get(str(uid))
        if not sess or sess.get("q_idx", 0) == 0:
            await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            t = last.get("t"); val = last.get("val", 0)
            if t in sess.get("scores", {}):
                sess["scores"][t] = max(0, sess["scores"].get(t, 0) - val)
            sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _ICHAZO_KB_CACHE.clear()
        _save_ichazo_sessions()
        await _ichazo_show_q(query, uid)

    elif action == "confirmcancel":
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی ئیچازۆ؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"icz:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"icz:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))

    elif action == "resume":
        if str(uid) in ICHAZO_USER_SESSIONS:
            await _ichazo_show_q(query, uid)
        else:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ تاقیکردنەوەیەکی چالاکت نییە.")
        return

    elif action == "cancel":
        if str(uid) in ICHAZO_USER_SESSIONS:
            del ICHAZO_USER_SESSIONS[str(uid)]
            _save_ichazo_sessions()
            _ICHAZO_KB_CACHE.clear()
        await _safe_edit(query, _TGX + " تاقیکردنەوەکە هەڵوەشایەوە. بۆ دەستپێکردنەوە /ichazo بنووسە.")


