async def naranjo_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    clicker_uid = query.from_user.id
    parts = query.data.split(":", 3)
    action = parts[1]

    cb_uid = None
    if len(parts) >= 3:
        try:
            cb_uid = int(parts[-1])
        except (ValueError, IndexError):
            cb_uid = None

    uid = cb_uid if cb_uid else clicker_uid

    if action == "start" and not _is_adv_allowed(clicker_uid, "naranjo"):
        await answered(_adv_premium_alert("Naranjo Enneagram", "🧬"), show_alert=True)
        return

    if action not in ("view", "back") and cb_uid and str(clicker_uid) != str(cb_uid):
        await answered("🔒 ئەم تێستە هی تۆ نییە! تێستی خۆت بکە /naranjo", show_alert=True)
        return

    if action == "start":
        NARANJO_USER_SESSIONS[str(uid)] = {
            "q_idx": 0,
            "scores": {i: 0 for i in range(1, 10)},
            "owner_id": uid
        }
        _save_naranjo_sessions()
        await _naranjo_show_q(query, uid)

    elif action == "ans":
        ans = parts[2] if len(parts) > 2 else "no"
        sess = NARANJO_USER_SESSIONS.get(str(uid))
        if not sess:
            await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کات بەسەرچوو! تکایە /naranjo بنووسە.")
            return
        q_idx = sess["q_idx"]
        score_map = {"5": 5, "4": 4, "3": 3, "2": 2, "1": 1}
        if q_idx < len(NARANJO_QUESTIONS):
            q = NARANJO_QUESTIONS[q_idx]
            score_val = score_map.get(ans, 0)
            sess["scores"][q["t"]] = sess["scores"].get(q["t"], 0) + score_val
            sess.setdefault("ans_log", []).append({"t": q["t"], "val": score_val})
            sess["q_idx"] += 1
        if sess["q_idx"] >= len(NARANJO_QUESTIONS):
            result = _calc_naranjo(sess["scores"])
            scores = dict(sess["scores"])
            del NARANJO_USER_SESSIONS[str(uid)]
            _save_naranjo_sessions()
            [_NARANJO_KB_CACHE.pop(k, None) for k in [(uid, True), (uid, False)]]
            await _naranjo_show_result(query, result, scores)
        else:
            await _naranjo_show_q(query, uid)

    elif action == "view":
        t = int(parts[2]) if len(parts) > 2 else 1
        await _naranjo_show_type(query, t)

    elif action == "back":
        keyboard = [
            [_ebtn("Naranjo Enneagram (351 Q)", "nrj:start", emoji_id="5386830501849897881", api_kwargs={"style": "success"})],
            [
                _ebtn("١ ", "nrj:view:1", emoji_id="5400250414929041085", api_kwargs={"style": "primary"}),
                _ebtn("٢", "nrj:view:2", api_kwargs={"icon_custom_emoji_id": "5420631872994553493", "style": "primary"}),
                _ebtn("٣", "nrj:view:3", emoji_id="5462927083132970373", api_kwargs={"style": "primary"}),
            ],
            [
                _ebtn("٤ ", "nrj:view:4", emoji_id="5380041425570275675", api_kwargs={"style": "primary"}),
                _ebtn("٥", "nrj:view:5", api_kwargs={"icon_custom_emoji_id": "5217751293107381480", "style": "primary"}),
                _ebtn("٦", "nrj:view:6", emoji_id="5454006698052184265", api_kwargs={"style": "primary"}),
            ],
            [
 _ebtn("٧", "nrj:view:7", emoji_id="5787166284705699232", api_kwargs={"style": "primary"}),
                _ebtn("٨", "nrj:view:8", emoji_id="5471936197943106990", api_kwargs={"style": "primary"}),
                _ebtn("٩","nrj:view:9", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5438652692480169323"),
            ],
        ]
        await _safe_edit(query, "<tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> ئینیاگرامی نارانخۆ\n\nجۆرێک هەڵبژێرە بۆ بینینی زانیارییەکان:", reply_markup=InlineKeyboardMarkup(keyboard))

    elif action == "prev":
        sess = NARANJO_USER_SESSIONS.get(str(uid))
        if not sess or sess.get("q_idx", 0) == 0:
            await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            t = last.get("t"); val = last.get("val", 0)
            if t in sess.get("scores", {}):
                sess["scores"][t] = max(0, sess["scores"].get(t, 0) - val)
            sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _NARANJO_KB_CACHE.clear()
        _save_naranjo_sessions()
        await _naranjo_show_q(query, uid)

    elif action == "confirmcancel":
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی نارانخۆ؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"nrj:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"nrj:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))

    elif action == "resume":
        if str(uid) in NARANJO_USER_SESSIONS:
            await _naranjo_show_q(query, uid)
        else:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ تاقیکردنەوەیەکی چالاکت نییە.")
        return

    elif action == "cancel":
        if str(uid) in NARANJO_USER_SESSIONS:
            del NARANJO_USER_SESSIONS[str(uid)]
            _save_naranjo_sessions()
            _NARANJO_KB_CACHE.clear()
        await _safe_edit(query, _TGX + " تاقیکردنەوەکە هەڵوەشایەوە. بۆ دەستپێکردنەوە /naranjo بنووسە.")


