async def socionics_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    clicker_uid = query.from_user.id
    parts = query.data.split(":", 3)
    action = parts[1]

    cb_uid = None
    if len(parts) >= 3:
        try:
            cb_uid = int(parts[-1])
        except (ValueError, IndexError):
            cb_uid = None

    uid = cb_uid if cb_uid else clicker_uid

    # ── چەکی خاوەنداری بۆ هەموو actionەکان جگە لە view ──
    if action not in ("view", "menu") and cb_uid and str(clicker_uid) != str(cb_uid):
        try: await answered("🔒 ئەم تێستە هی تۆ نییە! تێستی خۆت بکە /socionics", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action not in ("start", "menu", "view", "confirmcancel"):
        sess = SOCIONICS_USER_SESSIONS.get(str(uid))
        if not sess:
            SOCIONICS_USER_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {"E":0,"I":0,"S":0,"N":0,"T":0,"F":0,"J":0,"P":0,"Te":0,"Ti":0,"Fe":0,"Fi":0,"Se":0,"Si":0,"Ne":0,"Ni":0}, "owner_id": uid}
            _save_socionics_sessions()
            await _socionics_show_q(query, uid)
            return

    # ── دەستپێکردن ──
    if action == "start":
        SOCIONICS_USER_SESSIONS[str(uid)] = {
            "q_idx": 0,
            "scores": {"E": 0, "I": 0, "S": 0, "N": 0, "T": 0, "F": 0, "J": 0, "P": 0, "Te": 0, "Ti": 0, "Fe": 0, "Fi": 0, "Se": 0, "Si": 0, "Ne": 0, "Ni": 0},
            "owner_id": uid
        }
        _save_socionics_sessions()
        await _socionics_show_q(query, uid)

    # ── وەڵامدان ──
    elif action == "ans":
        sess = SOCIONICS_USER_SESSIONS.get(str(uid))
        if not sess:
            await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کات بەسەرچوو! تکایە /socionics بنووسە.")
            return
        answer = parts[2] if len(parts) > 2 else ""
        q_idx = sess["q_idx"]
        if q_idx < len(SOCIONICS_QUESTIONS):
            q = SOCIONICS_QUESTIONS[q_idx]
            score_map = {"5": 2, "4": 1, "3": 0, "2": -1, "1": -2}
            delta = score_map.get(answer, 0)
            if delta > 0:
                sess["scores"][q["pos"]] = sess["scores"].get(q["pos"], 0) + delta
            elif delta < 0:
                sess["scores"][q["neg"]] = sess["scores"].get(q["neg"], 0) + abs(delta)
            sess.setdefault("ans_log", []).append({"t": q.get("pos", q.get("neg", "?")), "val": abs(delta)})
            sess["q_idx"] += 1
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]
        if sess["q_idx"] >= len(SOCIONICS_QUESTIONS):
            result_code = _calc_socionics(sess["scores"])
            del SOCIONICS_USER_SESSIONS[str(uid)]; _save_socionics_sessions(); _SOC_KB_CACHE.pop(uid, None)
            await _show_socionics_result(query, result_code, sess["scores"])
        else:
            await _socionics_show_q(query, uid)

    # ── هەڵوەشاندنەوە ──
    if action == "back":
        sess = SOCIONICS_USER_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        await _socionics_show_q(query, uid, edit=True); return
    elif action == "confirmcancel":
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی سۆسیۆنیکس؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"soc:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"soc:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))

    elif action == "resume":
        if str(uid) in SOCIONICS_USER_SESSIONS:
            await _socionics_show_q(query, uid)
        else:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ تاقیکردنەوەیەکی چالاکت نییە.")
        return

    elif action == "cancel":
        if str(uid) in SOCIONICS_USER_SESSIONS:
            del SOCIONICS_USER_SESSIONS[str(uid)]; _save_socionics_sessions(); _SOC_KB_CACHE.pop(uid, None)
        await _safe_edit(query, _TGX + " تاقیکردنەوەی سۆسیۆنیکس هەڵوەشێنرایەوە.")

    # ── بینینی جۆرێک ──
    elif action == "view":
        code = parts[2] if len(parts) > 2 else ""
        info = SOCIONICS_TYPES.get(code)
        if not info:
            await _safe_edit(query, _TGX + " ئەم جۆرە نەدۆزرایەوە.")
            return
        text = (
            f"{info['emoji']} <b>{info['name']}</b>\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"{info['desc']}"
        )
        kb = [[_ebtn("گەڕانەوە", "soc:menu", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]
        await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup(kb))

    # ── مێنیوی سەرەکی ──
    elif action == "menu":
        keyboard = [
            [_ebtn("دەستپێکردنی تاقیکردنەوە (١٠٨ پرسیار)", "soc:start", emoji_id="5381961872952038862", api_kwargs={"style": "success"})],
            [
                _ebtn("ILI", "soc:view:ILI", api_kwargs={"icon_custom_emoji_id": "5217751293107381480", "style": "primary"}),
                _ebtn("LII", "soc:view:LII", api_kwargs={"icon_custom_emoji_id": "5213306719215577669", "style": "primary"}),
 _ebtn("ESE", "soc:view:ESE", emoji_id="5787166284705699232", api_kwargs={"style": "primary"}),
                _ebtn("SEI", "soc:view:SEI", api_kwargs={"icon_custom_emoji_id": "5330434012135571793", "style": "primary"}),
            ],
            [
                _ebtn("LIE", "soc:view:LIE", api_kwargs={"style": "primary", "icon_custom_emoji_id": "5195033767969839232"}),
                _ebtn(f"ILE", "soc:view:ILE", emoji_id="5220195537520711716", api_kwargs={"style": "primary"}),
                _ebtn("EIE ", "soc:view:EIE", emoji_id="5380041425570275675", api_kwargs={"style": "primary"}),
                _ebtn("IEI", "soc:view:IEI", api_kwargs={"style": "primary", "icon_custom_emoji_id": "5415765090932641459"}),
            ],
            [
                _ebtn("SLE", "soc:view:SLE", emoji_id="5454006698052184265", api_kwargs={"style": "primary"}),
                _ebtn("LSE", "soc:view:LSE", emoji_id="5472411062412254753", api_kwargs={"style": "primary"}),
                _ebtn("IEE", "soc:view:IEE", api_kwargs={"icon_custom_emoji_id": "5357584845465730934", "style": "primary"}),
                _ebtn("EII","soc:view:EII", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5206525811963757327"),
            ],
            [
                _ebtn("LSI", "soc:view:LSI", api_kwargs={"icon_custom_emoji_id": "5462921117423384478", "style": "primary"}),
                _ebtn("SLI", "soc:view:SLI", api_kwargs={"icon_custom_emoji_id": "5332394179374884835", "style": "primary"}),
                _ebtn("ESI", "soc:view:ESI", api_kwargs={"icon_custom_emoji_id": "5287519334569097506", "style": "primary"}),
                _ebtn("SEE", "soc:view:SEE", emoji_id="5472411062412254753", api_kwargs={"style": "primary"}),
            ],
        ]
