# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> cached keyboard بۆ socionics
_SOC_KB_CACHE: dict = {}

async def _socionics_show_q(query, uid: int, edit: bool = False):
    sess = SOCIONICS_USER_SESSIONS.get(str(uid))
    if not sess:
        return
    q_idx = sess["q_idx"]
    total = len(SOCIONICS_QUESTIONS)
    if q_idx >= total:
        return
    q = SOCIONICS_QUESTIONS[q_idx]
    progress = int((q_idx / total) * 10)
    bar = "█" * progress + "░" * (10 - progress)
    text = (
        f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji> تاقیکردنەوەی سۆسیۆنیکس\n"
        f"[{bar}] {q_idx+1}/{total}\n\n"
        f"<b>{q['q']}</b>"
    )
    markup = InlineKeyboardMarkup(_soc_kb(uid, q_idx, total))
    try:
        if edit:
            try:
                await query.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
            except Exception as _exc:
                if "not modified" not in str(_exc).lower():
                    await query.message.reply_text(text, parse_mode="HTML", reply_markup=markup)
        else:
            await _safe_edit(query, text, reply_markup=markup)
    except Exception as e:
        if "not modified" not in str(e).lower():
            raise

async def _show_socionics_result(query, code: str, scores: dict):
    save_test_result(query.from_user.id, "socionics", {
        "type": code,
        "name": SOCIONICS_TYPES.get(code, {}).get("name", code),
        "emoji": SOCIONICS_TYPES.get(code, {}).get("emoji", ""),
        "mbti_equiv": SOCIONICS_TYPES.get(code, {}).get("mbti_equiv", ""),
    })
    info = SOCIONICS_TYPES.get(code, {})
    name = info.get("name", code)
    emoji = info.get("emoji", "<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji>")
    raw_desc = info.get("desc", "")
    mbti_equiv = info.get("mbti_equiv", "")

    # سڕینەوەی * ی زیادە
    desc_lines = []
    for line in raw_desc.split("\n"):
        cleaned = line.strip("* ").rstrip("* ")
        desc_lines.append(cleaned)
    desc = "\n".join(desc_lines)

    def bar(a, b, la, lb):
        total = a + b
        pa = int((a / total) * 10) if total else 5
        pb = 10 - pa
        return f"`{la} {'█'*pa}{'░'*pb} {lb}`  ({a}/{b})"

    ei_bar = bar(scores.get("E",0), scores.get("I",0), "E", "I")
    sn_bar = bar(scores.get("S",0), scores.get("N",0), "S", "N")
    tf_bar = bar(scores.get("T",0), scores.get("F",0), "T", "F")
    jp_bar = bar(scores.get("J",0), scores.get("P",0), "J", "P")

    mbti_line = ""  # سڕایەوە لەلایەن داواکاری بەکارهێنەر

    text = (
        f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji> ئەنجامی سۆسیۆنیکست\n"
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"*{emoji} {name}*\n"
        f"{mbti_line}\n"
        f"{desc}\n\n"
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TCH} نمرەکانت:\n"
        f"{ei_bar}\n{sn_bar}\n{tf_bar}\n{jp_bar}"
    )
    kb = [[_ebtn("دووبارە تاقیکردنەوە", "soc:start", emoji_id="5353025084845994828", api_kwargs={"style": "success"}),
           _ebtn("مێنیو", "soc:menu", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]
    await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup(kb))


