async def zombie_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    uid = query.from_user.id
    p = get_zombie_player(uid)
    action = query.data.split(":")[1]

    def _kb():
        return InlineKeyboardMarkup([
            [_ebtn("🔫 تەقە بکە", "zomb:fight", api_kwargs={"style": "primary"}),
             _ebtn("ڕابکە", "zomb:escape", emoji_id="5235545969679935681", api_kwargs={"style": "primary"})],
            [_ebtn("چاککردنەوە", "zomb:repair", api_kwargs={"icon_custom_emoji_id": "5462921117423384478", "style": "primary"}),
             _ebtn("گەڕان", "zomb:scavenge", api_kwargs={"icon_custom_emoji_id": "5463172695132745432", "style": "primary"})],
        ])

    z_count = p["wave"] + random.randint(0,2)
    
    if action == "fight":
        if p["ammo"] <= 0:
            await answered("🔫 فیشەکت نەماوە! بگەڕێ بۆ فیشەک.", show_alert=True); return
        shots = min(p["ammo"], z_count)
        p["ammo"] -= shots
        killed = min(shots, z_count)
        p["kills"] += killed
        survived = z_count - killed
        if survived > 0:
            dmg = survived * random.randint(5,12)
            p["hp"] = max(0, p["hp"]-dmg)
            p["barricade"] = max(0, p["barricade"]-10)
        if p["hp"] > 0 and p["kills"] % 10 == 0:
            p["wave"] += 1
        save_zombie()
        msg = f"🔫 {killed} زۆمبیت کوشت! {survived} زۆمبی نزیکبوونەوە. زیان: {(survived*10) if survived else 0} HP"

    elif action == "escape":
        success = random.random() > 0.4
        if success:
            p["hp"] = min(100, p["hp"]+10)
            msg = "<tg-emoji emoji-id=\"5235545969679935681\">🏃</tg-emoji> ڕزگارت بوو! کاتت بەدەستهێنا بۆ حەسانەوە."
        else:
            dmg = random.randint(10,25)
            p["hp"] = max(0, p["hp"]-dmg)
            msg = f"<tg-emoji emoji-id=\"5235545969679935681\">🏃</tg-emoji> نەتتوانی ڕابکەیت! زیان: -{dmg} HP"
        save_zombie()

    elif action == "repair":
        p["barricade"] = min(100, p["barricade"]+25)
        msg = f"<tg-emoji emoji-id=\"5462921117423384478\">🔧</tg-emoji> بەربەستەکە چاککرایەوە! {p['barricade']}/100"
        save_zombie()

    elif action == "scavenge":
        found = random.randint(2,8)
        p["ammo"] += found
        dmg = random.randint(0,15)
        p["hp"] = max(0, p["hp"]-dmg)
        msg = f"<tg-emoji emoji-id=\"5463172695132745432\">📦</tg-emoji> {found} فیشەکت دۆزیەوە! {('-'+str(dmg)+' HP') if dmg else 'بە سەلامەتی گەڕایتەوە!'}"
        save_zombie()

    elif action == "status":
        msg = f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ {p['hp']}  🔫 {p['ammo']}  🧱 {p['barricade']}  <tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> {p['kills']}"

    if not p.get("alive", True) or p["hp"] <= 0:
        p["alive"] = False
        save_zombie()
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5447498242050792295\">☠</tg-emoji> زۆمبییەکان خواردیانیت!\n\n<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> کوژراو: {p['kills']} | قۆناغ: {p['wave']}\n\nبۆ دەستپێکردنەوە بنووسە: /zombie")
        return

    await _safe_edit(query, f"<tg-emoji emoji-id=\"5458708089513472966\">🧟</tg-emoji> قۆناغی {p['wave']}\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n{msg}\n\n"
        f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ {p['hp']}  🔫 {p['ammo']}  🧱 {p['barricade']}  <tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> {p['kills']}", reply_markup=_kb())

