async def personality_analyzer_cmd(update: Update, context: CallbackContext):
    uid = update.effective_user.id
    msgs = USER_MSG_HISTORY.get(uid, [])
    if len(msgs) < 5:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> شیکاری کەسایەتی\n\n"
            "پێویستە لانیکەم ٥ نامە بنووسیت تا بتوانم شیکاری کەسایەتیت بکەم.\n\n"
            f"ئێستا: {len(msgs)}/5 نامە تۆمار کراوە.\n\n"
            "زیاتر قسە بکە!", parse_mode="HTML"); return

    all_text = " ".join(msgs[-50:])
    scores = {k: sum(1 for w in v if w in all_text) for k, v in PERSONALITY_KEYWORDS.items()}
    top = sorted(scores, key=scores.get, reverse=True)
    
    type_labels = {
        "logical":   ("<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> لۆژیکی","بە لۆژیک و مانتیق بیر دەکەیتەوە و ئامانجگیری"),
        "emotional": ("<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ هەستیار","پەیوەندییەکان و هەستەکان لای تۆ زۆر گرنگن"),
        "creative":  ("<tg-emoji emoji-id=\"5330434012135571793\">🎨</tg-emoji> داهێنەر","خەیاڵت فراوانە و لایەنی هونەریت بەهێزە"),
        "social":    ("<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> کۆمەڵایەتی","حەزت بە تێکەڵبوونی خەڵک و کاری بەکۆمەڵە"),
        "leader":    ("<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> ڕابەر","توانای بڕیاردانت هەیە و بەرپرسیاریەت هەڵدەگریت"),
    }

    lines = "\n".join(
        f"""{_TSP if i==0 else '•'} {type_labels[t][0]}: {scores[t]} خاڵ"""
        for i, t in enumerate(top) if t in type_labels
    )
    main_type = type_labels.get(top[0], ("<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji>","نەناسراو"))
    save_test_result(update.effective_user.id, "personality", {
        "main_type": top[0] if top else "unknown",
        "label": main_type[0],
    })
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> شیکاری کەسایەتی تۆ\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"کەسایەتی سەرەکی: <b>{main_type[0]}</b>\n"
        f"{main_type[1]}\n\n"
        f"خاڵەکان (بەپێی {len(msgs)} نامە):\n{lines}\n\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"تێبینی: ئەمە تەنها پێشبینییەکی ژیری دەستکردە بەپێی قسەکانت!",
        parse_mode="HTML")

