async def mood_detector_cmd(update: Update, context: CallbackContext):
    uid = update.effective_user.id
    msgs = USER_MSG_HISTORY.get(uid, [])
    if not msgs:
        await update.message.reply_text(f"{_TCH} سەرەتا چەند نامەیەک بنووسە تا بتوانم مەزاجت دیاری بکەم!", parse_mode="HTML"); return


    recent = " ".join(msgs[-10:])
    scores = {}
    for mood, data in MOOD_KEYWORDS.items():
        scores[mood] = sum(1 for w in data["words"] if w in recent)
    
    top_mood = max(scores, key=scores.get) if any(scores.values()) else "ئارام"
    mood_data = MOOD_KEYWORDS[top_mood]
    
    advice_map = {
        "خۆشحاڵ":  "<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> بەردەوام بە! شادییەکەت بپارێزە.",
        "خەمگین":  "<tg-emoji emoji-id=\"5420631872994553493\">🤗</tg-emoji> تۆ تەنیا نیت! ئەگەر پێویستت بوو قسە بکە.",
        "تووڕە":   "🧘 ئارام بگرە — هەناسەیەکی قووڵ هەڵکێشە.",
        "ترساو":  "<tg-emoji emoji-id=\"5471936197943106990\">💪</tg-emoji> تۆ دەتوانیت! هەنگاوی بچووک بنێ.",
        "ئارام":   f"{_TCK} زۆر باشیت! باشترین دۆخ هەر ئەمەیە.",
        "بێزار":   "☕ کەمێک پشوو بدە — پێویستت پێیەتی.",
    }
    
    save_test_result(update.effective_user.id, "mood", {
        "top_mood": top_mood,
        "emoji": mood_data["emoji"],
    })
    await update.message.reply_text(
        f"{_TCH} دیاریکەری مەزاج — Mood Detector\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{mood_data['color']} دۆخی ئێستات: *{top_mood} {mood_data['emoji']}*\n\n"
        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> بەپێی {len(msgs[-10:])} پەیامی کۆتاییت\n\n"
        f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> پێشنیار: {advice_map.get(top_mood,'هیوای باشیت بۆ دەخوازم!')}",
        parse_mode="HTML")

