@guarded
async def guess_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    uid = query.from_user.id
    parts = query.data.split(":", 2)
    gtype = parts[1]

    if gtype == "number":
        secret = random.randint(1, 100)
        GUESS_DATA[uid] = {"type":"number","secret":secret,"attempts":0,"max":7}
        await _safe_edit(query, "<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> تەخمینی ژمارە\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            "ژمارەیەکم لە نێوان ١ بۆ ١٠٠ لە دڵم گرتووە!\n"
            "٧ هەولت هەیە. ژمارەکە بنووسە <tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji>")

    elif gtype == "word":
        word = random.choice(GUESS_WORDS)
        hidden = " ".join("_" * len(w) for w in word)
        GUESS_DATA[uid] = {"type":"word","secret":word,"attempts":0,"max":6,"revealed":[]}
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5472411062412254753\">🔤</tg-emoji> تەخمینی وشە\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"وشەیەکم هەڵبژاردووە:\n`{hidden}`\n\n"
            f"وشەکە لە {len(word)} پیت پێکهاتووە. پیتێک بنووسە!")

    elif gtype == "celeb":
        celeb = random.choice(GUESS_CELEBS)
        hint = f"ناوی یەکەم لە {len(celeb.split()[0])} پیت پێکهاتووە"
        GUESS_DATA[uid] = {"type":"celeb","secret":celeb,"attempts":0,"max":5,"hints":1}
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> تەخمینی کەسایەتی\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"بیرم لە کەسایەتییەکی بەناوبانگ کردووەتەوە!\n\n"
            f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> سەرەداو: {hint}\n\n"
            f"ناوی کێیە؟ بنووسە!")

async def handle_guess_answer(update: Update, context: CallbackContext) -> bool:
    uid = update.effective_user.id
    if uid not in GUESS_DATA:
        return False
    g = GUESS_DATA[uid]
    text = update.message.text.strip()

    if g["type"] == "number":
        try:
            guess = int(text)
        except ValueError:
            return False
        g["attempts"] += 1
        secret = g["secret"]
        if guess == secret:
            del GUESS_DATA[uid]
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> ڕاستە! ژمارەکە {secret} بوو! (لە {g['attempts']} هەوڵدا دۆزیتەوە)", parse_mode="HTML")
            return True
        hint = "<tg-emoji emoji-id=\"5395360491583352313\">⬆️</tg-emoji> گەورەترە" if guess < secret else "<tg-emoji emoji-id=\"5443127283898405358\">⬇️</tg-emoji> بچووکترە"
        if g["attempts"] >= g["max"]:
            del GUESS_DATA[uid]
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> هەوڵەکانت تەواو بوو! ژمارەکە {secret} بوو.", parse_mode="HTML")
            return True
        await update.message.reply_text(f"{hint} — {g['max']-g['attempts']} هەوڵی ترت ماوە", parse_mode="HTML")
        return True

    elif g["type"] == "word":
        if len(text) == 1:
            secret = g["secret"]
            g["attempts"] += 1
            if text in secret and text not in g["revealed"]:
                g["revealed"].append(text)
                display = " ".join(c if c in g["revealed"] else "_" for c in secret)
                if "_" not in display:
                    del GUESS_DATA[uid]
                    await update.message.reply_text(f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> پیرۆزە! وشەکە `{secret}` بوو!", parse_mode="HTML")
                    return True
                await update.message.reply_text(f"{_TCK} پیتی `{text}<code> هەیە!\n</code>{display}`", parse_mode="HTML")
            else:
                display = " ".join(c if c in g["revealed"] else "_" for c in secret)
                await update.message.reply_text(f"{_TGX} پیتی `{text}` تێدا نییە — {g['max']-g['attempts']} هەوڵی تر", parse_mode="HTML")
            if g["attempts"] >= g["max"]:
                del GUESS_DATA[uid]
                await update.message.reply_text(f"<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> دۆڕایت! وشەکە `{secret}` بوو.", parse_mode="HTML")
            return True

    elif g["type"] == "celeb":
        g["attempts"] += 1
        secret = g["secret"]
        if text.lower() in secret.lower() or secret.lower() in text.lower():
            del GUESS_DATA[uid]
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> تەواوە! ئەوە {secret} بوو! (لە {g['attempts']} هەوڵدا)", parse_mode="HTML")
            return True
        if g["attempts"] >= g["max"]:
            del GUESS_DATA[uid]
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> نەتتوانی بیدۆزیتەوە! وەڵامە ڕاستەکە {secret} بوو!", parse_mode="HTML")
            return True
        await update.message.reply_text(f"{_TGX} نەخێر! {g['max']-g['attempts']} هەوڵی ترت ماوە", parse_mode="HTML")
        return True

    return False

