                [_ebtn(f"هەموو ({bal:,})", f"gb:wit:{chat_id}:{uid}:x:{bal}", emoji_id="5983168981274465534", api_kwargs={"style": "primary"}),
                 _ebtn("گەڕانەوە", f"gb:back:{chat_id}:{uid}", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})],
