        lines = []
        for tx in reversed(txs[-15:]):
            emoji = "<tg-emoji emoji-id=\"5395360491583352313\">⬆️</tg-emoji>" if tx["amount"] > 0 else "<tg-emoji emoji-id=\"5443127283898405358\">⬇️</tg-emoji>"
