        if total_dep <= 0 or b["balance"] <= 0:
            await answered("❌" + " نە باڵانس و نە ئەندام بوونیان نییە!", show_alert=True); return
        # سوودی ١٠٪ دابەش دەکات بەگوێرەی پارچەی هەر کەسێک
        to_distribute = int(b["balance"] * 0.10)
        if to_distribute < 10:
            await answered("❌" + " باڵانس کەمە بۆ دابەشکردن!", show_alert=True); return
        distributed = 0
        for muid, mdata in mbs.items():
            dep   = mdata.get("deposited", 0)
