SCHEDULED_TX_FILE = "scheduled_transfers.json"
SCHEDULED_TX_DATA: dict = {}   # {uid: [{to, amount, interval_days, next_run, note, id}]}
try:
    with open(_hdata_path(SCHEDULED_TX_FILE), encoding="utf-8") as _stf:
        SCHEDULED_TX_DATA.update(json.load(_stf))
except Exception as _load_err:
    logger.debug("ℹ️ بارکردنی داتا: فایل هێشتا دروست نەبووە (ئاسایییە): %s", _load_err)

@guarded
async def scheduled_transfer_cmd(update: Update, context: CallbackContext):
    """/scheduledtx — بینین و دەستکاریکردنی گواستنەوەی ئۆتۆماتیک"""
    uid   = update.effective_user.id
    txs   = _stx_get(uid)
    coins = get_user_data(uid).get("coins", 0)

    kb = InlineKeyboardMarkup([
        [_ebtn("زیادکردنی نوێ", f"stx:add:{uid}", emoji_id="5230940806960919610", api_kwargs={"style": "primary"}),
         _ebtn("لیستی کردارە خۆکارەکان", f"stx:list:{uid}", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})],
        [_ebtn("بانک", "run:bank", emoji_id="5332455502917949981", api_kwargs={"style": "danger"}),
         _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})],
    ])

    if not txs:
        txt = (
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>گواستنەوەی خۆکار</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> کۆی کۆینەکانت: <b>{coins:,} {_TCN}</b>\n\n"
            f"هیچ گواستنەوەیەکی خۆکار تۆمار نەکراوە.\n\n"
            f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> دەتوانیت بڵێیت:\n"
            f"  • ڕۆژانە X کۆین بنێریت بۆ کەسێک\n"
            f"  • هەفتانە X کۆین پاشەکەوت بکەیت\n"
            f"  • مانگانە X کۆین بنێریت"
        )
    else:
        lines = []
        for tx in txs:
            status = f"{_TCK}" if tx.get("active", True) else "⏸️"
            lines.append(
                f"{status} ➜ {tx.get('note','')[:15]} | "
                f"بڕی <b>{tx.get('amount', 0):,}{_TCN}</b> هەر {tx['interval_days']} ڕۆژ جارێک\n"
                f"   وادەی داهاتوو: {tx.get('next_run','—')}"
            )
        txt = (
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>گواستنەوەی خۆکار</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> کۆی کۆینەکانت: <b>{coins:,} {_TCN}</b>\n\n"
            f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> کردارە خۆکارەکانت ({len(txs)}):\n\n" + "\n".join(lines)
        )
    await update.message.reply_text(txt, parse_mode="HTML", reply_markup=kb)

_STX_WAIT: dict = {}   # {uid: {"step": "amount"|"to"|"interval"|"note", "data": {}}}

async def scheduled_transfer_callback(update: Update, context: CallbackContext):
    query  = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    parts  = query.data.split(":")
    action = parts[1] if len(parts) > 1 else ""
    uid    = query.from_user.id
    txs    = _stx_get(uid)

    if action == "add":
        _STX_WAIT[uid] = {"step": "amount", "data": {}}
        await _safe_edit(query, 
            f"<tg-emoji emoji-id=\"5230940806960919610\">➕</tg-emoji> <b>گواستنەوەی خۆکاری نوێ</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هەنگاوی ١: دەتەوێت هەر جارێک چەند کۆین بنێریت؟\n"
            f"نموونە: <code>500</code>\n"
            f"(لانیکەم ١٠ کۆین)",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                _ebtn("هەڵوەشاندنەوە", f"stx:cancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})
            ]])
        )

    elif action == "list":
        if not txs:
            await answered("❌" + " هیچ گواستنەوەیەکی خۆکار بوونی نییە!", show_alert=True); return
        rows = []
        for i, tx in enumerate(txs):
            st  = f"{_TCK}" if tx.get("active", True) else "⏸️"
            lbl = f"{st} {tx.get('note','بێناو')[:12]} | {tx.get('amount', 0):,}{_TCN} هەر {tx['interval_days']}ڕۆژ"
            rows.append([
                _ebtn(lbl, f"stx:view:{uid}:{i}", api_kwargs={"style": "primary"}),
            ])
        rows.append([_ebtn("گەڕانەوە", f"stx:back:{uid}", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
        await _safe_edit(query, 
            f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>لیستی گواستنەوەکان</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",
            parse_mode="HTML", reply_markup=InlineKeyboardMarkup(rows)
        )

    elif action == "view" and len(parts) > 3:
        idx = int(parts[3])
        if idx >= len(txs):
            await answered("❌" + " نەدۆزرایەوە!", show_alert=True); return
        tx = txs[idx]
        st = f"{_TCK} چالاک" if tx.get("active", True) else "⏸️ ڕاگیراو"
        await _safe_edit(query, 
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>گواستنەوەی ئۆتۆماتیک #{idx+1}</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> تێبینی: <b>{tx.get('note','—')}</b>\n"
            f"{_TMN} بڕ: <b>{tx.get('amount', 0):,} {_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> بۆ: <code>{tx.get('to','—')}</code>\n"
            f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> هەر <b>{tx['interval_days']} ڕۆژ</b> جارێک\n"
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> جاری داهاتوو: <b>{tx.get('next_run','—')}</b>\n"
            f"{_TCH} باری: {st}",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [_ebtn("ڕاگرتن" if tx.get("active", True) else "دەستپێکردنەوە", f"stx:toggle:{uid}:{idx}", emoji_id="6282822561684263060", api_kwargs={"style": "danger"}),
                 _ebtn("سڕینەوە", f"stx:del:{uid}:{idx}", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})],
                [_ebtn("لیستەکە", f"stx:list:{uid}", emoji_id="5911212915968448930", api_kwargs={"style": "primary"}),
                 _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})],
            ])
        )

    elif action == "toggle" and len(parts) > 3:
        idx = int(parts[3])
        if idx < len(txs):
            txs[idx]["active"] = not txs[idx].get("active", True)
            _save_scheduled_tx()
            st = "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> چالاک کرا" if txs[idx]["active"] else "⏸️ ڕاگیرا"
            await answered(f"{st}!", show_alert=True)

    elif action == "del" and len(parts) > 3:
        idx = int(parts[3])
        if idx < len(txs):
            removed = txs.pop(idx)
            _save_scheduled_tx()
            await answered(f"🗑️ سڕایەوە: {removed.get('note','—')}", show_alert=True)

    elif action == "cancel":
        _STX_WAIT.pop(uid, None)
        await _safe_edit(query, 
            _TGX + " پڕۆسەکە هەڵوەشایەوە.",
            reply_markup=InlineKeyboardMarkup([[
                _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})
            ]])
        )

    elif action == "back":
        _STX_WAIT.pop(uid, None)
        coins = get_user_data(uid).get("coins", 0)
        await _safe_edit(query, 
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>گواستنەوەی ئۆتۆماتیک</b>\n\n"
            f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> کۆینت: <b>{coins:,} {_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> ئۆتۆماتیکەکانت: <b>{len(txs)}</b>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [_ebtn("زیادکردن", f"stx:add:{uid}", emoji_id="5230940806960919610", api_kwargs={"style": "primary"}),
                 _ebtn("لیست", f"stx:list:{uid}", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})],
                [_ebtn("بانک", "run:bank", emoji_id="5332455502917949981", api_kwargs={"style": "danger"}),
                 _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})],
            ])
        )

async def _handle_stx_message(update: Update, context: CallbackContext) -> bool:
    """هاندڵەر بۆ وەرگرتنی message لە STX wizard"""
    uid   = update.effective_user.id
    state = _STX_WAIT.get(uid)
    if not state:
        return False

    text  = (update.message.text or "").strip()
    step  = state["step"]
    data  = state["data"]

    if step == "amount":
        try:
            amt = int(text)
            if amt < 10:
                await update.message.reply_text(_TGX + " پێویستە لانیکەم ١٠ کۆین بێت!", parse_mode="HTML"); return True
            data["amount"] = amt
            state["step"]  = "to"
            await update.message.reply_text(
                f"{_TCK} بڕ: <b>{amt:,} {_TCN}</b>\n\n"
                f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هەنگاوی ٢: ئایدی (ID)ی بەکارهێنەر بنووسە (یان 0 بنووسە بۆ پاشەکەوتی خۆت):",
                parse_mode="HTML"
            )
        except ValueError:
            await update.message.reply_text(_TGX + " ژمارەیەک بنووسە!", parse_mode="HTML"); return True

    elif step == "to":
        try:
            to_id = int(text)
            data["to"] = to_id
            state["step"] = "interval"
            await update.message.reply_text(
                f"{_TCK} بۆ: <code>{to_id}</code>\n\n"
                f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هەنگاوی ٣: چەند ڕۆژ جارێک بنێردرێت؟ (١، ٧، ٣٠)",
                parse_mode="HTML"
            )
        except ValueError:
            await update.message.reply_text(_TGX + " تکایە ئایدی بە ژمارە بنووسە!", parse_mode="HTML"); return True

    elif step == "interval":
        try:
            days = int(text)
            if days < 1: days = 1
            if days > 365: days = 365
            data["interval_days"] = days
            state["step"] = "note"
            await update.message.reply_text(
                f"{_TCK} هەر <b>{days} ڕۆژ</b> جارێک\n\n"
                f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هەنگاوی ٤ (کۆتایی): تێبینییەک بنووسە (یان skip دابگرە):",
                parse_mode="HTML"
            )
        except ValueError:
            await update.message.reply_text(_TGX + " ژمارەیەک بنووسە!", parse_mode="HTML"); return True

    elif step == "note":
        note = text if text.lower() != "skip" else ""
        data["note"] = note[:30]

        # پاشەکەوتکردن
        txs = _stx_get(uid)
        new_tx = {
            "id":            int(time.time()),
            "to":            data.get("to", uid),
            "amount":        data["amount"],
            "interval_days": data["interval_days"],
            "note":          data.get("note", ""),
            "next_run":      (datetime.date.today() + datetime.timedelta(days=data["interval_days"])).isoformat(),
            "active":        True,
            "created":       datetime.date.today().isoformat(),
        }
        txs.append(new_tx)
        _save_scheduled_tx()
        _STX_WAIT.pop(uid, None)

        await update.message.reply_text(
            f"{_TCK} <b>گواستنەوەی خۆکار بە سەرکەوتوویی تۆمار کرا!</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"{_TMN} بڕ: <b>{data.get('amount', 0):,} {_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> بۆ: <code>{data.get('to', uid)}</code>\n"
            f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> هەر <b>{data['interval_days']} ڕۆژ</b>\n"
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> دواتر: <b>{new_tx['next_run']}</b>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                _ebtn("لیست", f"stx:list:{uid}", emoji_id="5911212915968448930", api_kwargs={"style": "primary"}),
                _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"}),
            ]])
        )

    return True

async def _run_scheduled_transfers(context: CallbackContext):
    """ئەرکی ئۆتۆماتیکی — هەر ساعەتێک چەک دەکات"""
    today = datetime.date.today().isoformat()
    changed = False
    for uid_str, txs in list(SCHEDULED_TX_DATA.items()):
        uid = int(uid_str)
        for tx in txs:
            if not tx.get("active", True): continue
            if tx.get("next_run", "") > today: continue
            amt    = tx["amount"]
            to_id  = tx.get("to", uid)
            # ── Lock بۆ جێگیری Race Condition لە گواستنەوەی شیدوار ──
            lock_s = _get_transfer_lock(uid)
            lock_r = _get_transfer_lock(to_id) if to_id and to_id != uid else None
            async with lock_s:
                sender = get_user_data(uid)
                if sender.get("coins", 0) < amt:
                    continue  # کۆینی بەس نییە — skip
                add_coins(uid, -amt)
            if to_id != 0 and to_id != uid:
                async with _get_transfer_lock(to_id):
                    add_coins(to_id, amt)
                try:
                    await context.bot.send_message(
                        to_id,
                        f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> گواستنەوەی ئۆتۆماتیک وەرگیرا!\n"
                        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> لە: <code>{uid}</code>\n"
                        f"{_TMN} بڕ: <b>{amt:,} {_TCN}</b>",
                        parse_mode="HTML"
                    )
                except Exception as _exc:
                    logger.debug("Suppressed Exception: %s", _exc)
            else:
                # پاشەکەوتی خۆی — بۆ بانک
                b = _bank_get(uid)
                b["balance"] += amt
                _bank_add_transaction(b, "ئۆتۆماتیک", amt, "گواستنەوەی شیدوار")
                _save_bank()
            # نوێکردنەوەی next_run
            tx["next_run"] = (
                datetime.date.today() + datetime.timedelta(days=tx["interval_days"])
            ).isoformat()
            changed = True
    if changed:
        _save_scheduled_tx()
        save_users(); save_coins()


