@guarded
async def txhistory_cmd(update: Update, context: CallbackContext):
    """/txhistory — تارێخچەی مامەڵەکان"""
    uid  = update.effective_user.id
    txs  = TX_HISTORY_DATA.get(str(uid), [])
    args = context.args or []

    await _txhistory_show(update.message.reply_text, uid, txs, filt="all", page=0)

async def txhistory_callback(update: Update, context: CallbackContext):
    query    = update.callback_query
    answered = _make_answerer(query)
    parts    = query.data.split(":")   # txh:<uid>:<filter>:<page>
    uid      = int(parts[1]) if len(parts) > 1 else query.from_user.id
    filt     = parts[2] if len(parts) > 2 else "all"
    page     = int(parts[3]) if len(parts) > 3 else 0
    txs      = TX_HISTORY_DATA.get(str(uid), [])
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX v34: answered() پێویستە — وەرنەکە spinner دادەمێنێتەوە
    await answered()

    async def _edit(text, **kw):
        try: await query.edit_message_text(text, **kw, parse_mode='HTML')
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    await _txhistory_show(_edit, uid, txs, filt=filt, page=page)


