@guarded
async def bankcard_cmd(update: Update, context: CallbackContext):
    """/bankcard — کارتی بانکی دیجیتاڵ"""
    uid  = update.effective_user.id
    name = _html_escape(update.effective_user.first_name or "بەکارهێنەر")
    card = _card_get_or_create(uid)
    b    = _bank_get(uid)
    await update.message.reply_text(
        _bankcard_text(card, name, b),
        parse_mode="HTML",
        reply_markup=_bankcard_kb(uid, not card.get("active", True))
    )

async def bankcard_callback(update: Update, context: CallbackContext):
    """هەموو دووگمەکانی کارتی بانکی"""
    query  = update.callback_query
    answered = _make_answerer(query)
    parts  = query.data.split(":")          # card:<action>:<uid>
    action = parts[1] if len(parts) > 1 else ""
    uid    = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else query.from_user.id
    caller = query.from_user.id

    # تەنها خاوەنی کارت یان ئاونەر
    if uid != caller and caller != OWNER_ID:
        try: await answered("❌" + " ئەمە کارتی تۆ نییە!", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    card = _card_get_or_create(uid)
    name = _html_escape(query.from_user.first_name or "بەکارهێنەر")
    b    = _bank_get(uid)

    # ─── ⋆⋅☆⋅⋆ ───
    # ١. نیشاندانی CVV  (popup — بەبێ query.answer() ی پێشوەختە)
    # ─── ⋆⋅☆⋅⋆ ───
    if action == "showcvv":
        status = f"{_TCK} چالاک" if card.get("active", True) else "<tg-emoji emoji-id=\"5422631223220540518\">⛔</tg-emoji> قفڵ کراوە"
        try:
            await answered(
                f"<tg-emoji emoji-id=\"5870972873450984431\">🔐</tg-emoji> کۆدی CVVی کارتەکەت\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
                f"CVV: {card['cvv']}\n"
                f"بەرواری بەسەرچوون: {card['exp']}\n"
                f"جۆری کارت: {card['type']}\n"
                f"دۆخ: {status}\n\n"
                f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئەم کۆدە نھێنییە — بۆ هیچ کەسێکی مەدە!",
                show_alert=True
            )
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    # ─── ⋆⋅☆⋅⋆ ───
    # ٢. نوێکردنەوەی کارت
    # ─── ⋆⋅☆⋅⋆ ───
    elif action == "renew":
        ud = get_user_data(uid)
        if ud.get("coins", 0) < 100:
            try: await answered(
                f"<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> کۆینی پێویست نییە!\n"
                f"پێویستت بە ١٠٠ <tg-emoji emoji-id=\"5379827763832203150\">🪙</tg-emoji> هەیە.\n"
                f"کۆینی ئێستات: {ud.get('coins',0):,} <tg-emoji emoji-id=\"5379827763832203150\">🪙</tg-emoji>",
                show_alert=True
            )
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        add_coins(uid, -100, "bankcard", "نوێکردنەوەی کارت")
        BANK_CARD_DATA[str(uid)] = _generate_card(uid)
        _save_bank_cards()
        save_users(); save_coins()   # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: هەر دووکیان پاشەکەوت — crash-safe
        card = _card_get_or_create(uid)   # کارتی نوێ
        b    = _bank_get(uid)
        try:
            await answered("✅ کارتێکی نوێ دروست کرا! (-١٠٠ 🪙)", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        try:
            await _safe_edit(query, 
                _bankcard_text(card, name, b),
                parse_mode="HTML",
                reply_markup=_bankcard_kb(uid, not card.get("active", True))
            )
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    # ─── ⋆⋅☆⋅⋆ ───
    # ٣. قفڵکردن / کردنەوە
    # ─── ⋆⋅☆⋅⋆ ───
    elif action == "freeze":
        was_active       = card.get("active", True)
        card["active"]   = not was_active
        BANK_CARD_DATA[str(uid)] = card
        _save_bank_cards()
        msg = "<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> کارتەکەت قفڵ کرا!" if not card["active"] else "<tg-emoji emoji-id=\"5231302159739395058\">🔓</tg-emoji> کارتەکەت کرایەوە!"
        try: await answered(msg, show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        try:
            await _safe_edit(query, 
                _bankcard_text(card, name, b),
                parse_mode="HTML",
                reply_markup=_bankcard_kb(uid, not card.get("active", True))
            )
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
