async def addfriend_cmd(update: Update, context: CallbackContext):
    user_id = update.effective_user.id
    
    if not context.args:
        await update.message.reply_text("<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> فەرمان: /addfriend [ئایدی یاریزان]", parse_mode="HTML")
        return
    
    try:
        friend_id = int(context.args[0])
        user_data = get_user_data(user_id)
        
        if "friends" not in user_data:
            user_data["friends"] = []
        
        if friend_id in user_data["friends"]:
            await update.message.reply_text(_TGX + " ئەم کەسە پێشتر لە لیستی هاوڕێکانتدایە!", parse_mode="HTML")

            return
        
        user_data["friends"].append(friend_id)
        save_users()
        
        await update.message.reply_text(f"{_TCK} هاوڕێی نوێ زیاد کرا!", parse_mode="HTML")

        
    except ValueError:
        await update.message.reply_text(_TGX + " تکایە ئایدییەکی دروست بنووسە!", parse_mode="HTML")



# ----------------- بانگکردنەوەکانی ئابووری (Economy Callbacks) -----------------

async def _safe_edit(
    query,
    text: str,
    reply_markup=None,
    parse_mode: str = "HTML",
    disable_web_page_preview: bool = False,
    **extra_kwargs,
) -> bool:
    """
    <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX v97 Bug#7: disable_web_page_preview و هەر kwargs ی تری پشتیوانی دەکات
    Safe edit — ئەگەر edit نەبوو، reply_text دەکات
     FIX: query.answer() فەوری لە دەستپێکدا — spinner ناچیتەوە
    Returns True if successful
    """
    # Rule 6: Empty text guard — هیچ کاری ناکات ئەگەر دەق بەتاڵ بێت
    if not text or not text.strip():
        return False

    MAX_LEN = 4096

    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> query.answer() — تەنها ئەگەر پێشتر وەڵام نەدرابێت (double-answer FIX v34)
    try:
        await query.answer()
    except Exception as _exc:
        # "query is too old" یان "already answered" — بێ گرفت، بەردەوام بە
        logger.debug("_safe_edit answer skip (already answered): %s", _exc)

    # ━━━ بناغەی kwargs بناسێنە ━━━
    # FIX v5: disable_web_page_preview بەکاردێنرێت
    base_kwargs: dict = {"parse_mode": parse_mode}
    if disable_web_page_preview:
        base_kwargs["disable_web_page_preview"] = True
    base_kwargs.update(extra_kwargs)
    send_kwargs: dict = dict(base_kwargs)

    # ━━━ ئەگەر دەق زیاتر لە 4096 بوو — دووپارچە بکاتەوە ━━━
    if len(text) > MAX_LEN:
        part1 = text[:MAX_LEN]
        part2 = text[MAX_LEN:]
        kwargs1 = dict(base_kwargs)
        kwargs2 = dict(base_kwargs)
        send_kwargs2 = dict(send_kwargs)
        if reply_markup:
            kwargs2["reply_markup"] = reply_markup
            send_kwargs2["reply_markup"] = reply_markup
        try:
            await query.edit_message_text(part1, **kwargs1)
            await query.message.reply_text(part2, **kwargs2)
            return True
        except Exception as _e:
            em = str(_e).lower()
            if "not modified" in em:
                return True
            try:
                chat = query.message.chat if query.message else None
                if chat:
                    await chat.send_message(part1, **send_kwargs)
                    await chat.send_message(part2, **send_kwargs2)
                    return True
            except Exception as _e2:
                logger.error("_safe_edit (split) failed: %s", _e2)
        return False

    # ━━━ ئاسایی: دەق ٤٠٩٦ یان کەمتر ━━━
    kwargs = dict(base_kwargs)
    if reply_markup:
        kwargs["reply_markup"] = reply_markup
    send_kwargs_full = dict(send_kwargs)
    if reply_markup:
        send_kwargs_full["reply_markup"] = reply_markup

    # ١. هەوڵی edit
    try:
        await query.edit_message_text(text, **kwargs)
        return True
    except Exception as _e:
        em = str(_e).lower()
        if "not modified" in em:
            return True

        #  FIX (BUG #fix-isl-4): Document_invalid لە کاتی custom emoji
        # نەگونجاو لە <tg-emoji> تاگدا. هەوڵی #١: تاگەکان بگۆڕە بە
        # یونیکۆدی fallback ـیان و دووبارە edit بکە.
        if "document_invalid" in em or "custom_emoji" in em:
            logger.warning(
                "_safe_edit Document_invalid — retrying with demoted tg-emoji tags"
            )
            try:
                # lazy import — نا بۆ گەرانەوەی circular import
                import sys as _sys
                _mm = _sys.modules.get("__main__") or _sys.modules.get("main")
                _demote = getattr(_mm, "_demote_tg_emoji_tags", None) if _mm else None
                if _demote:
                    demoted = _demote(text)
                    if demoted and demoted != text:
                        try:
                            await query.edit_message_text(demoted, **kwargs)
                            return True
                        except Exception as _ed:
                            em_d = str(_ed).lower()
                            if "not modified" in em_d:
                                return True
                            # هەوڵی دواتر: reply_text بە تێکستی demoted
                            try:
                                await query.message.reply_text(demoted, **send_kwargs_full)
                                return True
                            except Exception as _exc_d:
                                logger.error(
                                    "_safe_edit demoted reply_text failed: %s", _exc_d
                                )
            except Exception as _exc_demote:
                logger.error("_safe_edit demote retry crashed: %s", _exc_demote)

        # هەڵەکانی پەیامی سڕاو/بەسەرچوو — fallback بۆ reply_text
        if any(x in em for x in (
            "message_id_invalid", "message to edit not found",
            "too old", "query is too old", "message can't be edited",
            "there is no text in the message",
            "message_not_modified",
        )):
            try:
                await query.message.reply_text(text, **send_kwargs_full)
                return True
            except Exception as _exc:
                em_r = str(_exc).lower()
                if "document_invalid" in em_r or "custom_emoji" in em_r:
                    # ✅ هەوڵی دواتر: بە تێکستی demoted
                    try:
                        import sys as _sys2
                        _mm2 = _sys2.modules.get("__main__") or _sys2.modules.get("main")
                        _demote2 = getattr(_mm2, "_demote_tg_emoji_tags", None) if _mm2 else None
                        if _demote2:
                            await query.message.reply_text(_demote2(text), **send_kwargs_full)
                            return True
                    except Exception as _exc2:
                        logger.error("_safe_edit reply_text demote retry failed: %s", _exc2)
                logger.debug("Suppressed Exception: %s", _exc)
        if "there is no text" in em or "message can" in em:
            try:
                await query.edit_message_caption(caption=text[:1024], parse_mode=parse_mode)
                return True
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
        try:
            chat = query.message.chat if query.message else None
            if chat:
                await chat.send_message(text, **send_kwargs_full)
                return True
        except Exception as _e2:
            em2 = str(_e2).lower()
            # FIX: FloodControl — چاوەڕێ بکە دووبارە هەوڵ بدە
            if "flood control" in em2 or "retry in" in em2:
                import re as _re
                _m = _re.search(r"retry in (\d+)", em2)
                _secs = int(_m.group(1)) + 1 if _m else 5
                await asyncio.sleep(_secs)
                try:
                    if chat:
                        await chat.send_message(text, **send_kwargs_full)
                        return True
                except Exception as _e3:
                    _e3m = str(_e3).lower()
                    # FIX BUG#2: TimedOut کاتێک سەرڤەری تەلەگرام تەنبەڵە پاش flood-wait
                    # یەک هەوڵی دووەم بە 3 چرکە مانەوە
                    if "timed out" in _e3m or "timeout" in _e3m:
                        await asyncio.sleep(3)
                        try:
                            if chat:
                                await chat.send_message(text, **send_kwargs_full)
                                return True
                        except Exception as _e4:
                            logger.error("_safe_edit failed after flood-wait+timeout-retry (%ss): %s", _secs, _e4)
                    else:
                        logger.error("_safe_edit failed after flood-wait (%ss): %s", _secs, _e3)
            #  FIX (BUG #fix-isl-4): Document_invalid لە send_message ـیش —
            # یەکەم demote ئەنجام بدە، ئەگەر شکست هێنا plain HTML سڕاو.
            elif "document_invalid" in em2 or "custom_emoji" in em2:
                logger.warning("_safe_edit send_message Document_invalid — final demote retry")
                try:
                    import sys as _sys3
                    _mm3 = _sys3.modules.get("__main__") or _sys3.modules.get("main")
                    _demote3 = getattr(_mm3, "_demote_tg_emoji_tags", None) if _mm3 else None
                    if _demote3 and chat:
                        try:
                            await chat.send_message(_demote3(text), **send_kwargs_full)
                            return True
                        except Exception as _e4:
                            logger.error("_safe_edit final demote send failed: %s", _e4)
                except Exception as _exc_f:
                    logger.error("_safe_edit final retry crashed: %s", _exc_f)
            elif any(x in em2 for x in ("message_not_modified", "message to edit not found")):
                logger.debug("_safe_edit silenced (expected): %s", _e2)
            else:
                logger.error("_safe_edit failed: %s", _e2)
    return False

async def coins_callback(query, context):
    """economy:coins — نیشاندانی جزدانی تەواو (inline)"""
    try:
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> query.answer() لەناو _safe_edit دەکرێت — spinner خۆکار دەچێتەوە
        user_id   = query.from_user.id
        user_data = get_user_data(user_id)
        coins     = user_data.get("coins", 0)
        xp        = user_data.get("points", 0)
        level     = user_data.get("level", 1)
        b         = _bank_get(user_id)
        bank_total = b["balance"] + b["savings"]
        net_worth  = coins + bank_total - b.get("loan", 0)
        p          = _prestige_get(user_id)
        mult       = PRESTIGE_REWARDS.get(p.get("level", 0), {}).get("multiplier", 1.0)
        pstr       = f" ×{mult:.1f}" if p.get("level", 0) > 0 else ""
        vip_info   = BANK_VIP_PERKS[b["vip_level"]]
        cur_job    = user_data.get("current_job", "<tg-emoji emoji-id=\"5395850714855545663\">👷</tg-emoji> کرێکار")
        work_str   = user_data.get("work_streak", 0)

        # ئاستی دەوڵەمەندی
        if net_worth >= 1000000: wtitle = "<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> ملیۆنێری قارەمان"
        elif net_worth >= 100000: wtitle = f"{_TDM} ملیۆنێر"
        elif net_worth >= 50000:  wtitle = "<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji> دەوڵەمەند"
        elif net_worth >= 10000:  wtitle = "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji> ئاستی باش"
        elif net_worth >= 2000:   wtitle = "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji> ناوەند"
        else:                     wtitle = "<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> دەستپێکەر"

        # قەرز و term deposit
        loan_txt = f"\n<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> قەرز: <b>-{b.get('loan', 0):,} {_TCN}</b>" if b["loan"] > 0 else ""
        term_txt = f"\n<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> ماوەدار: <b>{b.get('term_deposit', 0):,} {_TCN}</b>" if b.get("term_deposit", 0) > 0 else ""

        rows = [
            [_ebtn("بانک", "run:bank", emoji_id="5332455502917949981", api_kwargs={"style": "danger"}),
             _ebtn("کار", "run:work", api_kwargs={"icon_custom_emoji_id": "5395850714855545663", "style": "primary"})],
            [_ebtn("گواستنەوە", "run:transfer", emoji_id="5983168981274465534", api_kwargs={"style": "primary"}),
             _ebtn("باشترینان", "run:leaderboard_coins", emoji_id="5462927083132970373", api_kwargs={"style": "primary"})],
            [_ebtn("کارت", "run:bankcard", api_kwargs={"icon_custom_emoji_id": "5445353829304387411", "style": "danger"}),
             _ebtn("کۆکردن", "economy:collect", api_kwargs={"icon_custom_emoji_id": "5463172695132745432", "style": "success"})],
            [_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})],
        ]
        await _safe_edit(query,
            f"{_TMN} <b>جزدانم</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> جزدان:  <b>{coins:,} {_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> پاشەکەوت: <b>{b.get('balance', 0):,} {_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5395724928148348717\">💹</tg-emoji> پاشەکەوتی پێشکەوتوو: <b>{b.get('savings', 0):,} {_TCN}</b>"
            f"{term_txt}\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"{_TDM} کۆی سەرمایە: <b>{net_worth:,} {_TCN}</b>{pstr}\n"
            f"<tg-emoji emoji-id=\"5789828777882162072\">🏅</tg-emoji> پلە: <b>{wtitle}</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> XP: <b>{xp:,}</b>  |  ئاست: <b>{level}</b>\n"
            f"<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> VIP: <b>{vip_info['emoji']} {vip_info['name']}</b>\n"
            f"<tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji> کاری ئێستا: <b>{cur_job}</b>\n"
            f"<tg-emoji emoji-id=\"5379636904075499661\">🔥</tg-emoji> ستریک کار: <b>{work_str} ڕۆژ</b>"
            f"{loan_txt}",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(rows)
        )
    except Exception as e:
        logger.error(f"Error in coins_callback: {e}")
        try:
            if hasattr(query, "answer"):
                await query.answer()
        except Exception:
            pass

async def job_callback(query, context):
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX v22: query.answer() فەوری — spinner دەچێتەوە پێش هەر مەرجێک
    try:
        await query.answer()
    except Exception as _ans_exc:
        logger.debug("job_callback answer suppressed: %s", _ans_exc)
    user_id   = query.from_user.id
    user_data = get_user_data(user_id)
    b         = _bank_get(user_id)
    level     = user_data.get("level", 1)
    coins     = user_data.get("coins", 0)
    bank_total = b["balance"] + b["savings"]

    vip_info  = BANK_VIP_PERKS[b["vip_level"]]
    jobs_avail = _get_available_jobs(level)
    job_names  = "، ".join(f"{j[0]}" for j in jobs_avail[:3]) if jobs_avail else "—"

    rows = [
        [_ebtn("بازاڕ", "run:jobmarket", emoji_id="5278702045883292456", api_kwargs={"style": "primary"}),
         _ebtn("کارکردن /work", "run:work", api_kwargs={"icon_custom_emoji_id": "5395850714855545663", "style": "primary"})],
        [_ebtn("کۆمپانیا", "run:business", api_kwargs={"icon_custom_emoji_id": "5307814064360010566", "style": "primary"}),
         _ebtn("پێشکەوتن", "run:job", emoji_id="5965109764781252317", api_kwargs={"style": "primary"})],
        [_ebtn("بانک", "run:bank", emoji_id="5332455502917949981", api_kwargs={"style": "danger"}),
         _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})],
    ]
    await _safe_edit(query, 
        f"<tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji> <b>ئابووری — کار و بازاڕ</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TCN} کۆینت: <b>{coins:,} {_TCN}</b>\n"
        f"<tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> بانک: <b>{bank_total:,} {_TCN}</b>\n"
        f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئاست: <b>{level}</b>  |  <tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> VIP: <b>{vip_info['name']}</b>\n\n"
        f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> کارە بەردەستەکان: {job_names}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"/work — کۆین بكسب بكە\n"
        f"/jobmarket — بازاڕی کار ببینە",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(rows)
    )

async def house_callback(query, context):
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX v22: query.answer() فەوری — spinner دەچێتەوە پێش هەر مەرجێک
    try:
        await query.answer()
    except Exception as _ans_exc:
        logger.debug("house_callback answer suppressed: %s", _ans_exc)
    user_id   = query.from_user.id
    user_data = get_user_data(user_id)
    coins     = user_data.get("coins", 0)

    HOUSES = [
        ("<tg-emoji emoji-id=\"5228909012552000246\">🏠</tg-emoji> خانووی سادە",  1000,  5,  "house_basic"),
        ("<tg-emoji emoji-id=\"5197708768091061888\">🏡</tg-emoji> خانووی ناوەند", 5000,  10, "house_mid"),
        ("<tg-emoji emoji-id=\"5330116450843636190\">🏰</tg-emoji> کۆشک",         15000, 20, "house_castle"),
    ]
    current = user_data.get("house", None)
    rows = []
    for h_name, h_price, h_xp, h_id in HOUSES:
        owned = (current == h_id)
        if owned:
            lbl = f"{_TCK} {h_name} (خاوەنداری)"
            cb  = "noop"
        elif coins >= h_price:
            lbl = f"<tg-emoji emoji-id=\"5438389200531527988\">🛒</tg-emoji> {h_name} — {h_price:,}{_TCN}"
            cb  = f"house_buy:{h_id}"
        else:
            lbl = f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> {h_name} — {h_price:,}{_TCN} (کۆینت بەس نییە)"
            cb  = "noop"
        rows.append([_ebtn(lbl, cb, api_kwargs={"style": "primary"})])
    rows.append([_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})])

    h_display = next((n for n,_,_,i in HOUSES if i == current), "هیچ")
    await _safe_edit(query, 
        f"<tg-emoji emoji-id=\"5228909012552000246\">🏠</tg-emoji> <b>خانووەکان</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5197708768091061888\">🏡</tg-emoji> خانووی ئێستات: <b>{h_display}</b>\n"
        f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> کۆینت: <b>{coins:,} {_TCN}</b>\n\n"
        f"خانوویەک هەڵبژێرە بۆ کڕین:",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(rows)
    )

async def collect_callback(query, context):
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX v41: query.answer() ڕاستەوخۆ — دووگمەی _make_answerer دووبارە نابێت
    # (submenu_callback پێشتر answered() کردووە — دووی جار نابێت)
    user_id   = query.from_user.id
    user_data = get_user_data(user_id)
    now       = time.time()
    COLLECT_CD = 3600  # ١ کاتژمێر cooldown

    last_c = user_data.get("last_collect_ts", 0)
    remaining = COLLECT_CD - (now - last_c)
    if remaining > 0:
        mins = int(remaining // 60)
        try:
            await query.answer(f"⏳ {mins} خولەک ماوە بۆ کۆکردنەوەی داهاتوو!", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    item_name, item_info = _weighted_collectible()
    if "collectibles" not in user_data:
        user_data["collectibles"] = []
    user_data["collectibles"].append(item_name)
    user_data["last_collect_ts"] = now
    add_coins(user_id, item_info["value"], "collect", item_name)
    save_users(); save_coins()   # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: هەر دووکیان پاشەکەوت — crash-safe

    total = len(user_data["collectibles"])
    keyboard = [
        [_ebtn("دووبارە کۆبکەرەوە", "economy:collect", emoji_id="5353025084845994828", api_kwargs={"style": "success"}),
         _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]
    ]
    await _safe_edit(query, 
        f"<tg-emoji emoji-id=\"5463172695132745432\">📦</tg-emoji> <b>کۆکردنەوە</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{item_info['emoji']} دۆزیتەوە: <b>{item_name}</b>\n"
        f"{_TMN} بڕی کۆین: <b>+{item_info.get('value', 0):,} {_TCN}</b>\n"
        f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> دەگمەنی: <b>{item_info['rarity']}</b>\n"
        f"<tg-emoji emoji-id=\"5463172695132745432\">📦</tg-emoji> کۆی کەلوپەلەکانت: <b>{total}</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> کۆکردنەوەی داهاتوو: ١ کاتژمێر دواتر",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )

