# ----------------- یاری مەتەڵ (Riddle Game) -----------------

async def error_handler(update: Update, context: CallbackContext):
    """بەڕێوەبەری هەڵەکان — هیچ هەڵەیەک بۆتەکە نادات خوار"""
    if context.error is None:
        return

    error_type = type(context.error).__name__
    error_message = str(context.error)

    # هەڵەکانی ئاسایی کە ignore دەکرێن
    _IGNORE = (
        "message is not modified",
        "query is too old",
        "message_id_invalid",
        "message to delete not found",
        "message can't be deleted",
        "bot was blocked",
        "bot is not a member",
        "networkerror",
        "timedout",
        "retryafter",
        "conflict",
        "terminated by other",
        "connectionerror",
        "connectionreseterror",
        "remotedisconnected",
        "sslerror",
        "httpx",
        "read timeout",
        "connect timeout",
        "pool timeout",
        "event loop is closed",
        "cancelled",
        "bad gateway",
        "gateway timeout",
        "service unavailable",
    )

    err_lower = (error_type + " " + error_message).lower()
    for pat in _IGNORE:
        if pat in err_lower:
            logger.debug("هەڵەی ئاسایی ignore کرا: %s", error_type)
            return

    # RetryAfter — بۆت لە ناردن بازداراوە
    if isinstance(context.error, RetryAfter):
        wait = context.error.retry_after
        logger.warning(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> RetryAfter %ss — بۆت چاوەڕێ دەکات...", wait)
        await asyncio.sleep(min(wait, 30))
        return

    logger.error("<tg-emoji emoji-id=\"5823259308665607384\">🚨</tg-emoji> هەڵەی نەزانراو: %s — %s", error_type, error_message[:120])

    # ناردنی پەیامی هەڵە بۆ بەکارهێنەر — تەنها بۆ هەڵەی گرنگ
    try:
        if update and update.callback_query:
            try:
                await update.callback_query.answer(" هەڵەیەک ڕوویدا!", show_alert=False)
            except Exception as _e:
                logger.debug("error_handler answer failed: %s", _e)
    except Exception as _e2:
        logger.debug("error_handler outer: %s", _e2)

