async def help_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    parts = query.data.split(":")
    if len(parts) < 2:
        return
    section = parts[1]

    # دوگمەکانی مێنیوی یارمەتی
    help_menu_keyboard = InlineKeyboardMarkup([
        [_ebtn("یارییە گشتییەکان", "help:games", emoji_id="5381825232862483894", api_kwargs={"style": "primary"}),
         _ebtn("یاریی شمشێر", "help:rpg", emoji_id="5395812579840925273", api_kwargs={"style": "primary"})],
        [_ebtn("مانەوە/مافیا", "help:survival", emoji_id="5458708089513472966", api_kwargs={"style": "primary"}),
         _ebtn("ئابووری", "help:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})],
        [_ebtn("کۆمپانیا/خانوو", "help:company", api_kwargs={"icon_custom_emoji_id": "5307814064360010566", "style": "primary"}),
         _ebtn("مارکێت", "help:market", emoji_id="6271698656517165534", api_kwargs={"style": "primary"})],
        [_ebtn("پڕۆفایل", "help:profile", emoji_id="5990252189799422376", api_kwargs={"style": "primary"}),
         _ebtn("ئیسلامی", "help:islamic", api_kwargs={"icon_custom_emoji_id": "5382295780889498241", "style": "primary"})],
        [_ebtn("خزمەتگوزارییەکان", "help:services", api_kwargs={"icon_custom_emoji_id": "5395758123950576680", "style": "primary"}),
         _ebtn("ئامرازەکان", "help:tools", emoji_id="5258500400918587241", api_kwargs={"style": "primary"})],
        [_ebtn("بەڕێوەبەر", "help:admin", api_kwargs={"icon_custom_emoji_id": "5341715473882955310", "style": "primary"}),
         _ebtn("🆕 نوێکارییەکان", "help:new", api_kwargs={"style": "primary"})],
        [_ebtn("تاقیکردنەوەی کەسایەتی", "help:personality", emoji_id="5264874622012126052", api_kwargs={"style": "primary"}),
         _ebtn("چرپەنامە", "help:whisper", api_kwargs={"icon_custom_emoji_id": "5190859184312167965", "style": "primary"})],
        [_ebtn("سەرەکی", "menu:back", emoji_id="5228909012552000246", api_kwargs={"style": "primary"})],
    ])

    if section == "back":
        await _safe_edit(query, "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> فەرمانەکانی بۆت\n\nتکایە بەشێک هەڵبژێرە:", reply_markup=help_menu_keyboard)
        return

    text = HELP_TEXTS.get(section, _TGX + " ئەم بەشە بوونی نییە!")
    back_kb = InlineKeyboardMarkup([
        [_ebtn("گەڕانەوە", "help:back", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]
    ])
    await _safe_edit(query, text, reply_markup=back_kb)

