async def company_callback(query, context):
    """کردنەوەی داشبۆردی کۆمپانیا ڕاستەوخۆ — FIX: بەجێی پەیامی ڕێنمایی"""
    try:
        await query.answer()
    except Exception as _e:
        logger.debug("company_callback answer: %s", _e)
    _chat = query.message.chat if query.message else None
    try:
        if query.message:
            await query.message.delete()
    except Exception as _e:
        logger.debug("company_callback delete: %s", _e)
    try:
        await business_cmd(_GFakeUpd(query), context)
    except Exception as _e:
        logger.error("company_callback → business_cmd: %s", _e)
        try:
            if _chat:
                await _chat.send_message(
                    "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> هەڵەیەک ڕووی دا. تکایە /business بنووسە.",
                    parse_mode="HTML"
                )
        except Exception as _e2:
            logger.debug("company_callback fallback: %s", _e2)
