async def referral_callback(query, context):
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: await لە ناو f-string نابێت — بۆ جیا کراوەوە
    user_id = query.from_user.id
    user_data = get_user_data(user_id)

    if not user_data.get("referral_code"):
        referral_code = f"REF{user_id}{random.randint(1000,9999)}"
        user_data["referral_code"] = referral_code
        REFERRAL_CODES[referral_code] = user_id
        save_users()
        save_referral()

    referral_code   = user_data["referral_code"]
    referrals_count = len(user_data.get("referrals", []))
    total_earned    = referrals_count * 500

    try:
        bot_info = await context.bot.get_me()
        bot_username = bot_info.username
    except Exception:
        bot_username = "bot"

    rows = [[_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]]
    await _safe_edit(query, 
        f"<tg-emoji emoji-id=\"5393611555130609821\">📨</tg-emoji> <b>سیستەمی بانگهێشت</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> کۆدی بانگهێشتت: <code>{referral_code}</code>\n"
        f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> بانگهێشتکراوەکان: <b>{referrals_count}</b> کەس\n"
        f"{_TMN} کۆی کسبکراو: <b>{total_earned:,} {_TCN}</b>\n\n"
        f"<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> لینک:\n"
        f"<code>https://t.me/{bot_username}?start={referral_code}</code>\n\n"
        f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> بۆ هەر کەسێک کە دێت +500{_TCN} وەردەگریت!",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(rows)
    )

