async def pokemon(update: Update, context: CallbackContext):
    try:
        user_id = update.effective_user.id
        
        if has_active_game(user_id):
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> تۆ ئێستا لەناو یارییەکی تریدای.\n\nتەواوی بکە یان بنووسە: /resetgame", parse_mode="HTML")
            return

        user_data = get_user_data(user_id)
        
        if not user_data.get("pokemon"):
            user_data["pokemon"] = []
        
        if random.random() < 0.3 or not user_data["pokemon"]:
            new_poke = random.choice(POKEMON_LIST).copy()
            pokemon_id = len(user_data["pokemon"]) + 1
            new_poke["id"] = pokemon_id
            new_poke["captured_date"] = datetime.datetime.now().isoformat()
            
            user_data["pokemon"].append(new_poke)
            
            if not user_data.get("active_pokemon"):
                user_data["active_pokemon"] = pokemon_id
            
            save_users()
            
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> پیرۆزە! پۆکمۆنێکی نوێت دۆزییەوە!\n\n"
                f"<tg-emoji emoji-id=\"5470088387048266598\">🐉</tg-emoji> ناو: {new_poke['name']}\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> جۆر: {new_poke['type']}\n"
                f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ تەندروستی (HP): {new_poke['hp']}\n"
                f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێزی هێرش: {new_poke['attack']}\n"
                f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئاست: {new_poke['level']}\n\n"
                f"{_TMN} خەڵات: +50 {_TCN} وەرگیرا",
                parse_mode="HTML"
            )
            
            add_coins(user_id, 50); save_users()   # {_TCK} FIX pokemon
        else:
            pokes = "\n".join([f"{i+1}. {p['name']} {p['type']} (ئاست: {p['level']})" for i, p in enumerate(user_data['pokemon'])])
            active = user_data['pokemon'][user_data.get('active_pokemon', 1)-1]['name'] if user_data.get('active_pokemon') else 'دیاری نەکراوە'
            
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"5470088387048266598\">🐉</tg-emoji> لیستی پۆکمۆنەکانت:\n\n{pokes}\n\n"
                f"{_TCK} پۆکمۆنی چالاک: {active}",
                parse_mode="HTML"
            )

    except Exception as e:
        logger.error("Error in pokemon: %s", e)
        await update.message.reply_text("<tg-emoji emoji-id=\"5470088387048266598\">🐉</tg-emoji> پۆکمۆن دۆزرایەوە!\n<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ HP: 100\n<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێرش: 55", parse_mode="HTML")

