async def defense_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner

    try:
        user_id = query.from_user.id
        active_game = get_active_game(user_id)
        
        if not active_game or active_game["type"] != "defense":
            await _safe_edit(query, "<tg-emoji emoji-id=\"5454415424319931791\">⌛</tg-emoji> کاتی ئەم یارییە بەسەرچووە.")
            remove_active_game(user_id)
            return

        action = query.data.split(":")[1]
        game_data = active_game["data"]
        
        if action == "defend":
            damage_reduction = random.randint(5, 15)
            actual_damage = max(0, game_data["enemy_attack"] - damage_reduction)
            game_data["current_health"] -= actual_damage
            user_action = f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> تۆ بەرگریت کرد و زەرەری دوژمنت بە بڕی {damage_reduction} کەمکردەوە!"
            
        elif action == "attack":
            damage_to_enemy = random.randint(20, 40)
            game_data["score"] += damage_to_enemy
            actual_damage = game_data["enemy_attack"]
            game_data["current_health"] -= actual_damage
            user_action = f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێرشت کرد و {damage_to_enemy} زەرەرت لە دوژمن دا!"
            
        elif action == "heal":
            heal_amount = random.randint(15, 25)
            game_data["current_health"] = min(game_data["base_health"], game_data["current_health"] + heal_amount)
            actual_damage = game_data["enemy_attack"]
            game_data["current_health"] -= actual_damage
            user_action = f"<tg-emoji emoji-id=\"5386468852718671397\">💊</tg-emoji> چارەسەرت بەکارهێنا و {heal_amount} تەندروستیت بۆ گەڕایەوە!"
        
        game_data["round"] += 1
        
        if game_data["current_health"] <= 0:
            # دۆڕان
            xp_gain = game_data["score"] // 10
            coins_gain = game_data["score"] // 5
            
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5384348715127442215\">💥</tg-emoji> بنکەکەت ڕووخا!\n\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> کۆی خاڵەکانت: {game_data['score']}\n"
                f"{_TMN} خەڵات: +{xp_gain} XP و +{coins_gain} {_TCN}\n"
                f"<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> ڕۆندی گەیشتوو: {game_data['round'] - 1}")
            
            add_points(user_id, xp_gain)
            add_coins(user_id, coins_gain)
            remove_active_game(user_id)
        else:
            if game_data["round"] % 3 == 0:
                enemies = ["<tg-emoji emoji-id=\"5377548540652333112\">👹</tg-emoji> دوژمنی سادە", "<tg-emoji emoji-id=\"5470088387048266598\">🐉</tg-emoji> ئەژدیهای گەورە", "<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> ڕۆبۆت", "👻 شێوەکار", "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> سەرکردەی تاریکی"]
                game_data["enemy"] = random.choice(enemies)
                game_data["enemy_attack"] = random.randint(15, 35) + (game_data["round"] // 3 * 5)
            
            if game_data["round"] > 10:
                user_data = get_user_data(user_id)
                user_data["defense_wins"] = user_data.get("defense_wins", 0) + 1
                save_users()
            
            keyboard = [
                [_ebtn("بەرگری", "defense:defend", emoji_id="5454006698052184265", api_kwargs={"style": "primary"}),
 _ebtn("️ هێرش", "defense:attack", emoji_id="5382170054311841219", api_kwargs={"style": "primary"})],
                [_ebtn("چارەسەر", "defense:heal", api_kwargs={"icon_custom_emoji_id": "5386468852718671397", "style": "success"})]
            ]
            reply_markup = InlineKeyboardMarkup(keyboard)

            await _safe_edit(query, f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> یاری بەرگری - ڕۆندی {game_data['round']}\n\n"
                f"{user_action}\n\n"
                f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ تەندروستی ماوە: {max(0, game_data['current_health'])}\n"
                f"<tg-emoji emoji-id=\"5377548540652333112\">👹</tg-emoji> دوژمن: {game_data['enemy']}\n"
                f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێزی دوژمن: {game_data['enemy_attack']}\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> خاڵ: {game_data['score']}\n\n"
                f"نۆرەی تۆیە:", reply_markup=reply_markup)
        
        update_game_data(user_id, game_data)

    except Exception as e:
        logger.error("هەڵە لە defense_callback: %s", e)
        await _safe_edit(query, _TGX + " هەڵەیەک لە یارییەکەدا ڕوویدا.")

