# ----------------- سیستەمی دژە سپام (Anti-Spam) -----------------
EXEMPT_CHAT_ID = -1002485156661
SPAM_INTERVAL = 6

last_sticker_time = {}
last_gif_time = {}

async def anti_spam_handler(update, context):
    """
    سیستەمی دژەسپام:
    - ستیکەر: لە ماوەی ٧ چرکەدا تەنیا یەک دانە — ئەوی دواتر دەسڕێتەوە
    - GIF/ئەنیمیشن: هەمان یاسای ستیکەر
    - فۆرواردکراوی دەرەکی: دەسڕێتەوە (FAST-PATH — کەمتر لە ١٠٠ms)
    - ستۆری: دەسڕێتەوە
    - چەناڵی دەرەکی: دەسڕێتەوە (بێدەنگ)
    - لینکی دەرەکی: دەسڕێتەوە
    ئادمین و خاوەن بۆت ئازادن
    """
    if not update.message:
        return

    msg  = update.message
    chat = update.effective_chat
    user = update.effective_user

    if not chat or chat.type == "private":
        return

    # خاوەن بۆت تەنیا — ئازادە
    if user and user.id == OWNER_ID:
        return

    # ⚡ ⚡ ⚡ FAST-PATH: فۆرواردی دەرەکی — یەکەم شت بسڕە، نە analytics، نە cache
    # ئەمە کاتی دەستوەرگرتنی forwardی سپام لە ٢٠٠-٥٠٠ms دادەبەزێنێت بۆ کەمتر لە ٥٠ms
    # چونکە هیچ I/O ئەجرا نابێت پێش بەرگری: سڕینەوە یەکەم، analytics پاشان
    if _is_forward_msg(msg):
        sender_chat = getattr(msg, 'sender_chat', None)
        # تەنها پۆستی چەناڵی پەیوەستکراو ـی ئازاد بە
        if sender_chat and sender_chat.id in (LINKED_CHANNEL_ID, DISCUSS_CHANNEL_ID, OWNER_ID):
            pass  # ئازادە — بەردەوام بە بە چێکی ئاسایی
        elif _is_forward_from_allowed_channel(msg):
            pass  # چەناڵی ڕێپێدراو — بەردەوام بە
        else:
            # سڕینەوەی فۆرواردی نائاسایی ـ خێرا و بێ پرسیار
            try:
                await msg.delete()
            except Exception:
                pass
            # ئامار پێشتر لە سەرەوەی handle_all_messages تۆمارکراوە
            return

    # ── Cached group access check ──
    _now_s = time.time()
    _csa = _GROUP_ACCESS_CACHE.get(chat.id)
    if _csa and _now_s < _csa[1]:
        if not _csa[0]: return
    else:
        _a_s = is_group_allowed(chat.id, chat.type)
        _GROUP_ACCESS_CACHE[chat.id] = (_a_s, _now_s + _GROUP_CACHE_TTL)
        if not _a_s: return
    # چەناڵی پەیوەستکراوی خۆی — ئازاد
    sender_chat = getattr(msg, 'sender_chat', None)
    if sender_chat and sender_chat.id in (LINKED_CHANNEL_ID, DISCUSS_CHANNEL_ID, OWNER_ID):
        return

    _cid_str = str(chat.id)
    should_delete = False
    reason = ""

    # ── ئامار پێشتر لە سەرەوەی handle_all_messages تۆمارکراوە ──

    # ── ١. ستیکەر — لە ٧ چرکەدا تەنیا یەک ──
    is_sticker = bool(msg.sticker)
    is_gif     = bool(msg.animation or
                     (msg.document and msg.document.mime_type == "video/mp4"))

    # ── ژمێرەری محتوا تەنها بۆ ستیکەر/GIF — تێکستی ئاسایی لە handle_group_messages_for_content دەژمێرێت ──
    if is_sticker or is_gif:
        await _increment_content_counter(chat.id, context, trigger_msg=msg)

    if is_sticker and _mod_get(_cid_str, "sticker_spam", True):
        _uid = user.id if user else 0
        _key = (_cid_str, _uid)
        _now = time.time()
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> تەنها دوایین timestamp پاشەکەوت دەکرێت — list filter نابێت
        if _now - GIF_TRACKER.get(_key, 0.0) < GIF_LIMIT:
            should_delete = True
            reason = "spam_sticker"
        else:
            GIF_TRACKER[_key] = _now

    # ── ٢. GIF/ئەنیمیشن — لە ٧ چرکەدا تەنیا یەک ──
    elif is_gif and _mod_get(_cid_str, "gif_spam", True):
        _uid = user.id if user else 0
        _key = (_cid_str, _uid)
        _now = time.time()
        if _now - GIF_TRACKER.get(_key, 0.0) < GIF_LIMIT:
            should_delete = True
            reason = "spam_gif"
        else:
            GIF_TRACKER[_key] = _now

    # ── ٣. ستۆری ──
    _is_story = (
        getattr(msg, 'story', None) is not None or
        getattr(getattr(msg, 'forward_origin', None), 'type', None) in ('story', 'Story') or
        (hasattr(msg, 'forward_origin') and msg.forward_origin is not None and
         'story' in str(type(msg.forward_origin)).lower()) or
        getattr(msg, 'forward_from_story', None) is not None
    )
    if _is_story and _mod_get(_cid_str, "story_filter", True):
        should_delete = True
        reason = "story"

    # ── ٤. فۆرواردکراوی دەرەکی (پاراستن بۆ توربۆ-handler) ──
    # تێبینی: forward بنەڕەتی پێشتر لە fast-path سڕاوە؛ ئەمە تەنها بۆ
    # دۆخی نائاسایی کە fast-path نەیتوانیوە بیسڕێتەوە (مثلا exception)
    elif not should_delete and _is_forward_msg(msg) and _mod_get(_cid_str, "forward_filter", True):
        if not _is_forward_from_allowed_channel(msg):
            should_delete = True
            reason = "forward_external"

    # ── ٥. پۆستی چەناڵی دەرەکی ──
    elif sender_chat and sender_chat.id not in (LINKED_CHANNEL_ID, DISCUSS_CHANNEL_ID, OWNER_ID):
        should_delete = True
        reason = "channel_post"

    # ── ٦. لینکی دەرەکی ──
    elif msg.text and not _is_link_allowed(msg.text):
        should_delete = True
        reason = "external_link"
    elif msg.caption and not _is_link_allowed(msg.caption):
        should_delete = True
        reason = "external_link_caption"

    if not should_delete:
        return

    # سڕینەوە
    try:
        await msg.delete()
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    # ئاگادارکردنەوەی کاتبەسەر (٥ چرکە)
    _name = _html_escape((user.first_name if user else None) or "کەس")

    if reason in ("forward_external", "channel_post", "spam_sticker", "spam_gif"):
        pass  # بێدەنگ — هیچ پەیامێک ناشێرێت

    elif reason == "story":
        try:
            _w = await msg.chat.send_message(
                f"<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> <b>{_name}</b> — هێنانەوەی ستۆری ڕێپێنەدراوە.",
                parse_mode="HTML"
            )
            await asyncio.sleep(5)
            await _w.delete()
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    elif reason == "external_link":
        try:
            _w = await msg.chat.send_message(
                f"<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> <b>{_name}</b> — لینکی دەرەکی ڕێپێنەدراوە.",
                parse_mode="HTML"
            )
            await asyncio.sleep(5)
            await _w.delete()
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored


# ── Cache بۆ is_admin — TTL 60 چرکە ──
# <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX v97: plain dict بەکاردەهێنێت — tuple کلیلەکان و TTL float values
#             بە JSON ناگونجێن، RedisCache بەکاردەهاتن هەڵەی 1535 جاری دروستکرد
_ADMIN_STATUS_CACHE: dict = {}   # {(chat_id, user_id): (bool, expire_ts)}
_ADMIN_CACHE_TTL = 600.0   # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 300→600 — ١٠ خولەکت

# ═════════════════════════
# <tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji>️ Admin Guardian — پاراستنی گرووپ لە هەڵسوکەوتی ئادمینە ناڕێک
# ئەگەر ئادمینێک ٥ میمبەری ڕیمۆڤ کرد لە ١ خولەک، ئۆتۆماتیک دیمۆت دەکرێت
# ═════════════════════════

_ADMIN_REMOVE_LOG: Dict[Tuple[int, int], deque] = {}
_GUARDIAN_MAX_REMOVES = 5
_GUARDIAN_WINDOW_SEC  = 60
_GUARDIAN_DEMOTED: Dict[Tuple[int, int], float] = {}
_GUARDIAN_LOG_FILE = "admin_guardian_log.json"

async def _guardian_demote_admin(chat_id: int, admin_id: int, admin_name: str,
                                  context: CallbackContext):
    """دیمۆتکردنی ئادمین — هەموو مۆڵەتەکانی لادەبرێت"""
    key = (chat_id, admin_id)
    _GUARDIAN_DEMOTED[key] = time.time()

    try:
        await context.bot.promote_chat_member(
            chat_id=chat_id,
            user_id=admin_id,
            can_manage_chat=False,
            can_delete_messages=False,
            can_manage_video_chats=False,
            can_restrict_members=False,
            can_promote_members=False,
            can_change_info=False,
            can_invite_users=False,
            can_post_messages=False,
            can_edit_messages=False,
            can_pin_messages=False,
            can_post_stories=False,
            can_edit_stories=False,
            can_delete_stories=False,
            can_manage_topics=False,
        )

        for cache_key in list(_ADMIN_STATUS_CACHE.keys()):
            if isinstance(cache_key, tuple) and len(cache_key) >= 2:
                if cache_key[0] == chat_id and cache_key[1] == admin_id:
                    del _ADMIN_STATUS_CACHE[cache_key]

        mention = f'<a href="tg://user?id={admin_id}">{admin_name}</a>'
        alert_text = (
            f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji><tg-emoji emoji-id=\"5823259308665607384\">🚨</tg-emoji> <b>سیستەمی پاراستنی گرووپ</b>\n\n"
            f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئادمین {mention} لە ئادمینی لابرا!\n\n"
            f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>هۆکار:</b> ڕیمۆڤکردنی <b>{_GUARDIAN_MAX_REMOVES} میمبەر</b> "
            f"لە ماوەی <b>{_GUARDIAN_WINDOW_SEC} چرکە</b>\n\n"
            f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> هەموو مۆڵەتەکانی لابران و ناتوانێت هیچ فەرمانێکی ئادمینانە بەکاربهێنێت.\n\n"
            f"ℹ️ <i>ئەم کردارە ئۆتۆماتیک بووە بۆ پاراستنی گرووپ.</i>"
        )
        await context.bot.send_message(chat_id=chat_id, text=alert_text, parse_mode="HTML")

        try:
            owner_text = (
                f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> <b>Guardian Alert</b>\n"
                f"ئادمین {admin_name} (ID: <code>{admin_id}</code>) دیمۆت کرا\n"
                f"لە چات: <code>{chat_id}</code>\n"
                f"هۆکار: {_GUARDIAN_MAX_REMOVES} ڕیمۆڤ لە {_GUARDIAN_WINDOW_SEC}چ"
            )
            await context.bot.send_message(chat_id=OWNER_ID, text=owner_text, parse_mode="HTML")
        except Exception as _load_err:
            logger.debug("Telegram API suppressed (intentional): %s", _load_err)

        log_data = _guardian_load_log()
        log_data.append({
            "chat_id": chat_id, "admin_id": admin_id, "admin_name": admin_name,
            "timestamp": datetime.datetime.now().isoformat(),
            "reason": f"{_GUARDIAN_MAX_REMOVES} removes in {_GUARDIAN_WINDOW_SEC}s"
        })
        _guardian_save_log(log_data)
        _ADMIN_REMOVE_LOG.pop(key, None)

        logger.warning(f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> Guardian: ئادمین {admin_name} ({admin_id}) دیمۆت کرا لە {chat_id}")
        audit_log("GUARDIAN_DEMOTE", admin_id, chat_id=chat_id,
                  details=f"Demoted after {_GUARDIAN_MAX_REMOVES} removes in {_GUARDIAN_WINDOW_SEC}s")

    except Exception as e:
        logger.error(f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> Guardian: هەڵە لە دیمۆتکردنی {admin_id}: {e}")
        try:
            await context.bot.send_message(
                chat_id=chat_id,
                text=f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji><tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> نەتوانرا ئادمین {admin_name} دیمۆت بکرێت.\nهۆکار: {e}\n"
                     f"تکایە دڵنیابە لەوەی بۆتەکە مۆڵەتی promote هەیە.",
                parse_mode="HTML"
            )
        except Exception as _load_err:
            logger.debug("Telegram API suppressed (intentional): %s", _load_err)

async def _guardian_check_before_cmd(update: Update, context: CallbackContext) -> bool:
    """ئەگەر ئادمینەکە دیمۆت کرابێت لەلایەن Guardian — True بگەڕێنەوە و بلۆکی بکە"""
    user = update.effective_user
    chat = update.effective_chat
    if not user or not chat:
        return False
    key = (chat.id, user.id)
    if key in _GUARDIAN_DEMOTED:
        try:
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji><tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> <b>ڕۆڵی ئادمینیت لابراوە!</b>\n\n"
                "لەلایەن سیستەمی پاراستنی گرووپەوە مۆڵەتەکانت لابراون.\n"
                "تکایە پەیوەندی بە خاوەنی گرووپ بکە.",
                parse_mode="HTML"
            )
        except Exception as _load_err:
            logger.debug("Telegram API suppressed (intentional): %s", _load_err)
        return True
    return False

# ═════════════════════════

async def is_admin(update: Update, context: CallbackContext) -> bool:
    """پشکنینی ئەوەی ئایا بەکارهێنەرەکە بەڕێوەبەری (ئادمین) گرووپەکەیە؟ — کاچکراو"""
    try:
        user_id = update.effective_user.id
        if user_id == OWNER_ID:
            return True
        chat = update.effective_chat
        if chat.type == "private":
            return user_id == OWNER_ID
        # ── Cache check ──
        _now_a = time.time()
        _key_a = (chat.id, user_id)
        _cached_a = _ADMIN_STATUS_CACHE.get(_key_a)
        if _cached_a and _now_a < _cached_a[1]:
            return _cached_a[0]
        # ── API call ──
        member = await context.bot.get_chat_member(chat.id, user_id)
        result = member.status in ["administrator", "creator"]
        _ADMIN_STATUS_CACHE[_key_a] = (result, _now_a + _ADMIN_CACHE_TTL)
        return result
    except Exception as e:
        logger.error("هەڵە لە پشکنینی ئادمین (is_admin): %s", e)
        return False

async def is_restrict_admin(update: Update, context: CallbackContext) -> bool:
    """
    پشکنینی مۆڵەتی can_restrict_members — کاچکراو (60s TTL)
    پشتگیری لە: ئادمینی ئاسایی + چەناڵی بەستراو (LINKED_CHANNEL_ID)
    """
    try:
        chat = update.effective_chat

        # ── چەناڵی بەستراو — sender_chat ──
        msg = update.message or update.edited_message
        if msg:
            sender_chat = getattr(msg, "sender_chat", None)
            if sender_chat and sender_chat.id == LINKED_CHANNEL_ID:
                return True

        user = update.effective_user
        if not user:
            return False
        user_id = user.id
        if user_id == OWNER_ID:
            return True
        if chat.type == "private":
            return user_id == OWNER_ID
        # ── Cache check (restrict-specific) ──
        _now_r = time.time()
        _key_r = (chat.id, user_id, "restrict")
        _cached_r = _ADMIN_STATUS_CACHE.get(_key_r)
        if _cached_r and _now_r < _cached_r[1]:
            return _cached_r[0]
        member = await context.bot.get_chat_member(chat.id, user_id)
        if member.status == "creator":
            _ADMIN_STATUS_CACHE[_key_r] = (True, _now_r + _ADMIN_CACHE_TTL)
            return True
        if member.status == "administrator":
            result_r = bool(getattr(member, "can_restrict_members", False))
            _ADMIN_STATUS_CACHE[_key_r] = (result_r, _now_r + _ADMIN_CACHE_TTL)
            return result_r
        _ADMIN_STATUS_CACHE[_key_r] = (False, _now_r + _ADMIN_CACHE_TTL)
        return False
    except Exception as e:
        logger.error("هەڵە لە پشکنینی مۆڵەتی ڕێسترکت: %s", e)
        return False

async def _is_linked_channel_admin(update: Update) -> bool:  # noqa: ASYNC100 — PTB job queue requires coroutine
    """
    ئایا ئەم پەیامە لە چەناڵی بەستراو هاتووە (sender_chat == LINKED_CHANNEL_ID)؟
    بۆ بەکارهێنان لە band_cmd و فەرمانەکانی تر.
    """
    msg = update.message or update.edited_message
    if msg:
        sender_chat = getattr(msg, "sender_chat", None)
        if sender_chat and sender_chat.id == LINKED_CHANNEL_ID:
            return True
    return False

