# سیستەمی ئامارەکانی هەفتانە (Weekly Activity)
# WEEKLY_STATS لە main.py import کراوە — ئەوێ definition و load هەیە
# ═════════════════════════

@guarded
async def weekac_cmd(update: Update, context: CallbackContext):
    """لیستی هەفتانەی چالاکترین ١٠ کەس — بە تاگ"""
    await _send_weekac(update.message, context, edit=False)

async def _send_weekac(msg_or_query, context, edit=False):
    """دروستکردن و ناردنی پەیامی هەفتانە"""

    # chat_id بدۆزەرەوە
    if edit:
        chat = msg_or_query.message.chat
        chat_id = str(chat.id)
    else:
        chat = msg_or_query.chat
        chat_id = str(chat.id)

    week_key = _get_week_key()
    week_data = WEEKLY_STATS.get(chat_id, {}).get(week_key, {})

    # ئیمۆجیەکانی ڕۆجانی هەفتە
    now = datetime.datetime.now()
    day_names = ["دووشەممە","سێشەممە","چوارشەممە","پێنجشەممە","هەینی","شەممە","یەکشەممە"]
    day_name = day_names[now.weekday()]
    week_num = now.isocalendar()[1]

    # ئەگەر هیچ داتایەک نەبوو
    if not week_data:
        text = (
            f"{_TCH} <b>لیستی چالاکترینانی ئەم هەفتەیە</b>\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            "<tg-emoji emoji-id=\"5384249028936477156\">😶</tg-emoji> هێشتا کەس پەیامی نەنێردووە ئەم هەفتەیە!\n\n"
            "<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> <i>پەیامەکانت دەنێری تا لیستەکە پڕ بێت</i>"
        )
        kb = InlineKeyboardMarkup([[
            _ebtn("نوێکردنەوە", "weekac:refresh", emoji_id="5353025084845994828", api_kwargs={"style": "primary"}),
            _ebtn("هەفتەی پێشوو", "weekac:prev", emoji_id="5255703720078879038", api_kwargs={"style": "primary"})
        ]])
        if edit:
            try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
            except Exception as _exc:
                if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)
        else:
            await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)
        return

    # top 10
    top10 = sorted(week_data.items(), key=lambda x: x[1], reverse=True)[:10]
    total_msgs = sum(week_data.values())
    total_users = len(week_data)
    max_cnt = top10[0][1] if top10 else 1

    lines = []
    tag_parts = []

    for i, (uid, cnt) in enumerate(top10):
        try:
            # چەناڵ یان ئەکاونت
            if uid.startswith("-"):
                chat_obj = await context.bot.get_chat(int(uid))
                name = chat_obj.title or f"چەناڵ {uid}"
                if chat_obj.username:
                    mention = f"@{chat_obj.username}"
                else:
                    mention = f"<tg-emoji emoji-id=\"6024112973226709843\">📢</tg-emoji> {name}"
            else:
                member = await context.bot.get_chat_member(chat.id, int(uid))
                name = member.user.first_name
                if member.user.username:
                    mention = f"@{member.user.username}"
                else:
                    mention = f'<a href="tg://user?id={uid}">{name}</a>'
        except Exception:
            name = f"بەکارهێنەر {uid}"
            mention = name

        # باری پرۆگرەس
        bar_len = max(1, int(cnt / max_cnt * 10))
        bar = "█" * bar_len + "░" * (10 - bar_len)
        pct = int(cnt / total_msgs * 100)

        medal = MEDAL_EMOJIS[i]
        crown = CROWN_COLORS[i]

        lines.append(
            f"{medal} {mention} {crown}\n"
            f"   ┗ <tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> <b>{cnt:,}</b> پەیام  {bar}  <i>{pct}%</i>"
        )
        tag_parts.append(mention)

    tag_line = "  ".join(tag_parts)

    # دروستکردنی دەق
    text = (
        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>چالاکترینانی ئەم هەفتەیە</b> <tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> هەفتەی <b>{week_num}</b>  |  <tg-emoji emoji-id=\"5395344333916376249\">🗓</tg-emoji> {day_name}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        + "\n\n".join(lines) +
        f"\n\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> کۆی پەیامەکان: <b>{total_msgs:,}</b>  |  <tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> ژ. کەسان: <b>{total_users}</b>\n"
        f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> هەموو هەفتەیەک سفر دەبێتەوە بە شەوی یەکشەممە\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5395487321967596182\">🏷</tg-emoji> <i>تاگکراوەکان:</i>\n{tag_line}"
    )

    kb = InlineKeyboardMarkup([
        [
            _ebtn("نوێکردنەوە", "weekac:refresh", emoji_id="5353025084845994828", api_kwargs={"style": "primary"}),
            _ebtn("هەفتەی پێشوو", "weekac:prev", emoji_id="5255703720078879038", api_kwargs={"style": "primary"}),
        ],
        [
            _ebtn("ئاماری هەفتەکانی تر", "weekac:history", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
        ]
    ])

    if edit:
        try:
            await msg_or_query.edit_message_text(
                text, parse_mode="HTML",
                reply_markup=kb,
                disable_web_page_preview=True
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    else:
        await msg_or_query.reply_text(
            text, parse_mode="HTML",
            reply_markup=kb,
            disable_web_page_preview=True
        )

async def weekac_callback(update: Update, context: CallbackContext):
    """کالبەکی دووگمەکانی /weekac"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    action = query.data.split(":", 1)[1] if ":" in query.data else ""
    chat_id = str(query.message.chat.id)

    if action == "refresh":
        await _send_weekac(query, context, edit=True)

    elif action == "prev":
        # هەفتەی پێشوو
        now = datetime.datetime.now()
        prev_week = now - datetime.timedelta(weeks=1)
        prev_key = f"{prev_week.year}-W{prev_week.isocalendar()[1]:02d}"
        week_data = WEEKLY_STATS.get(chat_id, {}).get(prev_key, {})

        if not week_data:
            await answered("📭 هیچ داتایەکی هەفتەی پێشوو نییە!", show_alert=True)
            return

        top10 = sorted(week_data.items(), key=lambda x: x[1], reverse=True)[:10]
        total_msgs = sum(week_data.values())
        max_cnt = top10[0][1] if top10 else 1
        lines = []
        tag_parts = []

        for i, (uid, cnt) in enumerate(top10):
            # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> cached name — fallback to API only for channels
            try:
                if uid.startswith("-"):
                    chat_obj = await context.bot.get_chat(int(uid))
                    name = chat_obj.title or f"چەناڵ {uid}"
                    mention = f"@{chat_obj.username}" if chat_obj.username else f"<tg-emoji emoji-id=\"6024112973226709843\">📢</tg-emoji> {name}"
                else:
                    ud_cs = USERS.get(uid, {})
                    name = ud_cs.get("name") or ud_cs.get("nickname") or f"بەکارهێنەر {uid[-4:]}"
                    mention = f'<a href="tg://user?id={uid}">{name}</a>'
            except Exception:
                name = f"بەکارهێنەر {uid}"
                mention = name

            bar_len = max(1, int(cnt / max_cnt * 10))
            bar = "█" * bar_len + "░" * (10 - bar_len)
            pct = int(cnt / total_msgs * 100)
            lines.append(
                f"{MEDAL_EMOJIS[i]} {mention} {CROWN_COLORS[i]}\n"
                f"   ┗ <tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> <b>{cnt:,}</b> پەیام  {bar}  <i>{pct}%</i>"
            )
            tag_parts.append(mention)

        tag_line = "  ".join(tag_parts)
        prev_week_num = prev_week.isocalendar()[1]
        text = (
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>هەفتەی پێشوو — هەفتەی {prev_week_num}</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            + "\n\n".join(lines) +
            f"\n\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> کۆی پەیامەکان: <b>{total_msgs:,}</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5395487321967596182\">🏷</tg-emoji> <i>تاگکراوەکان:</i>\n{tag_line}"
        )
        kb = InlineKeyboardMarkup([[
            _ebtn("هەفتەی ئێستا", "weekac:refresh", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})
        ]])
        await _safe_edit(query, text, reply_markup=kb, disable_web_page_preview=True)

    elif action == "history":
        # لیستی هەفتەکانی بارکراو
        chat_weeks = WEEKLY_STATS.get(chat_id, {})
        if not chat_weeks:
            await answered("📭 هیچ داتایەکی پێشوو نییە!", show_alert=True)
            return
        # ڕیزکردن بەپێی کلیل (نوێترین دواتر)
        sorted_weeks = sorted(chat_weeks.keys(), reverse=True)[:8]
        lines_h = []
        for wk in sorted_weeks:
            wdata = chat_weeks[wk]
            total = sum(wdata.values())
            top1 = max(wdata, key=wdata.get) if wdata else None
            top1_name = top1 if top1 else "—"
            if top1:
                try:
                    if top1.startswith("-"):
                        co = await context.bot.get_chat(int(top1))
                        top1_name = co.title or top1
                    else:
                        m = await context.bot.get_chat_member(query.message.chat.id, int(top1))
                        top1_name = _html_escape(m.user.first_name)
                except Exception:
                    top1_name = f"بەکارهێنەر {top1}"
            lines_h.append(f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>{wk}</b> — {total:,} پەیام  |  <tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> {top1_name}")

        text_h = (
            f"{_TCH} <b>مێژووی هەفتەکانی پێشوو</b>\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            + "\n".join(lines_h) +
            "\n\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"
        )
        kb_h = InlineKeyboardMarkup([[
            _ebtn("گەڕانەوە", "weekac:refresh", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})
        ]])
        await _safe_edit(query, text_h, reply_markup=kb_h)

async def whisper_cmd(update: Update, context: CallbackContext):
    """
    /whisper @user نامەکەت          ← ئاسایی
    /whisper @user نامەکەت --anon   ← ناناس
    """
    chat   = update.effective_chat
    sender = update.effective_user

    # ── پڕایڤت: ڕێنمایی ──
    if chat.type == "private":
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5190859184312167965\">💌</tg-emoji> <b>چرپەنامە — سیستەمی نامەی نهێنی</b>\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> <b>شێوازەکان:</b>\n\n"
            "١. <b>فەرمان لە گرووپ:</b>\n"
            "<code>/whisper @username نامەکەت</code>\n\n"
            "٢. <b>Inline mode (لە هەر شوێنێک):</b>\n"
            "<code>@best_313bot نامەکەت @username</code>\n\n"
            "٣. <b>ناناس بنێرە:</b>\n"
            "<code>/whisper @username نامەکەت --anon</code>\n\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> نامەکان دوای <b>٢٤ کاتژمێر</b> بەخۆیەوە دەسرێنەوە\n"
            "<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> تەنها گیرنەر دەیخوێنێتەوە\n"
            "↩️ گیرنەر دەتوانێت وەڵامی نهێنی بدات",
            parse_mode="HTML"
        )
        return

    # ── پارس کردن ──
    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5190859184312167965\">💌</tg-emoji> <b>شێوازی بەکارهێنان:</b>\n"
            "<code>/whisper @username نامەکەت</code>\n\n"
            "ناناس: <code>/whisper @username نامەکەت --anon</code>",
            parse_mode="HTML"
        )
        return

    anon = "--anon" in args
    args = [a for a in args if a != "--anon"]

    target_username = None
    msg_parts = []
    for arg in args:
        if arg.startswith("@") and len(arg) > 1 and target_username is None:
            target_username = arg.lstrip("@")
        else:
            msg_parts.append(arg)

    if not target_username:
        await update.message.reply_text(
            _TGX + " @username زیاد بکە!\n"
            "نموونە: <code>/whisper @Sara سڵاو!</code>",
            parse_mode="HTML"
        )
        return

    secret_msg = " ".join(msg_parts).strip()
    if not secret_msg:
        await update.message.reply_text(_TGX + " نامەکەت بەتاڵە!", parse_mode="HTML")

        return
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: ٥٠٠ → ٢٠٠٠ پیت (popup سنوور نییە ئێستا)
    MAX_WHISPER = 2000
    if len(secret_msg) > MAX_WHISPER:
        await update.message.reply_text(
            f"{_TGX} نامەکەت زۆر درێژە!\n"
            f"<tg-emoji emoji-id=\"5375510007439711210\">📏</tg-emoji> ئێستا: {len(secret_msg)} پیت\n"
            f"<tg-emoji emoji-id=\"5375510007439711210\">📏</tg-emoji> زۆرترین: {MAX_WHISPER} پیت",
            parse_mode="HTML"
        )
        return

    # ── سڕینەوەی نامەکۆنەکان ──
    _w_clean_expired()

    # ── دۆزینەوەی ئایدی گیرنەر (بۆ بەکارهێنەرانی بێ-username) ──
    target_user_id = 0
    try:
        chat_obj = await context.bot.get_chat(f"@{target_username}")
        if chat_obj and chat_obj.id:
            target_user_id = chat_obj.id
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    # ── دروستکردنی token ──
    token, _ = _w_new_entry(sender, target_username, secret_msg, chat.id, anon,
                            target_user_id=target_user_id)

    text, markup = _w_display_card(token)

    # سڕینەوەی نامەی بەکارهێنەر
    try:
        await update.message.delete()
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    try:
        sent = await context.bot.send_message(
            chat_id=chat.id,
            text=text,
            parse_mode="HTML",
            reply_markup=markup
        )
        WHISPER_DATA[token]["message_id"] = sent.message_id
        _WMSGID_MAP[f"{chat.id}:{sent.message_id}"] = token
        _w_save()
    except Exception as e:
        logger.error("whisper send error: %s", e)
        return

    # ئاگادارکردنەوەی گیرنەر — mention کورت و دەسرێتەوە
    async def _notify_target():
        try:
            sender_display = "ناناس <tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji>" if anon else sender.first_name
            mention = f"@{target_username}" if target_username else f"بەکارهێنەر"
            tag = await context.bot.send_message(
                chat_id=chat.id,
                text=f"<tg-emoji emoji-id=\"5190859184312167965\">💌</tg-emoji> {mention}، نامەیەکی نهێنیت هەیە لە {sender_display}! بۆتوندەکە کرتە بکە.",
                parse_mode="HTML"
            )
            await asyncio.sleep(10)
            try:
                await tag.delete()
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    _task_notify = asyncio.create_task(_notify_target())
    _task_notify.add_done_callback(lambda t: t.exception() if not t.cancelled() else None)


# ── Callback: خوێندنەوە و وەڵامدان ─── ⋆⋅☆⋅⋆ ───

async def whisper_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)   # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> FIX: پێش هەر شتێک
    user  = query.from_user
    parts = query.data.split(":", 2)

    if len(parts) < 3:
        await answered("❌" + " داتا هەڵەیە", show_alert=True)
        return

    action = parts[1]  # r = read, rep = reply
    token  = parts[2]

    # ── خوێندنەوە ──
    if action == "r":
        d = WHISPER_DATA.get(token)
        if not d:
            try:
                await answered(
                    "<tg-emoji emoji-id=\"5454415424319931791\">⌛</tg-emoji> نامەکە نەدۆزرایەوە یان کاتی تەواو بووە.\n"
                    f"نامەکان دوای {_WHISPER_TTL//86400} ڕۆژ دەسرێنەوە.",
                    show_alert=True
                )
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            # کارتەکە بسرەوە
            try: await query.message.delete()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return

        target_uname    = d.get("target_username", "").lower()
        target_user_id  = d.get("target_user_id", 0)
        sender_id       = d.get("sender_id", 0)
        user_uname      = (user.username or "").lower().lstrip("@")
        is_target       = (
            (user_uname and user_uname == target_uname) or
            (target_user_id and user.id == target_user_id)
        )
        is_sender       = (not d.get("anon")) and user.id == sender_id

        # ── نەخوێندراوەکان کە مۆڵەتیان نییە ──
        if not is_target and not is_sender:
            await answered(
                f"<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> ئەم نامەیە بۆ @{target_uname} ییە!\n"
                "تۆ مۆڵەتت نییە بیخوێنیتەوە.",
                show_alert=True
            )
            return

        # ── نامەکە بخوێنەوە ──
        try:
            msg_text = _w_decrypt(d["enc_message"], d["enc_key"])
        except Exception:
            await answered("❌" + " هەڵە لە کۆدگشاردنی نامەکە", show_alert=True)
            return

        # تۆمارکردنی خوێندنەوە
        read_by = d.setdefault("read_by", [])
        if user.id not in read_by:
            read_by.append(user.id)
            _w_save()
        # ✅ FIX BUG-2: edit_text تەنها یەکجار کراوە — لە ژێر دوای ناردنی پەیامی نهێنی

        # ── <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: نامەکە بە پەیامی نهێنی دەنێریت نەک popup ──
        # popup سنووری ٢٠٠ کاراکتەری هەیە — نامەی درێژ کراش دەکات
        label = "<tg-emoji emoji-id=\"5376478984535975697\">📥</tg-emoji> نامەی نهێنی بۆ تۆ" if is_target else "<tg-emoji emoji-id=\"5377688956774792701\">📤</tg-emoji> نامەی ناردراوت"

        # ── دەستنیشانکردنی keyboard ──
        if is_target and not d.get("reply_token"):
            keyboard = [
                [_ebtn("دووبارە بخوێنەرەوە", f"wp:r:{token}", api_kwargs={"icon_custom_emoji_id": "5379687326991555987", "style": "success"}),
                 _ebtn("↩️ وەڵامی نهێنی بدە", f"wp:rep:{token}", api_kwargs={"style": "primary"})],
            ]
        else:
            keyboard = [
                [_ebtn("دووبارە بخوێنەرەوە", f"wp:r:{token}", api_kwargs={"icon_custom_emoji_id": "5379687326991555987", "style": "success"})]
            ]

        # ── نمایشی نامە ──
        sender_display = d.get("sender_name","؟")
        is_anon = d.get("anon", False)
        from_txt = "ناناس <tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji>" if is_anon else sender_display

        # ── ✅ FIX: via (inline) whisper — query.message = None ──
        is_via = bool(query.inline_message_id and not query.message)

        # ── پەیامی نهێنی ──
        if is_via:
            # via ویسپەر: تەنها popup دەکرێت (chat_id نییە)
            short = msg_text[:200] + ("…" if len(msg_text) > 200 else "")
            try:
                await answered(short, show_alert=True)
            except Exception:
                await answered(msg_text[:50], show_alert=True)
        else:
            # ئاسایی: پەیامی نهێنی بنێرە
            try:
                secret_preview = msg_text if len(msg_text) <= 3000 else msg_text[:3000] + "…"
                sent_secret = await context.bot.send_message(
                    chat_id=query.message.chat.id,
                    text=(
                        f"<tg-emoji emoji-id=\"5231302159739395058\">🔓</tg-emoji> <b>{label}</b>\n"
                        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
                        f"<tg-emoji emoji-id=\"5377688956774792701\">📤</tg-emoji> لە: <b>{from_txt}</b>\n\n"
                        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> <b>نامەکە:</b>\n"
                        f"{secret_preview}"
                    ),
                    parse_mode="HTML",
                    reply_markup=InlineKeyboardMarkup(keyboard)
                )
                async def _delete_secret(msg):
                    await asyncio.sleep(60)
                    try: await msg.delete()
                    except Exception as _exc:
                        logger.debug("Suppressed Exception: %s", _exc)
                _task_del = asyncio.create_task(_delete_secret(sent_secret))
                _task_del.add_done_callback(lambda t: t.exception() if not t.cancelled() else None)
            except Exception as _se:
                logger.error("whisper read send error: %s", _se)
                short = msg_text[:180] + ("…" if len(msg_text) > 180 else "")
                try:
                    await answered(f"💌 {label}:\n\n{short}", show_alert=True)
                except Exception:
                    await answered("💌 نامەکەت خوێندیتەوە!", show_alert=True)
            await answered()

        # ── نوێکردنەوەی کارتی ئەصلی ──
        try:
            new_text, new_markup = _w_display_card(token)
            if is_via:
                # ✅ FIX: via — بە do_api_request نووێ دەکرێتەوە
                read_count2  = len(d.get("read_by", []))
                btn_label2   = "دووبارە بخوێنەرەوە" if read_count2 else "خوێندنەوەی نامەکە"
                has_reply2   = bool(d.get("reply_token"))
                inline_kb    = [[{
                    "text":                 btn_label2,
                    "callback_data":        f"wp:r:{token}",
                    "icon_custom_emoji_id": "5379687326991555987",
                    "style":                "primary",
                }]]
                if has_reply2:
                    inline_kb.append([{
                        "text":          "↩️ وەڵامەکە ببینە",
                        "callback_data": f"wp:r:{d['reply_token']}",
                        "style":         "primary",
                    }])
                await _w_api_request(context.bot, "editMessageText", {
                        "inline_message_id": query.inline_message_id,
                        "text":              new_text,
                        "parse_mode":        "HTML",
                        "reply_markup":      {"inline_keyboard": inline_kb},
                    })
            else:
                await query.message.edit_text(new_text, parse_mode="HTML", reply_markup=new_markup)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)
        return

    # ── وەڵامدان ──
    if action == "rep":
        d = WHISPER_DATA.get(token)
        if not d:
            await answered("❌" + " نامەکە نەدۆزرایەوە", show_alert=True)
            return

        target_uname   = d.get("target_username", "").lower()
        target_uid_rep = d.get("target_user_id", 0)
        user_uname     = (user.username or "").lower().lstrip("@")

        is_tgt_rep = (
            (user_uname and user_uname == target_uname) or
            (target_uid_rep and user.id == target_uid_rep)
        )
        if not is_tgt_rep:
            await answered("🚫 تەنها گیرنەر دەتوانێت وەڵام بدات", show_alert=True)
            return

        if d.get("reply_token"):
            await answered("⚠️ پێشتر وەڵامی دراوە بەم نامەیە!", show_alert=True)
            return

        # پاشەکەوتکردنی حالەتی چاوەڕوانی وەڵام
        _WHISPER_PENDING[user.id] = token
        context.user_data["whisper_reply_to"] = token

        # ✅ FIX: via ویسپەر — query.message = None
        chat_id = d.get("chat_id") or (query.message.chat.id if query.message else None)
        await answered("💬 وەڵامەکەت بنووسە — پەیامەکەت بنێرە!", show_alert=True)

        async def _rep_hint_cleanup():
            # ✅ FIX: via ویسپەر — chat_id = None بوو → send_message ناکرێت
            if not chat_id:
                await asyncio.sleep(300)
                _WHISPER_PENDING.pop(user.id, None)
                context.user_data.pop("whisper_reply_to", None)
                return
            try:
                hint = await context.bot.send_message(
                    chat_id=chat_id,
                    text=(
                        f"↩️ {user.first_name}، وەڵامەکەت بنووسە\n"
                        f"<i>تەنها پەیامەکەت بنێرە — بەبێ هیچ فەرمانێک</i>\n\n"
                        f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> ٥ خولەک کات هەیت. وایلێبێت!"
                    ),
                    parse_mode="HTML"
                )
                await asyncio.sleep(300)
                try:
                    await hint.delete()
                except Exception as _e:
                    logger.debug("Suppressed (intentional): %s", _e)
                _WHISPER_PENDING.pop(user.id, None)
                context.user_data.pop("whisper_reply_to", None)
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)

        _task_hint = asyncio.create_task(_rep_hint_cleanup())
        _task_hint.add_done_callback(lambda t: t.exception() if not t.cancelled() else None)
        return

async def _handle_whisper_reply(update, context) -> bool:
    """پەیامی وەڵامی ویسپەر دەپشکنێت — True ئەگەر هەڵگیرا"""
    user = update.effective_user
    chat = update.effective_chat
    if not user or not chat:
        return False

    reply_token = _WHISPER_PENDING.get(user.id) or context.user_data.get("whisper_reply_to")
    if not reply_token:
        return False

    text_raw = (update.message.text or "").strip() if update.message else ""
    if not text_raw or text_raw.startswith("/"):
        return False

    orig = WHISPER_DATA.get(reply_token)
    if not orig:
        _WHISPER_PENDING.pop(user.id, None)
        context.user_data.pop("whisper_reply_to", None)
        return False

    if len(text_raw) > 2000:
        try:
            err = await update.message.reply_text(f"{_TGX} نامەکەت زۆر درێژە! {len(text_raw)}/2000 پیت.", parse_mode="HTML")

            await asyncio.sleep(4)
            await err.delete()
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        return True

    # دروستکردنی ویسپەری وەڵام
    sender_id_orig = orig.get("sender_id", 0)
    sender_uname_orig = orig.get("sender_username", "")

    if not sender_id_orig and not sender_uname_orig:
        try:
            err = await update.message.reply_text(_TGX + " ناتوانرێت وەڵام بدرێت بۆ ناناس.", parse_mode="HTML")

            await asyncio.sleep(4)
            await err.delete()
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        _WHISPER_PENDING.pop(user.id, None)
        context.user_data.pop("whisper_reply_to", None)
        return True

    target_of_reply = sender_uname_orig or str(sender_id_orig)
    new_token, _ = _w_new_entry(user, target_of_reply, text_raw, chat.id, anon=False,
                                target_user_id=sender_id_orig)
    orig["reply_token"] = new_token
    WHISPER_DATA[reply_token] = orig
    _w_save()

    _WHISPER_PENDING.pop(user.id, None)
    context.user_data.pop("whisper_reply_to", None)

    # سڕینەوەی پەیامی بەکارهێنەر
    try:
        await update.message.delete()
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    # ناردنی ویسپەری وەڵام
    card_text, markup = _w_display_card(new_token)
    try:
        sent = await context.bot.send_message(
            chat_id=chat.id, text=card_text,
            parse_mode="HTML", reply_markup=markup
        )
        WHISPER_DATA[new_token]["message_id"] = sent.message_id
        _WMSGID_MAP[f"{chat.id}:{sent.message_id}"] = new_token
        _w_save()
    except Exception as e:
        logger.error("whisper reply send error: %s", e)

    # ✅ FIX BUG-1: نوێکردنەوەی کارتی ئەصلی — هەم ئاسایی هەم via (inline)
    try:
        orig_chat_id  = orig.get("chat_id")
        orig_msg_id   = orig.get("message_id")
        orig_inline   = orig.get("inline_message_id")
        new_text, _   = _w_display_card(reply_token)

        read_count_orig = len(orig.get("read_by", []))
        btn_label_orig  = "دووبارە بخوێنەرەوە" if read_count_orig else "خوێندنەوەی نامەکە"

        if orig_chat_id and orig_msg_id:
            # ئاسایی: پەیامی گرووپ
            new_text2, new_markup2 = _w_display_card(reply_token)
            await context.bot.edit_message_text(
                chat_id=orig_chat_id, message_id=orig_msg_id,
                text=new_text2, parse_mode="HTML", reply_markup=new_markup2
            )
        elif orig_inline:
            # ✅ FIX: via ویسپەر — بە inline_message_id نووێ دەکرێتەوە
            await _w_api_request(context.bot, "editMessageText", {
                    "inline_message_id": orig_inline,
                    "text":              new_text,
                    "parse_mode":        "HTML",
                    "reply_markup": {
                        "inline_keyboard": [[{
                            "text":                 btn_label_orig,
                            "callback_data":        f"wp:r:{reply_token}",
                            "icon_custom_emoji_id": "5379687326991555987",
                            "style":                "primary",
                        }], [{
                            "text":          "↩️ وەڵامەکە ببینە",
                            "callback_data": f"wp:r:{orig['reply_token']}",
                            "style":         "primary",
                        }]]
                    },
                })
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

    return True


# ── فەرمانی /wreply — پاشمایەکە بۆ کەسانی حەزکار ─── ⋆⋅☆⋅⋆ ───

async def wreply_cmd(update: Update, context: CallbackContext):
    """/wreply نامەکەت  — وەڵامی ویسپەر"""
    user  = update.effective_user
    chat  = update.effective_chat
    args  = context.args or []

    reply_token = _WHISPER_PENDING.get(user.id) or context.user_data.get("whisper_reply_to")
    if not reply_token:
        await update.message.reply_text(
            _TGX + " هیچ ویسپەرێک نییە بۆ وەڵامدان.\n"
            "سەرەتا دوگمەی «↩️ وەڵامی نهێنی بدە» دابگرە.",
            parse_mode="HTML"
        )
        return

    if not args:
        await update.message.reply_text(_TGX + " نامەی وەڵامەکەت بنووسە!", parse_mode="HTML")

        return

    # ── مستقیم وەڵامی ویسپەر دروست دەکەین بەبێ گوازینەوەی update.message.text ──
    reply_text_content = " ".join(args).strip()

    orig = WHISPER_DATA.get(reply_token)
    if not orig:
        _WHISPER_PENDING.pop(user.id, None)
        context.user_data.pop("whisper_reply_to", None)
        await update.message.reply_text(_TGX + " ویسپەرەکە نەدۆزرایەوە یان کاتی تەواو بووە.", parse_mode="HTML")

        return

    if len(reply_text_content) > 2000:  # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX BUG-3: 500→2000 یەکسان با _handle_whisper_reply
        await update.message.reply_text(_TGX + f" نامەکەت زۆر درێژە! {len(reply_text_content)}/2000 پیت.", parse_mode="HTML")

        return

    sender_id_orig = orig.get("sender_id", 0)
    sender_uname_orig = orig.get("sender_username", "")

    if not sender_id_orig and not sender_uname_orig:
        await update.message.reply_text(_TGX + " ناتوانرێت وەڵام بدرێت بۆ ناناس.", parse_mode="HTML")

        _WHISPER_PENDING.pop(user.id, None)
        context.user_data.pop("whisper_reply_to", None)
        return

    target_of_reply = sender_uname_orig or str(sender_id_orig)
    new_token, _ = _w_new_entry(user, target_of_reply, reply_text_content, chat.id, anon=False,
                                target_user_id=sender_id_orig)
    orig["reply_token"] = new_token
    WHISPER_DATA[reply_token] = orig
    _w_save()

    _WHISPER_PENDING.pop(user.id, None)
    context.user_data.pop("whisper_reply_to", None)

    # سڕینەوەی فەرمانی /wreply
    try:
        await update.message.delete()
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    # ناردنی ویسپەری وەڵام
    card_text, markup = _w_display_card(new_token)
    try:
        sent = await context.bot.send_message(
            chat_id=chat.id, text=card_text,
            parse_mode="HTML", reply_markup=markup
        )
        WHISPER_DATA[new_token]["message_id"] = sent.message_id
        _WMSGID_MAP[f"{chat.id}:{sent.message_id}"] = new_token
        _w_save()
    except Exception as e:
        logger.error("wreply send error: %s", e)

    # ✅ FIX BUG-1 (wreply_cmd): نوێکردنەوەی کارتی ئەصلی — هەم ئاسایی هەم via
    try:
        orig_chat_id  = orig.get("chat_id")
        orig_msg_id   = orig.get("message_id")
        orig_inline   = orig.get("inline_message_id")
        new_text, _   = _w_display_card(reply_token)

        read_count_orig = len(orig.get("read_by", []))
        btn_label_orig  = "دووبارە بخوێنەرەوە" if read_count_orig else "خوێندنەوەی نامەکە"

        if orig_chat_id and orig_msg_id:
            new_text2, new_markup2 = _w_display_card(reply_token)
            await context.bot.edit_message_text(
                chat_id=orig_chat_id, message_id=orig_msg_id,
                text=new_text2, parse_mode="HTML", reply_markup=new_markup2
            )
        elif orig_inline:
            # ✅ FIX: via ویسپەر
            await _w_api_request(context.bot, "editMessageText", {
                    "inline_message_id": orig_inline,
                    "text":              new_text,
                    "parse_mode":        "HTML",
                    "reply_markup": {
                        "inline_keyboard": [[{
                            "text":                 btn_label_orig,
                            "callback_data":        f"wp:r:{reply_token}",
                            "icon_custom_emoji_id": "5379687326991555987",
                            "style":                "primary",
                        }], [{
                            "text":          "↩️ وەڵامەکە ببینە",
                            "callback_data": f"wp:r:{orig['reply_token']}",
                            "style":         "primary",
                        }]]
                    },
                })
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored


# ── Inline Query ─── ⋆⋅☆⋅⋆ ───

async def whisper_inline_query(update: Update, context: CallbackContext):
    """@bot نامەکەت @username"""
    query  = update.inline_query
    sender = query.from_user
    raw    = (query.query or "").strip()

    # ڕێنمایی
    if not raw:
        await query.answer([
            InlineQueryResultArticle(
                id=str(uuid4()),
                title="💌 چرپەنامەی نهێنی بنێرە",
                description="شێوە: نامەکەت @username  ←  کرتە بکە",
                input_message_content=InputTextMessageContent(
                    "<tg-emoji emoji-id=\"5190859184312167965\">💌</tg-emoji> <b>شێوازی بەکارهێنان:</b>\n"
                    "<code>@best_313bot نامەکەت @username</code>\n\n"
                    "ناناس: <code>@best_313bot نامەکەت @username --anon</code>",
                    parse_mode="HTML"
                )
            )
        ], cache_time=0)
        return

    anon  = "--anon" in raw
    raw   = raw.replace("--anon", "").strip()
    words = raw.split()

    target_username = None
    msg_parts = []
    for w in words:
        if w.startswith("@") and len(w) > 1 and target_username is None:
            target_username = w.lstrip("@")
        else:
            msg_parts.append(w)

    secret_msg = " ".join(msg_parts).strip()

    if not target_username:
        await query.answer([
            InlineQueryResultArticle(
                id=str(uuid4()),
                title="💌 @username زیاد بکە",
                description=f"نموونە: {raw} @Rose",
                input_message_content=InputTextMessageContent(
                    "<tg-emoji emoji-id=\"5190859184312167965\">💌</tg-emoji> @username زیاد بکە!\nنموونە: <code>سڵاو @Rose</code>",
                    parse_mode="HTML"
                )
            )
        ], cache_time=0)
        return

    if not secret_msg:
        await query.answer([
            InlineQueryResultArticle(
                id=str(uuid4()),
                title=f"💌 نامەکەت بنووسە بۆ @{target_username}",
                description="نامەکەت لە پێش @username بنووسە",
                input_message_content=InputTextMessageContent(
                    f"<tg-emoji emoji-id=\"5190859184312167965\">💌</tg-emoji> نموونە: <code>سڵاو @{target_username}</code>",
                    parse_mode="HTML"
                )
            )
        ], cache_time=0)
        return

    if len(secret_msg) > 500:
        await query.answer([
            InlineQueryResultArticle(
                id=str(uuid4()),
                title=_TGX + " نامەکەت زۆر درێژە — زۆرترین ٥٠٠ پیت",
                description="کورتتری بکە",
                input_message_content=InputTextMessageContent(_TGX + " زۆر درێژە!")
            )
        ], cache_time=0)
        return

    _w_clean_expired()
    token, _ = _w_new_entry(sender, target_username, secret_msg, chat_id=None, anon=anon)
    text, markup = _w_display_card(token)

    _desc_name = "ناناس <tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji>" if anon else sender.first_name
    # ── plain markup بۆ inline answer (PTB api_kwargs لە nested keyboard سریالایز ناکات) ──
    # chosen_inline دواتر ئەیگۆڕێتەوە بە ئیمۆجی ئەنیمەیتد
    _plain_markup = InlineKeyboardMarkup([[
        InlineKeyboardButton("خوێندنەوەی نامەکە", callback_data=f"wp:r:{token}", api_kwargs={"icon_custom_emoji_id": "5454113432284446338", "style": "primary"})
    ]])
    await query.answer([
        InlineQueryResultArticle(
            id=token,
            title=f"💌 چرپەنامە بۆ @{target_username}  ←  کرتە بکە",
            description=f"{_desc_name} → @{target_username} | 🔒 نهێنییە",
            input_message_content=InputTextMessageContent(
                # ── placeholder: chosen_inline دەیگۆڕێتەوە بە ئەنیمەیتد ──
                f"To: @{target_username}",
                parse_mode="HTML"
            ),
            reply_markup=_plain_markup,
        )
    ], cache_time=0, is_personal=True)


async def _w_api_request(bot, endpoint: str, api_kwargs: dict) -> None:
    """
    do_api_request بدێل — PTB < 20.4 پشتگیری ناکات.
    ئەگەر bot.do_api_request هەبوو بەکاردێت، وەرنا httpx ڕاستەوخۆ.
    """
    if hasattr(bot, "do_api_request"):
        await bot.do_api_request(endpoint=endpoint, api_kwargs=api_kwargs)
        return
    import httpx as _hx
    url = f"https://api.telegram.org/bot{bot.token}/{endpoint}"
    async with _hx.AsyncClient(timeout=10.0) as _cli:
        await _cli.post(url, json=api_kwargs)

async def whisper_chosen_inline(update: Update, context: CallbackContext):  # noqa: ASYNC100 — PTB job queue requires coroutine
    """پاشەکەوتکردنی inline_message_id"""
    result = update.chosen_inline_result
    if not result:
        return
    token      = result.result_id
    inline_mid = result.inline_message_id
    d = WHISPER_DATA.get(token)
    if d and inline_mid:
        d["inline_message_id"] = inline_mid
        context.bot_data[f"whisper_{token}"] = d
        _w_save()

        # ── do_api_request bypass ───────────────────────────────────────────────
        # PTB نەیتیڤ icon_custom_emoji_id/style لە InlineKeyboardButton پشتگیری
        # نەدەکات (issue #5136). api_kwargs لە nested object نانێرێت.
        # do_api_request تەواوی PTB serialize بازدەکات — dict خاو ڕاستەوخۆ بۆ
        # Telegram API دەچێت بەبێ هیچ فلتەرێک.
        try:
            await asyncio.sleep(0.5)  # چاوەڕوانی تۆمارکردنی inline_message_id
            text, _ = _w_display_card(token)

            read_count = len(d.get("read_by", []))
            btn_label = "دووبارە بخوێنەرەوە" if read_count else "خوێندنەوەی نامەکە"

            # ── do_api_request: تێکستی ئەنیمەیتد + دووگمەی ئەنیمەیتد ──
            await _w_api_request(context.bot, "editMessageText", {
                    "inline_message_id": inline_mid,
                    "text":              text,   # text = _w_display_card → <tg-emoji> هەیە
                    "parse_mode":        "HTML",
                    "reply_markup": {
                        "inline_keyboard": [[{
                            "text":                  btn_label,
                            "callback_data":         f"wp:r:{token}",
                            "icon_custom_emoji_id":  "5379687326991555987",
                            "style":                 "primary",
                        }]]
                    },
                })
        except Exception as e:
            # Document_invalid = پەیامەکە سڕاوەتەوە یان بەسەرچووە — مۆڵەتداری بێدەنگ
            if "document_invalid" in str(e).lower():
                logger.debug("whisper_chosen_inline: inline message gone [%s]: %s", token, e)
            else:
                logger.warning("whisper_chosen_inline edit failed [%s]: %s", token, e)


