async def commands_cmd(update: Update, context: CallbackContext):
    """نیشاندانی هەموو فەرمانەکان بە تێکست"""
    lines = FULL_COMMANDS_TEXT.strip().split("\n")
    chunks = []
    current = []
    current_len = 0
    for line in lines:
        if current_len + len(line) + 1 > 3800:
            chunks.append("\n".join(current))
            current = [line]
            current_len = len(line)
        else:
            current.append(line)
            current_len += len(line) + 1
    if current:
        chunks.append("\n".join(current))

    for chunk in chunks:
        await update.message.reply_text(chunk, parse_mode="HTML")


