@guarded
async def auction_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5325870952980949513\">🏛</tg-emoji>️ /auction — سیستەمی مزایەدە"""
    args = context.args
    uid = str(update.effective_user.id)
    
    if not args:
        # بینینی مزایەدەکانی چالاک
        active = {k:v for k,v in AUCTION_DATA.items() 
                  if datetime.datetime.fromisoformat(v["end_time"]) > datetime.datetime.now()}
        if not active:
            text = "<tg-emoji emoji-id=\"5325870952980949513\">🏛</tg-emoji>️ <b>مزایەدە</b>\n\nهیچ مزایەدەیەکی چالاک نییە!\n\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بۆ دروستکردن:\n<code>/auction create [شت] [نرخی دەستپێک]</code>"
        else:
            lines = ["<tg-emoji emoji-id=\"5325870952980949513\">🏛</tg-emoji>️ <b>مزایەدەکانی چالاک</b>\n"]
            for aid, a in list(active.items())[:10]:
                remaining = datetime.datetime.fromisoformat(a["end_time"]) - datetime.datetime.now()
                mins = max(0, int(remaining.total_seconds() // 60))
                lines.append(
                    f"<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> <b>{a['item']}</b>\n"
                    f"   {_TMN} نرخی ئێستا: {a.get('current_bid', a.get('min_bid', 0)):,}{_TCN}\n"
                    f"   <tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> ماوە: {mins} خولەک\n"
                    f"   🔨 <code>/auction bid {aid} [بڕ]</code>"
                )
            text = "\n".join(lines)
        await update.message.reply_text(text, parse_mode="HTML")
        return
    
    sub = args[0].lower()
    
    if sub == "create" and len(args) >= 3:
        item_name = args[1]
        min_bid = int(args[2]) if args[2].isdigit() else 100
        if min_bid < 50:
            await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> لانیکەم نرخ 50{_TCN}", parse_mode="HTML"); return

        aid = f"auc_{int(datetime.datetime.now().timestamp())}"
        end_time = (datetime.datetime.now() + datetime.timedelta(hours=2)).isoformat()
        AUCTION_DATA[aid] = {
            "item": item_name, "seller": uid, "min_bid": min_bid,
            "current_bid": min_bid, "bidder": None, "end_time": end_time,
            "bids_count": 0
        }
        _save_auction()
        await update.message.reply_text(
            f"{_TCK} مزایەدە دروستکرا!\n\n"
            f"<tg-emoji emoji-id=\"5325870952980949513\">🏛</tg-emoji>️ شت: <b>{item_name}</b>\n"
            f"{_TMN} نرخی دەستپێک: <b>{min_bid:,}{_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> ماوە: ٢ کاتژمێر\n"
            f"🔨 بۆ پێشکەشکردن: <code>/auction bid {aid} [بڕ]</code>",
            parse_mode="HTML"
        )
    
    elif sub == "bid" and len(args) >= 3:
        aid = args[1]
        bid_amount = int(args[2]) if args[2].isdigit() else 0
        auc = AUCTION_DATA.get(aid)
        if not auc:
            await update.message.reply_text(_TGX + " مزایەدە نەدۆزرایەوە!", parse_mode="HTML"); return

        if datetime.datetime.fromisoformat(auc["end_time"]) < datetime.datetime.now():
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> مزایەدە تەواو بووە!", parse_mode="HTML"); return
        if bid_amount <= auc["current_bid"]:
            await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> پێویستە زیاتر لە {auc.get('current_bid', 0):,}{_TCN} پێشکەش بکەیت!", parse_mode="HTML"); return

        if get_user_data(int(uid)).get("coins", 0) < bid_amount:
            await update.message.reply_text(_TGX + " کۆینت بەس نییە!", parse_mode="HTML"); return

        
        # پارەی پێشوو بگەڕێنەوە
        if auc["bidder"]:
            add_coins(int(auc["bidder"]), auc["current_bid"], "auction", "refund")
        
        add_coins(int(uid), -bid_amount, "auction", "bid")
        auc["current_bid"] = bid_amount
        auc["bidder"] = uid
        auc["bids_count"] = auc.get("bids_count", 0) + 1
        _save_auction()
        await update.message.reply_text(
            f"🔨 پێشکەشکراوی تۆ تۆمار کرا!\n"
            f"{_TMN} نرخ: <b>{bid_amount:,}{_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5325870952980949513\">🏛</tg-emoji>️ شت: <b>{auc['item']}</b>",
            parse_mode="HTML"
        )

@guarded
async def investfund_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> /investfund — فۆندی وەبەرهێنانی هاوبەش"""
    uid = str(update.effective_user.id)
    args = context.args
    
    my_invest = INVEST_FUND.get("investors", {}).get(uid, 0)
    pool = INVEST_FUND.get("pool", 0)
    total_investors = len([v for v in INVEST_FUND.get("investors", {}).values() if v > 0])
    
    if not args:
        share_pct = (my_invest / pool * 100) if pool > 0 else 0
        kb = InlineKeyboardMarkup([
            [_ebtn("وەبەرهێنان", "ifund:invest", emoji_id="5990147899403539264", api_kwargs={"style": "primary"}),
             _ebtn("دەرهێنان", "ifund:withdraw", emoji_id="5983168981274465534", api_kwargs={"style": "primary"})],
            [_ebtn("ڕاپۆرت", "ifund:report", emoji_id="6271698656517165534", api_kwargs={"style": "danger"}),
             _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]
        ])
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> <b>فۆندی وەبەرهێنانی هاوبەش</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"{_TMN} کۆی فۆند: <b>{pool:,}{_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> وەبەرهێنەر: <b>{total_investors}</b>\n"
            f"{_TDM} بەشی تۆ: <b>{my_invest:,}{_TCN}</b> ({share_pct:.1f}%)\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> قازانج بەپێی بەشەکەت دابەش دەکرێت!\n\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بۆ وەبەرهێنان: <code>/investfund invest [بڕ]</code>\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بۆ دەرهێنان: <code>/investfund withdraw [بڕ]</code>",
            parse_mode="HTML"
        )
        return
    
    sub = args[0].lower()
    if sub == "invest" and len(args) >= 2 and args[1].isdigit():
        amount = int(args[1])
        if amount < 100: await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> لانیکەم 100{_TCN}", parse_mode="HTML"); return

        if get_user_data(int(uid)).get("coins", 0) < amount:
            await update.message.reply_text(_TGX + " کۆینت بەس نییە!", parse_mode="HTML"); return

        add_coins(int(uid), -amount, "investfund", "invest")
        INVEST_FUND["investors"][uid] = INVEST_FUND["investors"].get(uid, 0) + amount
        INVEST_FUND["pool"] = INVEST_FUND.get("pool", 0) + amount
        _save_invest_fund(); 
        await update.message.reply_text(f"{_TCK} <b>{amount:,}{_TCN}</b> وەبەرهێنرا لە فۆنددا!", parse_mode="HTML")
    
    elif sub == "withdraw" and len(args) >= 2 and args[1].isdigit():
        amount = int(args[1])
        if INVEST_FUND["investors"].get(uid, 0) < amount:
            await update.message.reply_text(_TGX + " بەشەکەت بەس نییە!", parse_mode="HTML"); return

        fee = int(amount * 0.02)  # 2% کرتی دەرهێنان
        net = amount - fee
        INVEST_FUND["investors"][uid] -= amount
        INVEST_FUND["pool"] = max(0, INVEST_FUND.get("pool", 0) - amount)
        add_coins(int(uid), net, "investfund", "withdraw")
        _save_invest_fund(); 
        await update.message.reply_text(
            f"{_TCK} <b>{net:,}{_TCN}</b> دەرهێنرا (کرت: {fee:,}{_TCN})", parse_mode="HTML"
        )

@guarded
async def exchange_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5393098942193898929\">💱</tg-emoji> /exchange — بازاڕی کریپتۆ"""
    uid = str(update.effective_user.id)
    args = context.args
    wallet = CRYPTO_WALLETS.get(uid, {})
    
    if not args:
        lines = ["<tg-emoji emoji-id=\"5393098942193898929\">💱</tg-emoji> <b>بازاڕی کریپتۆ</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"]
        for sym, data in CRYPTO_EXCHANGE.items():
            change_emoji = "<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji>" if data["change"] >= 0 else "<tg-emoji emoji-id=\"5393589131106359852\">📉</tg-emoji>"
            lines.append(f"{change_emoji} <b>{sym}</b>: {data.get('price', 0):,.2f}{_TCN} ({data['change']:+.1f}%)")
        
        lines.append(f"\n<tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji> <b>جزدانی کریپتۆی تۆ:</b>")
        if wallet:
            for sym, amt in wallet.items():
                if amt > 0:
                    val = amt * CRYPTO_EXCHANGE.get(sym, {}).get("price", 0)
                    lines.append(f"  {sym}: {amt:.4f} (بەها: {val:,.0f}{_TCN})")
        else:
            lines.append("  بەتاڵ")
        
        lines.append(f"\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> کڕین: <code>/exchange buy BTC 1000</code>")
        lines.append(f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> فرۆشتن: <code>/exchange sell BTC 0.5</code>")
        
        kb = InlineKeyboardMarkup([
            [_ebtn("چارت", "exch:chart", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
             _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]
        ])
        await update.message.reply_text("\n".join(lines), parse_mode="HTML", reply_markup=kb)
        return
    
    sub = args[0].lower()
    if sub == "buy" and len(args) >= 3:
        sym = args[1].upper()
        if sym not in CRYPTO_EXCHANGE:
            await update.message.reply_text(f"{_TGX} {sym} بوونی نییە! دەستەبەر: {', '.join(CRYPTO_EXCHANGE.keys())}", parse_mode="HTML"); return

        spend = int(args[2]) if args[2].isdigit() else 0
        if spend < 10: await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> لانیکەم 10{_TCN}", parse_mode="HTML"); return

        if get_user_data(int(uid)).get("coins", 0) < spend:
            await update.message.reply_text(_TGX + " کۆینت بەس نییە!", parse_mode="HTML"); return

        price = CRYPTO_EXCHANGE[sym]["price"]
        bought = spend / price
        add_coins(int(uid), -spend, "exchange", f"buy_{sym}")
        wallet[sym] = wallet.get(sym, 0) + bought
        CRYPTO_WALLETS[uid] = wallet
        _save_crypto_wallets(); 
        await update.message.reply_text(
            f"{_TCK} کڕیت <b>{bought:.6f} {sym}</b> بە <b>{spend:,}{_TCN}</b>",
            parse_mode="HTML"
        )
    
    elif sub == "sell" and len(args) >= 3:
        sym = args[1].upper()
        sell_amount = float(args[2]) if args[2].replace('.','').isdigit() else 0
        if wallet.get(sym, 0) < sell_amount:
            await update.message.reply_text(f"{_TGX} تەنها {wallet.get(sym,0):.6f} {sym} هەتە!", parse_mode='HTML'); return

        price = CRYPTO_EXCHANGE.get(sym, {}).get("price", 0)
        earned = int(sell_amount * price)
        tax = _apply_tax(uid, earned, f"sell_{sym}")
        wallet[sym] -= sell_amount
        CRYPTO_WALLETS[uid] = wallet
        add_coins(int(uid), tax, "exchange", f"sell_{sym}")
        _save_crypto_wallets(); 
        await update.message.reply_text(
            f"{_TCK} فرۆشتت <b>{sell_amount:.6f} {sym}</b> بە <b>{earned:,}{_TCN}</b> (باج: {earned-tax:,}{_TCN})",
            parse_mode="HTML"
        )

