@guarded
async def clanwar_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ /clanwar — دەستپێکردنی شەڕی کلان"""
    uid = str(update.effective_user.id)
    my_clan_id = CLAN_MEMBERS.get(uid)
    
    if not my_clan_id or my_clan_id not in CLAN_DATA:
        await update.message.reply_text(_TGX + " تۆ ئەندامی هیچ کلانێک نییت! /clan", parse_mode="HTML"); return

    
    clan = CLAN_DATA[my_clan_id]
    role = clan.get("roles", {}).get(uid, "member")
    if role not in ("leader", "officer"):
        await update.message.reply_text(_TGX + " تەنها سەرۆک و سەرباز دەتوانن شەڕ دەستپێبکەن!", parse_mode="HTML"); return

    
    # شەڕی چالاک هەیە؟
    active_war = None
    for wid, w in CLAN_WAR_DATA.items():
        if my_clan_id in (w.get("clan1"), w.get("clan2")) and w.get("status") == "active":
            active_war = w; break
    
    if active_war:
        c1 = CLAN_DATA.get(active_war["clan1"], {})
        c2 = CLAN_DATA.get(active_war["clan2"], {})
        s1 = active_war.get("score1", 0)
        s2 = active_war.get("score2", 0)
        remaining = datetime.datetime.fromisoformat(active_war["end_time"]) - datetime.datetime.now()
        mins = max(0, int(remaining.total_seconds() // 60))
        
        kb = InlineKeyboardMarkup([
 [_ebtn("️ هێرش!", f"cw:attack:{active_war.get('id','')}", emoji_id="5382170054311841219", api_kwargs={"style": "primary"}),
             _ebtn("بەرگری", f"cw:defend:{active_war.get('id','')}", emoji_id="5454006698052184265", api_kwargs={"style": "primary"}),],
            [_ebtn("ئامار", f"cw:stats:{active_war.get('id','')}", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
             _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]
        ])
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ <b>شەڕی کلان — چالاک!</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5330116450843636190\">🏰</tg-emoji> {c1.get('name','?')} vs <tg-emoji emoji-id=\"5330116450843636190\">🏰</tg-emoji> {c2.get('name','?')}\n"
            f"{_TCH} خاڵ: <b>{s1}</b> — <b>{s2}</b>\n"
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> ماوە: <b>{mins} خولەک</b>\n\n"
            f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێرش بکە بۆ بەدەستهێنانی خاڵ!",
            parse_mode="HTML"
        ); return
    
    # لیستی کلانەکانی تر بۆ شەڕ
    other_clans = [(cid, c) for cid, c in CLAN_DATA.items() 
                   if cid != my_clan_id and len([u for u,ci in CLAN_MEMBERS.items() if ci==cid]) >= 2]
    
    if not other_clans:
        await update.message.reply_text(_TGX + " هیچ کلانێکی تر نییە بۆ شەڕ!", parse_mode="HTML"); return

    
    btns = []
