@guarded
async def newevent_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> /newevent [ناو] [کاتژمێر] — دروستکردنی ڕووداو بۆ گروپ"""
    args = context.args
    if not args or len(args) < 2:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>دروستکردنی ڕووداو</b>\n\n"
            "<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <code>/newevent [ناو] [کاتژمێر]</code>\n"
            "<tg-emoji emoji-id=\"5357344722434152120\">🔸</tg-emoji> نمونە: <code>/newevent یاری 2</code> (2 کاتژمێر دوای ئێستا)",
            parse_mode="HTML"
        ); return
    
    name = args[0]
    try:
        hours = float(args[1])
    except ValueError:
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کاتژمێرەکە ژمارە بێت!", parse_mode="HTML"); return
    
    chat_id = str(update.effective_chat.id)
    event_time = (datetime.datetime.now() + datetime.timedelta(hours=hours)).isoformat()
    
    event = {
        "id": f"evt_{int(datetime.datetime.now().timestamp())}",
        "name": name, "time": event_time,
        "creator": str(update.effective_user.id),
        "participants": [str(update.effective_user.id)],
        "description": " ".join(args[2:]) if len(args) > 2 else ""
    }
    GROUP_EVENTS.setdefault(chat_id, []).append(event)
    _save_group_events()
    
    kb = InlineKeyboardMarkup([
        [_ebtn("بەشداری", f"evt:join:{event['id']}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
         _ebtn("نەبوون", f"evt:leave:{event['id']}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
    ])
    
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>ڕووداوی نوێ!</b>\n\n"
        f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> ناو: <b>{name}</b>\n"
        f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> کات: <b>{hours} کاتژمێر دوای ئێستا</b>\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> دروستکەر: {_html_escape(update.effective_user.first_name)}\n"
        f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> بەشداربوو: 1\n\n"
        f"{_TCK} کلیک بکە بۆ بەشداری!",
        parse_mode="HTML"
    )

@guarded
async def events_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> /events — ڕووداوەکانی گروپ"""
    chat_id = str(update.effective_chat.id)
    events = GROUP_EVENTS.get(chat_id, [])
    now = datetime.datetime.now()
    
    # تەنها ڕووداوەکانی نەهاتوو
    active = [e for e in events if datetime.datetime.fromisoformat(e["time"]) > now]
    
    if not active:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> هیچ ڕووداوێکی چالاک نییە!\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <code>/newevent [ناو] [کاتژمێر]</code>",
            parse_mode="HTML"
        ); return
    
    lines = ["<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>ڕووداوەکانی گروپ</b>\n"]
    for e in active[:10]:
        remaining = datetime.datetime.fromisoformat(e["time"]) - now
        hrs = int(remaining.total_seconds() // 3600)
        mins = int((remaining.total_seconds() % 3600) // 60)
        lines.append(
            f"\n<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> <b>{e['name']}</b>\n"
            f"   <tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> ماوە: {hrs}:{mins:02d}\n"
            f"   <tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> بەشداربوو: {len(e.get('participants',[]))}"
        )
    
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def group_event_callback(update: Update, context: CallbackContext):
    q = update.callback_query
    answered = _make_answerer(q)
    uid = str(q.from_user.id)
    parts = q.data.split(":")
    action = parts[1]
    event_id = parts[2]
    
    chat_id = str(q.message.chat.id)
    events = GROUP_EVENTS.get(chat_id, [])
    event = None
    for e in events:
        if e["id"] == event_id: event = e; break
    
    if not event: await answered("❌" + " ڕووداو نەدۆزرایەوە!", show_alert=True); return
    
    if action == "join":
        if uid not in event.get("participants", []):
            event.setdefault("participants", []).append(uid)
            _save_group_events()
            await answered(f"<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> بەشداری تۆمارکرا! ({len(event['participants'])} کەس)")
        else:
            await answered("ئێستاشت بەشداری!", show_alert=True)
    
    elif action == "leave":
        if uid in event.get("participants", []):
            event["participants"].remove(uid)
            _save_group_events()
            await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> بەشداریت هەڵوەشایەوە!")
        else:
            await answered("بەشداریت نییە!", show_alert=True)

@guarded
async def planner_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> /planner — پلانی ڕۆژانە"""
    uid = str(update.effective_user.id)
    args = context.args
    today = datetime.date.today().isoformat()
    
    if not args:
        tasks = DAILY_PLANNER.get(uid, {}).get(today, [])
        if not tasks:
            text = (
                f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>پلانی ڕۆژانە — {today}</b>\n\n"
                f"هیچ ئەرکێکت نییە بۆ ئەمڕۆ!\n\n"
                f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> زیادکردن: <code>/planner add [ئەرک]</code>\n"
                f"{_TCK} تەواو: <code>/planner done [ژمارە]</code>"
            )
        else:
            lines = [f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>پلانی ڕۆژانە — {today}</b>\n"]
            for i, t in enumerate(tasks, 1):
                status = f"{_TCK}" if t.get("done") else f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
                lines.append(f"{status} {i}. {t['text']}")
            done_count = sum(1 for t in tasks if t.get("done"))
            lines.append(f"\n{_TCH} تەواوکراو: {done_count}/{len(tasks)}")
            text = "\n".join(lines)
        await update.message.reply_text(text, parse_mode="HTML")
        return
    
    sub = args[0].lower()
    if sub == "add" and len(args) >= 2:
        task_text = " ".join(args[1:])
        DAILY_PLANNER.setdefault(uid, {}).setdefault(today, []).append({"text": task_text, "done": False})
        _save_daily_planner()
        cnt = len(DAILY_PLANNER[uid][today])
        await update.message.reply_text(f"{_TCK} ئەرکی {cnt} زیادکرا: <b>{task_text}</b>", parse_mode="HTML")
    
    elif sub == "done" and len(args) >= 2 and args[1].isdigit():
        idx = int(args[1]) - 1
        tasks = DAILY_PLANNER.get(uid, {}).get(today, [])
        if 0 <= idx < len(tasks):
            tasks[idx]["done"] = True
            _save_daily_planner()
            await update.message.reply_text(f"{_TCK} ئەرکی {idx+1} تەواوکرا!", parse_mode="HTML")

        else:
            await update.message.reply_text(_TGX + " ژمارە هەڵەیە!", parse_mode="HTML")

    
    elif sub == "clear":
        DAILY_PLANNER.get(uid, {}).pop(today, None)
        _save_daily_planner()
        await update.message.reply_text("<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> پلانی ئەمڕۆ پاککرایەوە!", parse_mode="HTML")

# ── یادەوەری خۆکارانەی ڕووداوەکان ──

async def _event_reminder_job(context):
    """چەکی ڕووداوەکان و ناردنی یادەوەری"""
    try:
        now = datetime.datetime.now()
        for chat_id, events in list(GROUP_EVENTS.items()):
            for event in events:
                try:
                    event_time = datetime.datetime.fromisoformat(event["time"])
                except (ValueError, KeyError):
                    continue
                diff = (event_time - now).total_seconds()
                # یادەوەری ١٥ خولەکی پێش
                if 0 < diff <= 900 and not event.get("reminded"):
                    event["reminded"] = True
                    _save_group_events()
                    try:
                        participants = event.get("participants", [])
                        text = (
                            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادەوەری!</b>\n\n"
                            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>{event['name']}</b> بەزووانە دەستپێدەکات!\n"
                            f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> بەشداربوو: {len(participants)} کەس\n"
                            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> ماوە: {int(diff//60)} خولەک"
                        )
                        await context.bot.send_message(int(chat_id), text, parse_mode="HTML")
                    except Exception as _e:
                        logger.error("event reminder error: %s", _e)

            # پاکردنەوەی ڕووداوە کۆنەکان
            try:
                GROUP_EVENTS[chat_id] = [
                    e for e in events
                    if datetime.datetime.fromisoformat(e["time"]) > now - datetime.timedelta(hours=1)
                ]
            except Exception:
                pass  # داتای خراپ — پاکردنەوە skip دەکرێت
    except Exception as _e:
        logger.error(f"_event_reminder_job هەڵە: {_e}", exc_info=True)

async def owneradd_group_callback(update: Update, context: CallbackContext):
    """callback: خاوەن دووگمەی مۆڵەتدارکردنی گرووپ کلیک دەکات"""
    query = update.callback_query
    if query.from_user.id != OWNER_ID:
        await query.answer("❌" + " تەنها بۆ خاوەن.", show_alert=True)
        return
    try:
        gid = int(query.data.split(":")[1])
    except (IndexError, ValueError):
        await query.answer("❌" + " هەڵە لە داتا.", show_alert=True)
        return

    groups = ALLOWED_GROUPS_DATA.get("groups", [])
    if gid in groups:
        await query.answer("⚠️ پێشتر زیادکراوە.", show_alert=True)
        return

    groups.append(gid)
    ALLOWED_GROUPS_DATA["groups"] = groups
    _save_allowed_groups(ALLOWED_GROUPS_DATA)
    _GROUP_ACCESS_CACHE.pop(gid, None)

    await query.answer("✅ گرووپەکە مۆڵەتدار کرا!", show_alert=True)
    try:
        await query.edit_message_reply_markup(reply_markup=None)
    except Exception as _exc:
        logger.debug("edit_message_reply_markup suppressed: %s", _exc)
    try:
        await context.bot.send_message(
            OWNER_ID,
            f"{_TCK} گرووپی <code>{gid}</code> زیادکرا.\n{_TCH} کۆی گرووپە مۆڵەتدارەکان: {len(groups)}",
            parse_mode="HTML"
        )
    except Exception as _exc:
        logger.debug("send_message to owner suppressed: %s", _exc)

