async def run_cmd_callback(update: Update, context: CallbackContext):
    """
    callback بۆ کارکردنی فەرمانەکان بە کلیک کردنی دووگمە
    pattern: run:<command_name>
    """
    query = update.callback_query
    cmd = query.data.split(":", 1)[1] if ":" in query.data else ""

    answered = _make_answerer(query)

    # ── چەکی Premium — پێش spinner تا show_alert کاربکات ──
    # نەخشەی cmd → کلیلی ADV_TESTS (چارەسەری ناکۆکی instincts/instinctual و هتد)
    _ADV_KEY_MAP = {
        # ── تێستە پریمیومەکان (tests_premium مێنیو) ──
        "tritype":     "tritype",
        "instincts":   "instinctual",   # ← FIX: run:instincts → ADV_TESTS["instinctual"]
        "attitudinal": "attitudinal",
        "temperament": "temperament",
        "alignment":   "alignment",
        "darktri":     "darktri",
        "darkempath":  "darkempath",
        "bigfive":     "bigfive",
        "mbtifunc":    "mbtifunc",
        "cpt":         "cpt",
        "mft":         "mft",
        "ichazo":      "ichazo",        # ← FIX: run:ichazo → پۆپئاپی پریمیوم
        "naranjo":     "naranjo",       # ← FIX: run:naranjo → پۆپئاپی پریمیوم
        "jung":        "jung",           # ← FIX: run:jung → پۆپئاپی پریمیوم
        "ysq":         "ysq",            # ← FIX: run:ysq → پۆپئاپی پریمیوم
        # ── تێستە خۆڕایییەکان (tests مێنیو) — پریمیوم چەک نییە ──
        # lovelang, attachment, cognitive, valuestest, via, selfesteem, eq, hsp
        # ئەمانە لە مێنیوی خۆڕایین، لێرەوە دەرکراون
    }
    premium_keys = set(_ADV_KEY_MAP.keys()) | {"iq"}
    if cmd in premium_keys:
        _adv_key = _ADV_KEY_MAP.get(cmd, cmd)
        _uid_prem = query.from_user.id
        _allowed = (
            cmd == "iq" and _is_iq_allowed(_uid_prem)
        ) or (
            cmd != "iq" and _is_adv_allowed(_uid_prem, _adv_key)
        )
        if not _allowed:
            if cmd == "iq":
                prem_name = "IQ"
                prem_icon_raw = "<tg-emoji emoji-id=\"5424809463129347629\">🧮</tg-emoji>"
            else:
                _info = ADV_TESTS.get(_adv_key, (_adv_key, f"{_TDM}"))
                prem_name = _info[0]
                # ── FIX Rule3: tg-emoji تاگ لێبکرەوە — پۆپئاپ HTML پشتگیری ناکات ──
                prem_icon_raw = re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", _info[1])
            # ── تەنها پۆپئاپی سەرشاشە — نامەی تازە نانێرێت ──
            try:
                await query.answer(
                    f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> {prem_icon_raw} تێستی {prem_name} پریمیومە!",
                    show_alert=True
                )
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return

    # ── جووابدانەوەی فەوری — تەنها کاتێک premium نەبوو ──
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> spinner

    # ── کلاسی نوێی پەیام بۆ ئەوەی فەرمانەکان بکارهێنین ──
    class _FMsg:
        def __init__(self, q, chat_ref):
            self._q    = q
            self._chat = chat_ref   # چات ذەخیرەکراو — حتا پاش سڕینی پەیام کاردەکات
            self.chat = chat_ref
            self.from_user = q.from_user
            self.reply_to_message = None
            self.text = ""
            self.message_id = q.message.message_id if q.message else None
            self.photo = None
            self.document = None
            self.sticker = None
            self.animation = None
            self.voice = None
            self.video = None
            self.audio = None
            self.entities = []
            self.caption = None
        async def reply_text(self, *a, **kw):
            # پەیامەکە سڕاوەتەوە — chat_ref بەکاربهێنە کە هێشتا ژیاوەیە
            if not self._chat:
                return
            kw.setdefault('parse_mode', 'HTML')
            import re as _re

            # ── هیلپەر: تەنیا <tg-emoji> tags دەسڕێتەوە، HTML تر دەمێنێتەوە ──
            def _strip_tg_emoji(txt: str) -> str:
                return _re.sub(r'<tg-emoji[^>]*>(.*?)</tg-emoji>', r'\1', txt)

            # ── هیلپەر: هەموو HTML دەسڕێتەوە — دوایین چارە ──
            def _strip_all_html(txt: str) -> str:
                return _re.sub(r'<[^>]+>', '', txt)

            # ── FIX BUG#1: RetryAfter جیا دەگیرێت — مانەوە + 3 هەوڵ ──
            for _attempt in range(3):
                try:
                    return await self._chat.send_message(*a, **kw)
                except RetryAfter as _ra:
                    if _attempt < 2:
                        await asyncio.sleep(_ra.retry_after + 1)
                    else:
                        logger.error("_FMsg.reply_text: gave up after flood-waits: %s", _ra)
                        return
                except BadRequest as _e:
                    _rm   = kw.get('reply_markup')
                    _pm   = kw.get('parse_mode', 'HTML')
                    _orig = a[0] if a else kw.get('text', '')
                    if 'document_invalid' in str(_e).lower():
                        # ── FIX: emoji-id نادروستە — تەنیا tg-emoji tags بسرەوە،
                        #    HTML (bold/italic/…) بپارێزە، parse_mode=HTML بمێنێتەوە ──
                        logger.warning("_FMsg.reply_text: Document_invalid — stripping tg-emoji tags only")
                        _txt_emu = _strip_tg_emoji(str(_orig))
                        _args_emu = (_txt_emu,) + a[1:] if a else ()
                        _kw_emu   = dict(kw)
                        if not a:
                            _kw_emu['text'] = _txt_emu
                        try:
                            return await self._chat.send_message(*_args_emu, **_kw_emu)
                        except Exception as _e2:
                            logger.error("_FMsg.reply_text emoji-strip fallback: %s", _e2)
                            # دوایین چارە: هەموو HTML بسرەوە
                            _txt_bare = _strip_all_html(str(_orig))
                            try:
                                return await self._chat.send_message(
                                    _txt_bare[:3800], reply_markup=_rm)
                            except Exception as _e3:
                                logger.error("_FMsg.reply_text bare fallback: %s", _e3)
                    else:
                        # BadRequest تری — HTML دەسرێتەوە و دووبارە هەوڵ دەدرێت
                        logger.error("_FMsg.reply_text BadRequest: %s", _e)
                        _txt_clean = _strip_all_html(str(_orig))
                        try:
                            return await self._chat.send_message(_txt_clean, reply_markup=_rm)
                        except RetryAfter as _ra2:
                            logger.error("_FMsg.reply_text BadRequest-fallback RetryAfter: %s", _ra2)
                            await asyncio.sleep(_ra2.retry_after + 1)
                            try:
                                return await self._chat.send_message(
                                    _txt_clean, reply_markup=_rm)
                            except Exception as _e3:
                                logger.error("_FMsg.reply_text BadRequest-fallback retry: %s", _e3)
                        except Exception as _e2:
                            logger.error("_FMsg.reply_text BadRequest-fallback: %s", _e2)
                            try:
                                await self._chat.send_message(
                                    _txt_clean[:3800], reply_markup=_rm)
                            except Exception as _e3:
                                logger.error("_FMsg.reply_text BadRequest truncate: %s", _e3)
                    return
                except Exception as _e:
                    # هەڵەی نەناسراو — هەموو HTML بسرەوە
                    logger.error("_FMsg.reply_text: %s", _e)
                    _rm        = kw.get('reply_markup')
                    _orig      = a[0] if a else kw.get('text', '')
                    _txt_clean = _strip_all_html(str(_orig))
                    try:
                        return await self._chat.send_message(_txt_clean, reply_markup=_rm)
                    except RetryAfter as _ra2:
                        logger.error("_FMsg.reply_text fallback RetryAfter: %s", _ra2)
                        await asyncio.sleep(_ra2.retry_after + 1)
                        try:
                            return await self._chat.send_message(_txt_clean, reply_markup=_rm)
                        except Exception as _e3:
                            logger.error("_FMsg.reply_text fallback retry: %s", _e3)
                    except Exception as _e2:
                        logger.error("_FMsg.reply_text fallback: %s", _e2)
                        try:
                            await self._chat.send_message(_txt_clean[:3800], reply_markup=_rm)
                        except Exception as _e3:
                            logger.error("_FMsg.reply_text truncate fallback: %s", _e3)
                    return
        async def reply_photo(self, *a, **kw):
            try:
                if self._chat:
                    return await self._chat.send_photo(*a, **kw)
            except Exception as _e:
                logger.error("_FMsg.reply_photo: %s", _e)
        async def reply_document(self, *a, **kw):
            try:
                if self._chat:
                    return await self._chat.send_document(*a, **kw)
            except Exception as _e:
                logger.error("_FMsg.reply_document: %s", _e)
        async def delete(self):
            try:
                if self._q.message:
                    await self._q.message.delete()
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    class _FUpd:
        def __init__(self, q):
            # chat reference پێش سڕینی پەیام ذەخیرە دەکەین
            _chat_ref = q.message.chat if q.message else None
            self.message          = _FMsg(q, _chat_ref)
            self.effective_user   = q.from_user
            self.effective_chat   = _chat_ref
            self.effective_message = _FMsg(q, _chat_ref)
            self.callback_query   = q
            self._q = q
            self._skip_access     = True   # guarded_callback پێشتر چەکی کردووە
        async def answer(self, *a, **kw):
            try: await self._q.answer(*a, **kw)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
    fu = _FUpd(query)

