async def warn_user_new(update: Update, context: CallbackContext):
    if not await is_restrict_admin(update, context):
        return
    
    target = None
    args_start = 0
    if update.message.reply_to_message:
        target = update.message.reply_to_message.from_user
    elif context.args:
        try:
            target_id = int(context.args[0])
            target = type('User', (), {'id': target_id, 'first_name': str(target_id), 'mention_html': lambda self=None, **kw: f'<a href="tg://user?id={target_id}">{target_id}</a>'})()
            args_start = 1
        except (ValueError, IndexError):
            pass  # intentionally ignored
    
    if not target:
        await update.message.reply_text("↩️ تکایە لەسەر پەیامی کەسێک ڕیپڵای بکە یان ئایدییەکەی بنووسە!\nنموونە: /warn 123456789 هۆکار", parse_mode='HTML'); return
    
    chat_id = str(update.effective_chat.id)
    uid = str(target.id)
    reason = " ".join(context.args[args_start:]) if context.args else "هیچ هۆکارێک دیاری نەکراوە"
    if not reason.strip():
        reason = "هیچ هۆکارێک دیاری نەکراوە"
    if chat_id not in WARNS:
        WARNS[chat_id] = {}
    if uid not in WARNS[chat_id]:
        WARNS[chat_id][uid] = []
    WARNS[chat_id][uid].append({"reason": reason, "time": datetime.datetime.now().isoformat(), "by": update.effective_user.id})
    _save_warns()
    count = len(WARNS[chat_id][uid])
    try:
        mention = target.mention_html()
    except Exception:
        mention = f'<a href="tg://user?id={target.id}">{_html_escape(target.first_name)}</a>'
    text = (f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئاگادارکردنەوە بۆ {mention}\n"
            f"<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> ژمارەی ئاگاداری: {count}/{MAX_WARNS}\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هۆکار: {reason}")
    if count >= MAX_WARNS:
        try:
            await context.bot.ban_chat_member(update.effective_chat.id, target.id)
            WARNS[chat_id][uid] = []
            _save_warns()
            text += f"\n\n<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> {mention} دەرکرا (Ban) بەهۆی گەیشتن بە زۆرترین ئاگاداری!"
        except Exception as e:
            text += f"\n{_TGX} نەتوانرا دەر بکرێت: {_html_escape(str(e))}"
    await update.message.reply_text(text, parse_mode="HTML")

