async def unban_user_new(update: Update, context: CallbackContext):
    if not await is_admin(update, context):

        await update.message.reply_text(_TGX + " تەنیا ئادمین!", parse_mode="HTML"); return

    if not context.args:
        await update.message.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> /unban [ئایدی]", parse_mode="HTML"); return
    try:
        await context.bot.unban_chat_member(update.effective_chat.id, int(context.args[0]))
        await update.message.reply_text(f"{_TCK} بەکارهێنەری {context.args[0]} ئازاد کرا!", parse_mode="HTML")

    except Exception as e:
        await update.message.reply_text(f"{_TGX} هەڵە: {_html_escape(str(e))}", parse_mode="HTML")



