async def mute_user_new(update: Update, context: CallbackContext):
    # ── میمبەری ئاسایی: بێدەنگ بمێنێت ──
    if not await is_restrict_admin(update, context):
        return

    target = None
    args_start = 0
    if update.message.reply_to_message:
        target = update.message.reply_to_message.from_user
    elif context.args:
        try:
            target_id = int(context.args[0])
            target = type('User', (), {'id': target_id, 'first_name': str(target_id), 'mention_html': lambda self=None: f'<a href="tg://user?id={target_id}">{target_id}</a>'})()
            args_start = 1
        except (ValueError, IndexError):
            pass  # intentionally ignored

    if not target:
        await update.message.reply_text(
            "↩️ لەسەر پەیامی کەسێک ڕیپڵای بکە یان ئایدییەکەی بنووسە!\n"
            "نموونە: /mute 1m  یان  /mute 30m  یان  /mute 1h",
            parse_mode='HTML',
        ); return

    # ── پارس کردنی کات: 1m، 30m، 1h، یان ژمارەی تەنها (خولەک) ──
    minutes = 10  # default
    if context.args and len(context.args) > args_start:
        raw = context.args[args_start].strip().lower()
        try:
            if raw.endswith("h"):
                minutes = int(raw[:-1]) * 60
            elif raw.endswith("m"):
                minutes = int(raw[:-1])
            elif raw.endswith("d"):
                minutes = int(raw[:-1]) * 60  * 24
            else:
                minutes = int(raw)
        except Exception:
            minutes = 10

    # سنوور: کەمترین ١ خولەک، زیاترین ١ ڕۆژ
    minutes = max(1, min(minutes, 1440))

    # نیشاندانی کات بەشێوەی خوێندنەوەی ئاسان
    if minutes >= 60:
        h = minutes // 60
        m = minutes % 60
        duration_text = f"{h} کاتژمێر" + (f" {m} خولەک" if m else "")
    else:
        duration_text = f"{minutes} خولەک"

    until = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=minutes)
    try:
        mention = target.mention_html()
    except Exception:
        mention = f'<a href="tg://user?id={target.id}">{_html_escape(target.first_name)}</a>'
    try:
        await context.bot.restrict_chat_member(
            update.effective_chat.id, target.id,
            permissions=ChatPermissions(can_send_messages=False),
            until_date=until
        )
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5379904450473273365\">🔇</tg-emoji> {mention} میوت کرا بۆ {duration_text}!",
            parse_mode="HTML"
        )
    except Exception as e:
        await update.message.reply_text(f"{_TGX} هەڵە: {_html_escape(str(e))}", parse_mode="HTML")

