async def word_chain_start_new(update: Update, context: CallbackContext):
    chat_id = update.effective_chat.id
    if update.effective_chat.type == "private":
        await update.message.reply_text("<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> یاری زنجیرەی وشە تەنها لە گرووپ کار دەکات.", parse_mode="HTML"); return
    if chat_id in WORD_CHAIN_ACTIVE:
        await update.message.reply_text("<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> یاری زنجیرەی وشە پێشتر دەستپێکراوە.\n\nبۆ کۆتایی هێنان: /endchain", parse_mode='HTML'); return
    # وشەیەک هەڵبژێرە کە کۆتایی پیتەکەی باشە
    good_words = [w for w in KURDISH_WORDS if w[-1] not in IMPOSSIBLE_END_LETTERS]
    start_word = random.choice(good_words if good_words else KURDISH_WORDS)
    WORD_CHAIN_ACTIVE[chat_id] = {
        "current_word": start_word, "used_words": [start_word],
        "last_player": None, "start_time": time.time(), "scores": {}
    }
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> یاری زنجیرەی وشە دەستپێکرد!\n\n"
        f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> یاساکان:\n"
        f"• وشەکەت بە دوایین پیتی وشەی پێشووەوە دەستپێ بکات\n"
        f"• وشە دووبارە مەکەرەوە\n"
        f"• لانیکەم ٢ پیت بێت\n\n"
        f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> وشەی یەکەم: *<b>{start_word}</b>*\n"
        f"<tg-emoji emoji-id=\"5341583133055669788\">➡</tg-emoji> دوایین پیت: *<b>{start_word[-1]}</b>*\n\n"
        f"بۆ کۆتایی هێنان: /endchain",
        parse_mode="HTML")

async def word_chain_end_new(update: Update, context: CallbackContext):
    chat_id = update.effective_chat.id
    if chat_id not in WORD_CHAIN_ACTIVE:
        await update.message.reply_text(_TGX + " هیچ یاریەک چالاک نییە!", parse_mode="HTML"); return

    game = WORD_CHAIN_ACTIVE.pop(chat_id)
    scores = game["scores"]
    if scores:
        top = sorted(scores.items(), key=lambda x: x[1], reverse=True)
        text = "🏁 یاری زنجیرەی وشە کۆتایی هات!\n\n<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> ئامار:\n"
        medals = ["<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>","4️⃣","5️⃣"]
        for i,(uid,sc) in enumerate(top[:5]):
            # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> cached name
            ud_wc = USERS.get(str(uid), {})
            name = ud_wc.get("name") or ud_wc.get("nickname") or f"یاریزان {str(uid)[-4:]}"
            text += f"{medals[i]} {name}: {sc} خاڵ\n"
        total = sum(sc for _,sc in scores.items())
        text += f"\n{_TCH} کۆی وشەکان: {len(game['used_words'])}\n<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> کۆی خاڵ: {total}"
    else:
        text = "🏁 یاری زنجیرەی وشە کۆتایی هات!\n(هیچ کەسێک بەشداری نەکرد)"
    await update.message.reply_text(text, parse_mode='HTML')

async def handle_word_chain_new(update: Update, context: CallbackContext) -> bool:
    chat_id = update.effective_chat.id
    if chat_id not in WORD_CHAIN_ACTIVE: return False
    if not update.message or not update.message.text: return False
    word = update.message.text.strip()
    if word.startswith("/"): return False
    game = WORD_CHAIN_ACTIVE[chat_id]
    uid = update.effective_user.id
    cur_word = game["current_word"]
    last_letter = cur_word[-1]
    if not word.startswith(last_letter):
        await update.message.reply_text(
            f"{_TGX} وشەکەت دەبێت بە *<b>{last_letter}</b>* دەستپێ بکات!\n<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> وشەی ئێستا: {cur_word}",
            parse_mode="HTML"); return True
    if word in game["used_words"]:
        await update.message.reply_text(f"{_TGX} وشەی *<b>{word}</b>* پێشتر بەکاردراوە!", parse_mode="HTML"); return True
    if len(word) < 2:
        await update.message.reply_text(_TGX + " وشەکە دەبێت لانیکەم ٢ پیت بێت!", parse_mode="HTML"); return True
    game["current_word"] = word
    game["used_words"].append(word)
    game["last_player"] = uid
    game["scores"][uid] = game["scores"].get(uid, 0) + len(word)
    xp = len(word) * 2
    add_points(uid, xp)
    # ئاگاداری ئەگەر کۆتایی پیت گرفت بێت
    warning = ""
    if word[-1] in IMPOSSIBLE_END_LETTERS:
        warning = f"\n\n<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئاگاداری: پیتی *<b>{word[-1]}</b>* زۆر گرفتە! هەوڵ بدە وشەیەک پیدا بکەیت."
    await update.message.reply_text(
        f"{_TCK} *<b>{word}</b> - باشە!\n<tg-emoji emoji-id=\"5341583133055669788\">➡</tg-emoji> دوایین پیت: <b>{word[-1]}</b>*\n+{xp} XP{warning}",
        parse_mode="HTML")
    return True

# ─── یادەوەری (/remind) ───

async def remind_cmd_new(update: Update, context: CallbackContext):
    """/remind [کات] [نامە]  —  یادەوەری دانان
    کات: 30s / 10m / 2h / 1d
    نموونە: /remind 30m نان بخوە
    """

    user_id = update.effective_user.id
    uid     = str(user_id)
    args    = context.args or []

    # ── ڕێنمایی ئەگەر بەبێ argument ──
    if not args:
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادەوەری دانان</b>\n\n"
            "شێواز: <code>/remind [کات] [نامە]</code>\n\n"
            "نموونەکان:\n"
            "• <code>/remind 30m نان بخوە</code>\n"
            "• <code>/remind 2h کتێب بخوێنەوە</code>\n"
            "• <code>/remind 1d ڕێکەوتەکەت</code>\n\n"
            "<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> یەکەکان: <code>s</code>=چرکە, <code>m</code>=خولەک, "
            "<code>h</code>=کاتژمێر, <code>d</code>=ڕۆژ",
            parse_mode="HTML"
        )
        return

    # ── پارسکردنی کات ──
    time_str = args[0].lower()
    _units   = {"s": 1, "m": 60, "h": 3600, "d": 86400}
    _m       = re.match(r'^(\d+)([smhd])$', time_str)
    if not _m:
        await update.message.reply_text(
            _TGX + " فۆرماتی کات هەڵەیە!\n\n"
            "نموونە: <code>30m</code> یان <code>2h</code> یان <code>1d</code>",
            parse_mode="HTML"
        )
        return

    amount  = int(_m.group(1))
    unit    = _m.group(2)
    seconds = amount * _units[unit]

    # ── سنووری کات ──
    if seconds < 10:
        await update.message.reply_text(_TGX + " کات دەبێت لانیکەم ١٠ چرکە بێت!", parse_mode="HTML"); return

    if seconds > 7 * 86400:
        await update.message.reply_text(_TGX + " کات دەبێت کەمتر لە ٧ ڕۆژ بێت!", parse_mode="HTML"); return


    message_text = " ".join(args[1:]).strip() if len(args) > 1 else f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> یادەوەرییەکەت!"

    fire_at = (datetime.datetime.now() + datetime.timedelta(seconds=seconds)).isoformat()

    if uid not in REMINDERS_NEW:
        REMINDERS_NEW[uid] = []

    # ── سنووری ژمارەی یادەوەری ──
    if len(REMINDERS_NEW[uid]) >= 10:
        await update.message.reply_text(
            _TGX + " زۆرترین ژمارەی یادەوەری ١٠ تایە!\n"
            "یادەوەرییەکانت ببینە: /myreminders",
            parse_mode="HTML"
        )
        return

    REMINDERS_NEW[uid].append({
        "message":  message_text,
        "fire_at":  fire_at,
        "chat_id":  update.effective_chat.id,
        "added_at": datetime.datetime.now().isoformat()
    })
    _save_reminders_new()

    # ── نیشاندانی کات بە شێوازی خوێندنەوەی ئاسان ──
    unit_names = {"s": "چرکە", "m": "خولەک", "h": "کاتژمێر", "d": "ڕۆژ"}
    await update.message.reply_text(
        f"{_TCK} یادەوەری دانرا!\n\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> نامە: <b>{message_text}</b>\n"
        f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> کات: <b>{amount} {unit_names[unit]}</b> دوای ئێستا\n\n"
        f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> بینینی هەموو یادەوەرییەکان: /myreminders",
        parse_mode="HTML"
    )

async def my_reminders_new(update: Update, context: CallbackContext):
    """/myreminders — نیشاندانی هەموو یادەوەرییەکان"""

    uid  = str(update.effective_user.id)
    rems = REMINDERS_NEW.get(uid, [])

    if not rems:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ یادەوەرییەکت نییە!\n\n"
            "بۆ دانانی یادەوەری:\n"
            "<code>/remind 30m نان بخوە</code>",
            parse_mode="HTML"
        )
        return

    now  = datetime.datetime.now()
    text = f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادەوەرییەکانت:</b>\n\n"
    valid = []
    for i, r in enumerate(rems, 1):
        try:
            fire = datetime.datetime.fromisoformat(r["fire_at"])
            diff = fire - now
            if diff.total_seconds() < 0:
                continue  # تێپەڕیوە
            valid.append(r)
            mins = int(diff.total_seconds() // 60)
            if mins < 60:
                remaining = f"{mins} خولەک"
            elif mins < 1440:
                remaining = f"{mins // 60} کاتژمێر"
            else:
                remaining = f"{mins // 1440} ڕۆژ"
            text += (
                f"{i}. <tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> {r['message']}\n"
                f"   <tg-emoji emoji-id=\"5386415655253730366\">🕐</tg-emoji> {fire.strftime('%H:%M - %Y/%m/%d')}\n"
                f"   <tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> {remaining} ماوە\n\n"
            )
        except Exception:
            continue

    if not valid:
        REMINDERS_NEW[uid] = []
        _save_reminders_new()
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ یادەوەرییەکی چالاکت نییە!",
            parse_mode="HTML"
        )
        return

    # نوێکردنەوەی لیست (تێپەڕیوەکان لابردن)
    REMINDERS_NEW[uid] = valid
    _save_reminders_new()

    kb = InlineKeyboardMarkup([[
        _ebtn("سڕینەوەی هەموو یادەوەرییەکان", "remind:clear_all", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})
    ]])
    await update.message.reply_text(text, parse_mode="HTML", reply_markup=kb)

async def _remind_clear_callback(update: Update, context: CallbackContext):
    """سڕینەوەی هەموو یادەوەرییەکان"""
    try:
        query = update.callback_query
        answered = _make_answerer(query)
        await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
        uid = str(query.from_user.id)
        if query.data == "remind:clear_all":
            REMINDERS_NEW[uid] = []
            _save_reminders_new()
            await _safe_edit(query, f"{_TCK} هەموو یادەوەرییەکانت سڕانەوە!")

    except Exception as e:
        logger.error(f"Error in _remind_clear_callback: {e}")
        try:
            if hasattr(query, "answer"):
                await query.answer()
        except Exception:
            pass

async def check_reminders_new(context: CallbackContext):
    """job — هەر ٦٠ چرکەیەک چەک دەکات"""
    now = datetime.datetime.now()
    changed = False

    for uid, rems in list(REMINDERS_NEW.items()):
        remaining = []
        for r in rems:
            try:
                fire = datetime.datetime.fromisoformat(r["fire_at"])
                if fire <= now:
                    # نێرینی یادەوەری
                    try:
                        chat_id = r.get("chat_id", int(uid))
                        await context.bot.send_message(
                            chat_id=chat_id,
                            text=f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادەوەری!</b>\n\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> {r['message']}",
                            parse_mode="HTML"
                        )
                    except Exception as _e:
                        logger.warning(f"remind send error uid={uid}: {_e}")
                    changed = True
                else:
                    remaining.append(r)
            except Exception:
                remaining.append(r)

        if len(remaining) != len(rems):
            REMINDERS_NEW[uid] = remaining
            changed = True

    if changed:
        _save_reminders_new()

async def _get_display_name_for_uid(bot, uid: str, chat_id_int: int, data: dict) -> str:
    """ناوی کەسی بدۆزەرەوە — ئەکاونت یان چەناڵ"""
    # ئەگەر ناوی پاشەکەوتکراو هەبوو — بەکاری بهێنە
    saved_name = data.get("name", "")
    if saved_name:
        return saved_name
    try:
        uid_int = int(uid)
        if uid_int < 0:
            # چەناڵ
            ch = await bot.get_chat(uid_int)
            return ch.title or ch.username or f"چەناڵ {uid}"
        else:
            m = await bot.get_chat_member(chat_id_int, uid_int)
            return m.user.first_name or f"بەکارهێنەر {uid}"
    except Exception:
        return f"بەکارهێنەر {uid}"


# ═════════════════════════
# <tg-emoji emoji-id=\"5462921117423384478\">🔧</tg-emoji> HELPER — _run_stats_from_callback
# بانگهێشتکراوە لە: profile:mystats / profile:groupstats /
#                   admin:groupstats / run:mystats / run:groupstats
# ═════════════════════════

class _FakeMsg:
    """پەیامی دروست‌کراو بۆ callback — بۆ ئەوەی reply_text کار بکات"""
    def __init__(self, query):
        self._query   = query
        self.chat     = query.message.chat     if query.message else None
        self.chat_id  = query.message.chat_id  if query.message else None
        self.sender_chat = None   # callback query — هیچکات sender_chat نییە

    async def reply_text(self, text, **kwargs):
        """پەیام بنێرە بەشێوەی پەیامی نوێ (نەک edit)"""
        try:
            chat = self.chat
            if chat:
                kwargs.setdefault("parse_mode", "HTML")
                await chat.send_message(text, **kwargs)
        except Exception as _e:
            logger.error("_FakeMsg.reply_text هەڵە: %s", _e)


class _FakeUpdate:
    """Update‌ی دروست‌کراو بۆ callback — ئامارەکان call بکە بەبێ /command"""
    def __init__(self, query):
        self.effective_user  = query.from_user
        self.effective_chat  = query.message.chat if query.message else None
        self.message         = _FakeMsg(query)
        self.callback_query  = query

async def _run_stats_from_callback(query, context, mode: str = "my"):
    """
    ئاماری کەس یان گرووپ بنیشانە لە callback_query.
    mode = 'my'    → my_stats_new
    mode = 'group' → group_stats_new
    """
    answered = _make_answerer(query)

    if not query.message:
        await answered("⚠️ هەڵەیەک ڕووی دا — پەیامەکە نەدۆزرایەوە", show_alert=True)
        return

    try:
        fake = _FakeUpdate(query)
        if mode == "my":
            await my_stats_new(fake, context)
        else:
            await group_stats_new(fake, context)
    except Exception as _e:
        logger.error(f"_run_stats_from_callback(mode={mode}) هەڵە: {_e}")
        try:
            await query.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> هەڵەیەک لە نیشاندانی ئامار ڕووی دا.", parse_mode="HTML")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
# ═════════════════════════

async def group_stats_new(update: Update, context: CallbackContext):
    """ئامارەکانی گرووپ — پشتگیری لە ئەکاونت + چەناڵ"""
    chat_id = str(update.effective_chat.id)
    stats = GROUP_STATS.get(chat_id, {})
    if not stats:
        await update.message.reply_text(f"{_TCH} هێشتا هیچ ئاماری نییە!", parse_mode="HTML"); return


    sorted_users = sorted(stats.items(), key=lambda x: x[1].get("msgs", 0), reverse=True)[:10]
    total_msgs = sum(v.get("msgs", 0) for v in stats.values())
    total_users = len(stats)

    medals = ["<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]
    lines = []
    tag_parts = []

    for i, (uid, data) in enumerate(sorted_users):
        name = await _get_display_name_for_uid(context.bot, uid, update.effective_chat.id, data)
        cnt = data.get("msgs", 0)
        try:
            uid_int = int(uid)
            if uid_int < 0:
                # چەناڵ — @username یان ناو
                ch = await context.bot.get_chat(uid_int)
                if ch.username:
                    mention = f"@{ch.username}"
                else:
                    mention = f"<tg-emoji emoji-id=\"6024112973226709843\">📢</tg-emoji> {name}"
            else:
                m = await context.bot.get_chat_member(update.effective_chat.id, uid_int)
                if m.user.username:
                    mention = f"@{m.user.username}"
                else:
                    mention = f'<a href="tg://user?id={uid}">{name}</a>'
        except Exception:
            mention = name
        lines.append(f"{medals[i]} {mention}: <b>{cnt:,}</b> پەیام")
        tag_parts.append(mention)

    tag_line = "  ".join(tag_parts)
    sep = "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"
    text = (
        f"{_TCH} <b>ئامارەکانی گرووپ</b>\n"
        f"{sep}\n"
        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> کۆی پەیامەکان: <b>{total_msgs:,}</b>\n"
        f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> کۆی کەسەکان: <b>{total_users}</b>\n"
        f"{sep}\n\n"
        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> زۆرترین نامەنووس:\n\n"
        + "\n".join(lines)
        + f"\n\n{sep}\n"
        + "<tg-emoji emoji-id=\"5395487321967596182\">🏷</tg-emoji> <i>تاگکراوەکان:</i>\n"
        + tag_line
    )
    await update.message.reply_text(text, parse_mode="HTML", disable_web_page_preview=True)

async def my_stats_new(update: Update, context: CallbackContext):
    """ئامارەکانی کەس — پشتگیری لە ئەکاونت + چەناڵ"""
    msg = update.message
    chat_id = str(update.effective_chat.id)
    sep = "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"
    week_key = _get_week_key()

    # sender_chat check — ئایا بەناوی چەناڵ داواکراوە؟
    sender_chat = getattr(msg, 'sender_chat', None)
    if sender_chat:
        uid = str(sender_chat.id)
        name = sender_chat.title or sender_chat.username or f"چەناڵ {uid}"
        gs = GROUP_STATS.get(chat_id, {}).get(uid, {})
        msgs_here = gs.get("msgs", 0)
        weekly_count = WEEKLY_STATS.get(chat_id, {}).get(week_key, {}).get(uid, 0)
        # ڕێزبەندی لە گرووپدا
        all_sorted = sorted(GROUP_STATS.get(chat_id, {}).items(), key=lambda x: x[1].get("msgs", 0), reverse=True)
        rank = next((i+1 for i,(_uid,_) in enumerate(all_sorted) if _uid == uid), 0)
        total = len(all_sorted)
        text = (
            f"{_TCH} <b>ئامارەکانی چەناڵ</b>\n"
            f"{sep}\n"
            f"<tg-emoji emoji-id=\"6024112973226709843\">📢</tg-emoji> <b>{name}</b>\n"
            f"{sep}\n\n"
            f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> پەیامەکان لەم گرووپە: <b>{msgs_here:,}</b>\n"
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> ئەم هەفتەیە: <b>{weekly_count:,}</b>\n"
            f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> ڕتبە: <b>{rank}/{total}</b> لەم گرووپە\n"
        )
        await msg.reply_text(text, parse_mode="HTML")
        return

    if not update.effective_user:
        return

    uid = str(update.effective_user.id)
    uname = _html_escape(update.effective_user.first_name or f"بەکارهێنەر {uid}")
    gs = GROUP_STATS.get(chat_id, {}).get(uid, {})
    u = get_user_data(int(uid))
    msgs_here = gs.get("msgs", 0)
    weekly_count = WEEKLY_STATS.get(chat_id, {}).get(week_key, {}).get(uid, 0)

    # ڕێزبەندی لە گرووپدا
    all_sorted = sorted(GROUP_STATS.get(chat_id, {}).items(), key=lambda x: x[1].get("msgs", 0), reverse=True)
    rank = next((i+1 for i,(_uid,_) in enumerate(all_sorted) if _uid == uid), 0)
    total = len(all_sorted)

    # ڕێزبەندی هەفتانە لەم گرووپدا
    week_data = WEEKLY_STATS.get(chat_id, {}).get(week_key, {})
    week_sorted = sorted(week_data.items(), key=lambda x: x[1], reverse=True)
    week_rank = next((i+1 for i,(_uid,_) in enumerate(week_sorted) if _uid == uid), 0)

    games_played = u.get('games_played', 0)
    games_won    = u.get('games_won', 0)
    win_rate = round(games_won/games_played*100) if games_played else 0

    text = (
        f"{_TCH} <b>ئامارەکانت — {uname}</b>\n"
        f"{sep}\n\n"
        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> پەیامەکانت لەم گرووپە: <b>{msgs_here:,}</b>\n"
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> ئەم هەفتەیە: <b>{weekly_count:,}</b> (ڕتبە #{week_rank if week_rank else '—'})"
        f"\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> کۆی پەیامەکانت: <b>{u.get('messages',0):,}</b>\n"
        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> ڕتبەت لەم گرووپە: <b>#{rank}</b> لە {total} کەسەوە\n"
        f"{sep}\n"
        f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> لێڤڵ: <b>{u.get('level',1)}</b>  |  <tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> XP: <b>{u.get('points',0):,}</b>\n"
        f"{_TMN} کۆین: <b>{u.get('coins',0):,}</b> {_TCN}\n"
        f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> یاریەکان: <b>{games_played}</b>  |  <tg-emoji emoji-id=\"5789828777882162072\">🏅</tg-emoji> بردنەوە: <b>{games_won}</b> ({win_rate}%)\n"
        f"<tg-emoji emoji-id=\"5379636904075499661\">🔥</tg-emoji> بەردەوامی: <b>{u.get('streak',0)}</b> ڕۆژ\n"
        f"<tg-emoji emoji-id=\"5395487321967596182\">🏷</tg-emoji> نازناو: <b>{u.get('nickname', 'بێ نازناو')}</b>"
    )
