async def market_sell_new(update: Update, context: CallbackContext):
    if not context.args or len(context.args) < 2:   # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: context.args=None کاتی callback
        await update.message.reply_text("<tg-emoji emoji-id=\"5278702045883292456\">🏪</tg-emoji> فەرمان: /sell [کاڵا] [نرخ]\nنموونە: /sell ئەڵماس 150", parse_mode="HTML"); return
    uid = update.effective_user.id
    u = get_user_data(uid)
    item = context.args[0]
    try: price = int(context.args[1])
    except Exception: await update.message.reply_text(_TGX + " نرخەکە هەڵەیە!", parse_mode="HTML"); return

    if price <= 0:
        await update.message.reply_text(_TGX + " نرخەکە دەبێت لە ٠ گەورەتر بێت!", parse_mode="HTML"); return

    colls = u.get("collectibles", [])
    if item not in colls:
        await update.message.reply_text(f"{_TGX} کاڵای {item} لە جزدانی تۆدا نییە!\n<tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji> کاڵاکانت: {', '.join(colls) if colls else 'بەتاڵ'}", parse_mode="HTML"); return

    listing_id = f"{uid}_{int(time.time())}"
    MARKET[listing_id] = {"seller": uid, "item": item, "price": price, "listed": datetime.datetime.now().isoformat()}
    colls.remove(item); _save_market(); save_users()
    await update.message.reply_text(f"{_TCK} کاڵای {item} لە بازاڕدا دانرا!\n{_TMN} نرخ: {price} {_TCN}\n<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: `{listing_id[:12]}...`", parse_mode="HTML")

async def market_view_new(update: Update, context: CallbackContext):
    if not MARKET:
        await update.message.reply_text("<tg-emoji emoji-id=\"5278702045883292456\">🏪</tg-emoji> بازاڕ بەتاڵە!\nفەرمانی /sell بەکاربهێنە بۆ فرۆشتنی کاڵاکانت.", parse_mode="HTML"); return
    text = "<tg-emoji emoji-id=\"5278702045883292456\">🏪</tg-emoji> بازاڕی بەکارهێنەران:\n\n"
    for lid, data in list(MARKET.items())[:10]:
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> cached name — no API call
        seller = USERS.get(str(data["seller"]), {}).get("nickname") or USERS.get(str(data["seller"]), {}).get("name") or str(data["seller"])
        text += f"• {data[f'item']} | {_TMN} {data['price']} {_TCN} | <tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> {seller}\n  <tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> `{lid[:10]}`\n\n"
    text += "<tg-emoji emoji-id=\"5438389200531527988\">🛒</tg-emoji> بۆ کڕینی کاڵا: /buymarket [ئایدی]"
    await update.message.reply_text(text, parse_mode="HTML")

async def market_buy_new(update: Update, context: CallbackContext):
    if not context.args:
        await update.message.reply_text("<tg-emoji emoji-id=\"5438389200531527988\">🛒</tg-emoji> فەرمان: /buymarket [ئایدی]", parse_mode='HTML'); return
    lid_prefix = context.args[0]
    buyer = update.effective_user.id

    # ── Lock بۆ جێگیری کڕینی هاوکات یەک کاڵا ──
    async with _get_market_lock():
        found_lid = next((k for k in MARKET if k.startswith(lid_prefix) or k == lid_prefix), None)
        if not found_lid:
            await update.message.reply_text(_TGX + " کاڵاکە نەدۆزرایەوە!", parse_mode="HTML"); return

        data = MARKET[found_lid]
        buyer_d = get_user_data(buyer)
        if buyer == data["seller"]:
            await update.message.reply_text(_TGX + " ناتوانیت کاڵایەک بکڕیت کە خۆت داتناوە بۆ فرۆشتن!", parse_mode="HTML"); return

        if buyer_d.get("coins", 0) < data["price"]:
            await update.message.reply_text(f"{_TGX} کۆینی پێویستت نییە! پێویستت بە {data['price']} {_TCN} هەیە.", parse_mode="HTML"); return

        add_coins(buyer, -data["price"])
        add_coins(data["seller"], data["price"])
        # FIX: buyer_d ئێستا بەکاردەهێنین — نەک get_user_data(buyer) دووجار
        if "collectibles" not in buyer_d: buyer_d["collectibles"] = []
        buyer_d["collectibles"].append(data["item"])
        del MARKET[found_lid]; _save_market(); save_users()

    seller_id = data["seller"]
    item_name = data["item"]
    price     = data["price"]
    await update.message.reply_text(f"{_TCK} کاڵای {item_name} بە بڕی {price} {_TCN} کڕدرا!", parse_mode="HTML")

    try:
        await context.bot.send_message(seller_id, f"{_TMN} کاڵای {item_name}ەکەت فرۆشرا! بڕی +{price} {_TCN} بۆت زیاد کرا.", parse_mode="HTML")
    except Exception as _exc:
        logger.debug("Suppressed Exception: %s", _exc)
