async def translate_cmd_new(update: Update, context: CallbackContext):
    _TGL = "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji>"
    _TSP = "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"
    _TFL = "<tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji>"
    _TSC = "<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji>"
    _DIVIDER = f"{_TSP} ════ {_TFL} ════ {_TSP}"
    _VALID = {"en","ar","ku","tr","fa","fr","de","es","ru","zh","ja","it"}

    msg = update.effective_message
    if not context.args:
        # بە ریپڵ بەبێ ئارگۆمێنت: نیشاندانی مینیو
        await msg.reply_text(
            f"{_TGL} <b>وەرگێڕانی پڕۆفیشناڵ</b>\n"
            f"{_DIVIDER}\n\n"
            f"{_TSC} بەکارهێنان:\n\n"
            f"<b>١.</b> ریپڵی پەیامێک بکە + <code>/translate en</code>\n"
            f"<b>٢.</b> <code>/translate fr دەقەکەت</code>\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> کۆدی زمانەکان:\n"
            f"<code>en</code> ئینگلیزی · <code>ar</code> عەرەبی · <code>ku</code> کوردی\n"
            f"<code>tr</code> تورکی · <code>fa</code> فارسی · <code>fr</code> فەڕەنسی\n"
            f"<code>de</code> ئەڵمانی · <code>es</code> ئیسپانی · <code>ru</code> ڕووسی\n"
            f"<code>zh</code> چینی · <code>ja</code> ژاپۆنی · <code>it</code> ئیتالی",
            parse_mode="HTML"
        )
        return

    lang = context.args[0].lower()
    if lang not in _VALID:
        await msg.reply_text(
            f"{_TGX} کۆدی زمان نەزانراوە: <code>{_html_escape(lang)}</code>\n\n"
            f"زمانە دروستەکان:\n"
            f"<code>en ar ku tr fa fr de es ru zh ja it</code>",
            parse_mode="HTML"
        )
        return

    # تێکست لە ریپڵ یان ئارگۆمێنتەکان
    text = ""
    if msg.reply_to_message:
        text = (msg.reply_to_message.text or msg.reply_to_message.caption or "").strip()
    if not text:
        text = " ".join(context.args[1:]).strip()
    if not text:
        await msg.reply_text(
            f"{_TGX} تکایە دەقێک بنووسە یان پەیامێک ریپڵی بکە!",
            parse_mode="HTML"
        )
        return

    await _do_translate(msg.reply_text, lang, text)

async def translate_lang_callback(update: Update, context: CallbackContext):
    """دوگمەی هەڵبژاردنی زمان"""
    try:
        query = update.callback_query
        answered = _make_answerer(query)
        await answered()
        lang = query.data.split(":")[1]
        _LANG_MAP: dict = {
            "en": ("ئینگلیزی",      "🇬🇧"),
            "ar": ("عەرەبی",        "🇸🇦"),
            "ku": ("کوردی سۆرانی",  "🇮🇶"),
            "tr": ("تورکی",         "🇹🇷"),
            "fa": ("فارسی",         "🇮🇷"),
            "fr": ("فەڕەنسی",       "🇫🇷"),
            "de": ("ئەڵمانی",       "🇩🇪"),
            "es": ("ئیسپانی",       "🇪🇸"),
            "ru": ("ڕووسی",         "🇷🇺"),
            "zh": ("چینی",          "🇨🇳"),
            "ja": ("ژاپۆنی",        "🇯🇵"),
            "it": ("ئیتالی",        "🇮🇹"),
        }
        lang_name, lang_flag = _LANG_MAP.get(lang, (lang.upper(), "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji>"))
        uid = query.from_user.id
        TRANSLATE_WAITING[uid] = (lang, time.time())
        _TGL = "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji>"
        _TSP = "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"
        _TFL = "<tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji>"
        _TSC = "<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji>"
        _TLT = "<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji>"
        _DIVIDER = f"{_TSP} ════ {_TFL} ════ {_TSP}"
        keyboard = InlineKeyboardMarkup([[
            _ebtn("هەڵوەشاندنەوە", "translate:cancel",
                  emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
        ]])
        await _safe_edit(query,
            f"{_TGL} <b>وەرگێڕانی پڕۆفیشناڵ</b>\n"
            f"{_DIVIDER}\n\n"
            f"{lang_flag} زمانی هەڵبژێردراو: <b>{lang_name}</b>\n\n"
            f"{_TSC} ئێستا دەقەکەت بنووسە یان پەیامێک ریپڵی بکە.\n\n"
            f"{_TLT} بۆتەکە فەوری وەرگێڕانی دەکات!\n\n"
            f"<i>(فەرمانێکی تر بنووسە بۆ هەڵوەشاندنەوە)</i>",
            parse_mode="HTML", reply_markup=keyboard)
    except Exception as e:
        logger.error(f"Error in translate_lang_callback: {e}")
        try:
            if hasattr(query, "answer"):
                await query.answer()
        except Exception:
            pass

