async def id_command(update: Update, context: CallbackContext):
    """نیشاندانی زانیاری تێر و تەسەلی ئەکاونت — بۆ هەمووان"""
    try:
        if update.message.reply_to_message:
            user = update.message.reply_to_message.from_user
        elif context.args:
            try:
                target_id = int(context.args[0])
                try:
                    chat = await context.bot.get_chat(target_id)
                    user = chat
                except Exception:
                    user = type('User', (), {
                        'id': target_id, 'first_name': str(target_id),
                        'last_name': None, 'username': None,
                        'language_code': None, 'is_premium': False
                    })()
            except ValueError:
                user = update.effective_user
        else:
            user = update.effective_user

        await _send_id_info(update.message.reply_text, user, context, message=update.message)

    except Exception as e:
        logger.error(f"هەڵە لە id_command: {e}", exc_info=True)
        await update.message.reply_text(_TGX + " ببورە، هەڵەیەک ڕوویدا.", parse_mode="HTML")

async def ids_command(update: Update, context: CallbackContext):
    """ڕیپلەی پەیامی کەسێک بکە — تەنیا ئایدیەکەی دەدات"""
    msg = update.message
    if not msg.reply_to_message:
        await msg.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تکایە ڕیپلەی پەیامی کەسێک بکە.", parse_mode="HTML")
        return
    uid = msg.reply_to_message.from_user.id
    await msg.reply_text(f"<code>{uid}</code>", parse_mode="HTML")

async def id_info_callback(query, context):
    answered = _make_answerer(query)
    """دوگمەی ID لە مێنیوی پڕۆفایلدا"""
    # _html_escape() گلۆبەل بەکاردێت — closure لادەبرا
    try:
        await answered()
        user    = query.from_user
        user_id = user.id

        full_name  = f"{user.first_name or ''} {user.last_name or ''}".strip() or "نەزانراو"
        username   = f"@{user.username}" if user.username else "نییە"
        language   = user.language_code or "نەزانراو"
        is_premium = f"{_TCK} بەڵێ" if getattr(user, 'is_premium', False) else _TGX + " نییە"

        bot_data = get_user_data(user_id)
        points   = bot_data.get("points", 0)
        level    = bot_data.get("level", 1)
        coins    = bot_data.get("coins", 0)
        messages = bot_data.get("messages", 0)
        rank     = get_user_rank(level)
        joined   = bot_data.get("joined_date", "")
        if joined:
            try:
                joined = datetime.datetime.fromisoformat(joined).strftime("%Y/%m/%d")
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        bio = ""
        try:
            chat_info = await context.bot.get_chat(user_id)
            bio = chat_info.bio or ""
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        text = (
            f"<b><tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> زانیارییەکانی ئەکاونت</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: <code>{user_id}</code>\n"
            f"<tg-emoji emoji-id=\"5438343003863292149\">📛</tg-emoji> ناو: {_html_escape(full_name)}\n"
            f"<tg-emoji emoji-id=\"5472411062412254753\">🔤</tg-emoji> ناسناو: {_html_escape(username)}\n"
            f"<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> زمان: {_html_escape(language)}\n"
            f"{_TDM} تێلیگرام پریمیۆم: {is_premium}\n"
        )
        if bio:
            text += f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بایۆ: {_html_escape(bio)}\n"
        text += (
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> ئامارەکانی ناو بۆت:\n"
            f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئاست: {level} | {rank}\n"
            f"<tg-emoji emoji-id=\"5789828777882162072\">🏅</tg-emoji> خاڵ: {points:,}\n"
            f"{_TMN} کۆین: {coins:,}\n"
            f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> پەیامەکان: {messages:,}\n"
        )
        if joined:
            text += f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> ڕێکەوتی بەشداری: {_html_escape(joined)}"

        kb      = InlineKeyboardMarkup([[_ebtn("گەڕانەوە بۆ پڕۆفایل", "menu:profile", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]])
        chat_id = query.message.chat.id

        # ── وێنەی پڕۆفایل ──
        photo_id = None
        try:
            photos = await context.bot.get_user_profile_photos(user_id, limit=1)
            if photos and photos.total_count > 0:
                photo_id = photos.photos[0][-1].file_id
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        if photo_id:
            try:
                await query.message.delete()
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
            try:
                await context.bot.send_photo(
                    chat_id=chat_id, photo=photo_id,
                    caption=text, parse_mode="HTML"
                )
            except Exception as _pe:
                logger.warning("id_info photo error: %s", _pe)
                await context.bot.send_message(
                    chat_id=chat_id, text=text,
                    parse_mode="HTML"
                )
        else:
            try:
                await _safe_edit(query, text, reply_markup=kb)
            except Exception:
                await query.message.reply_text(text, parse_mode="HTML", reply_markup=kb)

    except Exception as e:
        logger.error(f"هەڵە لە id_info_callback: {e}", exc_info=True)
        try:
            await _safe_edit(query, "هەڵەیەک ڕوویدا لە بارکردنی زانیارییەکان.\nتکایە دووبارە هەوڵ بدەرەوە.", reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:profile", emoji_id="6271611232457855630", api_kwargs={"style": "primary"})]]))
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored


