async def addinfo_menu_cmd(update: Update, context: CallbackContext):
    """مێنیوی بەڕێوەبردنی زانیارییەکان"""
    user_id = update.effective_user.id
    if user_id != OWNER_ID:
        await update.message.reply_text(_TGX + " ئەم فەرمانە تەنها بۆ خاوەنی بۆت ڕێپێدراوە.", parse_mode="HTML")

        return
    
    if context.args:
        raw = update.message.text
        after_cmd = raw.split(None, 1)
        if len(after_cmd) >= 2:
            body = after_cmd[1].strip()
            parts = body.split(None, 1)
            if parts[0].startswith("#"):
                tag_raw = parts[0][1:]
                tag_key = tag_raw.lower()
                content = parts[1].strip() if len(parts) > 1 else ""
                if content:
                    HASH_INFO_DATA[tag_key] = {
                        "tag": tag_raw,
                        "content": content,
                        "date": datetime.datetime.now().strftime("%Y-%m-%d"),
                        "added_by": user_id
                    }
                    save_hash_info()
                    preview = content[:100] + ("..." if len(content) > 100 else "")
                    keyboard = [
                        [_ebtn("لیستی هەموو زانیارییەکان", "addinfo:list", emoji_id="5911212915968448930", api_kwargs={"style": "primary"}),
                         _ebtn("سڕینەوە", f"addinfo:del:{tag_key}", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})],
                        [_ebtn("زیادکردنی دانەیەکی تر", "addinfo:new", emoji_id="5230940806960919610", api_kwargs={"style": "primary"})]
                    ]
                    await update.message.reply_text(
                        f"{_TCK} زانیارییەکە بە سەرکەوتوویی پاشەکەوت کرا!\n\n<tg-emoji emoji-id=\"5395626195440147722\">🔖</tg-emoji> تاگ: `#{tag_raw}`\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> کورتە: {preview}\n<tg-emoji emoji-id=\"5375510007439711210\">📏</tg-emoji> درێژی: {len(content)} پیت\n\nئێستا هەرکەسێک بنووسێت `#{tag_raw}` بۆتەکە ئەم دەقە دەنێرێت.",
                        parse_mode="HTML",
                        reply_markup=InlineKeyboardMarkup(keyboard)
                    )
                    return
    
    keyboard = [
        [_ebtn("زیادکردنی زانیاری نوێ", "addinfo:new", emoji_id="5230940806960919610", api_kwargs={"style": "primary"})],
        [_ebtn("بینینی هەموو زانیارییەکان", "addinfo:list", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})],
        [_ebtn("سڕینەوەی زانیاری", "addinfo:dellist", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})],
    ]
    await update.message.reply_text(
        "<tg-emoji emoji-id=\"5445275347366989283\">📚</tg-emoji> مێنیوی بەڕێوەبردنی زانیارییەکان\n\n"
        "لێرەدا دەتوانیت وەڵامی ئامادەکراو بۆ هاشتاگەکان دابنێیت.\n"
        "شێوازی نووسین: <code>/addinfo #ناو_یان_تاگ دەقی وەڵامەکە</code>\n\n"
        "بۆ نموونە: <code>/addinfo #ڕێسا تکایە ڕێز لە یاساکان بگرن.</code>\n\n"
        "کە یەکێک بنووسێت <code>#ڕێسا</code> بۆتەکە وەڵامی دەداتەوە.",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )

async def addinfo_callback(update: Update, context: CallbackContext):
    """وەڵامدەرەوەی دوگمەکانی addinfo"""
    try:
        query = update.callback_query
        answered = _make_answerer(query)
        user_id = query.from_user.id
        if user_id != OWNER_ID:
            await answered("❌" + " تەنها بۆ خاوەنی بۆت!", show_alert=True)
            return

        parts = query.data.split(":")
        action = parts[1] if len(parts) > 1 else ""

        if action == "new":
            await _safe_edit(query, "<tg-emoji emoji-id=\"5230940806960919610\">➕</tg-emoji> زیادکردنی زانیاری نوێ\n\n"
                "فەرمانەکە بەم شێوەیە بنووسە:\n"
                "<code>/addinfo #تاگ تێکستی وەڵامەکە</code>\n\n"
                "بۆ نموونە:\n"
                "<code>/addinfo #یارمەتی بۆ یارمەتی پەیوەندی بە ئادمین بکە.</code>", reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "addinfo:menu", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]))

        elif action == "list":
            if not HASH_INFO_DATA:
                await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ زانیارییەک زیاد نەکراوە.\n\nفەرمانی /addinfo بەکاربهێنە بۆ زیادکردن.", reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "addinfo:menu", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]))
                return

            lines = []
            buttons = []
            for k, v in list(HASH_INFO_DATA.items())[:20]:
                lines.append(f"<tg-emoji emoji-id=\"5395626195440147722\">🔖</tg-emoji> `#{v['tag']}` — {len(v['content'])} پیت")
                buttons.append([_ebtn(f"سڕینەوەی #{v['tag']}", f"addinfo:del:{k}", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})])

            buttons.append([_ebtn("گەڕانەوە", "addinfo:menu", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
            text = f"<tg-emoji emoji-id=\"5445275347366989283\">📚</tg-emoji> هەموو زانیارییەکان ({len(HASH_INFO_DATA)} دانە):\n\n" + "\n".join(lines)
            await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup(buttons))

        elif action == "del" and len(parts) > 2:
            tag_key = parts[2]
            if tag_key in HASH_INFO_DATA:
                tag_raw = HASH_INFO_DATA[tag_key]["tag"]
                keyboard = [
                    [_ebtn("بەڵێ، بسڕێتەوە", f"addinfo:confirm_del:{tag_key}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
                     _ebtn("نەخێر، گەڕانەوە", "addinfo:list", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
                ]
                await _safe_edit(query, f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئایا دڵنیایت لە سڕینەوەی زانیاری تاگی `#{tag_raw}`؟", reply_markup=InlineKeyboardMarkup(keyboard))
            else:
                await _safe_edit(query, _TGX + " زانیارییەکە نەدۆزرایەوە.")

        elif action == "confirm_del" and len(parts) > 2:
            tag_key = parts[2]
            if tag_key in HASH_INFO_DATA:
                tag_raw = HASH_INFO_DATA[tag_key]["tag"]
                del HASH_INFO_DATA[tag_key]
                save_hash_info()
                await _safe_edit(query, f"زانیاری تاگی `#{tag_raw}` بە سەرکەوتوویی سڕایەوە.", reply_markup=InlineKeyboardMarkup([[_ebtn("لیستی زانیارییەکان", "addinfo:list", emoji_id="5857044938755149915", api_kwargs={"style": "primary"})]]))
            else:
                await _safe_edit(query, _TGX + " هەڵەیەک ڕوویدا.")

        elif action == "dellist":
            if not HASH_INFO_DATA:
                await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ زانیارییەک نییە بۆ سڕینەوە.", reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "addinfo:menu", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]))
                return
            buttons = []
            for k, v in list(HASH_INFO_DATA.items())[:15]:
                buttons.append([_ebtn(f"#{v['tag']}", f"addinfo:del:{k}", emoji_id="5379723202853383390", api_kwargs={"style": "primary"})])
            buttons.append([_ebtn("گەڕانەوە", "addinfo:menu", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
            await _safe_edit(query, "<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> تاگێک هەڵبژێرە بۆ سڕینەوە:", reply_markup=InlineKeyboardMarkup(buttons))

        elif action == "menu":
            keyboard = [
                [_ebtn("زیادکردنی زانیاری نوێ", "addinfo:new", emoji_id="5230940806960919610", api_kwargs={"style": "primary"})],
                [_ebtn("بینینی هەموو زانیارییەکان", "addinfo:list", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})],
                [_ebtn("سڕینەوەی زانیاری", "addinfo:dellist", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})],
            ]
            await _safe_edit(query, "<tg-emoji emoji-id=\"5445275347366989283\">📚</tg-emoji> مێنیوی بەڕێوەبردنی زانیارییەکان\n\nفەرمانێک هەڵبژێرە:", reply_markup=InlineKeyboardMarkup(keyboard))

    except Exception as e:
        logger.error(f"Error in addinfo_callback: {e}")
        try:
            if hasattr(query, "answer"):
                await query.answer()
        except Exception:
            pass

async def smart_remind_cmd(update: Update, context: CallbackContext):
    """/sremind [کات] [نامە]  —  یادەوەری زیرەک بۆ کەسی تر (ئەگەر ڕیپڵ بوو) یا خۆت"""

    user = update.effective_user
    uid  = str(user.id)
    args = context.args or []

    if not args:
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادەوەری زیرەک</b>\n\n"
            "شێواز: <code>/sremind [کات] [نامە]</code>\n\n"
            "نموونەکان:\n"
            "• <code>/sremind 30m کتێب بخوێنەوە</code>\n"
            "• <code>/sremind 1h کارەکەت تەواو بکە</code>\n\n"
            "<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> ئەگەر پەیامێک ڕیپڵ بکەیت، یادەوەری بۆ ئەو کەسە دەنێرێت.",
            parse_mode="HTML"
        )
        return

    time_str = args[0].lower()
    _units   = {"s": 1, "m": 60, "h": 3600, "d": 86400}
    _m       = re.match(r'^(\d+)([smhd])$', time_str)
    if not _m:
        await update.message.reply_text(
            _TGX + " فۆرماتی کات هەڵەیە!\nنموونە: <code>30m</code>, <code>2h</code>, <code>1d</code>",
            parse_mode="HTML"
        )
        return

    amount  = int(_m.group(1))
    unit    = _m.group(2)
    seconds = amount * _units[unit]
    if seconds < 10 or seconds > 7 * 86400:
        await update.message.reply_text(_TGX + " کات دەبێت لە نێوان ١٠ چرکە و ٧ ڕۆژدا بێت!", parse_mode="HTML"); return


    message_text = " ".join(args[1:]).strip() if len(args) > 1 else f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> یادەوەرییەکەت!"
    fire_at      = (datetime.datetime.now() + datetime.timedelta(seconds=seconds)).isoformat()

    # ئایا ڕیپڵ بووە — بۆ کەسی تر؟
    target_uid  = uid
    target_name = _html_escape(user.first_name)
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        t = update.message.reply_to_message.from_user
        target_uid  = str(t.id)
        target_name = _html_escape(t.first_name)

    if target_uid not in SMART_REMINDERS:
        SMART_REMINDERS[target_uid] = []
    if len(SMART_REMINDERS[target_uid]) >= 10:
        await update.message.reply_text(_TGX + " ئەو کەسە ١٠ یادەوەریی هەیە! زیاتر نادرێت.", parse_mode="HTML"); return


    SMART_REMINDERS[target_uid].append({
        "message":    message_text,
        "fire_at":    fire_at,
        "chat_id":    update.effective_chat.id,
        "from_uid":   uid,
        "from_name":  user.first_name,
    })
    _save_smart_reminders()

    unit_names = {"s": "چرکە", "m": "خولەک", "h": "کاتژمێر", "d": "ڕۆژ"}
    if target_uid == uid:
        msg = f"{_TCK} یادەوەری دانرا!\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> {message_text}\n<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> {amount} {unit_names[unit]} دواتر"
    else:
        msg = f"{_TCK} یادەوەری بۆ <b>{target_name}</b> دانرا!\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> {message_text}\n<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> {amount} {unit_names[unit]} دواتر"
    await update.message.reply_text(msg, parse_mode="HTML")

async def sremind_callback(update: Update, context: CallbackContext):
    """مێنیوی /sremind callbacks"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    data = query.data  # sremind:...
    uid  = str(query.from_user.id)

    if data == "sremind:howto":
        await _safe_edit(query, "<tg-emoji emoji-id=\"5472411062412254753\">📖</tg-emoji> <b>چۆنیەتی بەکارهێنانی /sremind</b>\n\n"
            "<code>/sremind 30m نامەکە</code> — بۆ خۆت\n"
            "<code>/sremind 1h نامەکە</code> — ئەگەر پەیامێک ڕیپڵ کەیت، بۆ ئەو کەسە\n\n"
            "<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> یەکەکان:\n"
            "• <code>s</code> = چرکە\n• <code>m</code> = خولەک\n"
            "• <code>h</code> = کاتژمێر\n• <code>d</code> = ڕۆژ", reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:sremind", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]))
    elif data == "sremind:list":
        rems = SMART_REMINDERS.get(uid, [])
        if not rems:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ یادەوەرییەکت نییە!\n<code>/sremind 30m نامەکە</code>", reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:sremind", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]))
            return
        now  = datetime.datetime.now()
        text = f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادەوەرییەکانت:</b>\n\n"
        for i, r in enumerate(rems, 1):
            try:
                fire = datetime.datetime.fromisoformat(r["fire_at"])
                diff = int((fire - now).total_seconds() // 60)
                rem_str = f"{diff}خ" if diff < 60 else f"{diff//60}ک"
                text += f"{i}. {r['message']} — <tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji>{rem_str}\n"
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
        await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:sremind", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]))

async def check_smart_reminders(context: CallbackContext):
    """job — هەر ٣٠ چرکەیەک چەک دەکات"""
    now     = datetime.datetime.now()
    changed = False

    for uid, rems in list(SMART_REMINDERS.items()):
        remaining = []
        for r in rems:
            try:
                fire = datetime.datetime.fromisoformat(r["fire_at"])
                if fire <= now:
                    try:
                        chat_id = r.get("chat_id", int(uid))
                        from_name = r.get("from_name", "")
                        header = f"<tg-emoji emoji-id=\"5454113432284446338\">📩</tg-emoji> یادەوەری لە <b>{from_name}</b>:\n\n" if from_name and r.get("from_uid") != uid else f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادەوەری!</b>\n\n"
                        await context.bot.send_message(
                            chat_id=chat_id,
                            text=f"{header}<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> {r['message']}",
                            parse_mode="HTML"
                        )
                    except Exception as _e:
                        logger.warning(f"sremind send error uid={uid}: {_e}")
                    changed = True
                else:
                    remaining.append(r)
            except Exception:
                remaining.append(r)

        if len(remaining) != len(rems):
            SMART_REMINDERS[uid] = remaining
            changed = True

    if changed:
        _save_smart_reminders()

