async def debate_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":", 3)
    action = parts[1] if len(parts) > 1 else ""
    debate_id = parts[2] if len(parts) > 2 else ""
    uid = str(query.from_user.id)
    uname = _html_escape(str(query.from_user.first_name or uid))

    # ── دەستپێکردنی دیبەیتی هەڕەمەکی ──
    if action == "random_start":
        topic = random.choice(DEBATE_TOPICS)
        new_debate_id = f"d_{int(time.time())}"
        chat_id = query.message.chat.id
        DEBATE_DATA[new_debate_id] = {
            "topic": topic,
            "chat_id": chat_id,
            "votes_yes": [],
            "votes_no": [],
            "opinions": [],
            "created_at": datetime.datetime.now().isoformat(),
            "active": True,
            "creator": uid
        }
        _save_debate()
        keyboard = [
            [_ebtn(f"هاوڕام (0)", f"debate:yes:{new_debate_id}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
             _ebtn(f"هاوڕا نیم (0)", f"debate:no:{new_debate_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})],
            [_ebtn("ڕای خۆت بنووسە", f"debate:opinion:{new_debate_id}", emoji_id="5303138782004924588", api_kwargs={"style": "primary"})],
            [_ebtn("ئەنجامەکان", f"debate:results:{new_debate_id}", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
             _ebtn("باشترین ڕاکان", f"debate:best:{new_debate_id}", emoji_id="5462927083132970373", api_kwargs={"style": "primary"})],
            [_ebtn("کۆتاییهێنان", f"debate:close:{new_debate_id}", emoji_id="5240241223632954241", api_kwargs={"style": "primary"})],
        ]
        await answered()
        await _safe_edit(query,
            f"<tg-emoji emoji-id=\"5438175921045545379\">🎙</tg-emoji> گفتوگۆی کراوە\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> بابەت: {topic}\n\n<tg-emoji emoji-id=\"5255934767844567828\">🗳</tg-emoji> دەنگ بدە یان ڕای خۆت دەرببڕە!\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
        return

    # ── دەستپێکردنی دیبەیتی تایبەت ──
    elif action == "custom_start":
        DEBATE_OPINION_WAITING[query.from_user.id] = "CUSTOM_TOPIC"
        await answered()
        await _safe_edit(query,
            "<tg-emoji emoji-id=\"5397686620101055828\">✏️</tg-emoji> <b>دەستپێکردنی گفتوگۆ</b>\n\n"
            "<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بابەتێک بنووسە بۆ گفتوگۆکردن:\n\n"
            "<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> <i>نموونە: ئایا زیرەکی دەستکرد مەترسییە بۆ سەر مرۆڤ؟</i>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[_ebtn("هەڵوەشاندنەوە", "menu:debate", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]]))
        return

    elif action == "yes" or action == "no":
        debate = DEBATE_DATA.get(debate_id)
        if not debate or not debate.get("active"):
            await answered("❌" + " ئەم گفتوگۆیە داخراوە!", show_alert=True)
            return
        yes_list = debate.setdefault("votes_yes", [])
        no_list  = debate.setdefault("votes_no",  [])
        # Toggle vote
        if action == "yes":
            if uid in yes_list:
                yes_list.remove(uid)
            else:
                yes_list.append(uid)
                if uid in no_list: no_list.remove(uid)
        else:
            if uid in no_list:
                no_list.remove(uid)
            else:
                no_list.append(uid)
                if uid in yes_list: yes_list.remove(uid)
        _save_debate()
        kb = InlineKeyboardMarkup([
            [_ebtn(f"هاوڕام ({len(yes_list)})", f"debate:yes:{debate_id}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
             _ebtn(f"هاوڕا نیم ({len(no_list)})", f"debate:no:{debate_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})],
            [_ebtn("بیروڕاکەت بنووسە", f"debate:opinion:{debate_id}", emoji_id="5303138782004924588", api_kwargs={"style": "primary"})],
            [_ebtn("ئەنجامەکان", f"debate:results:{debate_id}", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
             _ebtn("باشترین بیروڕا", f"debate:best:{debate_id}", emoji_id="5462927083132970373", api_kwargs={"style": "primary"})],
            [_ebtn("داخستن", f"debate:close:{debate_id}", emoji_id="5231302159739395058", api_kwargs={"style": "primary"})],
        ])
        try:
            await query.edit_message_reply_markup(reply_markup=kb)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        await answered("<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> دەنگت تۆمارکرا!" if (uid in yes_list or uid in no_list) else "↩️ دەنگەکەت لادرا")

    elif action == "opinion":
        debate = DEBATE_DATA.get(debate_id)
        if not debate or not debate.get("active"):
            await answered("❌" + " ئەم گفتوگۆیە داخراوە!", show_alert=True)
            return
        DEBATE_OPINION_WAITING[int(uid)] = debate_id
        await answered()
        try:
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> بیروڕاکەت لەسەر بابەتەکە بنووسە:\n\n"
                f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> {debate['topic']}\n\n"
                f"پاشەکەوت دەکرێت — تکایە تێکستەکەت بنووسە:", reply_markup=InlineKeyboardMarkup([[
                    _ebtn("هەڵوەشاندنەوە", f"debate:cancel:{debate_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})
                ]]))
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    elif action == "cancel":
        DEBATE_OPINION_WAITING.pop(int(uid), None)
        await answered()
        debate = DEBATE_DATA.get(debate_id)
        if debate:
            yes_list = debate.get("votes_yes", [])
            no_list  = debate.get("votes_no",  [])
            kb = InlineKeyboardMarkup([
                [_ebtn(f"هاوڕام ({len(yes_list)})", f"debate:yes:{debate_id}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
                 _ebtn(f"هاوڕا نیم ({len(no_list)})", f"debate:no:{debate_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})],
                [_ebtn("بیروڕاکەت بنووسە", f"debate:opinion:{debate_id}", emoji_id="5303138782004924588", api_kwargs={"style": "primary"})],
                [_ebtn("ئەنجامەکان", f"debate:results:{debate_id}", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
                 _ebtn("باشترین بیروڕا", f"debate:best:{debate_id}", emoji_id="5462927083132970373", api_kwargs={"style": "primary"})],
                [_ebtn("داخستن", f"debate:close:{debate_id}", emoji_id="5231302159739395058", api_kwargs={"style": "primary"})],
            ])
            try:
                await _safe_edit(query, f"<tg-emoji emoji-id=\"5438175921045545379\">🎙</tg-emoji> گفتوگۆی کراوە\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> بابەت: {debate['topic']}\n\n<tg-emoji emoji-id=\"5255934767844567828\">🗳</tg-emoji> دەنگ بدە یان ڕای خۆت دەرببڕە!\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>", reply_markup=kb)
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

    elif action == "results":
        debate = DEBATE_DATA.get(debate_id)
        if not debate:
            await answered("❌" + " نەدۆزرایەوە!", show_alert=True)
            return
        yes_c = len(debate.get("votes_yes", []))
        no_c  = len(debate.get("votes_no",  []))
        total = yes_c + no_c
        ops   = len(debate.get("opinions", []))
        pct_y = round(yes_c / total * 100) if total else 0
        pct_n = 100 - pct_y if total else 0
        bar_y = "<tg-emoji emoji-id=\"5377467322820763002\">🟩</tg-emoji>" * (pct_y // 10) + f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>" * (10 - pct_y // 10)
        bar_n = "<tg-emoji emoji-id=\"5429155592075778686\">🟥</tg-emoji>" * (pct_n // 10) + f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>" * (10 - pct_n // 10)
        text = (
            f"{_TCH} ئەنجامی گفتوگۆ\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> {debate['topic']}\n\n"
            f"{_TCK} هاوڕا: {yes_c} ({pct_y}%)\n{bar_y}\n\n"
            f"{_TGX} نەیار: {no_c} ({pct_n}%)\n{bar_n}\n\n"
            f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> بیروڕاکان: {ops}\n"
            f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> کۆی دەنگدەران: {total}"
        )
        try:
            await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup([[
                    _ebtn("گەڕانەوە", f"debate:back:{debate_id}", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})
                ]]))
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

    elif action == "best":
        debate = DEBATE_DATA.get(debate_id)
        if not debate:
            await answered("❌" + " نەدۆزرایەوە!", show_alert=True)
            return
        opinions = debate.get("opinions", [])
        if not opinions:
            await answered("هێشتا هیچ بیروڕایەک نییە!", show_alert=True)
            return
        top = sorted(opinions, key=lambda x: x.get("likes", 0), reverse=True)[:5]
        text = f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> باشترین بیروڕاکان\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> {debate['topic']}\n\n"
        for i, op in enumerate(top, 1):
            side_e = f"{_TCK}" if op.get("side") == "yes" else (_TGX if op.get("side") == "no" else "<tg-emoji emoji-id=\"5429482752619615220\">⚪</tg-emoji>")
            text += f"{i}. {side_e} <b>{op.get('name','?')}</b>\n<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> {op.get('text','')[:150]}\n<tg-emoji emoji-id=\"5438383058728296995\">👍</tg-emoji> {op.get('likes',0)} لایک\n\n"
        try:
            await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup([[
                    _ebtn("لایک بدە", f"debate:like:{debate_id}:0", emoji_id="5438383058728296995", api_kwargs={"style": "success"}),
                    _ebtn("گەڕانەوە", f"debate:back:{debate_id}", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})
                ]]))
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    elif action == "like":
        op_idx = int(parts[3]) if len(parts) > 3 else 0
        debate = DEBATE_DATA.get(debate_id)
        if debate and "opinions" in debate and op_idx < len(debate["opinions"]):
            op = debate["opinions"][op_idx]
            liked_by = op.setdefault("liked_by", [])
            if uid in liked_by:
                await answered("پێشتر لایکت دابووە!", show_alert=True)
            else:
                liked_by.append(uid)
                op["likes"] = op.get("likes", 0) + 1
                _save_debate()
                await answered("<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ لایک دراو!")
        else:
            await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> نەدۆزرایەوە!")

    elif action == "close":
        debate = DEBATE_DATA.get(debate_id)
        if not debate:
            await answered("❌" + " نەدۆزرایەوە!", show_alert=True)
            return
        if debate.get("creator") != uid and int(uid) != OWNER_ID:
            await answered("❌" + " تەنها دامەزرێنەر یان ئادمین دەتوانێت داببخاتەوە!", show_alert=True)
            return
        debate["active"] = False
        _save_debate()
        await answered()
        yes_c = len(debate.get("votes_yes", []))
        no_c  = len(debate.get("votes_no",  []))
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> گفتوگۆکە داخرا\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> {debate['topic']}\n\n"
            f"{_TCK} هاوڕا: {yes_c} | {_TGX} نەیار: {no_c}\n\n"
            f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> کۆی بیروڕاکان: {len(debate.get('opinions', []))}")

    elif action == "back":
        debate = DEBATE_DATA.get(debate_id)
        if not debate:
            await answered()
            return
        await answered()
        yes_list = debate.get("votes_yes", [])
        no_list  = debate.get("votes_no",  [])
        kb = InlineKeyboardMarkup([
            [_ebtn(f"هاوڕام ({len(yes_list)})", f"debate:yes:{debate_id}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
             _ebtn(f"هاوڕا نیم ({len(no_list)})", f"debate:no:{debate_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})],
            [_ebtn("بیروڕاکەت بنووسە", f"debate:opinion:{debate_id}", emoji_id="5303138782004924588", api_kwargs={"style": "primary"})],
            [_ebtn("ئەنجامەکان", f"debate:results:{debate_id}", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
             _ebtn("باشترین بیروڕا", f"debate:best:{debate_id}", emoji_id="5462927083132970373", api_kwargs={"style": "primary"})],
            [_ebtn("داخستن", f"debate:close:{debate_id}", emoji_id="5231302159739395058", api_kwargs={"style": "primary"})],
        ])
        try:
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5438175921045545379\">🎙</tg-emoji> گفتوگۆی کراوە\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> بابەت: {debate['topic']}\n\n<tg-emoji emoji-id=\"5255934767844567828\">🗳</tg-emoji> دەنگ بدە یان ڕای خۆت دەرببڕە!\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>", reply_markup=kb)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

# ── Memory ──
MEMORY_FILE = "memory_data.json"
MEMORY_DATA: dict = load_data(MEMORY_FILE, {})

async def memory_cmd(update: Update, context: CallbackContext):
    uid = str(update.effective_user.id)
    args = context.args
    if args:
        # /memory ناوم ئاکۆیە — ڕاستەوخۆ پاشەکەوت بکە
        text = " ".join(args)
        user_mem = MEMORY_DATA.setdefault(uid, {"facts": [], "prefs": {}})
        facts = user_mem.setdefault("facts", [])
        facts.append(text[:200])
        if len(facts) > 50:
            facts.pop(0)
        _save_memory()
        await update.message.reply_text(f"{_TCK} پاشەکەوت کرا: <i>{text[:100]}</i>", parse_mode="HTML")
        return
    user_mem = MEMORY_DATA.get(uid, {"facts": [], "prefs": {}})
    facts = user_mem.get("facts", [])
    keyboard = InlineKeyboardMarkup([
        [_ebtn("پاشەکەوت", "mem:save", emoji_id="5462956611033117422", api_kwargs={"style": "success"}),
         _ebtn("زانیارییەکان", "mem:view", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})],
        [_ebtn("حەزەکان", "mem:prefs", emoji_id="5377652766623701383", api_kwargs={"style": "success"}),
         _ebtn("هەموو", "mem:all", emoji_id="5264874622012126052", api_kwargs={"style": "primary"})],
        [_ebtn("سڕینەوە", "mem:delete", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})],
    ])
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>سیستەمی بیرکەوتنەوە</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"کۆی زانیارییەکانت: {len(facts)}\n\n"
        f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> <i>نموونە: /memory ناوم ئاکۆیە</i>",
        parse_mode="HTML",
        reply_markup=keyboard
    )

async def memory_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    action = query.data.split(":", 1)[1] if ":" in query.data else ""
    uid = str(query.from_user.id)
    uname = _html_escape(str(query.from_user.first_name or uid))

    user_mem = MEMORY_DATA.setdefault(uid, {"facts": [], "prefs": {}})

    back_btn = [[_ebtn("گەڕانەوە", "menu:memory", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]

    if action == "view":
        facts = user_mem.get("facts", [])
        if not facts:
            text = "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> هێشتا هیچ زانیارییەکت پاشەکەوت نەکراوە.\n\n/memory بنووسە یان دووگمەی پاشەکەوتکردن بەکاربهێنە."
        else:
            text = f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>زانیارییەکانت</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            for i, f in enumerate(facts[-10:], 1):
                text += f"{i}. {f}\n"
        await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup(back_btn))

    elif action == "all":
        facts = user_mem.get("facts", [])
        prefs = user_mem.get("prefs", {})
        text = f"<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>هەموو بیرەوەرییەکانت — {uname}</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        if facts:
            text += "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>زانیاری:</b>\n"
            for i, f in enumerate(facts, 1):
                text += f"  {i}. {f}\n"
        else:
            text += "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> هیچ زانیارییەک نییە.\n"
        if prefs:
            text += "\n<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ <b>حەزەکانت:</b>\n"
            for k, v in list(prefs.items())[:10]:
                text += f"  • {k}: {v}\n"
        await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup(back_btn))

    elif action == "prefs":
        prefs = user_mem.get("prefs", {})
        if not prefs:
            text = "<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ هێشتا هیچ حەزێکت تۆمار نەکراوە.\n\nنموونە: /memory حەزم لە فوتبۆل"
        else:
            text = "<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ <b>حەزەکانت:</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            for k, v in list(prefs.items())[:15]:
                text += f"• {k}: {v}\n"
        await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup(back_btn))

    elif action == "save":
        context.user_data["memory_waiting"] = True
        await _safe_edit(query, "<tg-emoji emoji-id=\"5462956611033117422\">💾</tg-emoji> <b>پاشەکەوتکردنی زانیاری</b>\n\nزانیارییەکەت بنووسە:\n\nنموونەکان:\n• ناوم ئاکۆیە\n• خوێندنگام لە هەولێرە\n• حەزم لە میوزیک", reply_markup=InlineKeyboardMarkup([[_ebtn("هەڵوەشاندنەوە", "mem:cancel", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]]))

    elif action == "cancel":
        context.user_data.pop("memory_waiting", None)
        await _safe_edit(query, "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>سیستەمی بیرکەوتنەوە</b>\n\nبۆتەکە هەندێک لە زانیارییەکانت لەبیر دەگرێت.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("پاشەکەوت", "mem:save", emoji_id="5462956611033117422", api_kwargs={"style": "success"}),
                 _ebtn("زانیارییەکان", "mem:view", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})],
                [_ebtn("حەزەکان", "mem:prefs", emoji_id="5377652766623701383", api_kwargs={"style": "success"}),
                 _ebtn("هەموو", "mem:all", emoji_id="5264874622012126052", api_kwargs={"style": "primary"})],
                [_ebtn("سڕینەوە", "mem:delete", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})],
                [_ebtn("گەڕانەوە", "menu:back", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})],
            ]))

    elif action == "delete":
        user_mem["facts"] = []
        user_mem["prefs"] = {}
        MEMORY_DATA[uid] = user_mem
        _save_memory()
        await answered("✅ هەموو بیرەوەرییەکانت سڕدرانەوە!", show_alert=True)
        await _safe_edit(query, "<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> بیرەوەرییەکانت سڕدرانەوە.\n\nدەتوانیت دووبارە زانیارییەکانت زیادبکەیت.", reply_markup=InlineKeyboardMarkup(back_btn))

