async def mindmap_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    parts = query.data.split(":", 2)
    action = parts[1] if len(parts) > 1 else ""
    mm_id  = parts[2] if len(parts) > 2 else ""
    uid = str(query.from_user.id)

    back_btn = [[_ebtn("گەڕانەوە", "menu:mindmap", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]

    if action == "new":
        context.user_data["mindmap_waiting"] = "title"
        await _safe_edit(query, "<tg-emoji emoji-id=\"5230940806960919610\">➕</tg-emoji> <b>نەخشەی هزری نوێ</b>\n\nناوی نەخشەکە بنووسە:\n(نموونە: پڕۆژەی کار، ئامانجەکانم، ...)", reply_markup=InlineKeyboardMarkup([[_ebtn("هەڵوەشاندنەوە", "mm:cancel", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]]))

    elif action == "list":
        user_maps = {k: v for k, v in MINDMAP_DATA.items() if v.get("owner") == uid}
        if not user_maps:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> هێشتا هیچ نەخشەیەکت نییە.\n\n<tg-emoji emoji-id=\"5230940806960919610\">➕</tg-emoji> دووگمەی دروستکردن بەکاربهێنە.", reply_markup=InlineKeyboardMarkup([
                    [_ebtn("نەخشەی نوێ", "mm:new", emoji_id="5230940806960919610", api_kwargs={"style": "primary"})],
                    *back_btn
                ]))
            return
        btns = [[_ebtn(v.get('title', 'بێ ناو'), f"mm:view:{k}", emoji_id="5231263977480144467", api_kwargs={"style": "primary"})]
                for k, v in list(user_maps.items())[:10]]
        btns.extend(back_btn)
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>نەخشەکانت ({len(user_maps)})</b>\n\nیەکێک هەڵبژێرە:", reply_markup=InlineKeyboardMarkup(btns))

    elif action == "view":
        mm = MINDMAP_DATA.get(mm_id)
        if not mm:
            await answered("❌" + " نەدۆزرایەوە!", show_alert=True)
            return
        nodes = mm.get("nodes", [])
        text = f"<tg-emoji emoji-id=\"5231263977480144467\">🗺</tg-emoji> <b>{mm.get('title','نەخشە')}</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        if nodes:
            text += "\n".join(f"  {'  ' * n.get('level',0)}{'├─' if n.get('level',0) else '◉'} {n.get('text','—')}" for n in nodes[:30])
        else:
            text += "هێشتا هیچ گرێبەستێک زیادنەکراوە."
        await _safe_edit(query, text, reply_markup=InlineKeyboardMarkup([
                [_ebtn("گرێبەستی نوێ", f"mm:addnode:{mm_id}", emoji_id="5230940806960919610", api_kwargs={"style": "primary"}),
                 _ebtn("سڕینەوە", f"mm:del:{mm_id}", emoji_id="5379723202853383390", api_kwargs={"style": "danger"})],
                [_ebtn("گەڕانەوە", "mm:list", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]
            ]))

    elif action == "addnode":
        context.user_data["mindmap_waiting"] = f"node:{mm_id}"
        await _safe_edit(query, "<tg-emoji emoji-id=\"5230940806960919610\">➕</tg-emoji> گرێبەستی نوێ بنووسە:\n(نموونە: کار → پڕۆژەی وێبسایت)", reply_markup=InlineKeyboardMarkup([[_ebtn("هەڵوەشاندنەوە", f"mm:view:{mm_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]]))

    elif action == "del":
        if mm_id in MINDMAP_DATA and MINDMAP_DATA[mm_id].get("owner") == uid:
            del MINDMAP_DATA[mm_id]
            _save_mindmap()
            await answered("✅ نەخشەکە سڕدرایەوە!", show_alert=True)
        await _safe_edit(query, "<tg-emoji emoji-id=\"5231263977480144467\">🗺</tg-emoji> <b>نەخشەی هزر</b>\n\nبیرۆکەکانت بە شێوەی ڕێکخراو بنووسە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("نەخشەی نوێ", "mm:new", emoji_id="5230940806960919610", api_kwargs={"style": "primary"})],
                [_ebtn("نەخشەکان", "mm:list", api_kwargs={"icon_custom_emoji_id": "5231263977480144467", "style": "primary"})],
                *back_btn
            ]))

    elif action == "cancel":
        context.user_data.pop("mindmap_waiting", None)
        await _safe_edit(query, "<tg-emoji emoji-id=\"5231263977480144467\">🗺</tg-emoji> <b>نەخشەی هزر</b>\n\nبیرۆکەکانت بە شێوەی ڕێکخراو بنووسە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("نەخشەی نوێ", "mm:new", emoji_id="5230940806960919610", api_kwargs={"style": "primary"})],
                [_ebtn("نەخشەکان", "mm:list", api_kwargs={"icon_custom_emoji_id": "5231263977480144467", "style": "primary"})],
                *back_btn
            ]))

async def handle_memory_input(update, context) -> bool:
    """بەرێوەبردنی وەڵامی بیرەوەری"""
    if not context.user_data.get("memory_waiting"):
        return False
    context.user_data.pop("memory_waiting", None)
    uid = str(update.effective_user.id)
    text = update.message.text.strip()
    if not text or len(text) < 2:
        await update.message.reply_text(_TGX + " تکایە تێکستێکی گونجاو بنووسە.", parse_mode="HTML")

        return True
    user_mem = MEMORY_DATA.setdefault(uid, {"facts": [], "prefs": {}})
    facts = user_mem.setdefault("facts", [])
    facts.append(text[:200])
    if len(facts) > 50:
        facts.pop(0)
    MEMORY_DATA[uid] = user_mem
    _save_memory()
    await update.message.reply_text(
        f"{_TCK} پاشەکەوت کرا:\n<i>{text[:100]}</i>\n\n"
        f"کۆی زانیارییەکانت: {len(facts)}",
        parse_mode="HTML"
    )
    return True

async def handle_mindmap_input(update, context) -> bool:
    """بەرێوەبردنی وەڵامی مایندمەپ"""
    waiting = context.user_data.get("mindmap_waiting")
    if not waiting:
        return False
    context.user_data.pop("mindmap_waiting", None)
    uid = str(update.effective_user.id)
    text = update.message.text.strip()

    if waiting == "title":
        if len(text) < 2:
            await update.message.reply_text(_TGX + " ناوەکەت زۆر کورتە.", parse_mode="HTML")

            return True
        mm_id = f"mm_{uid}_{int(time.time())}"
        MINDMAP_DATA[mm_id] = {
            "title": text[:100],
            "owner": uid,
            "nodes": [],
            "created": datetime.datetime.now().isoformat()
        }
        _save_mindmap()
        await update.message.reply_text(
            f"{_TCK} نەخشەی <b>{text}</b> دروستکرا!\n\nئێستا دەتوانیت گرێبەست زیادبکەیت.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                _ebtn("گرێبەستی نوێ", f"mm:addnode:{mm_id}", emoji_id="5230940806960919610", api_kwargs={"style": "primary"}),
                _ebtn("نەخشەکان", "mm:list", api_kwargs={"icon_custom_emoji_id": "5231263977480144467", "style": "primary"})
            ]])
        )
    elif waiting.startswith("node:"):
        mm_id = waiting.split(":", 1)[1]
        mm = MINDMAP_DATA.get(mm_id)
        if not mm or mm.get("owner") != uid:
            await update.message.reply_text(_TGX + " نەخشەکە نەدۆزرایەوە.", parse_mode="HTML")

            return True
        level = 1 if "→" in text else 0
        node_text = text.replace("→", "").strip()
        mm.setdefault("nodes", []).append({"text": node_text[:100], "level": level})
        if len(mm["nodes"]) > 50:
            mm["nodes"].pop(0)
        _save_mindmap()
        await update.message.reply_text(
            f"{_TCK} زیادکرا: <i>{node_text[:50]}</i>\n\nدەتوانیت زیاتر زیادبکەیت.",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                _ebtn("گرێبەستی تر", f"mm:addnode:{mm_id}", emoji_id="5230940806960919610", api_kwargs={"style": "primary"}),
                _ebtn("بینین", f"mm:view:{mm_id}", api_kwargs={"icon_custom_emoji_id": "5379687326991555987", "style": "primary"})
            ]])
        )
    return True

async def mindmap_skip_sub_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()

# ── Banned Words Management (addword/removeword/listwords) ──

async def addword_cmd(update: Update, context: CallbackContext):
    """زیادکردنی وشەی قەدەغەکراو"""
    if not await is_restrict_admin(update, context):
        await update.message.reply_text(_TGX + " تەنیا ئادمین!", parse_mode="HTML"); return

    args = context.args
    if not args:
        await update.message.reply_text("شێواز: /addword [وشە]", parse_mode='HTML'); return
    word = " ".join(args).lower().strip()
    BANNED_WORDS_DATA.setdefault("words", [])
    if word not in BANNED_WORDS_DATA["words"]:
        BANNED_WORDS_DATA["words"].append(word)
        _save_banned_words()
        await update.message.reply_text(f"{_TCK} وشەی <code>{word}</code> زیادکرا.", parse_mode="HTML")
    else:
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئەم وشەیە پێشتر هەیە.", parse_mode="HTML")

async def addword_interactive_cmd(update: Update, context: CallbackContext):
    """زیادکردنی چەند وشە — هەر خەتێک وشەیەکە"""
    if not await is_restrict_admin(update, context):
        await update.message.reply_text(_TGX + " تەنیا ئادمین!", parse_mode="HTML"); return

    args = context.args
    if not args:
        await update.message.reply_text("شێواز: /addwords وشە١ وشە٢ وشە٣", parse_mode='HTML'); return
    BANNED_WORDS_DATA.setdefault("words", [])
    added = []
    for w in args:
        w = w.lower().strip()
        if w and w not in BANNED_WORDS_DATA["words"]:
            BANNED_WORDS_DATA["words"].append(w)
            added.append(w)
    if added:
        _save_banned_words()
        await update.message.reply_text(f"{_TCK} {len(added)} وشە زیادکران:\n" + ", ".join(f"<code>{w}</code>" for w in added), parse_mode="HTML")
    else:
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> هیچ وشەیەکی نوێ نەبوو.", parse_mode="HTML")

async def removeword_cmd(update: Update, context: CallbackContext):
    """سڕینەوەی وشەی قەدەغەکراو"""
    if not await is_restrict_admin(update, context):
        await update.message.reply_text(_TGX + " تەنیا ئادمین!", parse_mode="HTML"); return

    args = context.args
    if not args:
        await update.message.reply_text("شێواز: /removeword [وشە]", parse_mode='HTML'); return
    word = " ".join(args).lower().strip()
    words = BANNED_WORDS_DATA.get("words", [])
    if word in words:
        words.remove(word)
        _save_banned_words()
        await update.message.reply_text(f"{_TCK} وشەی <code>{word}</code> سڕایەوە.", parse_mode="HTML")
    else:
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئەم وشەیە نەدۆزرایەوە.", parse_mode="HTML")

async def listwords_cmd(update: Update, context: CallbackContext):
    """لیستی وشە قەدەغەکراوەکان"""
    if not await is_restrict_admin(update, context):
        await update.message.reply_text(_TGX + " تەنیا ئادمین!", parse_mode="HTML"); return

    words = BANNED_WORDS_DATA.get("words", [])
    if not words:
        await update.message.reply_text("<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ وشەیەک قەدەغە نەکراوە.", parse_mode='HTML'); return
    text = "<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> <b>وشە قەدەغەکراوەکان:</b>\n\n"
    for i, w in enumerate(words, 1):
        text += f"{i}. <code>{w}</code>\n"
    await update.message.reply_text(text, parse_mode="HTML")

