async def bwaction_callback(update: Update, context: CallbackContext):
    """کردارەکانی banned words admin panel"""
    try:
        query = update.callback_query
        answered = _make_answerer(query)
        await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
        action = query.data.replace("bwaction:", "")
        BANNED_WORDS_DATA["action"] = action
        _save_banned_words()
        labels = {
        "delete": "سڕینەوەی پەیام",
        "delete_warn": "ئاگادارکردنەوە",
        "delete_mute_temp": "میوتی کاتی",
        "delete_mute": "میوت بۆ هەمیشە",
        "delete_ban": "بانکردن",
        }
        await _safe_edit(query, f"{_TCK} کردار دانرا: <b>{labels.get(action, action)}</b>")
    except Exception as e:
        logger.error(f"Error in bwaction_callback: {e}")
        try:
            if hasattr(query, "answer"):
                await query.answer()
        except Exception:
            pass

async def bw_delete_callback(update: Update, context: CallbackContext):
    """سڕینەوەی وشەی قەدەغەکراو بە کلیک لەسەر دووگمە"""
    query = update.callback_query
    answered = _make_answerer(query)

    if query.from_user.id != OWNER_ID:
        try:
            await answered("❌" + " تەنها خاوەنی بۆت!", show_alert=True)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
        return

    parts = query.data.split(":")  # bw:del:N  یان  bw:page:N
    if len(parts) < 3:
        return

    action_bw = parts[1]
    param = parts[2]

    words = BANNED_WORDS_DATA.get("words", [])

    if action_bw == "del":
        try:
            idx_del = int(param)
            if 0 <= idx_del < len(words):
                removed = words[idx_del]
                words.pop(idx_del)
                BANNED_WORDS_DATA["words"] = words
                _save_banned_words()
                # نوێکردنەوەی نیشاندان
                if not words:
                    txt = "" + _TCK + " وشەی <b>{}</b> سڕایەوە.\n\n<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> لیست ئێستا بەتاڵە.".format(removed)
                    kb = [[_ebtn("گەڕانەوە", "menu:admin", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]]
                else:
                    txt = (
                        f"{_TCK} وشەی <b>{removed}</b> سڕایەوە.\n"
                        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                        f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> کۆی ماوەکان: <b>{len(words)}</b> دانە\n\n"
                        f"👆 وشەی تری دەتەوێت بیسڕیتەوە کلیک بکە:"
                    )
                    show_words = words[:15]
                    word_btns = []
                    for ri in range(0, len(show_words), 2):
                        row = [_ebtn(f"{show_words[ri]}", f"bw:del:{ri}", emoji_id="5379723202853383390", api_kwargs={"style": "primary"})]
                        if ri + 1 < len(show_words):
                            row.append(_ebtn(f"{show_words[ri+1]}", f"bw:del:{ri+1}", emoji_id="5379723202853383390", api_kwargs={"style": "primary"}))
                        word_btns.append(row)
                    if len(words) > 15:
                        word_btns.append([_ebtn(f"زیاتر ({len(words)-15} دانەی تر)", "bw:page:1", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"})])
                    word_btns.append([_ebtn("گەڕانەوە", "menu:admin", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
                    kb = word_btns
                try:
                    await _safe_edit(query, txt, reply_markup=InlineKeyboardMarkup(kb))
                except Exception as _e:
                    logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
            else:
                await answered("❌" + " وشەکە نەدۆزرایەوە!", show_alert=True)
        except (ValueError, IndexError):
            await answered("❌" + " هەڵە!", show_alert=True)

    elif action_bw == "page":
        try:
            page = int(param)
            per_page = 15
            start = page * per_page
            end = start + per_page
            show_words = words[start:end]
            if not show_words:
                await answered("❌" + " پەڕەی تر نییە!", show_alert=True)
                return
            txt = (
                f"<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> لیستی وشەی قەدەغەکراو ({len(words)} دانە) — پەڕە {page+1}\n\n"
                f"👆 وشەیەک کلیک بکە بۆ سڕینەوە:"
            )
            word_btns = []
            for ri in range(0, len(show_words), 2):
                real_idx = start + ri
                row = [_ebtn(f"{show_words[ri]}", f"bw:del:{real_idx}", emoji_id="5379723202853383390", api_kwargs={"style": "primary"})]
                if ri + 1 < len(show_words):
                    real_idx2 = start + ri + 1
                    row.append(_ebtn(f"{show_words[ri+1]}", f"bw:del:{real_idx2}", emoji_id="5379723202853383390", api_kwargs={"style": "primary"}))
                word_btns.append(row)
            nav = []
            if page > 0:
                nav.append(_ebtn("پاشەکەوت", f"bw:page:{page-1}", api_kwargs={"style": "primary", "icon_custom_emoji_id": "5341583133055669788"}))
            if end < len(words):
                nav.append(_ebtn("پێشەوە", f"bw:page:{page+1}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"}))
            if nav:
                word_btns.append(nav)
            word_btns.append([_ebtn("گەڕانەوە", "menu:admin", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
            try:
                await _safe_edit(query, txt, reply_markup=InlineKeyboardMarkup(word_btns))
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        except (ValueError, IndexError):
            await answered("❌" + " هەڵە!", show_alert=True)

