# /leaderboard_coins ─── ڕیزبەندی کۆین ───

async def leaderboard_coins_cmd(update, context):
    """<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> ڕیزبەندی دەوڵەمەندی — شێوازی پڕۆفیشناڵ"""
    user_id = update.effective_user.id

    all_users = []
    for uid_str, udata in list(USERS.items()):
        wallet = udata.get("coins", 0)
        b = BANK_DATA.get(uid_str, {})
        bank_t = b.get("balance", 0) + b.get("savings", 0)
        loan = b.get("loan", 0)
        total = wallet + bank_t - loan
        if total > 0:
            all_users.append((uid_str, total, wallet, bank_t))

    all_users.sort(key=lambda x: x[1], reverse=True)
    top = all_users[:10]

    medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>","④","⑤","⑥","⑦","⑧","⑨","⑩"]
    
    my_rank = None
    for i, (uid_str, total, wallet, bank_t) in enumerate(all_users[:50]):
        if uid_str == str(user_id):
            my_rank = i + 1
            break

    max_total = top[0][1] if top else 1

    lines = []
    lines.append("╔══════════════╗")
    lines.append(f"║  {_TDM} <b>باشترین دەوڵەمەندان</b>  ║")
    lines.append("╚══════════════╝")
    lines.append("")

    for i, (uid_str, total, wallet, bank_t) in enumerate(top):
        udata_lb = USERS.get(uid_str, {})
        _raw_name = udata_lb.get("first_name") or udata_lb.get("name") or "کەس"
        _nick_lb = udata_lb.get("nickname","")
        name = (f"{_raw_name}({_nick_lb})" if _nick_lb and _nick_lb not in _AUTO_NICKNAMES else _raw_name)[:20]
        vip_info = BANK_VIP_PERKS.get(BANK_DATA.get(uid_str, {}).get("vip_level", 0), BANK_VIP_PERKS[0])
        
        filled = int(min(total / max(max_total, 1), 1.0) * 10)
        bar = "█" * filled + "░" * (10 - filled)
        
        marker = f" <tg-emoji emoji-id=\"5255703720078879038\">◀</tg-emoji>" if uid_str == str(user_id) else ""
        lines.append(f"{medals[i]} {vip_info['emoji']} <b>{name}</b>{marker}")
        lines.append(f"   <code>[{bar}]</code> {_TDM} {total:,} {_TCN}")
        lines.append(f"   <tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> {wallet:,} + <tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> {bank_t:,}")
        if i < len(top) - 1:
            lines.append("")

    my_rank_txt = f"\n\n{'─' * 28}\n<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> <b>ئاستی تۆ: #{my_rank}</b>" if my_rank else ""
    my_total = get_user_data(user_id).get("coins", 0) + BANK_DATA.get(str(user_id), {}).get("balance", 0) + BANK_DATA.get(str(user_id), {}).get("savings", 0)

    text = "\n".join(lines) if lines else "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هێشتا هیچ کۆینداریەک نییە."
    if lines:
        text += f"{my_rank_txt}\n{_TMN} کۆی دەوڵەمەندیت: <b>{my_total:,} {_TCN}</b>"

    kb = InlineKeyboardMarkup([[
        _ebtn("نوێکردنەوە", "run:leaderboard_coins", emoji_id="5353025084845994828", api_kwargs={"style": "primary"}),
        _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})
    ]])

    chat = getattr(update, "effective_chat", None)
    msg = getattr(update, "message", None)

    if chat:
        try:
            await chat.send_message(text, parse_mode="HTML", reply_markup=kb)
        except Exception:
            if msg:
                try:
                    await msg.reply_text(text, parse_mode="HTML", reply_markup=kb)
                except Exception as _exc:
                    logger.debug("Suppressed Exception: %s", _exc)
    elif msg:
        await msg.reply_text(text, parse_mode="HTML", reply_markup=kb)


