async def shop_callback(update, context):
    """هەموو دووگمەکانی فرۆشگا"""
    if hasattr(update, "callback_query") and update.callback_query is not None:
        query = update.callback_query
    else:
        query = update
    answered = _make_answerer(query)  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> lazy answerer
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner

    parts   = query.data.split(":")
    action  = parts[1] if len(parts) > 1 else ""
    user_id = query.from_user.id

    async def _refresh(cat: str = "boost"):
        ud    = get_user_data(user_id)
        coins = ud.get("coins", 0)
        b     = _bank_get(user_id)
        total = coins + b["balance"] + b["savings"]
        try:
            await _safe_edit(query, _shop_header_text(coins, total, cat), reply_markup=_shop_build_kb(ud, cat))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    # ١. کردنەوەی فرۆشگا
    if action in ("shop", ""):
        await _refresh("boost")
        return

    # ٢. گۆڕینی category
    if action == "cat":
        cat = parts[2] if len(parts) > 2 else "boost"
        await _refresh(cat)
        return

    # ٣. بانکوچە
    if action == "inventory":
        ud  = get_user_data(user_id)
        inv = ud.get("inventory", [])
        if not inv:
            try: await answered("📦 بانکوچەکەت بەتاڵە!\n/work بکە تا کۆین کسب بکەیت.", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        counts: dict = {}
        for i in inv:
            counts[i["name"]] = counts.get(i["name"], 0) + 1
        lines = [f"  ×{c} {n}" if c > 1 else f"  {n}" for n, c in sorted(counts.items(), key=lambda x: -x[1])]
        try:
            await answered(f"📦 بانکوچەکەت ({len(inv)} شت):\n" + "\n".join(lines), show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    # ٤. کڕین
    if action == "buy" and len(parts) > 2:
        item_id = parts[2]
        item    = SHOP_ITEMS.get(item_id)
        if not item:
            try: await answered("❌" + " شتەکە نەدۆزرایەوە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        ud    = get_user_data(user_id)
        limit = item.get("limit", 0)
        owned = _count_item(ud, item_id)
        if limit > 0 and owned >= limit:
            try: await answered(
                f"<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> {item['name']} — سنووری کڕین تەواو بووە!\n"
                f"زیاتر لە {limit} دانە ناتوانیت بکڕیت.",
                show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        coins = ud.get("coins", 0)
        if coins < item["price"]:
            need = item["price"] - coins
            try: await answered(
                f"<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> کۆینت بەس نییە!\n\n"
                f"<tg-emoji emoji-id=\"5990147899403539264\">💰</tg-emoji> نرخ:   {item.get('price', 0):,} <tg-emoji emoji-id=\"5379827763832203150\">🪙</tg-emoji>\n"
                f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> هەیتە: {coins:,} <tg-emoji emoji-id=\"5379827763832203150\">🪙</tg-emoji>\n"
                f"<tg-emoji emoji-id=\"5393589131106359852\">📉</tg-emoji> کەمی:  {need:,} <tg-emoji emoji-id=\"5379827763832203150\">🪙</tg-emoji>\n\n"
                f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> /work بکە بۆ کسبکردنی زیاتر!",
                show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        add_coins(user_id, -item["price"], "shop", item["name"])
        if "inventory" not in ud:
            ud["inventory"] = []
        ud["inventory"].append({
            "id": item_id, "name": item["name"],
            "type": item["type"],
            "bought_at": datetime.datetime.now().isoformat()
        })
        effect_msg = _apply_item_effect(user_id, ud, item_id)
        save_users(); save_coins()
        new_coins = get_user_data(user_id).get("coins", 0)
        try:
            await answered(
                f"<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> {item['name']} کڕیت!\n\n"
                f"<tg-emoji emoji-id=\"5472411062412254753\">📖</tg-emoji> {item['desc']}\n"
                + (f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> {effect_msg}\n" if effect_msg else "")
                + f"\n<tg-emoji emoji-id=\"5990147899403539264\">💰</tg-emoji> کۆینی ماوەت: {new_coins:,} <tg-emoji emoji-id=\"5379827763832203150\">🪙</tg-emoji>",
                show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        await _refresh(item.get("cat", "boost"))
        return

    # ٥. ماڵی کڕاو
    if action == "owned":
        try: await answered("✅ ئەم شتە پێشتر هەیتە!", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
