async def marry_cmd(update, context):
    """پێشنیازی کابینبوون"""
    user_id = update.effective_user.id
    user_name = _html_escape(update.effective_user.first_name)

    _back_kb = InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]])

    # ئایا خۆی کابینبووە؟
    if str(user_id) in MARRIAGES:
        partner_id = MARRIAGES[str(user_id)]
        try:
            partner = await context.bot.get_chat(partner_id)
            partner_name = _html_escape(partner.first_name)
        except Exception:
            partner_name = f"بەکارهێنەر {partner_id}"
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5393107596553000968\">💍</tg-emoji> تۆ پێشتر کابینبووتەوە بە <b>{partner_name}</b>!\n\n"
            f"بۆ هەڵوەشاندنەوە: /divorce",
            parse_mode="HTML",
            reply_markup=_back_kb
        )
        return

    # پێویستی بە ریپڵای
    if not update.message.reply_to_message:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5393107596553000968\">💍</tg-emoji> <b>هاوسەرگیری</b>\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            "وەڵامی پەیامی کەسێک بدەرەوە و /marry بنووسە!\n\n"
            "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> نموونە: وەڵامی پەیامی کەسێک بدەرەوە، پاشان /marry بنووسە.",
            parse_mode="HTML",
            reply_markup=_back_kb
        )
        return

    target = update.message.reply_to_message.from_user
    target_id = target.id
    target_name = _html_escape(target.first_name)

    if target_id == user_id:
        await update.message.reply_text(_TGX + " ناتوانیت بە خۆت کابینببیتەوە! <tg-emoji emoji-id=\"5316584460592897465\">😄</tg-emoji>", reply_markup=_back_kb, parse_mode="HTML")

        return

    if target.is_bot:
        await update.message.reply_text(_TGX + " ناتوانیت بە بۆتێک کابینببیتەوە!", reply_markup=_back_kb, parse_mode="HTML")

        return

    if str(target_id) in MARRIAGES:
        await update.message.reply_text(f"{_TGX} {target_name} پێشتر کابینبووەتەوە!", reply_markup=_back_kb, parse_mode="HTML")

        return

    # تۆمارکردنی پێشنیاز
    MARRIAGE_PROPOSALS[target_id] = user_id

    keyboard = [
        [
            _ebtn("قبوڵی دەکەم ", f"marry:accept:{user_id}", api_kwargs={"icon_custom_emoji_id": "5393107596553000968", "style": "success"}),
            _ebtn("قبوڵی ناکەم", f"marry:reject:{user_id}", api_kwargs={"icon_custom_emoji_id": "5379600826350214977", "style": "danger"}),
        ]
    ]
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5393107596553000968\">💍</tg-emoji> <b>پێشنیازی هاوسەرگیری!</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5190859184312167965\">💌</tg-emoji> {user_name} دەیەوێت بە {target_name} هاوسەرگیری بکات!\n\n"
        f"<b>{target_name}</b> ئایا قبوڵی دەکەیت؟",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )

async def marry_callback(update, context):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    proposer_id = int(parts[2]) if len(parts) > 2 else 0
    accepter_id = query.from_user.id

    # ── تەنها target دەتوانێت قبوڵ یان ڕەت بکاتەوە ──
    if accepter_id not in MARRIAGE_PROPOSALS or MARRIAGE_PROPOSALS[accepter_id] != proposer_id:
        try: await answered("❌" + " ئەم پێشنیازە بۆ تۆ نییە!", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "accept":
        # چەکی ئایا خۆی کابینبووە
        if str(accepter_id) in MARRIAGES:
            try: await answered("❌" + " تۆ پێشتر کابینبووتەوە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        if str(proposer_id) in MARRIAGES:
            try: await answered("❌" + " ئەو کەسە پێشتر کابینبووەتەوە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            MARRIAGE_PROPOSALS.pop(accepter_id, None)
            return

        MARRIAGES[str(proposer_id)] = accepter_id
        MARRIAGES[str(accepter_id)] = proposer_id
        _save_marriages()
        MARRIAGE_PROPOSALS.pop(accepter_id, None)

        # نیشانەی کابینبوون
        ud1 = get_user_data(proposer_id)
        ud2 = get_user_data(accepter_id)
        for ud in [ud1, ud2]:
            if "badges" not in ud:
                ud["badges"] = []
            if "<tg-emoji emoji-id=\"5393107596553000968\">💍</tg-emoji> کابینبووە" not in ud["badges"]:
                ud["badges"].append("<tg-emoji emoji-id=\"5393107596553000968\">💍</tg-emoji> کابینبووە")
        save_users()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> FIX: نیشانەکانی هەردوو کەسەکە پاشەکەوت بکە

        try:
            proposer_name = _html_escape((await context.bot.get_chat(proposer_id)).first_name)
        except Exception:
            proposer_name = f"بەکارهێنەر {proposer_id}"

        try:
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5206591963050025931\">🎊</tg-emoji> پیرۆزە!\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
                f"<tg-emoji emoji-id=\"5393107596553000968\">💍</tg-emoji> {_html_escape(proposer_name)} و {_html_escape(query.from_user.first_name)} هاوسەرگیری کرد!\n\n"
                f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ هیوای ژیانێکی خۆش!")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    elif action == "reject":
        MARRIAGE_PROPOSALS.pop(accepter_id, None)
        try:
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5379600826350214977\">💔</tg-emoji> {_html_escape(query.from_user.first_name)} ڕەتی کردەوە...\n\n"
                f"😅 بەداخەوە، هەوڵی دیکە بدەرەوە!")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)

async def divorce_cmd(update, context):
    """هەڵوەشاندنەوەی کابینبوون"""
    user_id = update.effective_user.id
    if str(user_id) not in MARRIAGES:
        await update.message.reply_text(_TGX + " تۆ کابینبووە نیتەوە!", parse_mode="HTML")

        return

    partner_id = MARRIAGES[str(user_id)]
    del MARRIAGES[str(user_id)]
    if str(partner_id) in MARRIAGES:
        del MARRIAGES[str(partner_id)]
    _save_marriages()

    await update.message.reply_text(
        "<tg-emoji emoji-id=\"5379600826350214977\">💔</tg-emoji> هەڵوەشاندنەوەی کابینبوون\n\n"
        "کابینبوونەکەت هەڵوەشێنرایەوە.\n"
        "بۆ دەستپێکردنی نوێ: /marry",
        parse_mode="HTML"
    )


