GIFTS = {
    "گوڵ": {"emoji": "🌹", "coins": 10, "xp": 5, "msg": "گوڵێکی جوانی نێردووەتە"},
    "شوکولات": {"emoji": "🍫", "coins": 20, "xp": 10, "msg": "شوکولاتێکی شیرینی نێردووەتە"},
    f"ئەڵماس": {"emoji": f"{_TDM}", "coins": 100, "xp": 30, "msg": "ئەڵماسێکی بەهای نێردووەتە"},
    "تاج": {"emoji": "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>", "coins": 200, "xp": 50, "msg": "تاجێکی زێڕینی نێردووەتە"},
    "بەخت": {"emoji": "<tg-emoji emoji-id=\"5363985003866769909\">🍀</tg-emoji>", "coins": 50, "xp": 20, "msg": "دیاریی بەختێکی نێردووەتە"},
    "ستێر": {"emoji": "<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>", "coins": 75, "xp": 25, "msg": "ئەستێرەیەکی تایبەتی نێردووەتە"},
}

async def gift_cmd(update, context):
    """ناردنی دیاری"""
    user_id = update.effective_user.id
    user_data = get_user_data(user_id)
    user_name = _html_escape(update.effective_user.first_name)

    _back_kb = InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]])

    if not update.message.reply_to_message:
        lines = [f"{v['emoji']} {k} — {v['coins']} {_TCN} تێچووی" for k, v in GIFTS.items()]
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5381873589899267194\">🎁</tg-emoji> <b>ناردنی دیاری</b>\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            "ریپڵای پەیامی کەسێک بکە و بنووسە:\n"
            "<code>/gift [ناوی دیاری]</code>\n\n"
            "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> دیارییەکان:\n" + "\n".join(lines),
            parse_mode="HTML",
            reply_markup=_back_kb
        )
        return

    target = update.message.reply_to_message.from_user
    if target.is_bot:
        await update.message.reply_text(_TGX + " ناتوانیت دیاری بۆ بۆت بنێریت!", reply_markup=_back_kb, parse_mode="HTML")

        return
    if target.id == user_id:
        await update.message.reply_text(_TGX + " ناتوانیت دیاری بۆ خۆت بنێریت!", reply_markup=_back_kb, parse_mode="HTML")

        return

    gift_name = " ".join(context.args) if context.args else ""
    gift = GIFTS.get(gift_name)

    if not gift:
        lines = [f"{v['emoji']} {k}" for k, v in GIFTS.items()]
        await update.message.reply_text(
            f"{_TGX} دیارییەکە نەدۆزرایەوە!\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> دیارییەکانی بەردەست:\n" + "\n".join(lines),
            parse_mode="HTML",
            reply_markup=_back_kb
        )
        return

    coins = user_data.get("coins", 0)
    if coins < gift["coins"]:
        await update.message.reply_text(
            f"{_TGX} کۆینی پێویستت نییە!\n"
            f"پێویستت بە {gift['coins']} {_TCN} هەیە بەڵام تەنها {coins} {_TCN}ت هەیە.",
            reply_markup=_back_kb,
            parse_mode="HTML"
        )
        return

    add_coins(user_id, -gift["coins"])
    add_coins(target.id, gift["coins"] // 2)
    add_points(target.id, gift["xp"])
    save_users()   # {_TCK} FIX gift

    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5381873589899267194\">🎁</tg-emoji> <b>دیاری نێردرا!</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{gift['emoji']} {user_name} {gift['msg']} {target.first_name}!\n\n"
        f"{_TMN} {target.first_name} +{gift['coins']//2} {_TCN} و +{gift['xp']} XP وەرگرت!",
        parse_mode="HTML",
        reply_markup=_back_kb
    )


# ═════════════════════════
# فەرمانی /rob — دزی کۆین
# ═════════════════════════

ROB_COOLDOWN = 14400   # ٤ کاتژمێر

async def rob_cmd(update: Update, context: CallbackContext):
    """/rob — دزینی کۆین بە سیستەمی پێشکەوتوو"""
    user_id   = update.effective_user.id
    user_data = get_user_data(user_id)
    now       = time.time()

    # cooldown
    last_rob = user_data.get("last_rob_ts", 0)
    if now - last_rob < ROB_COOLDOWN:
        rem  = int(ROB_COOLDOWN - (now - last_rob))
        hrs  = rem // 3600
        mins = (rem % 3600) // 60
        time_txt = f"{hrs} کاتژمێر و {mins} خولەک" if hrs > 0 else f"{mins} خولەک"
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> هێشتا ناتوانیت دزی بکەیت!\n<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> ماوە: <b>{time_txt}</b>",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]])
        )
        return

    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: دیاریکردنی مەقسەد — ریپڵ و ئایدی هەردووکیان چاکسازیکران
    target_id   = None
    target_name = None
    target_obj  = None   # ئۆبجێکتی ڕاستەقینەی Telegram (بۆ is_bot چێک)

    if update.message.reply_to_message:
        ru = update.message.reply_to_message.from_user
        if ru and not ru.is_bot and ru.id != user_id:
            target_id   = ru.id
            target_name = _html_escape(ru.first_name or str(ru.id))
            target_obj  = ru
        elif ru is None:
            await update.message.reply_text(_TGX + " ناتوانرێت ئایدی ئەو پەیامە بزانرێت.", parse_mode="HTML")

            return
        elif ru.is_bot:
            await update.message.reply_text(_TGX + " ناتوانیت لە بۆتێک بدزیت!", parse_mode="HTML")

            return
        elif ru.id == user_id:
            await update.message.reply_text(_TGX + " ناتوانیت لە خۆتت بدزیت! <tg-emoji emoji-id=\"5316584460592897465\">😄</tg-emoji>", parse_mode="HTML")

            return
    elif context.args:
        raw = context.args[0].lstrip("@")
        try:
            target_id   = int(raw)
            # ناوی ئەو کەسە لە USERS بدۆزەرەوە ئەگەر هەبوو
            _udat       = USERS.get(str(target_id), {})
            target_name = _udat.get("nickname") or _udat.get("name") or str(target_id)
        except ValueError:
            await update.message.reply_text(
                _TGX + " ئایدییەکی دروست بنووسە!\n"
                "نموونە: <code>/rob 123456789</code>",
                parse_mode="HTML"
            )
            return

    if not target_id:
        await update.message.reply_text(
            "🦹 <b>دزی کۆین</b>\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            "بۆ دزین، یەکێک لەم دوو شێوازەیە بەکاربهێنە:\n\n"
            "١. ریپڵای لەسەر پەیامی ئەو کەسە بکە\n"
            "٢. ئایدییەکەی بنووسە:\n"
            "<code>/rob 123456789</code>\n\n"
            f"{_TCH} <b>شانسی سەرکەوتن لەسەر بنەمای:</b>\n"
            "• ئاستی تۆ\n"
            "• نمرەی ئەمانەتت\n"
            "• بیمەی مەقسەد",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]])
        )
        return

    target_data = get_user_data(target_id)
    if target_name is None:
        target_name = target_data.get("nickname") or target_data.get("name") or str(target_id)

    # ── چێکی بیمەی بانک ──
    b_target = _bank_get(target_id)
    if b_target.get("insurance_active"):
        penalty = max(100, int(user_data.get("coins", 0) * 0.12))
        add_coins(user_id, -penalty, "rob_fail", "بیمەی مەقسەد")
        user_data["last_rob_ts"] = now
        save_users()
        _bank_update_credit(_bank_get(user_id), False)
        _save_bank()
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> <b>{target_name}</b> بیمەی بانکی هەیە!\n\n"
            f"🚔 دەستگیرت کرایت و سزایت درا!\n"
            f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> سزا: <b>-{penalty:,} {_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5393589131106359852\">📉</tg-emoji> نمرەی ئەمانەتت کەم بوو",
            parse_mode="HTML"
        )
        return

    # ── چێکی rob_shield ──
    if _has_item(target_data, "rob_shield"):
        _remove_item(target_data, "rob_shield")
        penalty = max(50, int(user_data.get("coins", 0) * 0.10))
        add_coins(user_id, -penalty, "rob_fail", "سپەری مەقسەد")
        user_data["last_rob_ts"] = now
        save_users()
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> <b>{target_name}</b> سپەری پاراستنی هەبوو!\n\n"
            f"🦹 هەوڵەکەت شکست خوارد!\n"
            f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> سزا: <b>-{penalty:,} {_TCN}</b>",
            parse_mode="HTML"
        )
        return

    target_coins = target_data.get("coins", 0)
    if target_coins < 100:
        await update.message.reply_text(
            f"😅 <b>{target_name}</b> کۆینی پێویستی نییە بۆ دزین!\n"
            f"{_TMN} کۆینەکانی: {target_coins:,} {_TCN}",
            parse_mode="HTML"
        )
        return

    # ── شانسی سەرکەوتن لەسەر بنەمای ئاست و credit score ──
    my_level    = user_data.get("level", 1)
    my_credit   = _bank_get(user_id).get("credit_score", 100)
    base_chance = 0.35 + min(0.25, my_level * 0.01)
    if my_credit < 60:
        base_chance *= 0.7

    user_data["last_rob_ts"] = now

    if random.random() < base_chance:
        # ── سەرکەوتوو ──
        stolen = random.randint(
            max(50, int(target_coins * 0.05)),
            min(800, int(target_coins * 0.25))
        )
        add_coins(user_id,    stolen,  "rob", f"لە {target_name}")
        add_coins(target_id, -stolen,  "rob", f"{update.effective_user.first_name}ی دزی")
        _bank_update_credit(b_target, False)
        _save_bank()
        save_users()   # {_TCK} FIX
        await update.message.reply_text(
            f"🦹 <b>سەرکەوتوو!</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> لە <b>{target_name}</b> دزیت\n"
            f"{_TMN} دزراو: <b>+{stolen:,} {_TCN}</b>\n"
            f"{_TCH} شانس بوو: {int(base_chance*100)}٪\n\n"
            f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> زۆر دزی نەکە — credit score ت کەم دەبێت!",
            parse_mode="HTML"
        )
        try:
            await context.bot.send_message(
                target_id,
                f"<tg-emoji emoji-id=\"5823259308665607384\">🚨</tg-emoji> <b>{_html_escape(update.effective_user.first_name)}</b> {stolen:,} {_TCN}ی لەت دزی!\n"
                f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> لە دوکان <b><tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> پاراستن لە دزی</b> یان <b><tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> بیمەی بانک</b> بکڕە!",
                parse_mode="HTML"
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    else:
        # ── شکستخوار ──
        penalty = max(50, int(user_data.get("coins", 0) * 0.08))
        add_coins(user_id, -penalty, "rob_fail", f"{target_name}")
        _bank_update_credit(_bank_get(user_id), False)
        _save_bank()
        save_users()   # {_TCK} FIX
        await update.message.reply_text(
            f"🚔 <b>شکست خوارد!</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"دەستگیرت کرایت کاتێک دەیتەویست لە <b>{target_name}</b> بدزیت!\n"
            f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> سزا: <b>-{penalty:,} {_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5393589131106359852\">📉</tg-emoji> نمرەی ئەمانەتت کەم بوو",
            parse_mode="HTML"
        )

