async def handle_clan_create_text(update, context):
    """وەڵامی تێکستی دروستکردنی کلان"""
    user_id = update.effective_user.id
    if user_id not in _CLAN_CREATE_WAIT:
        return False

    del _CLAN_CREATE_WAIT[user_id]
    clan_name = update.message.text.strip()

    if len(clan_name) < 3 or len(clan_name) > 20:
        await update.message.reply_text(_TGX + " ناوی کلان دەبێت لە ٣ تا ٢٠ پیت بێت!", parse_mode="HTML")

        return True

    # پشکنین ئایا کلانێکی هەیە
    _, existing = _get_user_clan(user_id)
    if existing:
        await update.message.reply_text(_TGX + " تۆ پێشتر ئەندامی کلانێکیت!", parse_mode="HTML")

        return True

    # دروستکردنی کلانی نوێ
    clan_id = f"clan_{user_id}_{int(time.time())}"
    CLANS[clan_id] = {
        "name": clan_name,
        "leader": str(user_id),
        "members": [],
        "xp": 0,
        "created_at": datetime.datetime.now().isoformat(),
    }
    _save_clans()

    # نیشانەی سەرۆکی کلان
    ud = get_user_data(user_id)
    if "badges" not in ud:
        ud["badges"] = []
    if "<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ سەرۆکی کلان" not in ud["badges"]:
        ud["badges"].append("<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ سەرۆکی کلان")
    save_users()

    await update.message.reply_text(
        f"{_TCK} کلانی {clan_name} دروستکرا!\n\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> کۆدی کلان: `{clan_id}`\n"
        f"بۆ بانگهێشتکردنی هاوڕێکان: /clan",
        parse_mode="HTML"
    )
    return True


