ACTIVE_POLLS: dict = {}  # {chat_id: {poll_data}}

async def vote_cmd(update, context):
    """دروستکردنی دەنگدان"""
    user_id = update.effective_user.id

    _back_kb = InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})]])

    if not context.args:
        await update.message.reply_text(
            f"{_TCH} <b>دروستکردنی دەنگدان</b>\n"
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            "شێواز: <code>/vote [پرسیار] | [هەڵبژاردە١] | [هەڵبژاردە٢] | ...</code>\n\n"
            "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> نموونە:\n"
            "<code>/vote کام ڕەنگە جوانترە؟ | شین | سور | سەوز</code>",
            parse_mode="HTML",
            reply_markup=_back_kb
        )
        return

    full_text = " ".join(context.args)
    parts = [p.strip() for p in full_text.split("|")]

    if len(parts) < 3:
        await update.message.reply_text(_TGX + " لانیکەم پێویستت بە پرسیار و دوو هەڵبژاردەیە!", reply_markup=_back_kb, parse_mode="HTML")

        return

    question = parts[0]
    options = parts[1:]

    if len(options) > 6:
        await update.message.reply_text(_TGX + " زۆرترین ٦ هەڵبژاردەت دەبێت!", reply_markup=_back_kb, parse_mode="HTML")

        return

    poll_id = f"poll_{update.effective_chat.id}_{int(time.time())}"
    poll_data = {
        "question": question,
        "options": {opt: [] for opt in options},
        "creator": user_id,
        "chat_id": str(update.effective_chat.id),
        "created_at": datetime.datetime.now().isoformat(),
        "active": True,
    }
    ACTIVE_POLLS[poll_id] = poll_data

    keyboard = _build_poll_keyboard(poll_id, poll_data)
    await update.message.reply_text(
        f"{_TCH} دەنگدان\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> {question}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5255934767844567828\">🗳</tg-emoji> دەنگت بدە!",
        parse_mode="HTML",
        reply_markup=keyboard
    )

async def vote_callback(update, context):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1] if len(parts) > 1 else ""
    user_id = query.from_user.id

    if action == "results":
        poll_id = parts[2] if len(parts) > 2 else ""
        poll = ACTIVE_POLLS.get(poll_id)
        if not poll:
            await answered("❌" + " دەنگدانەکە نەدۆزرایەوە!", show_alert=True)
            return
        total = sum(len(v) for v in poll["options"].values())
        lines = []
        for opt, voters in poll["options"].items():
            count = len(voters)
            pct = int(count / total * 100) if total > 0 else 0
            bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
            lines.append(f"<b>{opt}</b>\n{bar} {pct}% ({count})")
        await _safe_edit(query, f"{_TCH} ئەنجامی دەنگدان\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> {poll['question']}\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            + "\n\n".join(lines) +
            f"\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5255934767844567828\">🗳</tg-emoji> کۆی دەنگەکان: {total}", reply_markup=InlineKeyboardMarkup([[
                _ebtn("گەڕانەوە", f"vote:back:{poll_id}", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})
            ]]))

    elif action == "close":
        poll_id = parts[2] if len(parts) > 2 else ""
        poll = ACTIVE_POLLS.get(poll_id)
        if poll and (str(user_id) == str(poll["creator"]) or user_id == OWNER_ID):
            poll["active"] = False
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> دەنگدانەکە داخرا\n\n<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> {poll['question']}")
        else:
            await answered("❌" + " تەنها دروستکەر دەتوانێت داببخات!", show_alert=True)

    elif action == "back":
        poll_id = parts[2] if len(parts) > 2 else ""
        poll = ACTIVE_POLLS.get(poll_id)
        if poll:
            await _safe_edit(query, f"{_TCH} دەنگدان\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> {poll['question']}\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n<tg-emoji emoji-id=\"5255934767844567828\">🗳</tg-emoji> دەنگت بدە!", reply_markup=_build_poll_keyboard(poll_id, poll))

    else:
        # دەنگدان بۆ هەڵبژاردەیەک
        poll_id = action
        chosen_opt = ":".join(parts[2:]) if len(parts) > 2 else ""
        poll = ACTIVE_POLLS.get(poll_id)
        if not poll:
            await answered("❌" + " دەنگدانەکە نەدۆزرایەوە!", show_alert=True)
            return
        if not poll["active"]:
            await answered("🔒 دەنگدانەکە داخراوە!", show_alert=True)
            return

        # دەنگی پێشتر داوە
        uid_str = str(user_id)
        for opt, voters in poll["options"].items():
            if uid_str in voters:
                voters.remove(uid_str)

        # زیادکردنی دەنگی نوێ
        for opt in poll["options"]:
            if opt[:20] == chosen_opt[:20]:
                poll["options"][opt].append(uid_str)
                await answered(f"✅ دەنگت بۆ '{opt}' تۆمار کرا!", show_alert=True)
                break

        try:
            await query.edit_message_reply_markup(
                reply_markup=_build_poll_keyboard(poll_id, poll)
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored


