async def _iq_show_question(msg_or_query, uid, edit=False):
    sess = IQ_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(IQ_QUESTIONS)
    if q_idx >= total:
        return
    order = sess.get("order", list(range(total)))
    real_idx = order[q_idx] if q_idx < len(order) else q_idx
    q = IQ_QUESTIONS[real_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    sec_names = {
        "logic": "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> مەنتق", "math": "<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> بیرکاری",
        "spatial": "<tg-emoji emoji-id=\"5438569421654234414\">📐</tg-emoji> فەزایی", "verbal": "<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> زمانەوانی",
        "general": "<tg-emoji emoji-id=\"5399898266265475100\">🌍</tg-emoji> زانیاری گشتی", "riddle": "<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> مەتەڵ",
        "number": "<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> ژمارە", "mixed": "<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> تێکەڵ"
    }
    sec = sec_names.get(q.get("section", ""), "<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji>")
    text = (
        f"<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>تێستی IQ</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}\n"
        f"[{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{q['q']}</b>"
    )
    kb = []
    row = []
    for i, (label, code) in enumerate(q["opts"]):
        row.append(_ebtn(f"{label}", f"iq:ans:{uid}:{code}", api_kwargs={"style": "primary"}))
        if len(row) == 2:
            kb.append(row); row = []
    if row: kb.append(row)
    _nav_iq = []
    if q_idx > 0:
        _nav_iq.append(_ebtn("گەڕانەوە", f"iq:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"}))
    _nav_iq.append(_ebtn(f"{q_idx+1}/{total}", "noop", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}))
    _nav_iq.append(_ebtn("وازهێنان", f"iq:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}))
    kb.append(_nav_iq)
    markup = InlineKeyboardMarkup(kb)
    try:
        if edit:
            try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
            except Exception as _exc:
                if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
        else:
            await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        if "not modified" not in str(e).lower():
            raise

async def iq_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)
    if str(uid) != clicker_uid:
        try: await answered("🔒 ئەم تێستە هی تۆ نییە! تێستی خۆت بکە /iq", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "back":
        sess = IQ_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        last_ans = None
        if sess.get("answers"): last_ans = sess["answers"].pop()
        if last_ans and last_ans.get("ok"):
            sess["score"] = max(0, sess["score"] - 1)
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _save_iq()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _iq_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی IQ؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو وەڵامەکانت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"iq:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"iq:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        if str(uid) in IQ_SESSIONS:
            await _iq_show_question(query, uid, edit=True)
        else:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ تاقیکردنەوەیەکی چالاکت نییە. /iq بنووسە.")
        return

    if action == "cancel":
        IQ_SESSIONS.pop(str(uid), None); _save_iq()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " تاقیکردنەوەکە هەڵوەشایەوە.\n/iq بنووسە بۆ دووبارە دەستپێکردن.")
        return

    if action == "start":
        _ord = list(range(len(IQ_QUESTIONS)))
        IQ_SESSIONS[str(uid)] = {"q_idx": 0, "score": 0, "answers": [], "order": _ord}
        _save_iq()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _iq_show_question(query, uid, edit=True)
        return

    if action == "restart":
        _ord2 = list(range(len(IQ_QUESTIONS)))
        IQ_SESSIONS[str(uid)] = {"q_idx": 0, "score": 0, "answers": [], "order": _ord2}
        _save_iq()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _iq_show_question(query, uid, edit=True)
        return

    if action == "next":
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> next دیگر بەکارناهێنرێت — پرسیار ڕاستەوخۆ نیشاندەدرێت
        sess = IQ_SESSIONS.get(str(uid))
        if not sess:
            try: await answered("⚠️ /iq بنووسە بۆ دووبارە.", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        if sess["q_idx"] >= len(IQ_QUESTIONS):
            await _iq_show_result(query, uid)
        else:
            await _iq_show_question(query, uid, edit=True)
        return

    if action == "ans":
        chosen = parts[3] if len(parts) > 3 else ""
        sess = IQ_SESSIONS.get(str(uid))
        if not sess:
            try: await answered()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        q_idx = sess["q_idx"]
        if q_idx >= len(IQ_QUESTIONS): return
        order = sess.get("order", list(range(len(IQ_QUESTIONS))))
        real_idx = order[q_idx] if q_idx < len(order) else q_idx
        q = IQ_QUESTIONS[real_idx]
        correct = q["ans"]
        is_correct = (chosen == correct)
        if is_correct:
            sess["score"] += 1
        sess["answers"].append({"q": real_idx, "chosen": chosen, "correct": correct, "ok": is_correct})
        sess["q_idx"] += 1
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> پاشەکەوت لە کۆتاییدا نەک هەر کلیک

        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> feedback popup — نەک پەیامی جیاواز (یەک edit نەک دوو)
        expl = q.get("explain", "").replace(f"{_TCK} ", "").replace(_TGX + " ", "")
        if is_correct:
            fb = f"{_TCK} وەڵامی دروست! — {expl}" if expl else f"{_TCK} وەڵامی دروست!"
        else:
            fb = f"{_TGX} هەڵەیە! ✓ {expl}" if expl else f"{_TGX} هەڵەیە! وەڵامی دروست: {correct}"
        try: await answered(fb[:200], show_alert=False)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        if sess["q_idx"] >= len(IQ_QUESTIONS):
            await _iq_show_result(query, uid)
        else:
            await _iq_show_question(query, uid, edit=True)
        return

async def _iq_show_result(query, uid):
    sess = IQ_SESSIONS.pop(str(uid), {}); _save_iq()
    score = sess.get("score", 0)
    total = len(IQ_QUESTIONS)

    user = query.from_user
    name = user.first_name or "کەسێک"
    if user.last_name:
        name += f" {user.last_name}"
    username_part = f" (@{user.username})" if user.username else ""

    result_data = {
        "score": score,
        "total": total,
        "pct": round(score / total * 100) if total else 0,
    }
    save_info = save_test_result(int(uid), "iq", result_data)
    
    comparison = _build_comparison_section("iq", int(uid), result_data)
    footer = _build_result_footer(
        xp_bonus=save_info.get("xp_bonus", 0),
        streak=save_info.get("streak", 0),
        total=save_info.get("total_completed", 0),
        is_retake=save_info.get("is_retake", False)
    )

    text = (
        f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> <b>{name}</b>{username_part} تێستی IQ تەواو کرد!\n\n"
        + _iq_result_text(score, total, sess)
        + comparison
        + footer
    )

    kb = InlineKeyboardMarkup([
        [_ebtn("دووبارە تاقی بکەرەوە", f"iq:restart:{uid}", emoji_id="5353025084845994828", api_kwargs={"style": "success"}),
         _ebtn("تێستەکانم", "run:testprofile", emoji_id="5386830501849897881", api_kwargs={"style": "primary"})],
        [_ebtn("داخستن", f"iq:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})],
    ])

    await _safe_edit(query, text, reply_markup=kb)


