async def _sci_show_question(msg_or_query, uid, edit=False):
    sess = SCI_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(SCI_QUESTIONS)
    if q_idx >= total: return
    # بەکارهێنانی ئۆردەری ڕەندەم
    order = sess.get("order", list(range(total)))
    real_idx = order[q_idx]
    q = SCI_QUESTIONS[real_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    cat_names = {"physics": f"{_TLT} فیزیک", "chemistry": "<tg-emoji emoji-id=\"5381961872952038862\">🧪</tg-emoji> کیمیا", "biology": "<tg-emoji emoji-id=\"6026321200597176575\">🌿</tg-emoji> بایۆلۆجی", "astro": "<tg-emoji emoji-id=\"5364181936707216367\">🌌</tg-emoji> ئەستێرەناسی"}
    lvl_names = {1: "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> ئاسان", 2: "<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> ناوەند", 3: "<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> قورس"}
    cat = cat_names.get(q["cat"], "")
    lvl = lvl_names.get(q["lvl"], "")
    text = (
        f"<tg-emoji emoji-id=\"5364181936707216367\">🌌</tg-emoji> <b>تێستی زانستی</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}  |  {cat}  |  {lvl}\n"
        f"[{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{q['q']}</b>"
    )
    kb = []
    for label, code in q["opts"]:
        kb.append([_ebtn(label, f"sci:ans:{uid}:{code}", api_kwargs={"style": "primary"})])
    _nav_sci = []
    if q_idx > 0:
        _nav_sci.append(_ebtn("گەڕانەوە", f"sci:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"}))
    _nav_sci.append(_ebtn(f"{q_idx+1}/{total}", "noop", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}))
    _nav_sci.append(_ebtn("وازهێنان", f"sci:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}))
    kb.append(_nav_sci)
    markup = InlineKeyboardMarkup(kb)
    try:
        if edit:
            try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
            except Exception as _exc:
                if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
        else:
            await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        if "not modified" not in str(e).lower():
            raise

async def sci_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)
    if str(uid) != clicker_uid:
        try: await answered("🔒 ئەم تێستە هی تۆ نییە! تێستی خۆت بکە /sciencetest", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "back":
        sess = SCI_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _save_sci()
        await _sci_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی زانستی؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"sci:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"sci:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _sci_show_question(query, uid, edit=True); return
    if action == "cancel":
        SCI_SESSIONS.pop(str(uid), None); _save_sci()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " تاقیکردنەوەکە هەڵوەشایەوە.\n/sciencetest بنووسە بۆ دووبارە.")
        return

    if action == "start":
        order = list(range(len(SCI_QUESTIONS)))
        SCI_SESSIONS[str(uid)] = {"q_idx": 0, "score": 0, "answers": [], "start_time": time.time(), "order": order}
        _save_sci()
        await _sci_show_question(query, uid, edit=True)
        return

    if action == "restart":
        order = list(range(len(SCI_QUESTIONS)))
        SCI_SESSIONS[str(uid)] = {"q_idx": 0, "score": 0, "answers": [], "start_time": time.time(), "order": order}
        _save_sci()
        await _sci_show_question(query, uid, edit=True)
        return

    if action == "next":
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> next دیگر بەکارناهێنرێت — پرسیار ڕاستەوخۆ نیشاندەدرێت
        sess = SCI_SESSIONS.get(str(uid))
        if not sess:
            try: await answered("⚠️ /sciencetest بنووسە بۆ دووبارە.", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        if sess["q_idx"] >= len(SCI_QUESTIONS):
            await _sci_show_result(query, uid)
        else:
            await _sci_show_question(query, uid, edit=True)
        return

    if action != "ans": return

    sess = SCI_SESSIONS.get(str(uid))
    if not sess:
        try: await answered()
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    if sess.get("q_idx", 0) >= len(SCI_QUESTIONS): await answered(); return

    chosen = parts[3] if len(parts) > 3 else ""
    q_idx = sess["q_idx"]
    order = sess.get("order", list(range(len(SCI_QUESTIONS))))
    real_idx = order[q_idx] if q_idx < len(order) else q_idx
    q = SCI_QUESTIONS[real_idx]
    correct = (chosen == q["ans"])
    if correct: sess["score"] += 1
    sess["answers"].append({"q": real_idx, "chosen": chosen, "correct": correct})
    sess["q_idx"] += 1
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> پاشەکەوت لە کۆتاییدا نەک هەر کلیک

    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> feedback popup — ڕاستەوخۆ پرسیاری داهاتوو (یەک edit نەک دوو)
    expl = q.get("explain", "").replace(f"{_TCK} ", "").replace(_TGX + " ", "")
    if correct:
        fb = f"{_TCK} ڕاستە! — {expl}" if expl else f"{_TCK} ڕاستە!"
    else:
        fb = f"{_TGX} هەڵەیە! ✓ {expl}" if expl else f"{_TGX} هەڵەیە!"
    try: await answered(fb[:200], show_alert=False)
    except Exception as _exc:
        logger.debug("Suppressed Exception: %s", _exc)
    if sess["q_idx"] >= len(SCI_QUESTIONS):
        await _sci_show_result(query, uid)
    else:
        await _sci_show_question(query, uid, edit=True)

async def addadv_cmd(update: Update, context: CallbackContext):
    """
    /addadv [ئایدی] [تێست1] [تێست2] ...
    نموونە: /addadv 123456789 bigfive alignment
    یان: /addadv 123456789 all  ← بۆ هەموو تێستەکان
    تێستەکان: bigfive, instinctual, tritype, attitudinal, temperament, alignment, darktri, darkempath, mbtifunc, cpt, ichazo, naranjo, mft, jung
    """
    user_id = update.effective_user.id
    if user_id != OWNER_ID:
        await update.message.reply_text(_TGX + " ئەم فەرمانە تەنها بۆ ئەدمین دیاری کراوە.", parse_mode="HTML")

        return

    TEST_KEYS = list(ADV_TESTS.keys())
    TESTS_LIST = "\n".join([f"• `{k}` — {v[1]} {v[0]}" for k, v in ADV_TESTS.items()])

    if not context.args or len(context.args) < 2:
        users = ADV_PREMIUM_USERS.get("users", {})
        if users:
            lines = []
            for uid, tests in users.items():
                test_names = ", ".join(tests)
                lines.append(f"• `{uid}` ← {test_names}")
            list_text = "\n".join(lines)
        else:
            list_text = "— کەس نییە —"
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> بەکارهێنانی فەرمان:\n"
            "<code>/addadv [ئایدی] [تێست...]</code>\n\n"
            "نموونەکان:\n"
            "<code>/addadv 123456789 bigfive alignment</code>\n"
            "<code>/addadv 123456789 all</code> ← هەموو تێستەکان\n\n"
            f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> تێستە بەردەستەکان:\n{TESTS_LIST}\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> ئێستا ({len(users)} کەس):\n{list_text}",
            parse_mode="HTML"
        )
        return

    try:
        target_id = int(context.args[0])
    except ValueError:
        await update.message.reply_text(_TGX + " ئایدی دروست نییە.", parse_mode="HTML")

        return

    requested = [t.lower() for t in context.args[1:]]
    if "all" in requested:
        new_tests = ["all"]
    else:
        invalid = [t for t in requested if t not in TEST_KEYS]
        if invalid:
            await update.message.reply_text(
                f"{_TGX} تێستی نادروست: `{'<code>, </code>'.join(invalid)}`\n\n"
                f"تێستە دروستەکان:\n{TESTS_LIST}",
                parse_mode="HTML"
            )
            return
        new_tests = requested

    users = ADV_PREMIUM_USERS.get("users", {})
    uid_str = str(target_id)
    existing = users.get(uid_str, [])
    if "all" in new_tests:
        merged = ["all"]
    else:
        merged = list(set(existing + new_tests))
    users[uid_str] = merged
    ADV_PREMIUM_USERS["users"] = users
    _save_adv_premium()

    tests_display = "هەموو تێستەکان <tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji>" if "all" in merged else ", ".join(merged)
    await update.message.reply_text(
        f"{_TCK} نوێکرایەوە!\n\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: `{target_id}`\n"
        f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> تێستەکانی ڕێگەپێدراو: {tests_display}",
        parse_mode="HTML"
    )

async def removeadv_cmd(update: Update, context: CallbackContext):
    """
    /removeadv [ئایدی] [تێست1] [تێست2] ...  ← سڕینەوەی تێستی دیاریکراو
    /removeadv [ئایدی] all  ← سڕینەوەی هەموو مۆڵەتەکان
    """
    user_id = update.effective_user.id
    if user_id != OWNER_ID:
        await update.message.reply_text(_TGX + " ئەم فەرمانە تەنها بۆ ئەدمین دیاری کراوە.", parse_mode="HTML")

        return

    users = ADV_PREMIUM_USERS.get("users", {})
    if not context.args:
        if users:
            lines = []
            for uid, tests in users.items():
                test_names = "هەموو" if "all" in tests else ", ".join(tests)
                lines.append(f"• `{uid}` ← {test_names}")
            list_text = "\n".join(lines)
        else:
            list_text = "— هیچ کەسێک نییە —"
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> لیستی ڕێگەپێدراوانی پریمیوم\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"{list_text}\n\n"
            f"{_TCH} کۆی گشتی: {len(users)} کەس\n\n"
            f"<tg-emoji emoji-id=\"5231265631042548053\">➖</tg-emoji> سڕینەوەی تێست: <code>/removeadv [ئایدی] [تێست]</code>\n"
            f"<tg-emoji emoji-id=\"5231265631042548053\">➖</tg-emoji> سڕینەوەی هەموو: <code>/removeadv [ئایدی] all</code>",
            parse_mode="HTML"
        )
        return

    try:
        target_id = int(context.args[0])
    except ValueError:
        await update.message.reply_text(_TGX + " ئایدی دروست نییە.", parse_mode="HTML")

        return

    uid_str = str(target_id)
    if uid_str not in users:
        await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئایدی `{target_id}` لە لیستدا نییە.", parse_mode="HTML")
        return

    if len(context.args) < 2 or context.args[1].lower() == "all":
        del users[uid_str]
        ADV_PREMIUM_USERS["users"] = users
        _save_adv_premium()
        await update.message.reply_text(f"{_TCK} هەموو مۆڵەتەکانی `{target_id}` سڕایەوە.", parse_mode="HTML")
        return

    to_remove = [t.lower() for t in context.args[1:]]
    existing = users.get(uid_str, [])
    if "all" in existing:
        existing = list(ADV_TESTS.keys())
    updated = [t for t in existing if t not in to_remove]
    if updated:
        users[uid_str] = updated
    else:
        del users[uid_str]
    ADV_PREMIUM_USERS["users"] = users
    _save_adv_premium()
    remaining = ", ".join(updated) if updated else "هیچ"
    await update.message.reply_text(
        f"{_TCK} نوێکرایەوە!\n\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: `{target_id}`\n"
        f"<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> سڕایەوە: {', '.join(to_remove)}\n"
        f"{_TCK} ماوەتەوە: {remaining}",
        parse_mode="HTML"
    )

