@guarded
async def darktri_cmd(update: Update, context: CallbackContext):
    user_id = update.effective_user.id
    # ── چەکی Premium ──
    if not _is_adv_allowed(user_id, "darktri"):
        await update.message.reply_text(
            _adv_premium_msg("Dark Triad", "<tg-emoji emoji-id=\"5465384878168102994\">🖤</tg-emoji>"),
            parse_mode="HTML"); return

    uid = str(user_id)
    DT_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {"M": 0, "N": 0, "P": 0}}
    _save_dt()
    name = _html_escape(update.effective_user.first_name or "تۆ")
    mention = _user_mention(update.effective_user)
    intro = (
        f"{mention}\n\n"
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> <b>تێستی Dark Triad — سێکوچکەی تاریک</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"سڵاو {name}! <tg-emoji emoji-id=\"5963225377944902253\">👋</tg-emoji>\n\n"
        f"ئەم تێستە <b>١٢٥ پرسیار</b>ی هەیە و سێ تایبەتمەندی دەپێوێت:\n\n"
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> <b>ماکیاڤیلیانیزم</b> — ستراتیژی و فریودان\n"
        f"<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> <b>نارسیسیزم</b> — خۆپەرستی و گەورەبینی\n"
        f"<tg-emoji emoji-id=\"5465384878168102994\">🖤</tg-emoji> <b>سایکۆپاتی</b> — بێبیمی و کەمسۆزی\n\n"
        f"<i><tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> نزیکەی ٢٥ خولەک دەخایەنێت</i>"
    )
    kb = InlineKeyboardMarkup([[
        _ebtn("دەستپێبکە", f"dt:start:{uid}", emoji_id="6282822561684263060", api_kwargs={"style": "success"}),
        _ebtn("لابردن", f"dt:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})
    ]])
    await update.message.reply_text(intro, parse_mode="HTML", reply_markup=kb)

async def _dt_show_question(msg_or_query, uid, edit=False):
    sess = DT_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(DT_QUESTIONS)
    if q_idx >= total: return
    _sess_ord = sess.get("order", list(range(len(DT_QUESTIONS))))
    q = DT_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    trait_names = {"M": "<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> ماکیاڤیلیانیزم", "N": "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> نارسیسیزم", "P": "<tg-emoji emoji-id=\"5465384878168102994\">🖤</tg-emoji> سایکۆپاتی"}
    t = trait_names.get(q["trait"], "")
    text = (
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> <b>تێستی Dark Triad</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}\n"
        f"[{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{q['q']}</b>\n\n"
    )
    kb = [[
        _ebtn("هیچ", f"dt:ans:{uid}:1", api_kwargs={"style": "primary"}),
        _ebtn("کەمێک", f"dt:ans:{uid}:2", api_kwargs={"style": "primary"}),
        _ebtn("نازانم", f"dt:ans:{uid}:3", api_kwargs={"style": "primary"}),
        _ebtn("بەڵێ", f"dt:ans:{uid}:4", api_kwargs={"style": "success"}),
        _ebtn("زۆر", f"dt:ans:{uid}:5", api_kwargs={"style": "primary"}),
    ], [
        *([ _ebtn("گەڕانەوە", f"dt:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"})] if q_idx > 0 else []),
        _ebtn(f"{q_idx+1}/{total}", "noop", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
        _ebtn("وازهێنان", f"dt:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
    ]]
    markup = InlineKeyboardMarkup(kb)
    try:
        if edit:
            try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
            except Exception as _exc:
                if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
        else:
            await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        if "not modified" not in str(e).lower():
            raise

async def dt_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)

    # چەکی خاوەنداری
    if action not in ("view",) and str(uid) != str(clicker_uid):
        try: await answered("🔒 ئەم تاقیکردنەوەیە هی تۆ نییە! تاقیکردنەوەی خۆت بکە /darktri", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "back":
        sess = DT_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        await _dt_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی سێگۆشەی تاریک؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"dt:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"dt:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _dt_show_question(query, uid, edit=True); return
    if action == "cancel":
        DT_SESSIONS.pop(str(uid), None); _save_dt()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " هەڵوەشایەوە.\n/darktri بنووسە بۆ دەستپێکردنەوە.")
        return

    if action == "start":
        DT_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {"M": 0, "N": 0, "P": 0}}
        _save_dt()
        await _dt_show_question(query, uid, edit=True)
        return

    if action == "restart":
        DT_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {"M": 0, "N": 0, "P": 0}}
        _save_dt()
        await _dt_show_question(query, uid, edit=True)
        return

    if action != "ans": return
    sess = DT_SESSIONS.get(str(uid))
    if not sess:
        await answered(); return

    if sess.get("q_idx", 0) >= len(DT_QUESTIONS): await answered(); return
    val = int(parts[3]) if len(parts) > 3 else 3
    q_idx = sess["q_idx"]
    _sess_ord = sess.get("order", list(range(len(DT_QUESTIONS))))
    q = DT_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    score = val if q["key"] == "+" else (6 - val)
    sess["scores"][q["trait"]] += score
    sess["q_idx"] += 1
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]

    if sess["q_idx"] >= len(DT_QUESTIONS):
        await _dt_show_result(query, uid)
    else:
        await _dt_show_question(query, uid, edit=True)


