def _is_ysq_allowed(user_id: int) -> bool:
    """چەکی مۆڵەتی تێستی YSQ — لە ADV_PREMIUM_USERS"""
    if user_id == OWNER_ID:
        return True
    return _is_adv_allowed(user_id, "ysq")

