# ئاستی سکیما بەپێی خاڵی ناوەند
# ════════════════════════════════════════════════════════════════════

def _ysq_schema_level(avg: float) -> tuple:
    """دەگەڕێتەوە (label, icon, color_style)"""
    if avg < 2.0:
        return "زۆر نزم", "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji>", "success"
    if avg < 3.0:
        return "نزم",      "<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji>", "primary"
    if avg < 4.0:
        return "ناوەند",   "<tg-emoji emoji-id=\"5431855765000331501\">🟠</tg-emoji>", "primary"
    if avg < 4.5:
        return "بەرز",     "<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji>", "danger"
    return     "زۆر بەرز", "<tg-emoji emoji-id=\"5422631223220540518\">⛔</tg-emoji>",  "danger"

# ════════════════════════════════════════════════════════════════════
# ئەنجامی YSQ — هەر ١٨ سکیما جیاجیا
# ════════════════════════════════════════════════════════════════════

async def _ysq_show_result(query, uid):
    sess = YSQ_SESSIONS.pop(str(uid), {}); _save_ysq()
    answers = sess.get("answers", {})   # {q_idx: score}
    total_q = len(YSQ_QUESTIONS)

    # ── خاڵی هەر سکیمایەک ──
    schema_scores: dict[str, list[int]] = {k: [] for k in YSQ_SCHEMAS}
    for idx, score in answers.items():
        _, sk = YSQ_QUESTIONS[int(idx)]
        schema_scores[sk].append(score)

    # ── ناوەند بۆ هەر سکیمایەک ──
    schema_avgs: dict[str, float] = {}
    for sk, vals in schema_scores.items():
        schema_avgs[sk] = round(sum(vals) / len(vals), 2) if vals else 0.0

    # پاشەکەوتکردن بۆ پڕۆفایل
    save_test_result(query.from_user.id, "ysq", {
        "schemas": schema_avgs,
        "timestamp": __import__("datetime").datetime.now().isoformat(),
    })

    user = query.from_user
    name = html.escape(user.first_name or "کەسێک")
    if user.last_name:
        name += f" {html.escape(user.last_name)}"
    username_part = f"@{html.escape(user.username)}" if user.username else name

    sep = (
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ "
        "<tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ "
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"
    )

    # ── سکیماکانی بەرز (avg >= 3.0) ──
    high_schemas = [(sk, avg) for sk, avg in schema_avgs.items() if avg >= 3.0]
    high_schemas.sort(key=lambda x: x[1], reverse=True)

    # ── دروستکردنی تێکستی هەر سکیمایەک ──
    domain_lines: dict[int, list[str]] = {1: [], 2: [], 3: [], 4: [], 5: []}
    for sk, meta in YSQ_SCHEMAS.items():
        avg = schema_avgs.get(sk, 0.0)
        lbl, icon, _ = _ysq_schema_level(avg)
        bar = _progress_bar(int(avg * 20), 100, 8)   # ناوەند × ٢٠ بۆ ١٠٠
        domain_lines[meta["domain"]].append(
            f"  {icon} <b>{meta['emoji']} {meta['name']}</b>  "
            f"<code>[{bar}]</code>  <b>{avg:.1f}/5</b>  — {lbl}"
        )

    # ── دروستکردنی تێکستی ئەنجام ──
    text = (
        f"<tg-emoji emoji-id=\"5379884861127432488\">🌀</tg-emoji> <b>ئەنجامی YSQ — Schema Therapy</b>\n"
        f"{sep}\n\n"
        f"<tg-emoji emoji-id=\"5963225377944902253\">👋</tg-emoji> {username_part}\n\n"
        f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>شیکردنەوەی ١٨ سکیما بە ٥ دۆمەین</b>\n"
        f"{sep}\n\n"
    )

    for dom_id, (dom_name, dom_icon) in YSQ_DOMAIN_NAMES.items():
        text += f"{dom_icon} <b>دۆمەینی {dom_id} — {dom_name}</b>\n"
        text += "\n".join(domain_lines[dom_id]) + "\n\n"

    text += sep + "\n\n"

    # ── سکیماکانی بەرز ──
    if high_schemas:
        text += (
            "<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> "
            "<b>سکیماکانی پێویست بە سەرنج (خاڵی بەرز):</b>\n"
        )
        for sk, avg in high_schemas[:5]:   # زۆرترین ٥
            meta = YSQ_SCHEMAS[sk]
            lbl, icon, _ = _ysq_schema_level(avg)
            text += (
                f"  {icon} <b>{meta['emoji']} {meta['name']}</b> "
                f"({meta['en']})  <b>{avg:.1f}/5</b>\n"
                f"  <i>{meta['desc']}</i>\n"
            )
        text += (
            "\n<i>سکیماکانی بەرز ئەوانەن کە باوەڕی ژیانی کەموکووڕی "
            "کار دەکەن لە ناوەوەدا و پێویستی بە کاری ئەرکی Schema Therapy هەیە.</i>\n\n"
        )
    else:
        text += (
            "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> "
            "<b>هیچ سکیمایەکی بەرز نەدۆزراوەتەوە!</b> خاڵەکانت لە ئاستی تەندروستیدان.\n\n"
        )

    text += sep

    kb = InlineKeyboardMarkup([[
        _ebtn(
            "<tg-emoji emoji-id=\"5379884861127432488\">🌀</tg-emoji> دووبارەی بکەرەوە",
            f"ysq:restart:{uid}",
            emoji_id="5379884861127432488",
            api_kwargs={"style": "primary"},
        )
    ]])

    try:
        await _safe_edit(query, text, reply_markup=kb)
    except Exception:
        await query.message.reply_text(text, parse_mode="HTML", reply_markup=kb)

# ════════════════════════════════════════════════════════════════════
# نیشاندانی پرسیار
# ════════════════════════════════════════════════════════════════════

async def _ysq_show_question(msg_or_query, uid: str, edit: bool = False):
    sess = YSQ_SESSIONS.get(uid)
    if not sess:
        return

    q_idx   = sess["q_idx"]
    total   = len(YSQ_QUESTIONS)
    if q_idx >= total:
        return

    q_text, schema_key = YSQ_QUESTIONS[q_idx]
    meta    = YSQ_SCHEMAS[schema_key]
    bar     = _progress_bar(q_idx, total)
    pct     = int((q_idx / total) * 100)
    dom_name, dom_icon = YSQ_DOMAIN_NAMES[meta["domain"]]

    text = (
        f"<tg-emoji emoji-id=\"5379884861127432488\">🌀</tg-emoji> <b>YSQ — Schema Therapy</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ "
        f"<tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ "
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> "
        f"{q_idx+1}/{total}  |  {meta['emoji']} {meta['name']}  |  {dom_icon} {dom_name}\n"
        f"[{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ "
        f"<tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ "
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{q_text}</b>\n\n"
        f"<i>گونجاوترین وەڵام بۆ خۆت هەڵبژێرە ↑ زۆر — هیچ ↓</i>"
    )

    kb = []
    for label, val, eid in YSQ_ANSWERS:
        kb.append([_ebtn(
            label,
            f"ysq:ans:{uid}:{q_idx}:{val}",
            emoji_id=eid,
            api_kwargs={"style": "primary"},
        )])

    nav = []
    if q_idx > 0:
        nav.append(_ebtn(
            "گەڕانەوە",
            f"ysq:back:{uid}",
            api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"},
        ))
    nav.append(_ebtn(
        f"{q_idx+1}/{total}",
        "noop",
        emoji_id="6271698656517165534",
        api_kwargs={"style": "primary"},
    ))
    nav.append(_ebtn(
        "وازهێنان",
        f"ysq:confirmcancel:{uid}",
        emoji_id="6271611232457855630",
        api_kwargs={"style": "danger"},
    ))
    kb.append(nav)

    markup = InlineKeyboardMarkup(kb)
    try:
        if edit:
            try:
                await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
            except Exception as exc:
                if "not modified" not in str(exc).lower():
                    await msg_or_query.message.reply_text(text, parse_mode="HTML", reply_markup=markup)
        else:
            await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        if "not modified" not in str(e).lower():
            raise

