# ════════════════════════════════════════════════════════════════════
# callback handler
# ════════════════════════════════════════════════════════════════════

async def ysq_callback(update: Update, context: CallbackContext):
    query   = update.callback_query
    answered = _make_answerer(query)
    parts   = query.data.split(":")
    action  = parts[1]
    uid     = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker = str(query.from_user.id)

    # چەکی خاوەن تێست
    if uid != clicker:
        try:
            await answered(
                "<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> ئەم تێستە هی تۆ نییە! تێستی خۆت بکە /ysq",
                show_alert=True,
            )
        except Exception as exc:
            logger.debug("Suppressed Exception: %s", exc)
        return

    # ── start / restart ──
    if action in ("start", "restart"):
        YSQ_SESSIONS[uid] = {
            "q_idx":   0,
            "answers": {},
            "start_time": __import__("time").time(),
        }
        _save_ysq()
        try: await answered()
        except Exception as exc: logger.debug("Suppressed Exception: %s", exc)
        await _ysq_show_question(query, uid, edit=True)
        return

    # ── cancel (لە پرۆسەی دەستپێکردن) ──
    if action == "cancel":
        YSQ_SESSIONS.pop(uid, None); _save_ysq()
        try: await answered()
        except Exception as exc: logger.debug("Suppressed Exception: %s", exc)
        await _safe_edit(
            query,
            _TGX + " تاقیکردنەوەکە هەڵوەشایەوە.\n/ysq بنووسە بۆ دووبارە.",
        )
        return

    # ── confirmcancel ──
    if action == "confirmcancel":
        try: await answered()
        except Exception as exc: logger.debug("Suppressed Exception: %s", exc)
        await _safe_edit(
            query,
            "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> "
            "<b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تێستی YSQ؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.",
            reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"ysq:cancel:{uid}",
                       emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە",  f"ysq:resume:{uid}",
                       emoji_id="6271611232457855630", api_kwargs={"style": "primary"})],
            ]),
        )
        return

    # ── resume ──
    if action == "resume":
        try: await answered()
        except Exception as exc: logger.debug("Suppressed Exception: %s", exc)
        await _ysq_show_question(query, uid, edit=True)
        return

    # ── back ──
    if action == "back":
        sess = YSQ_SESSIONS.get(uid)
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as exc: logger.debug("Suppressed Exception: %s", exc)
            return
        prev_idx = sess["q_idx"] - 1
        sess["answers"].pop(str(prev_idx), None)
        sess["q_idx"] = prev_idx
        _save_ysq()
        try: await answered()
        except Exception as exc: logger.debug("Suppressed Exception: %s", exc)
        await _ysq_show_question(query, uid, edit=True)
        return

    # ── ans ──
    if action == "ans":
        # ysq:ans:{uid}:{q_idx}:{val}
        if len(parts) < 5:
            try: await answered()
            except Exception as exc: logger.debug("Suppressed Exception: %s", exc)
            return

        sess = YSQ_SESSIONS.get(uid)
        if not sess:
            try: await answered("⚠️ /ysq بنووسە بۆ دووبارە.", show_alert=True)
            except Exception as exc: logger.debug("Suppressed Exception: %s", exc)
            return

        q_idx_str = parts[3]
        val       = int(parts[4])

        # ئەگەر پرسیارەکەی پێشتر وەڵام دراوە، وازیان لێ هێنا (anti-skip)
        sess["answers"][q_idx_str] = val
        sess["q_idx"] = int(q_idx_str) + 1
        _save_ysq()

        # ── feedback popup ──
        labels = {5: "زۆر", 4: "بەڵێ", 3: "نازانم", 2: "کەمێک", 1: "هیچ"}
        fb = f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> {labels.get(val, str(val))} ← تۆماری کراوە"
        try: await answered(fb[:200], show_alert=False)
        except Exception as exc: logger.debug("Suppressed Exception: %s", exc)

        total = len(YSQ_QUESTIONS)
        if sess["q_idx"] >= total:
            await _ysq_show_result(query, uid)
        else:
            await _ysq_show_question(query, uid, edit=True)
        return

    # ── fallback ──
    try: await answered()
    except Exception as exc: logger.debug("Suppressed Exception: %s", exc)


