# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> cached keyboard بۆ de
_DE_KB_CACHE: dict = {}

async def _de_show_question(msg_or_query, uid, edit=False):
    sess = DE_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(DE_QUESTIONS)
    if q_idx >= total: return
    _sess_ord = sess.get("order", list(range(len(DE_QUESTIONS))))
    q = DE_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    trait_names = {
        "EM": "<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> مانیپولەیشنی سۆزداری",
        "SI": "🕸 زیرەکیی کۆمەڵایەتیی ژەهراوی",
        "CE": "<tg-emoji emoji-id=\"5891198677606732755\">🧊</tg-emoji> هاوسۆزیی سارد",
        "GC": "<tg-emoji emoji-id=\"5188497854242495901\">🌑</tg-emoji> گاسلایتینگ و کۆنترۆڵ"
    }
    t = trait_names.get(q["trait"], "")
    # mention لەلایەن user دروست دەکرێت
    try:
        _u = getattr(msg_or_query, 'from_user', None)
        mention = _user_mention(_u) if _u else ""
    except Exception:
        mention = ""
    text = (
        f"{mention}\n\n"
        f"<tg-emoji emoji-id=\"5386543529315064132\">💜</tg-emoji> <b>تێستی Dark Empath</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}\n"
        f"[{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{q['q']}</b>\n\n"
        f"<i>بە چەند ڕادەیەک لەگەڵ ئەم ووتەیە دەکەویت؟</i>"
    )
    _de_nav = []
    if q_idx > 0:
        _de_nav.append(_ebtn("گەڕانەوە", f"de:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"}))
    _de_nav.append(_ebtn(f"{q_idx+1}/{total}", "noop", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}))
    _de_nav.append(_ebtn("وازهێنان", f"de:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}))
    markup = InlineKeyboardMarkup([[
        _ebtn("هیچ", f"de:ans:{uid}:1", api_kwargs={"style": "primary"}),
        _ebtn("کەمێک", f"de:ans:{uid}:2", api_kwargs={"style": "primary"}),
        _ebtn("نازانم", f"de:ans:{uid}:3", api_kwargs={"style": "primary"}),
        _ebtn("بەڵێ", f"de:ans:{uid}:4", api_kwargs={"style": "success"}),
        _ebtn("زۆر", f"de:ans:{uid}:5", api_kwargs={"style": "primary"}),
    ], _de_nav])
    try:
        if edit:
            try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
            except Exception as _exc:
                if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
        else:
            await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        if "not modified" not in str(e).lower():
            raise

async def de_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)

    if action not in ("view",) and str(uid) != str(clicker_uid):
        try: await answered("🔒 ئەم تاقیکردنەوەیە هی تۆ نییە! تاقیکردنەوەی خۆت بکە /darkempath", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "back":
        sess = DE_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        await _de_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی Dark Empath؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"de:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"de:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _de_show_question(query, uid, edit=True); return
    if action == "cancel":
        DE_SESSIONS.pop(str(uid), None); _save_de()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " هەڵوەشایەوە.\n/darkempath بنووسە بۆ دەستپێکردنەوە.")
        return

    if action == "start":
        DE_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {"EM": 0, "SI": 0, "CE": 0, "GC": 0}}
        _save_de()
        await _de_show_question(query, uid, edit=True)
        return

    if action == "restart":
        DE_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {"EM": 0, "SI": 0, "CE": 0, "GC": 0}}
        _save_de()
        await _de_show_question(query, uid, edit=True)
        return

    if action != "ans": return
    sess = DE_SESSIONS.get(str(uid))
    if not sess:
        await answered(); return

    if sess.get("q_idx", 0) >= len(DE_QUESTIONS): await answered(); return
    val = int(parts[3]) if len(parts) > 3 else 3
    q_idx = sess["q_idx"]
    _sess_ord = sess.get("order", list(range(len(DE_QUESTIONS))))
    q = DE_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    score = val if q["key"] == "+" else (6 - val)
    sess["scores"][q["trait"]] += score
    sess["q_idx"] += 1
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]

    if sess["q_idx"] >= len(DE_QUESTIONS):
        await _de_show_result(query, uid)
    else:
        await _de_show_question(query, uid, edit=True)


