async def _b5_show_question(msg_or_query, uid, edit=False):
    sess = B5_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(B5_QUESTIONS)
    if q_idx >= total: return
    _sess_ord = sess.get("order", list(range(len(B5_QUESTIONS))))
    q = B5_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    trait_names = {
        "O": "<tg-emoji emoji-id=\"5454327111202381881\">🌈</tg-emoji> کرانەوە بەڕووی ئەزموون",
        "C": "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> ڕێکخراوی",
        "E": "<tg-emoji emoji-id=\"5201827869361188827\">☀</tg-emoji> تێکەڵاوبوون",
        "A": "<tg-emoji emoji-id=\"5429178965287782978\">💚</tg-emoji> سازگاری",
        "N": "<tg-emoji emoji-id=\"5287519334569097506\">🌊</tg-emoji> ناجێگیری سۆزداری",
    }
    t = trait_names.get(q["trait"], "")
    text = (
        f"<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> <b>تێستی Big Five</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}\n"
        f"[{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{q['q']}</b>\n\n"
    )
    kb = [[
        _ebtn("هیچ", f"b5:ans:{uid}:1", api_kwargs={"style": "primary"}),
        _ebtn("کەمێک", f"b5:ans:{uid}:2", api_kwargs={"style": "primary"}),
        _ebtn("نازانم", f"b5:ans:{uid}:3", api_kwargs={"style": "primary"}),
        _ebtn("بەڵێ", f"b5:ans:{uid}:4", api_kwargs={"style": "success"}),
        _ebtn("زۆر", f"b5:ans:{uid}:5", api_kwargs={"style": "primary"}),
    ], [
        *([ _ebtn("گەڕانەوە", f"b5:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"})] if q_idx > 0 else []),
        _ebtn(f"{q_idx+1}/{total}", "noop", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
        _ebtn("وازهێنان", f"b5:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
    ]]
    markup = InlineKeyboardMarkup(kb)
    if edit:
        try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=markup)
        except Exception as _exc:
            if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)
    else:
        await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=markup)

async def b5_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)

    if action not in ("view",) and str(uid) != str(clicker_uid):
        try: await answered("🔒 ئەم تاقیکردنەوەیە هی تۆ نییە! تاقیکردنەوەی خۆت بکە /bigfive", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "back":
        sess = B5_SESSIONS.get(uid)
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        await _b5_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی Big Five؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"b5:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"b5:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _b5_show_question(query, uid, edit=True); return
    if action == "cancel":
        B5_SESSIONS.pop(uid, None); _save_b5()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " هەڵوەشایەوە.\n/bigfive بنووسە بۆ دووبارە.")
        return

    if action == "start":
        B5_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {"E": 0, "A": 0, "C": 0, "N": 0, "O": 0}}
        _save_b5()
        await _b5_show_question(query, uid, edit=True)
        return

    if action == "restart":
        B5_SESSIONS[str(uid)] = {"q_idx": 0, "scores": {"E": 0, "A": 0, "C": 0, "N": 0, "O": 0}}
        _save_b5()
        await _b5_show_question(query, uid, edit=True)
        return

    if action != "ans": return
    sess = B5_SESSIONS.get(uid)
    if not sess:
        await answered(); return

    if sess.get("q_idx", 0) >= len(B5_QUESTIONS): await answered(); return
    val = int(parts[3]) if len(parts) > 3 else 3
    q_idx = sess["q_idx"]
    _sess_ord = sess.get("order", list(range(len(B5_QUESTIONS))))
    q = B5_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    score = val if q["polarity"] == "+" else (6 - val)
    trait = q["trait"]
    sess["scores"][trait] = sess["scores"].get(trait, 0) + score
    sess.setdefault("ans_log", []).append({"t": trait, "val": val})
    sess["q_idx"] += 1
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]

    if sess["q_idx"] >= len(B5_QUESTIONS):
        await _b5_show_result(query, uid)
    else:
        await _b5_show_question(query, uid, edit=True)

async def tag_all_cmd(update: Update, context: CallbackContext):
    """تاگکردنی هەموو میمبەرانی چالاکی گرووپ — تەنها ئاوێنەر"""
    if not update.effective_chat or not update.effective_user:
        return
    chat = update.effective_chat
    user = update.effective_user
    if user.id != OWNER_ID:
        if update.message:
            await update.message.reply_text(_TGX + " تەنها ئاوێنەر دەتوانێت ئەم فەرمانە بەکاربهێنێت!", parse_mode="HTML")

        return
    if chat.type == "private":
        if update.message:
            await update.message.reply_text(_TGX + " ئەم فەرمانە تەنها لە گرووپدا کار دەکات!", parse_mode="HTML")

        return
    try:
        chat_id_str = str(chat.id)
        stats = GROUP_STATS.get(chat_id_str, {})
        members = []
        for uid, info in stats.items():
            try:
                uid_int = int(uid)
                if uid_int > 0:
                    members.append({"id": uid_int, "name": info.get("name", "کەس")})
            except ValueError:
                pass  # intentionally ignored
        if not members:
            if update.message:
                await update.message.reply_text(_TGX + " هیچ میمبەرێکی تۆمارکراو نییە هێشتا!\n<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> بۆت پێویستە کاتێک فرست ببێت میمبەرانی پەیام بنێرن.", parse_mode="HTML")

            return
        # پەیامی سەرەکی
        msg_text = ""
        if update.message:
            msg_text = (update.message.text or "").replace("/tagall", "").strip()
        header = f"<tg-emoji emoji-id=\"6024112973226709843\">📢</tg-emoji> <b>{msg_text}</b>\n\n" if msg_text else "<tg-emoji emoji-id=\"6024112973226709843\">📢</tg-emoji> ئاگادارکردنەوەی هەموو میمبەران\n\n"
        reply_fn = update.message.reply_text if update.message else None
        if reply_fn:
            await reply_fn(f"{header}<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> کۆی میمبەران: {len(members)} کەس", parse_mode="HTML")
        chunk_size = 5
        for i in range(0, len(members), chunk_size):
            chunk = members[i:i+chunk_size]
            text = " ".join([f'<a href="tg://user?id={m["id"]}">{m["name"]}</a>' for m in chunk])
            try:
                if reply_fn:
                    await reply_fn(text, parse_mode="HTML")
                await asyncio.sleep(0.1)  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 0.5→0.1
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    except Exception as e:
        if update.message:
            await update.message.reply_text(f"{_TGX} هەڵە: {_html_escape(str(e))}", parse_mode="HTML")



