# <tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> سیستەمی وشەی قەدەغەکراو — پێشکەوتوو
# ═════════════════════════

BANNED_WORDS_FILE = "banned_words.json"
BANNED_WORDS_DATA: dict = {}
try:
    with open(_hdata_path(BANNED_WORDS_FILE), "r", encoding="utf-8") as _bwf:
        BANNED_WORDS_DATA = json.load(_bwf)
except Exception:
    BANNED_WORDS_DATA = {"words": [], "action": "delete"}
    # action: delete | delete_warn | delete_ban | delete_mute | delete_mute_temp

async def check_banned_words(update, context):
    """بپشکنە و وشەی قەدەغەکراو بدۆزەرەوە"""
    if not update.message:
        return
    user = update.effective_user
    chat = update.effective_chat
    if not user or not chat:
        return
    if chat.type not in ("group", "supergroup"):
        return
    text = (update.message.text or update.message.caption or "").lower()
    words = BANNED_WORDS_DATA.get("words", [])
    found = None
    for w in words:
        if w in text:
            found = w
            break
    if not found:
        return
    # سڕینەوەی پەیام
    try:
        await update.message.delete()
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    # کردارە پاشەکەوتراوەکە بخوێنەوە و ڕاستەوخۆ جێبەجێ بکە
    action = BANNED_WORDS_DATA.get("action", "delete")
    action_labels = {
        "delete": "پەیامەکەی سڕایەوە",
        "delete_warn": "ئاگادارکرایەوە",
        "delete_mute_temp": "میوتی کاتی (١ساعەت) کرا",
        "delete_mute": "میوت بۆ هەمیشە کرا",
        "delete_ban": "بانکرا",
    }
    result_text = action_labels.get(action, "پەیامەکەی سڕایەوە")
    if action == "delete_warn":
        try:
            await context.bot.send_message(
                chat.id,
                f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <a href='tg://user?id={user.id}'>{_html_escape(user.first_name)}</a>، وشەی قەدەغەکراو بەکارهێنا! ئاگادارکراوەتەوە.",
                parse_mode="HTML"
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    elif action == "delete_mute_temp":
        try:
            await context.bot.restrict_chat_member(
                chat.id, user.id,
                permissions=ChatPermissions(can_send_messages=False),
                until_date=datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=1)  # میوتی ١ساعەت
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
    elif action == "delete_mute":
        try:
            await context.bot.restrict_chat_member(
                chat.id, user.id,
                permissions=ChatPermissions(can_send_messages=False)
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
    elif action == "delete_ban":
        try:
            await context.bot.ban_chat_member(chat.id, user.id)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    # ئاگادارکردنەوەی ئادمین
    try:
        await context.bot.send_message(
            chat.id,
            f"<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> وشەی قەدەغەکراو دۆزرایەوە\n\n"
            f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> بەکارهێنەر: <a href='tg://user?id={user.id}'>{_html_escape(user.first_name)}</a>\n",
            f"<tg-emoji emoji-id=\"5472411062412254753\">🔤</tg-emoji> وشە: `{found}`\n"
            f"<tg-emoji emoji-id=\"5341715473882955310\">⚙️</tg-emoji> کردار: <b>{result_text}</b>",
            parse_mode="HTML"
        )
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

async def bw_take_action_callback(update: Update, context: CallbackContext):
    """کاردانەوە بۆ وشەی قەدەغەکراو بەپێی هەڵبژاردنی ئەدمین"""
    query = update.callback_query
    answered = _make_answerer(query)
    # تەنها ئەدمینان و خاوەن
    try:
        caller = query.from_user
        chat_member = await context.bot.get_chat_member(query.message.chat.id, caller.id)
        if caller.id != OWNER_ID and chat_member.status not in ("administrator", "creator"):
            await answered("❌" + " تەنها ئەدمینان!", show_alert=True)
            return
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    parts = query.data.split(":")  # bwtake:user_id:chat_id:action
    if len(parts) < 4:
        return
    target_user_id = int(parts[1])
    target_chat_id = int(parts[2])
    action = parts[3]
    labels = {
        "delete": "پەیامەکەی سڕایەوە",
        "mute_temp": "میوتی کاتی (١ساعەت) کرا",
        "mute": "میوت بۆ هەمیشە کرا",
        "ban": "بانکرا",
    }
    result_text = labels.get(action, "کردار جێبەجێکرا")
    if action == "delete":
        pass  # پەیام پێشتر سڕاوەتەوە
    elif action == "mute_temp":
        try:
            await context.bot.restrict_chat_member(
                target_chat_id, target_user_id,
                permissions=ChatPermissions(can_send_messages=False),
                until_date=datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=1)
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
    elif action == "mute":
        try:
            await context.bot.restrict_chat_member(
                target_chat_id, target_user_id,
                permissions=ChatPermissions(can_send_messages=False)
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
    elif action == "ban":
        try:
            await context.bot.ban_chat_member(target_chat_id, target_user_id)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    try:
        await _safe_edit(query, f"{_TCK} کردار جێبەجێکرا: <b>{result_text}</b>")
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored


