async def _panas_show_question(msg_or_query, uid, edit=False):
    sess = PANAS_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(PANAS_QUESTIONS)
    if q_idx >= total: return
    _sess_ord = sess.get("order", list(range(len(PANAS_QUESTIONS))))
    q = PANAS_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    type_label = "" if q["type"] == "P" else ""
    example = q.get("ex", "")
    text = (
        f"<b>تێستی PANAS</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}\n"
        f"[{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>تا چەندێک ئەم هەستە لەدەروونتدایە؟</b>\n\n"
        f"<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> <b>{q['q']}</b>\n\n"
        f"<i><tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> نموونە: {example}</i>\n\n"
    )
    kb = InlineKeyboardMarkup([[
        _ebtn("هیچ", f"panas:ans:{uid}:1", api_kwargs={"style": "primary"}),
        _ebtn("کەمێک", f"panas:ans:{uid}:2", api_kwargs={"style": "primary"}),
        _ebtn("نازانم", f"panas:ans:{uid}:3", api_kwargs={"style": "primary"}),
        _ebtn("بەڵێ", f"panas:ans:{uid}:4", api_kwargs={"style": "success"}),
        _ebtn("زۆر", f"panas:ans:{uid}:5", api_kwargs={"style": "primary"}),
    ], [
        *([ _ebtn("گەڕانەوە", f"panas:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"})] if q_idx > 0 else []),
        _ebtn(f"{q_idx+1}/{total}", "noop", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
        _ebtn("وازهێنان", f"panas:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
    ]])
    try:
        if edit:
            try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
            except Exception as _exc:
                if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)
        else:
            await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)
    except Exception as e:
        if "not modified" not in str(e).lower():
            raise

async def panas_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)
    if action not in ("view",) and str(uid) != str(clicker_uid):
        try: await answered("🔒 ئەم تاقیکردنەوەیە هی تۆ نییە! /panas بنووسە", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    if action == "back":
        sess = PANAS_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess[last["t"]] = max(0, sess.get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        await _panas_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی PANAS؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"panas:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"panas:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _panas_show_question(query, uid, edit=True); return
    if action == "cancel":
        PANAS_SESSIONS.pop(str(uid), None); _save_panas()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " هەڵوەشایەوە.\n/panas بنووسە بۆ دووبارە.")
        return
    if action == "start":
        PANAS_SESSIONS[str(uid)] = {"q_idx": 0, "P": 0, "N": 0, "order": list(range(len(PANAS_QUESTIONS)))}
        _save_panas()
        await _panas_show_question(query, uid, edit=True)
        return
    if action != "ans": return
    sess = PANAS_SESSIONS.get(str(uid))
    if not sess:
        await answered(); return
    if sess.get("q_idx", 0) >= len(PANAS_QUESTIONS): await answered(); return
    val = int(parts[3]) if len(parts) > 3 else 3
    q_idx = sess["q_idx"]
    _sess_ord = sess.get("order", list(range(len(PANAS_QUESTIONS))))
    q = PANAS_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    sess[q["type"]] = sess.get(q["type"], 0) + val
    sess.setdefault("ans_log", []).append({"t": q["type"], "val": val})
    sess["q_idx"] += 1
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]
    if sess["q_idx"] >= len(PANAS_QUESTIONS):
        await _panas_show_result(query, uid)
    else:
        await _panas_show_question(query, uid, edit=True)

