async def instincts_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)
    if action not in ("view",) and str(uid) != str(clicker_uid):
        try: await answered("🔒 ئەم تاقیکردنەوەیە هی تۆ نییە! /instincts بنووسە", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    if action == "back":
        sess = INSTINCTS_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
            sess["stage"] = "most"
            sess["most_choice"] = None
            sess["most_idx"] = -1
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        await _inst_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی Instincts؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"inst:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"inst:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _inst_show_question(query, uid, edit=True); return
    if action == "cancel":
        INSTINCTS_SESSIONS.pop(str(uid), None); _save_instincts()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " هەڵوەشایەوە.\n/instincts بنووسە بۆ دووبارە.")
        return
    if action == "start":
        INSTINCTS_SESSIONS[str(uid)] = {"q_idx": 0, "SP": 0, "SO": 0, "SX": 0, "stage": "most", "order": list(range(len(INSTINCTS_QUESTIONS)))}
        _save_instincts()
        await _inst_show_question(query, uid, edit=True)
        return
    if action != "ans": return
    sess = INSTINCTS_SESSIONS.get(str(uid))
    if not sess:
        await answered(); return
    if sess.get("q_idx", 0) >= len(INSTINCTS_QUESTIONS): await answered(); return

    # parts: inst:ans:{uid}:{stage}:{opt_idx}
    stage = parts[3] if len(parts) > 3 else "most"
    opt_idx = int(parts[4]) if len(parts) > 4 else 0
    q_idx = sess["q_idx"]
    _sess_ord = sess.get("order", list(range(len(INSTINCTS_QUESTIONS))))
    q = INSTINCTS_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]

    if stage == "most":
        # خاڵی ٢ بۆ most
        chosen_type = q["opts"][opt_idx]["type"]
        sess[chosen_type] = sess.get(chosen_type, 0) + 2
        sess["stage"] = "least"
        sess["most_idx"] = opt_idx
        sess["most_choice"] = q["opts"][opt_idx]["text"][:50] + "..."
        _save_instincts()
        await _inst_show_question(query, uid, edit=True)
    else:
        # least — خاڵی ٠ بۆ least، خاڵی ١ بۆ ناوەڕاست
        most_idx = sess.get("most_idx", -1)
        chosen_type = q["opts"][opt_idx]["type"]
        # ناوەڕاستەکە (نە most نە least) = ١ خاڵ
        neutral_idx = [i for i in range(3) if i != most_idx and i != opt_idx]
        if neutral_idx:
            neutral_type = q["opts"][neutral_idx[0]]["type"]
            sess[neutral_type] = sess.get(neutral_type, 0) + 1
        # least = ٠ خاڵ (هیچ زیاد ناکرێت)
        # پێش چوون بۆ پرسیاری داهاتوو
        sess["q_idx"] += 1
        sess["stage"] = "most"
        sess.pop("most_idx", None)
        sess.pop("most_choice", None)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]
        if sess["q_idx"] >= len(INSTINCTS_QUESTIONS):
            await _inst_show_result(query, uid)
        else:
            await _inst_show_question(query, uid, edit=True)

