async def tritype_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)
    if action not in ("view",) and str(uid) != str(clicker_uid):
        try: await answered("🔒 ئەم تاقیکردنەوەیە هی تۆ نییە! /tritype بنووسە", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    if action == "back":
        sess = TRITYPE_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        await _trit_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی Tritype؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"trit:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"trit:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _trit_show_question(query, uid, edit=True); return
    if action == "cancel":
        TRITYPE_SESSIONS.pop(str(uid), None); _save_tritype()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " هەڵوەشایەوە.\n/tritype بنووسە بۆ دووبارە.")
        return
    if action == "start":
        TRITYPE_SESSIONS[str(uid)] = {
            "q_idx": 0,
            "scores": {"5":0,"6":0,"7":0,"2":0,"3":0,"4":0,"8":0,"9":0,"1":0},
            "first_name": query.from_user.first_name or "",
            "username": query.from_user.username or "",
            "chat_id": query.message.chat.id if query.message else 0,
            "order": list(range(len(TRITYPE_QUESTIONS))),
        }
        _save_tritype()
        await _trit_show_question(query, uid, edit=True)
        return
    if action != "ans": return
    sess = TRITYPE_SESSIONS.get(str(uid))
    if not sess:
        await answered(); return
    if sess.get("q_idx", 0) >= len(TRITYPE_QUESTIONS): await answered(); return
    val = int(parts[3]) if len(parts) > 3 else 3
    q_idx = sess["q_idx"]
    q = TRITYPE_QUESTIONS[q_idx]
    sess["scores"][q["type"]] = sess["scores"].get(q["type"], 0) + val
    sess.setdefault("ans_log", []).append({"t": q["type"], "val": val})
    sess["q_idx"] += 1
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]
    if sess["q_idx"] >= len(TRITYPE_QUESTIONS):
        await _trit_show_result(query, uid)
    else:
        await _trit_show_question(query, uid, edit=True)

