# ─── ⋆⋅☆⋅⋆ ───
# کیبۆردی CPT — کاش بۆ خێرایی
# ─── ⋆⋅☆⋅⋆ ───
_CPT_KB_CACHE: dict = {}

async def _cpt_show_question(msg_or_query, uid, edit=False):
    sess = CPT_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(CPT_QUESTIONS)
    if q_idx >= total: return
    _ord = sess.get("order", list(range(total)))
    q = CPT_QUESTIONS[_ord[q_idx] if q_idx < len(_ord) else q_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    dir_icon = {"I": "<tg-emoji emoji-id=\"5863753952549409507\">🟣</tg-emoji>", "A": "<tg-emoji emoji-id=\"5431855765000331501\">🟠</tg-emoji>", "Z": "🔷", "E": "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji>"}.get(q["dir"], "<tg-emoji emoji-id=\"5429482752619615220\">⚪</tg-emoji>")
    text = (
        f"<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>CPT — Cognitive Personality Theory</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}  {dir_icon}  [{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> <b>{q['q']}</b>\n\n"
        f"<i>تا چەندێک ئەم بابەتە لەگەڵت دەگوونجێت؟</i>"
    )
    kb = _cpt_kb(uid, q_idx, total)
    if edit:
        try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        except Exception as _exc:
            if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)
    else:
        await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)

# ─── ⋆⋅☆⋅⋆ ───
# ئەنجام
# ─── ⋆⋅☆⋅⋆ ───

async def cpt_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)

    if action not in ("view",) and str(uid) != str(clicker_uid):
        try: await answered("🔒 ئەم تاقیکردنەوەیە هی تۆ نییە! /cpt بنووسە", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی CPT؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"cpt:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"cpt:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _cpt_show_question(query, uid, edit=True); return
    if action == "cancel":
        CPT_SESSIONS.pop(str(uid), None); _save_cpt()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " هەڵوەشایەوە.\n\n/cpt بنووسە بۆ دووبارەکردنەوە.")
        return

    if action == "start":
        _ord = list(range(len(CPT_QUESTIONS)))
        random.shuffle(_ord)
        CPT_SESSIONS[str(uid)] = {
            "q_idx": 0, "I": 0, "A": 0, "Z": 0, "E": 0,
            "order": _ord, "ans_log": []
        }
        _save_cpt()
        await _cpt_show_question(query, uid, edit=True)
        return

    if action == "back":
        sess = CPT_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess[last["d"]] = max(0, sess.get(last["d"], 0) - last["v"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _save_cpt()
        await answered()
        await _cpt_show_question(query, uid, edit=True)
        return

    if action != "ans": return

    sess = CPT_SESSIONS.get(str(uid))
    if not sess:
        await answered(); return

    if sess.get("q_idx", 0) >= len(CPT_QUESTIONS): await answered(); return
    val = int(parts[3]) if len(parts) > 3 else 3
    q_idx = sess["q_idx"]
    _ord = sess.get("order", list(range(len(CPT_QUESTIONS))))
    q = CPT_QUESTIONS[_ord[q_idx] if q_idx < len(_ord) else q_idx]
    d = q["dir"]
    sess[d] = sess.get(d, 0) + val
    sess.setdefault("ans_log", []).append({"d": d, "v": val})
    sess["q_idx"] += 1
    _save_cpt()

    if sess["q_idx"] >= len(CPT_QUESTIONS):
        await answered()
        await _cpt_show_result(query, uid)
    else:
        await answered()
        await _cpt_show_question(query, uid, edit=True)


