async def _mft_show_question(msg_or_query, uid, edit=False):
    sess = MFT_SESSIONS.get(str(uid))
    if not sess:
        return
    q_idx = sess["q_idx"]
    total = len(MFT_QUESTIONS)
    if q_idx >= total:
        return
    _ord = sess.get("order", list(range(total)))
    q = MFT_QUESTIONS[_ord[q_idx] if q_idx < len(_ord) else q_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    dir_icons = {"C": "<tg-emoji emoji-id=\"5429178965287782978\">💚</tg-emoji>", "F": "<tg-emoji emoji-id=\"5400250414929041085\">⚖️</tg-emoji>", "L": "<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji>", "A": "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>", "S": "<tg-emoji emoji-id=\"5382295780889498241\">🕌</tg-emoji>", "Li": "<tg-emoji emoji-id=\"5911385672437993040\">🗽</tg-emoji>", "P": "<tg-emoji emoji-id=\"6271698656517165534\">📊</tg-emoji>"}
    d_icon = dir_icons.get(q["d"], "<tg-emoji emoji-id=\"5429482752619615220\">⚪</tg-emoji>")
    text = (
        f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji> <b>تێستی بنچینەی ئەخلاقی — MFT</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}  {d_icon}  [{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> <b>{q['q']}</b>\n\n"
        f"<i>تا چەندێک ئەم بابەتە لەگەڵت دەگوونجێت؟</i>"
    )
    kb = _mft_kb(uid, q_idx)
    if edit:
        try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        except Exception as _exc:
            if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)
    else:
        await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)

# ── ئەنجام ──

async def _mft_show_result(query, uid):
    sess = MFT_SESSIONS.pop(str(uid), {})
    _save_mft()

    keys = ["C", "F", "L", "A", "S", "Li", "M"]
    scores = {k: sess.get(k, 0) for k in keys}
    pcts = _mft_pct(scores)
    profile = _mft_get_profile(scores)

    save_test_result(int(uid), "mft", {
        "profile": profile["name"],
        **{f"{k}_pct": pcts[k] for k in keys},
    })

    # بارچارت
    max_v = max(scores.values()) or 1
    bars = ""
    for k, (kname, ename, icon) in MFT_FOUNDATIONS.items():
        bar = _progress_bar(scores[k], max_v, 8)
        bars += f"{icon} <b>{kname}</b>: [{bar}] {pcts[k]}%\n"

    # تایپی سیاسی
    keys_sorted = sorted(scores, key=scores.get, reverse=True)
    top3 = " · ".join(MFT_FOUNDATIONS[k][0] for k in keys_sorted[:3])

    text = (
        f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji> <b>ئەنجامی تێستی بنچینەی ئەخلاقی</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>پرۆفایلت:</b> {profile['name']}\n\n"
        f"{profile['desc']}\n\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TCH} <b>خاڵەکانت بە بنچینە:</b>\n\n"
        f"{bars}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> <b>بنچینەی سەرەکییەکانت:</b> {top3}\n\n"
        f"<i>Moral Foundations Theory — Jonathan Haidt</i>"
    )

    kb = InlineKeyboardMarkup([[
        _ebtn("دووبارە", f"mft:start:{uid}", emoji_id="5353025084845994828", api_kwargs={"style": "success"}),
        _ebtn("داخستن", f"mft:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
    ]])
    await _safe_edit(query, text, reply_markup=kb)

