# ── سێشن ──
JUNG_SESSIONS: dict = {}
_JUNG_KB_CACHE: dict = {}

def _save_jung():
    _test_save(JUNG_SESSIONS, "jung_sessions.json")

# ── Jung option-text: ئارکیەتایپ → کورتترین فرمانی بەرامبەر ──
_JUNG_OPT_PHRASES: dict = {
    "SA": "گەڕانی تێگەیشتن و شیکاری شتەکان",
    "IN": "هیوادارماندن و باوەڕبە باشی ژیان",
    "RL": "کۆنترۆڵ و ئاراستەدانی هەموو شتێک",
    "HR": "هەوڵدانی توانا و چیرەدەستی",
    "MG": "گۆڕانکاری لە ڕێگەی ئاگاییەکی نهێنی",
    "CR": "داهێنانی شتێکی نوێ و یەکتا",
    "EX": "دۆزینەوەی ئیمکانیات و ئازادی",
    "CG": "پاراستن و خزمەت بە کەسانی تر",
    "LV": "پەیوەندیی قووڵ و هەستی گەرمی",
    "JS": "شادی و گرنگدانی بەکاتی ئێستا",
    "EM": "گرێدانی خۆت بە تر و هاوکاری",
    "RB": "هەڵوەشاندنەوەی زنجیرە و گۆڕانکاری",
}

def _jung_kb(uid: int, q_idx: int) -> InlineKeyboardMarkup:
    if q_idx >= len(JUNG_QUESTIONS):
        return InlineKeyboardMarkup([])
    q = JUNG_QUESTIONS[q_idx]
    qt = q.get("t", "4")
    cache_key = f"{qt}:{uid}:{q_idx}"
    if cache_key not in _JUNG_KB_CACHE:
        _cancel = _ebtn("وازهێنان", f"jung:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})
        # ✅ دووگمەی گەڕانەوە — تەنها لە پرسیاری دووەم بەردەوام نیشان دەدرێت
        _prev = _ebtn("گەڕانەوە", f"jung:prev:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"}) if q_idx > 0 else None
        if qt == "4":
            rows = [
                [
                    _ebtn("A", f"jung:ans:{uid}:A", emoji_id="5231070734016607712", api_kwargs={"style": "primary"}),
                    _ebtn("B", f"jung:ans:{uid}:B", emoji_id="5231070734016607712", api_kwargs={"style": "primary"}),
                    _ebtn("C", f"jung:ans:{uid}:C", emoji_id="5231070734016607712", api_kwargs={"style": "primary"}),
                    _ebtn("D", f"jung:ans:{uid}:D", emoji_id="5231070734016607712", api_kwargs={"style": "primary"}),
                ],
                [_prev, _cancel] if _prev else [_cancel],
            ]
        elif qt == "2":
            rows = [
                [
                    _ebtn("A", f"jung:ans:{uid}:A", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
                    _ebtn("B", f"jung:ans:{uid}:B", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
                ],
                [_prev, _cancel] if _prev else [_cancel],
            ]
        else:  # yn
            rows = [
                [
                    _ebtn("بەڵێ", f"jung:ans:{uid}:A", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
                    _ebtn("نەخێر", f"jung:ans:{uid}:B", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
                ],
                [_prev, _cancel] if _prev else [_cancel],
            ]
        _JUNG_KB_CACHE[cache_key] = InlineKeyboardMarkup(rows)
    return _JUNG_KB_CACHE[cache_key]

async def _jung_show_question(msg_or_query, uid: int, edit=False):
    sess = JUNG_SESSIONS.get(str(uid))
    if not sess:
        return
    q_idx = sess["q_idx"]
    total = len(JUNG_QUESTIONS)
    if q_idx >= total:
        return
    q = JUNG_QUESTIONS[q_idx]
    qt = q.get("t", "4")
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)

    # ── بژاردەکان: ئۆتۆماتیک دروستدەکرێت ──
    opts = ""
    if qt == "4":
        if q.get("Aq"):                          # داتای تێکستی ئامادەیە
            opts = (
                f"\n\n<b>A.</b> {q['Aq']}\n"
                f"<b>B.</b> {q['Bq']}\n"
                f"<b>C.</b> {q['Cq']}\n"
                f"<b>D.</b> {q['Dq']}"
            )
        else:                                    # ئۆتۆ: لە ئارکیەتایپ دروست بکە
            def _opt4(key):
                ws = q.get(key, {})
                pri = max(ws, key=ws.get) if ws else ""
                return _JUNG_OPT_PHRASES.get(pri, "بژاردەیەک")
            opts = (
                f"\n\n<b>A.</b> {_opt4('A')}\n"
                f"<b>B.</b> {_opt4('B')}\n"
                f"<b>C.</b> {_opt4('C')}\n"
                f"<b>D.</b> {_opt4('D')}"
            )
    elif qt == "2":
        if q.get("Aq"):
            opts = f"\n\n<b>A.</b> {q['Aq']}\n<b>B.</b> {q['Bq']}"
        else:                                    # "X یان Y؟" → دەرکردنی ئۆتۆماتیک
            _q_text = q.get("q", "")
            _parts  = _q_text.replace("؟", "").split(" یان ")
            if len(_parts) >= 2:
                _a_txt = _parts[0].strip().split()[-1]    # کلیلەی ئاخری بەشی یەکەم
                _b_txt = _parts[1].strip().split()[0]     # کلیلەی یەکەمی بەشی دووەم
                opts = f"\n\n<b>A.</b> {_a_txt}\n<b>B.</b> {_b_txt}"

    text = (
        f"<tg-emoji emoji-id=\"5201914481671682382\">💎</tg-emoji> <b>Jungian Archetypes (PMAI)</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}  [{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> <b>{q['q']}</b>"
        f"{opts}"
    )
    kb = _jung_kb(uid, q_idx)
    if edit:
        try:
            await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        except Exception as _exc:
            _excm = str(_exc).lower()
            if "not modified" not in _excm:
                # ✅ FIX: CallbackQuery.reply_text بوونی نییە — message بەکاردەهێنین
                try:
                    _target = (
                        msg_or_query.message
                        if hasattr(msg_or_query, "message") and msg_or_query.message
                        else msg_or_query
                    )
                    await _target.reply_text(text, parse_mode="HTML", reply_markup=kb)
                except Exception as _e2:
                    logger.error("_jung_show_question fallback failed: %s", _e2)
    else:
        await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)

# ── پولاریتی چێک: کانفلیکتی ئارکیەتایپ ──
_JUNG_POLARITY_PAIRS = [
    ("EX", "EM", "گەڕیدە ↔ هاوڕێ", "ئازادی تا ئاستی بیزاریی لە پەیوەندی بەرامبەر پێویستی پەیوەندی — کێشەی ناوەکی"),
    ("RB", "RL", "یاخی ↔ فەرمانڕەوا", "تێکشکاندنی سیستەم بەرامبەر بونیاتنانی سیستەم — دوو هێزی جەنگکار"),
    ("IN", "SA", "بێتاوان ↔ حەکیم", "خۆشبینیی پێناسەنەکراو بەرامبەر هەستبوون بە قووڵای تاریکی ڕاستی"),
    ("HR", "CG", "پاڵەوان ↔ دایک", "سەرکەوتن لە هەر بارودۆخێک بەرامبەر پاراستنی هەموو کەسێک — ناڕاستی ناوەوە"),
    ("MG", "IN", "جادووگەر ↔ بێتاوان", "کۆنترۆڵکردنی واقیع بەرامبەر پاراستنی سادەیی بێتاوانانە"),
    ("CR", "EM", "داهێنەر ↔ هاوڕێ", "جیاوازی کامڵ بەرامبەر ئارەزووی قبوڵکراوی — ناڕاستی ناسنامە"),
]

async def _jung_show_result(query, uid: int):
    sess = JUNG_SESSIONS.pop(str(uid), {})
    _save_jung()

    arcs = ["CG","RL","CR","IN","SA","EX","RB","MG","HR","LV","JS","EM"]
    scores = {k: round(sess.get(k, 0.0), 2) for k in arcs}
    total_s = sum(scores.values()) or 1.0
    pcts = {k: int((scores[k] / total_s) * 100) for k in arcs}

    sorted_arcs = sorted(arcs, key=lambda k: scores[k], reverse=True)
    dominant_key = sorted_arcs[0]
    support_key  = sorted_arcs[1]
    shadow_key   = sorted_arcs[-1]

    dominant = JUNG_ARCHETYPES[dominant_key]
    support  = JUNG_ARCHETYPES[support_key]
    shadow   = JUNG_ARCHETYPES[shadow_key]

    # پولاریتی چێک
    conflict_txt = ""
    for k1, k2, pair_name, desc in _JUNG_POLARITY_PAIRS:
        if scores[k1] > 0 and scores[k2] > 0:
            ratio = min(scores[k1], scores[k2]) / max(scores[k1], scores[k2])
            if ratio > 0.7:
                conflict_txt += (
                    f"\n<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> "
                    f"<b>{pair_name}</b>: {desc}"
                )

    # بارچارت
    max_v = max(scores.values()) or 1.0
    bars = ""
    for k in sorted_arcs:
        arc = JUNG_ARCHETYPES[k]
        bar = _progress_bar(scores[k], max_v, 7)
        bars += f"{arc['icon']} <b>{arc['name']}</b>: [{bar}] {pcts[k]}%\n"

    text = (
        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>ئارکیەتایپەکانی یۆنگ — ئەنجامەکانت</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"

        f"{_DIV}\n"
        f"{dominant['icon']} <b>ئارکیەتایپی سەرەکی: {dominant['name']}</b>\n"
        f"{_DIV}\n"
        f"{dominant['desc']}\n\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> <b>ئارەزووی بنەڕەتی:</b> {dominant['desire']}\n"
        f"<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> <b>ترسی بنەڕەتی:</b> {dominant['fear']}\n"
        f"<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>لایەنی تاریک:</b> {dominant['shadow']}\n\n"

        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"

        f"{support['icon']} <b>ئارکیەتایپی پاڵپشت: {support['name']}</b>\n"
        f"<i>{support['desc'][:160]}...</i>\n\n"

        f"<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> <b>ئارکیەتایپی سێبەر: {shadow['name']}</b>\n"
        f"<i>ئەم لایەنەی کەسایەتیت ئەو بەشەیە کە کەمترین گەشەی کردووە و زۆرجار نادیدەی دەگریت. کارکردن لەسەر ئەم لایەنە قورسترین بەڵام گرنگترین هەنگاوە بۆ گەیشتن بە هاوسەنگی دەروونی.</i>\n"
        f"<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> ترسی بنەڕەتی: <i>{shadow['fear']}</i>\n"
    )

    if conflict_txt:
        text += (
            f"\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>کێشەی جەمسەرگیری — دوگانەیی ناوەکی:</b>"
            f"{conflict_txt}\n"
            f"<i>ناسینی ئەم جەمسەرانە یارمەتیت دەدات لە ململانێ ناوەکییەکانت تێبگەیت.</i>\n"
        )

    text += (
        f"\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5258274739041883702\">🔍</tg-emoji> <b>پرۆفایلی تەواوی ١٢ ئارکیەتایپ:</b>\n\n"
        f"{bars}\n"
        f"<i>بنەما: پێوەری ئارکیەتایپی پیرسۆن-مار (PMAI) — کارل گوستاڤ یۆنگ</i>"
    )

    save_test_result(int(uid), "jung", {
        "dominant": dominant_key,
        "support": support_key,
        "shadow": shadow_key,
        **{f"{k}_pct": pcts[k] for k in arcs},
    })

    kb = InlineKeyboardMarkup([
        [
            _ebtn("دووبارە", f"jung:start:{uid}", emoji_id="5353025084845994828", api_kwargs={"style": "success"}),
            _ebtn("داخستن", f"jung:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
        ],
        [_ebtn("گەڕانەوە", "menu:back", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})],
    ])
    await _safe_edit(query, text, reply_markup=kb)

