# ── کالبەکی jung ──
async def jung_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    data  = query.data
    parts = data.split(":")
    action = parts[1] if len(parts) > 1 else ""
    uid_str = parts[2] if len(parts) > 2 else str(query.from_user.id)

    if str(query.from_user.id) != uid_str:
        await query.answer("ئەم بەشە بۆ تۆ نییە.", show_alert=True)
        return

    uid = int(uid_str)

    async def answered(txt=""):
        try:
            await query.answer(txt)
        except Exception:
            pass

    # ── دەستپێکردن ──
    if action == "start":
        JUNG_SESSIONS[uid_str] = {
            "q_idx": 0,
            "ans_log": [],   # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> بۆ گەڕانەوەی پرسیاری پێشوو
            **{k: 0.0 for k in JUNG_ARCHETYPES},
        }
        _save_jung()
        _JUNG_KB_CACHE.clear()
        await answered()
        await _jung_show_question(query, uid, edit=True)
        return

    # ── کانسڵ — پشتپرسینەوە ──
    if action == "confirmcancel":
        await answered()
        try:
            await query.edit_message_text(
                "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەکە؟</b>\n\n"
                "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
                "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([
                    [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"jung:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                    [_ebtn("نەخێر، بەردەوام بە",  f"jung:resume:{uid}",  emoji_id="6271611232457855630", api_kwargs={"style": "success"})],
                ]),
            )
        except Exception:
            try:
                await query.message.reply_text(
                    "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئایا دڵنیایت؟",
                    parse_mode="HTML",
                )
            except Exception:
                pass
        return

    # ── کانسڵ — دڵنیاکراوە ──
    if action == "cancel":
        JUNG_SESSIONS.pop(uid_str, None)
        _save_jung()
        await answered()
        try:
            await query.edit_message_text(
                "<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> تێستەکە هەڵوەشایەوە. بۆ دەستپێکردنەوە /jung بنووسە.",
                parse_mode="HTML",
            )
        except Exception:
            try:
                await query.message.reply_text(
                    "<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> تێستەکە هەڵوەشایەوە.",
                    parse_mode="HTML",
                )
            except Exception:
                pass
        return

    # ── بەردەوامبوون — resume ──
    if action == "resume":
        await answered()
        await _jung_show_question(query, uid, edit=True)
        return

    # ── گەڕانەوەی پرسیاری پێشوو ──
    if action == "prev":
        sess = JUNG_SESSIONS.get(uid_str)
        if not sess or sess.get("q_idx", 0) == 0:
            await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            for arc_key, w in last.get("weights", {}).items():
                sess[arc_key] = max(0.0, sess.get(arc_key, 0.0) - w)
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _JUNG_KB_CACHE.clear()
        _save_jung()
        await answered()
        await _jung_show_question(query, uid, edit=True)
        return

    # ── وەڵامدانەوەی پرسیار ──
    if action == "ans":
        choice = parts[3] if len(parts) > 3 else ""
        sess = JUNG_SESSIONS.get(uid_str)
        if not sess:
            await answered("تێستەکە نەدۆزرایەوە. /jung بنووسە.")
            return

        q_idx = sess["q_idx"]
        if q_idx >= len(JUNG_QUESTIONS):
            await answered()
            await _jung_show_result(query, uid)
            return

        q = JUNG_QUESTIONS[q_idx]
        weights = q.get(choice, {})
        for arc_key, w in weights.items():
            sess[arc_key] = sess.get(arc_key, 0.0) + w

        # ✅ FIX: وەڵام تۆمار بکە بۆ گەڕانەوەی پرسیاری پێشوو
        sess.setdefault("ans_log", []).append({"choice": choice, "weights": weights})
        sess["q_idx"] += 1
        _save_jung()

        if sess["q_idx"] >= len(JUNG_QUESTIONS):
            await answered()
            await _jung_show_result(query, uid)
        else:
            await answered()
            await _jung_show_question(query, uid, edit=True)
        return

    await answered()

