async def _align_show_question(msg_or_query, uid, edit=False):
    sess = ALIGN_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(ALIGN_QUESTIONS)
    if q_idx >= total: return
    _sess_ord = sess.get("order", list(range(len(ALIGN_QUESTIONS))))
    q = ALIGN_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    text = (
        f"<tg-emoji emoji-id=\"5400250414929041085\">⚖️</tg-emoji> <b>Alignment</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> {q_idx+1}/{total}\n"
        f"[{bar}] {pct}%\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> <b>{q['q']}</b>\n\n"
        f"<i>تا چەندێک ئەم بابەتە لەگەڵت دەگوونجێت؟</i>"
    )
    kb = InlineKeyboardMarkup([[
        _ebtn("هیچ", f"align:ans:{uid}:1", api_kwargs={"style": "primary"}),
        _ebtn("کەمێک", f"align:ans:{uid}:2", api_kwargs={"style": "primary"}),
        _ebtn("نازانم", f"align:ans:{uid}:3", api_kwargs={"style": "primary"}),
        _ebtn("بەڵێ", f"align:ans:{uid}:4", api_kwargs={"style": "success"}),
        _ebtn("زۆر", f"align:ans:{uid}:5", api_kwargs={"style": "primary"}),
    ], [
        *([ _ebtn("گەڕانەوە", f"align:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"})] if q_idx > 0 else []),
        _ebtn(f"{q_idx+1}/{total}", "noop", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
        _ebtn("وازهێنان", f"align:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
    ]])
    if edit:
        try: await msg_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        except Exception as _exc:
            if "not modified" not in str(_exc).lower(): await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)
    else:
        await msg_or_query.reply_text(text, parse_mode="HTML", reply_markup=kb)

async def alignment_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(query.from_user.id)
    clicker_uid = str(query.from_user.id)
    if action not in ("view",) and str(uid) != str(clicker_uid):
        try: await answered("🔒 ئەم تاقیکردنەوەیە هی تۆ نییە! /alignment بنووسە", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    if action == "back":
        sess = ALIGN_SESSIONS.get(str(uid))
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        _save_align()
        await _align_show_question(query, uid, edit=True); return
    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی Alignment؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"align:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"align:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        await _align_show_question(query, uid, edit=True); return
    if action == "cancel":
        ALIGN_SESSIONS.pop(str(uid), None); _save_align()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, _TGX + " هەڵوەشایەوە.\n\n/alignment بنووسە بۆ دووبارەکردنەوە.")
        return
    if action == "start":
        ALIGN_SESSIONS[str(uid)] = {"q_idx": 0, "L": 0, "C": 0, "G": 0, "E": 0, "order": list(range(len(ALIGN_QUESTIONS)))}
        _save_align()
        await _align_show_question(query, uid, edit=True)
        return
    if action != "ans": return
    sess = ALIGN_SESSIONS.get(str(uid))
    if not sess:
        await answered(); return
    if sess.get("q_idx", 0) >= len(ALIGN_QUESTIONS): await answered(); return
    val = int(parts[3]) if len(parts) > 3 else 3
    q_idx = sess["q_idx"]
    _sess_ord = sess.get("order", list(range(len(ALIGN_QUESTIONS))))
    q = ALIGN_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    sess[q["dir"]] = sess.get(q["dir"], 0) + val
    sess["q_idx"] += 1
    _save_align()
    if sess["q_idx"] >= len(ALIGN_QUESTIONS):
        await _align_show_result(query, uid)
    else:
        await _align_show_question(query, uid, edit=True)

async def notify_owner_private_msg(update: Update, context: CallbackContext):
    """کاتێک کەسێک DM بنێرێت بۆ بۆت، خاوەنەکەی ئاگادار دەکاتەوە"""
    msg = update.message
    if not msg:
        return
    chat = update.effective_chat
    user = update.effective_user

    # تەنیا لە چاتی تایبەت
    if not chat or chat.type != "private":
        return
    # خاوەنی بۆت خۆی DM کردبێت — ئاگادار ناکاتەوە
    if user and user.id == OWNER_ID:
        return

    sender_name = ""
    sender_link = ""
    if user:
        fname = user.first_name or ""
        lname = user.last_name or ""
        sender_name = f"{fname} {lname}".strip()
        username = f"@{user.username}" if user.username else ""
        sender_link = f'<a href="tg://user?id={user.id}">{sender_name}</a>'
        uid_text = f"{user.id}"
        uname_text = username or "—"
    else:
        sender_link = "نەناسراو"
        uid_text = "—"
        uname_text = "—"

    content = msg.text or msg.caption or ""
    content_preview = content[:200] if content else "[ فایل / مێدیا ]"

    text = (
        f"<tg-emoji emoji-id=\"5454113432284446338\">📩</tg-emoji> <b>پەیامی تایبەتی نوێ!</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> نێردەر: {sender_link}\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: <code>{uid_text}</code>\n"
        f"<tg-emoji emoji-id=\"5438343003863292149\">📛</tg-emoji> یوزەرنەیم: {uname_text}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> پەیام:\n{content_preview}"
    )
    # ── دووگمەکانی بەڕێوەبردن ──
    kb = None
    try:
        await context.bot.send_message(
            chat_id=OWNER_ID,
            text=text,
            parse_mode="HTML"
        )
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

async def notify_owner_bot_added(update: Update, context: CallbackContext):
    """کاتێک بۆتەکە بۆ گروپێک زیاد بکرێت یان دەرببکرێت، خاوەنەکەی ئاگادار دەکاتەوە"""
    result = update.my_chat_member
    if not result:
        return

    chat = result.chat
    added_by = result.from_user
    new_status = result.new_chat_member.status
    old_status = result.old_chat_member.status

    chat_name = chat.title or chat.username or str(chat.id)
    chat_id = chat.id
    chat_type = {"group": "گروپ", "supergroup": "سوپەرگروپ", "channel": "چەناڵ"}.get(chat.type, chat.type)

    adder_name = ""
    adder_link = ""
    if added_by:
        fname = added_by.first_name or ""
        lname = added_by.last_name or ""
        adder_name = f"{fname} {lname}".strip()
        adder_link = f'<a href="tg://user?id={added_by.id}">{adder_name}</a>'
        uid_text = str(added_by.id)
        uname_text = f"@{added_by.username}" if added_by.username else "—"
    else:
        adder_link = "نەناسراو"
        uid_text = "—"
        uname_text = "—"

    # دیاریکردنی جۆری ئەکشن
    if old_status in ("left", "kicked") and new_status == "member":
        action = f"{_TCK} زیادکرا"
        emoji = "<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji>"
    elif old_status == "member" and new_status in ("left", "kicked"):
        action = _TGX + " دەرکرا / چووەدەرەوە"
        emoji = "<tg-emoji emoji-id=\"5456337168781810982\">😢</tg-emoji>"
    elif new_status == "administrator":
        action = "<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئادمین کرا"
        emoji = "<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>"
    elif old_status == "administrator" and new_status == "member":
        action = "<tg-emoji emoji-id=\"5443127283898405358\">⬇️</tg-emoji> ئادمینێتی لادرا"
        emoji = "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji>"
    else:
        return  # گۆڕانکارییەکی گرنگ نییە

    text = (
        f"{emoji} <b>بۆت لە {chat_type}ێک {action}!</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"6024112973226709843\">📢</tg-emoji> ناوی {chat_type}: <b>{chat_name}</b>\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: <code>{chat_id}</code>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> کەسێک کردی: {adder_link}\n"
        f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: <code>{uid_text}</code>\n"
        f"<tg-emoji emoji-id=\"5438343003863292149\">📛</tg-emoji> یوزەرنەیم: {uname_text}"
    )
    try:
        await context.bot.send_message(
            chat_id=OWNER_ID,
            text=text,
            parse_mode="HTML"
        )
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored


