@guarded
async def compare_cmd(update: Update, context: CallbackContext):
    """بەراوردکردنی ئەنجامی تێستەکان"""

    # ئەگەر @user یان reply هەبوو → بەراوردی دوو بەکارهێنەر
    if (context.args and context.args[0]) or (update.message and update.message.reply_to_message):
        await compare_users_cmd(update, context)
        return

    uid = update.effective_user.id
    ud = get_user_data(uid)
    results = ud.get("test_results", {})

    if len(results) < 2:
        await update.message.reply_text(
            _TGX + " پێویستە لانیکەم ٢ تێست تەواو کردبیت بۆ بەراوردکردن!\n"
            "<tg-emoji emoji-id=\"5341583133055669788\">➡</tg-emoji> /testprofile بۆ بینینی تێستەکانت",
            parse_mode="HTML"
        )
        return

    # دۆزینەوەی بەراوردکردنە بەردەستەکان
    available = []
    for pair_key, pair in COMPARE_PAIRS.items():
        if pair["key1"] in results and pair["key2"] in results:
            available.append((pair_key, pair))

    if not available:
        done_list = ", ".join(TEST_META.get(k, ("", k))[1] for k in results.keys())
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> هیچ بەراوردکردنێکی بەردەست نییە بۆ تێستە تەواوکراوەکانت.\n\n"
            f"تێستە تەواوکراوەکانت: {done_list}\n\n"
            f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> پێشنیار: تێستی MBTI و Socionics تەواو بکە بۆ بەراوردکردن!"
        , parse_mode="HTML")
        return

    keyboard = []
    for pair_key, pair in available:
        keyboard.append([_ebtn(f"{pair['title']}", f"cmp:{pair_key}", api_kwargs={"style": "primary"})])
    keyboard.append([_ebtn("گەڕانەوە", "cmp:back", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])

    text = (
        f"╔══════════════╗\n"
        f"║  <tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> بەراوردکردنی تێستەکان  ║\n"
        f"╚══════════════╝\n\n"
        f"{_TCH} <b>{len(available)}</b> بەراوردکردن بەردەستە بۆت:\n\n"
        f"هەر یەکێک هەڵبژێرە بۆ بینینی شیکاری قووڵ:"
    )

    await update.message.reply_text(
        text,
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )

async def compare_callback(update: Update, context: CallbackContext):
    """کاڵباکی بەراوردکردن"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()

    data = query.data  # cmp:mbti_socionics / cmp:back
    parts = data.split(":")

    if len(parts) < 2:
        return

    action = parts[1]

    if action == "back":
        await query.message.delete()
        return

    if action == "menu":
        # نیشاندانی مینیوی بەراوردکردنەکان
        uid = query.from_user.id
        ud = get_user_data(uid)
        results = ud.get("test_results", {})
        available = []
        for pk, pp in COMPARE_PAIRS.items():
            if pp["key1"] in results and pp["key2"] in results:
                available.append((pk, pp))

        keyboard = []
        for pk, pp in available:
            keyboard.append([_ebtn(f"{pp['title']}", f"cmp:{pk}", api_kwargs={"style": "primary"})])
        keyboard.append([_ebtn("داخستن", "cmp:back", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])

        text = (
            f"╔══════════════╗\n"
            f"║  <tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> بەراوردکردنی تێستەکان  ║\n"
            f"╚══════════════╝\n\n"
            f"{_TCH} <b>{len(available)}</b> بەراوردکردن بەردەستە:"
        )
        try:
            await query.message.edit_text(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(keyboard))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    pair_key = action
    if pair_key not in COMPARE_PAIRS:
        await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> بەراوردکردنەکە نەدۆزرایەوە")
        return

    uid = query.from_user.id
    ud = get_user_data(uid)
    results = ud.get("test_results", {})

    pair = COMPARE_PAIRS[pair_key]

    if pair["key1"] not in results or pair["key2"] not in results:
        await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> هەردوو تێستەکە تەواو نەکراون!")
        return

    r1 = results[pair["key1"]]
    r2 = results[pair["key2"]]

    # بانگکردنی فەنکشنی شیکاری
    analyze_fn = pair["analyze"]
    fn_map = {
        "_compare_mbti_socionics": _compare_mbti_socionics,
        "_compare_mbti_enneagram": _compare_mbti_enneagram,
        "_compare_mbti_bigfive": _compare_mbti_bigfive,
        "_compare_ennea_instinct": _compare_ennea_instinct,
        "_compare_ennea_tritype": _compare_ennea_tritype,
        "_compare_darktri_darkempath": _compare_darktri_darkempath,
        "_compare_mbti_temperament": _compare_mbti_temperament,
        "_compare_bigfive_darktri": _compare_bigfive_darktri,
        "_compare_socionics_ennea": _compare_socionics_ennea,
        "_compare_bigfive_temperament": _compare_bigfive_temperament,
        "_compare_attachment_lovelang": _compare_attachment_lovelang,
        "_compare_mbti_alignment": _compare_mbti_alignment,
        "_compare_eq_bigfive": _compare_eq_bigfive,
        "_compare_panas_bigfive": _compare_panas_bigfive,
        "_compare_ennea_darktri": _compare_ennea_darktri,
        "_compare_selfesteem_darktri": _compare_selfesteem_darktri,
        "_compare_via_values": _compare_via_values,
        "_compare_cpt_mbti": _compare_cpt_mbti,
        "_compare_mft_alignment": _compare_mft_alignment,
        "_compare_hsp_panas": _compare_hsp_panas,
        "_compare_cognitive_eq": _compare_cognitive_eq,
        "_compare_socionics_temperament": _compare_socionics_temperament,
    }

    fn = fn_map.get(analyze_fn)
    if not fn:
        await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> شیکاری بەردەست نییە")
        return

    analysis_text, match_pct = fn(r1, r2, pair)
    match_em = _match_emoji(match_pct)
    match_bar = _pct_bar(match_pct, "سازگاری", 10)

    text = (
        f"╔══════════════╗\n"
        f"║  <tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> {pair['title']}  ║\n"
        f"╚══════════════╝\n\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <i>{pair['desc']}</i>\n\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"{analysis_text}\n\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{match_em} <code>{match_bar}</code>\n\n"
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> بەروار: {r1.get('date', '?')} | {r2.get('date', '?')}"
    )

    keyboard = [
        [_ebtn("بەراوردکردنەکانی تر", "cmp:menu", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})],
    ]

    try:
        await query.message.edit_text(
            text,
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
    except Exception:
        await query.message.reply_text(
            text,
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(keyboard)
        )



