async def _wx_cb(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    data  = query.data          # wx:now:ll:36.19:44.00 / wx:now:Erbil / wx:forecast:Erbil / wx:kurdistan
    parts = data.split(":", 4)
    action = parts[1] if len(parts) > 1 else ""
    # پشتیوانی لە wx:now:ll:lat:lon (lat/lon نوێ) و wx:now:Erbil (ناوی شار کۆن)
    if len(parts) >= 5 and parts[2] == "ll":
        city = f"ll:{parts[3]}:{parts[4]}"   # → "ll:36.19:44.00" بۆ _fetch_weather
    elif len(parts) > 3 and parts[2] == "id":
        city = f"id:{parts[3]}"   # پشتیوانی کۆن
    else:
        city = parts[2] if len(parts) > 2 else ""

    if action == "now" and city:
        d = await _fetch_weather(city)
        if d:
            city_safe = city[:48]   # ── FIX #1: بڕکردنی city بۆ callback_data ──
            try:
                await _safe_edit(query, _build_current(d, city_safe), reply_markup=_wx_kb(city_safe))
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        else:
            await answered("❌" + " کێشەیەک هەیە", show_alert=True)

    elif action == "forecast" and city:
        d = await _fetch_forecast(city)
        if d:
            city_safe = city[:48]   # ── FIX #1: بڕکردنی city بۆ callback_data ──
            kb = InlineKeyboardMarkup([
                [_ebtn("کەشوهەوای ئێستا", f"wx:now:{city_safe}", api_kwargs={"style": "primary", "icon_custom_emoji_id": "5201827869361188827"}),
                 _ebtn("زانیاری تر", f"wx:details:{city_safe}", api_kwargs={"style": "primary", "icon_custom_emoji_id": "5382021607357162402"})],
                [_ebtn("گەڕانەوە", "menu:weather", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})],
            ])
            try:
                await _safe_edit(query, _build_forecast(d, city_safe), reply_markup=kb)
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        else:
            await answered("❌" + " کێشەیەک هەیە", show_alert=True)

    elif action == "details" and city:
        d = await _fetch_weather(city)
        if d:
            city_safe = city[:48]   # ── FIX #1: بڕکردنی city بۆ callback_data ──
            kb = InlineKeyboardMarkup([
                [_ebtn("کەشوهەوای ئێستا", f"wx:now:{city_safe}", api_kwargs={"style": "primary", "icon_custom_emoji_id": "5201827869361188827"}),
                 _ebtn("پێشبینی ٥ ڕۆژ", f"wx:forecast:{city_safe}", emoji_id="5274055917766202507", api_kwargs={"style": "primary"})],
                [_ebtn("گەڕانەوە", "menu:weather", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})],
            ])
            try:
                await _safe_edit(query, _build_details(d, city_safe), reply_markup=kb)
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        else:
            await answered("❌" + " کێشەیەک هەیە", show_alert=True)

    elif action == "kurdistan":
        # شارانێک کە City ID تایبەتیان هەیە بۆ OWM، ئەوانیش کە بە ناو دەگەڕێن
        rows = []
        for i in range(0, len(KURDISTAN_CITIES), 2):
            row = []
            for lbl, en_name, lat, lon in KURDISTAN_CITIES[i:i+2]:
                cb = f"wx:now:ll:{lat}:{lon}"
                row.append(_ebtn(lbl, cb, api_kwargs={"style": "primary"}))
            rows.append(row)
        rows.append([_ebtn("گەڕانەوە", "menu:weather", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
        try:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> <b>شارەکانی کوردستان</b>\n\nشارێک هەڵبژێرە:", reply_markup=InlineKeyboardMarkup(rows))
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

async def _tprofile_cb(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    parts = query.data.split(":")
    if len(parts) >= 3 and parts[1] == "refresh":
        try:
            target_id = int(parts[2])
        except (ValueError, IndexError):
            target_id = query.from_user.id
        await testprofile_callback(query, target_id)
        return
    if len(parts) >= 3 and parts[1] == "compare":
        try:
            target_id = int(parts[2])
        except (ValueError, IndexError):
            target_id = query.from_user.id
        my_id = query.from_user.id
        # بچۆ بۆ مێنیوی بەراوردکردن — ucmp:myid:targetid:menu
        my_ud = get_user_data(my_id)
        target_ud = get_user_data(target_id)
        my_results = my_ud.get("test_results", {})
        target_results = target_ud.get("test_results", {})
        common = set(my_results.keys()) & set(target_results.keys()) & set(TEST_META.keys())
        my_name = my_ud.get("first_name", str(my_id))
        try:
            target_chat = await context.bot.get_chat(target_id)
            target_name = target_chat.first_name or str(target_id)
        except Exception:
            target_name = target_ud.get("first_name", str(target_id))
        keyboard = []
        for t in sorted(common):
            emoji, name = TEST_META.get(t, ("?", t))
            keyboard.append([_ebtn(f"{emoji} {name}", f"ucmp:{my_id}:{target_id}:{t}", api_kwargs={"style": "primary"})])
        keyboard.append([_ebtn("هەمووی", f"ucmp:{my_id}:{target_id}:all", emoji_id="6271698656517165534", api_kwargs={"style": "primary"})])
        keyboard.append([_ebtn("داخستن", "ucmp:close", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
        text = (
            f"╔══════════════╗\n"
            f"║  <tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> بەراوردی دوو بەکارهێنەر  ║\n"
            f"╚══════════════╝\n\n"
            f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> <b>{_html_escape(my_name)}</b>  ⟷  <tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> <b>{_html_escape(target_name)}</b>\n\n"
            f"<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> تێستی هاوبەش: <b>{len(common)}</b>\n\n"
            f"تێستێک هەڵبژێرە:"
        )
        try:
            await query.message.edit_text(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(keyboard))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    user = query.from_user

    # _html_escape() گلۆبەل بەکاردێت — closure لادەبرا

    try:
        # ── بایۆ ──
        bio = ""
        try:
            chat_info = await context.bot.get_chat(user.id)
            bio = chat_info.bio or ""
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        # ── داتای بۆت ──
        bot_data = get_user_data(user.id)
        level   = bot_data.get("level", 1)
        points  = bot_data.get("points", 0)
        coins   = bot_data.get("coins", 0)
        msgs    = bot_data.get("messages", 0)
        rank    = get_user_rank(level)
        joined  = bot_data.get("joined_date", "")
        if joined:
            try:
                joined = datetime.datetime.fromisoformat(joined).strftime("%Y/%m/%d")
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        full_name  = f"{user.first_name or ''} {user.last_name or ''}".strip() or "نەزانراو"
        username   = f"@{user.username}" if user.username else "نییە"
        language   = user.language_code or "نەزانراو"
        is_premium = f"{_TCK} بەڵێ" if getattr(user, 'is_premium', False) else _TGX + " نییە"

        # ── دروستکردنی تێکست ──
        text = (
            f"<b><tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> زانیارییەکانی ئەکاونت</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5319118551427078910\">🆔</tg-emoji> ئایدی: <code>{user.id}</code>\n"
            f"<tg-emoji emoji-id=\"5438343003863292149\">📛</tg-emoji> ناو: {_html_escape(full_name)}\n"
            f"<tg-emoji emoji-id=\"5472411062412254753\">🔤</tg-emoji> ناسناو: {_html_escape(username)}\n"
            f"<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> زمان: {_html_escape(language)}\n"
            f"{_TDM} پریمیۆم: {is_premium}\n"
        )
        if bio:
            text += f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بایۆ: {_html_escape(bio)}\n"
        text += (
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> ئامارەکانی ناو بۆت:\n"
            f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئاست: {level} | {rank}\n"
            f"<tg-emoji emoji-id=\"5789828777882162072\">🏅</tg-emoji> خاڵ: {points:,}\n"
            f"{_TMN} کۆین: {coins:,}\n"
            f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> پەیامەکان: {msgs:,}\n"
        )
        if joined:
            text += f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> بەشداریکردن: {_html_escape(joined)}"

        kb = InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "profile:info", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})]])

        # ── وێنەی پڕۆفایل ──
        photo_id = None
        try:
            photos = await context.bot.get_user_profile_photos(user.id, limit=1)
            if photos and photos.total_count > 0:
                photo_id = photos.photos[0][-1].file_id
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        chat_id = query.message.chat.id

        if photo_id:
            # پەیامی کۆن بسڕە، وێنەی نوێ بنێرە
            try:
                await query.message.delete()
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
            try:
                await context.bot.send_photo(
                    chat_id=chat_id,
                    photo=photo_id,
                    caption=text,
                    parse_mode="HTML"
                )
            except Exception as _pe:
                logger.warning("show_my_id photo error: %s", _pe)
                # fallback بۆ تەکست
                try:
                    await context.bot.send_message(
                        chat_id=chat_id, text=text,
                        parse_mode="HTML"
                    )
                except Exception as _e:
                    logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        else:
            # وێنە نییە — پەیامی کۆن دەستکاری بکە
            try:
                await _safe_edit(query, text, reply_markup=kb)
            except Exception:
                try:
                    await context.bot.send_message(
                        chat_id=chat_id, text=text,
                        parse_mode="HTML"
                    )
                except Exception as _ex:
                    logger.error("show_my_id send error: %s", _ex)

    except Exception as e:
        logger.error(f"show_my_id error: {e}", exc_info=True)
        try:
            await _safe_edit(query, "ببورە، هەڵەیەک ڕوویدا.\nتکایە دووبارە هەوڵ بدەرەوە.", reply_markup=InlineKeyboardMarkup([[_ebtn("گەڕانەوە", "profile:info", emoji_id="6271611232457855630", api_kwargs={"style": "primary"})]]))
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

