@guarded
async def chatstats_cmd(update: Update, context: CallbackContext):
    uid = str(update.effective_user.id)
    cid = str(update.effective_chat.id)
    args = context.args or []

    # ئامارگری گشتی گرووپ ئەگەر پارامیتری "group" هاتبوو
    if args and args[0] == "group":
        chat_data = CSTAT.get(cid, {})
        if not chat_data:
            await update.message.reply_text(f"{_TCH} هیچ داتایەک نییە.", parse_mode="HTML"); return

        # ئەوەی زیاتر reply کردووە
        totals = {u: sum(v.values()) for u, v in chat_data.items()}
        top = sorted(totals.items(), key=lambda x: x[1], reverse=True)[:10]
        medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"]+["▪️"]*7
        lines = "\n".join(f"{medals[i]} <code>{u}</code>: {c}" for i,(u,c) in enumerate(top))
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> <b>باشترین چاتکارانی گرووپ</b>\n\n{lines}",
            parse_mode="HTML"
        )
        return

    my = CSTAT.get(cid, {}).get(uid, {})
    if not my:
        await update.message.reply_text(
            f"{_TCH} هیچ ئامارێکی پەیوەندیت نییە!\n\n"
            "ئامار کاتێک reply دەکەیت تۆمار دەکرێت.",
            parse_mode="HTML"
        ); return

    top = sorted(my.items(), key=lambda x: x[1], reverse=True)[:10]
    total = sum(my.values())
    medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"]+["▪️"]*7
    lines = ""
    for i,(tid,cnt) in enumerate(top):
        pct = int((cnt/total)*100)
        bar = "█"*(pct//10) + "░"*(10-pct//10)
        lines += f"{medals[i]} <code>{tid}</code>: [{bar}] {cnt} ({pct}%)\n"

    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> <b>ئامارگری پەیوەندیت</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"{_TCH} کۆی replyکراو: {total}\n\n"
        f"زیاتر reply دەکەیت بۆ:\n\n"
        f"{lines}\n"
        f"<i>/chatstats group — ئامارگری گرووپ</i>",
        parse_mode="HTML"
    )


