async def today_callback(update: Update, context: CallbackContext):
    q = update.callback_query
    answered = _make_answerer(q)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> spinner
    now = datetime.datetime.now()
    # دووترین ئێوێنتی نزیک
    future = []
    for (m, d), (y, ev) in _TODAY_DB.items():
        try:
            ev_date = datetime.datetime(now.year, m, d)
            if ev_date < now: ev_date = ev_date.replace(year=now.year+1)
            future.append((ev_date, y, ev))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    future.sort(key=lambda x: x[0])
    if future:
        nd, ny, nev = future[0]
        days_left = (nd - now).days
        try:
            await _safe_edit(q, f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> <b>نزیکترین ئێوێنت</b>\n\n"
                f"<tg-emoji emoji-id=\"5395344333916376249\">🗓</tg-emoji> {nd.strftime('%d/%m/%Y')} — {days_left} ڕۆژی ماوە\n\n"
                f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> [{ny}] {nev}")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
