@guarded
async def antiraid_cmd(update: Update, context: CallbackContext):
    user = update.effective_user
    chat = update.effective_chat

    # تەنها ئادمین
    try:
        m = await context.bot.get_chat_member(chat.id, user.id)
        if m.status not in ("administrator", "creator") and user.id != OWNER_ID:
            await update.message.reply_text(_TGX + " تەنها ئادمینەکان!", parse_mode="HTML"); return

    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

    cid = str(chat.id)
    cfg = ANTIRAID_DATA.setdefault(cid, dict(_ANTIRAID_DEFAULTS))
    enabled = cfg.get("enabled", False)
    action_labels = {"mute": "<tg-emoji emoji-id=\"5379904450473273365\">🔇</tg-emoji> بێدەنگ", "kick": "👢 دەرکردن", "ban": "<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> بان"}

    kb = InlineKeyboardMarkup([
        [_ebtn(f"{_TCK + ' چالاک' if enabled else _TGX + ' ناچالاک'} — {'ناچالاک بکە' if enabled else 'چالاک بکە'}", f"ar2:toggle:{cid}", api_kwargs={"style": "danger"})],
        [
            _ebtn("میوت" + ("" if cfg["action"]=="mute" else ""), f"ar2:action:mute:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
            _ebtn("دەرکردن" + ("" if cfg["action"]=="kick" else ""), f"ar2:action:kick:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
            _ebtn("بان" + ("" if cfg["action"]=="ban" else ""), f"ar2:action:ban:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
        ],
        [
            _ebtn(f"کەم (٣/١٠s)" + ("" if cfg["threshold"]==3 else ""), f"ar2:sens:low:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
            _ebtn(f"مامناوەند (٥/١٠s)" + ("" if cfg["threshold"]==5 else ""), f"ar2:sens:mid:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
            _ebtn(f"بەرز (٨/١٥s)" + ("" if cfg["threshold"]==8 else ""), f"ar2:sens:high:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
        ],
    ])

    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> <b>سیستەمی Anti-Raid</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"باری ئێستا: {_TCK + ' چالاک' if enabled else _TGX + ' ناچالاک'}\n"
        f"کردار: {action_labels.get(cfg['action'], cfg['action'])}\n"
        f"ئاست: {cfg['threshold']} کەس لە {cfg['window']} چرکەدا\n\n"
        f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> ئەگەر ژمارەی جۆینکردن لە ئاستەکەی باڵاتر بوو،\n"
        f"بۆتەکە ئۆتۆماتیک کردار دەکات.",
        parse_mode="HTML"
    )

async def antiraid_callback(update: Update, context: CallbackContext):
    q = update.callback_query
    answered = _make_answerer(update.callback_query)
    await answered()
    parts = q.data.split(":")
    if len(parts) < 2: return
    action = parts[1]

    if action == "toggle":
        if len(parts) < 3: return
        cid = parts[2]
        cfg = ANTIRAID_DATA.setdefault(cid, dict(_ANTIRAID_DEFAULTS))
        cfg["enabled"] = not cfg.get("enabled", False)
        _save_antiraid()
        state = "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> چالاک کرا" if cfg["enabled"] else "<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> ناچالاک کرا"
        await answered(f"🛡️ Anti-Raid {state}", show_alert=True)
        # نوێکردنەوەی پەیام
        action_labels = {"mute": "<tg-emoji emoji-id=\"5379904450473273365\">🔇</tg-emoji> بێدەنگ", "kick": "👢 دەرکردن", "ban": "<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> بان"}
        enabled = cfg["enabled"]
        kb = InlineKeyboardMarkup([
            [_ebtn(f"{_TCK + ' چالاک' if enabled else _TGX + ' ناچالاک'} — {'ناچالاک بکە' if enabled else 'چالاک بکە'}", f"ar2:toggle:{cid}", api_kwargs={"style": "danger"})],
            [
                _ebtn("میوت" + ("" if cfg["action"]=="mute" else ""), f"ar2:action:mute:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
                _ebtn("دەرکردن" + ("" if cfg["action"]=="kick" else ""), f"ar2:action:kick:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
                _ebtn("بان" + ("" if cfg["action"]=="ban" else ""), f"ar2:action:ban:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
            ],
            [
                _ebtn(f"کەم" + ("" if cfg["threshold"]==3 else ""), f"ar2:sens:low:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
                _ebtn(f"مامناوەند" + ("" if cfg["threshold"]==5 else ""), f"ar2:sens:mid:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
                _ebtn(f"بەرز" + ("" if cfg["threshold"]==8 else ""), f"ar2:sens:high:{cid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"}),
            ],
        ])
        try:
            await q.edit_message_reply_markup(reply_markup=kb)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

    elif action == "action":
        act = parts[2]; cid = parts[3]
        cfg = ANTIRAID_DATA.setdefault(cid, dict(_ANTIRAID_DEFAULTS))
        cfg["action"] = act
        _save_antiraid()
        labels = {"mute": "<tg-emoji emoji-id=\"5379904450473273365\">🔇</tg-emoji> میوت", "kick": "👢 دەرکردن", "ban": "<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> بان"}
        await answered(f"✅ کردار: {labels.get(act, act)}", show_alert=True)

    elif action == "sens":
        level = parts[2]; cid = parts[3]
        cfg = ANTIRAID_DATA.setdefault(cid, dict(_ANTIRAID_DEFAULTS))
        if level == "low":   cfg["threshold"] = 3;  cfg["window"] = 10
        elif level == "mid": cfg["threshold"] = 5;  cfg["window"] = 10
        elif level == "high":cfg["threshold"] = 8;  cfg["window"] = 15
        _save_antiraid()
        await answered(f"✅ ئاستی هەستیاری نوێکرا", show_alert=True)

async def _antiraid_check_join(update: Update, context: CallbackContext):
    """هەر کاتێک کەسێک جۆین دەکات ئەمە پەیوەست دەکرێت"""
    chat = update.effective_chat
    if not chat: return
    cid = str(chat.id)
    cfg = ANTIRAID_DATA.get(cid, {})
    if not cfg.get("enabled"): return

    now = time.time()
    threshold = cfg.get("threshold", 5)
    window = cfg.get("window", 10)
    act = cfg.get("action", "mute")

    # تۆمارکردنی کاتی جۆینکردن
    _RAID_JOIN_LOG.setdefault(cid, [])
    _RAID_JOIN_LOG[cid] = [t for t in _RAID_JOIN_LOG[cid] if now - t < window]
    _RAID_JOIN_LOG[cid].append(now)

    count = len(_RAID_JOIN_LOG[cid])
    if count < threshold: return

    # <tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> RAID تەشخیسکرا!
    _RAID_JOIN_LOG[cid] = []  # ڕیسێت بکەرەوە

    try:
        member = update.effective_member or update.message.new_chat_members[0] if update.message else None
        new_user = member.user if member else None
    except Exception:
        new_user = None

    alert_txt = (
        f"<tg-emoji emoji-id=\"5823259308665607384\">🚨</tg-emoji> <b>RAID تەشخیسکرا!</b>\n\n"
        f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> {count} کەس لە {window} چرکەدا جۆین کرد!\n"
        f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> کردار: <b>{act}</b> لەسەر نوێترین جۆینکەر."
    )

    if new_user:
        try:
            if act == "mute":
                until = int(now) + 3600
                await context.bot.restrict_chat_member(
                    chat.id, new_user.id,
                    permissions=ChatPermissions(can_send_messages=False),
                    until_date=until
                )
            elif act == "kick":
                await context.bot.ban_chat_member(chat.id, new_user.id)
                await context.bot.unban_chat_member(chat.id, new_user.id)
            elif act == "ban":
                await context.bot.ban_chat_member(chat.id, new_user.id)
        except Exception as e:
            alert_txt += f"\n{_TGX} هەڵە: {e}"

    if cfg.get("alert", True):
        try:
            await context.bot.send_message(chat.id, alert_txt, parse_mode="HTML")
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored


