async def dna_callback(update: Update, context: CallbackContext):
    q = update.callback_query
    answered = _make_answerer(update.callback_query)
    await answered()
    parts = q.data.split(":")
    if len(parts) < 2: return
    action = parts[1]

    if action == "refresh":
        if len(parts) < 3: return
        uid  = parts[2]
        d = DNA_DATA.get(uid)
        if not d:
            try: await q.answer("DNA نەدۆزرایەوە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        coins = COINS.get(uid, 0)
        d["xp_bonus"] = min(200, coins // 100)
        _save_dna()
        try:
            kb = InlineKeyboardMarkup([
                [_ebtn("DNA تێکەڵ بکە", f"dna:mix_prompt:{uid}", emoji_id="5381961872952038862", api_kwargs={"style": "primary"}),
                 _ebtn("باشترینان", "dna:top", emoji_id="6271698656517165534", api_kwargs={"style": "primary"})],
                [_ebtn("نوێکردنەوە", f"dna:refresh:{uid}", emoji_id="5353025084845994828", api_kwargs={"style": "primary"})],
            ])
            await _safe_edit(q, _dna_card(d, uid), reply_markup=kb)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    elif action == "top":
        if not DNA_DATA:
            await answered("هێشتا DNA تۆمارنەکراوە!", show_alert=True); return
        scored = []
        for uid2, d2 in DNA_DATA.items():
            total = sum(d2["traits"].values()) + d2.get("xp_bonus", 0)
            pers, _ = _dna_personality(d2["traits"])
            scored.append((total, d2["name"], pers))
        scored.sort(reverse=True)
        medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"]
        lines = ["<tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> <b>باشترین DNAکان</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"]
        for i, (total, name, pers) in enumerate(scored[:10]):
            m = medals[i] if i < 3 else f"{i+1}."
            lines.append(f"{m} {name} — {pers} ({total}pt)")
        await _safe_edit(q, "\n".join(lines), reply_markup=InlineKeyboardMarkup([[
                _ebtn("گەڕانەوە", f"dna:refresh:{q.from_user.id}", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})
            ]]))

    elif action == "mix_prompt":
        await _safe_edit(q, "<tg-emoji emoji-id=\"5381961872952038862\">🧪</tg-emoji> <b>DNA تێکەڵ بکە</b>\n\n"
            "بۆ تێکەڵکردنی DNA بنووسە:\n"
            "<code>/dnamix @یوزەرنەیم</code>\n\n"
            "یان reply بکە بەسەر پەیامی کەسێک و بنووسە /dnamix", reply_markup=InlineKeyboardMarkup([[
                _ebtn("گەڕانەوە", f"dna:refresh:{parts[2]}", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})
            ]]))

    elif action == "mix_confirm":
        uid1, uid2 = parts[2], parts[3]
        await _do_dna_mix(q, uid1, uid2, answered=answered)

@guarded
async def dnamix_cmd(update: Update, context: CallbackContext):
    user = update.effective_user
    uid1 = str(user.id)
    name1 = user.first_name or "کەس"
    _get_dna(uid1, name1)

    # دۆزینەوەی کەسی دووەم
    uid2 = None; name2 = None
    if update.message.reply_to_message and update.message.reply_to_message.from_user:
        t = update.message.reply_to_message.from_user
        if not t.is_bot:
            uid2 = str(t.id); name2 = t.first_name or "کەس"
    elif context.args:
        uname = context.args[0].lstrip("@")
        for uid_t, d_t in DNA_DATA.items():
            if d_t.get("name", "").lower() == uname.lower():
                uid2 = uid_t; name2 = d_t["name"]; break
        if not uid2:
            await update.message.reply_text(
                f"{_TGX} <b>{uname}</b> تا ئێستا /dna نەبینیوە!\n"
                "پێشتر با ئەو کەسە /dna بنووسێت.",
                parse_mode="HTML"); return

    if not uid2:
        await update.message.reply_text(
            _TGX + " تکایە reply بکە بەسەر پەیامی کەسێک یان بنووسە:\n"
            "<code>/dnamix @یوزەرنەیم</code>", parse_mode="HTML"); return

    if uid1 == uid2:
        await update.message.reply_text(_TGX + " ناتوانیت DNA ی خۆت لەگەڵ خۆت تێکەڵ بکەیت! 😅", parse_mode="HTML"); return


    _get_dna(uid2, name2)

    kb = InlineKeyboardMarkup([[
        _ebtn("بەڵێ، تێکەڵ بکە!", f"dna:mix_confirm:{uid1}:{uid2}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}),
        _ebtn("نەخێر", f"dna:refresh:{uid1}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
    ]])
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5381961872952038862\">🧪</tg-emoji> <b>DNA تێکەڵ بکە</b>\n\n"
        f"<tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> {name1}  ×  {name2} <tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji>\n\n"
        f"دوای تێکەڵکردن مووجودی نوێ دروست دەبێت!\n"
        f"ئایا دڵنیایت؟",
        parse_mode="HTML"
    )

async def _do_dna_mix(q, uid1: str, uid2: str, answered=None):
    """{_TCK} FIX v34: answered پارامەتەری زیادکرا — spinner دادانەوە"""
    d1 = DNA_DATA.get(uid1)
    d2 = DNA_DATA.get(uid2)
    if not d1 or not d2:
        if answered:
            await answered("DNA نەدۆزرایەوە!", show_alert=True)
        else:
            try: await q.answer("DNA نەدۆزرایەوە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
        return

    # دروستکردنی مووجودی نوێ — تێکەڵی دوو کەس
    child_uid = f"child_{uid1}_{uid2}"
    child_name = f"<tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> {d1['name'][:6]}+{d2['name'][:6]}"
    child_traits = {}
    for _, _, tkey in _DNA_TRAITS:
        v1 = d1["traits"].get(tkey, 50)
        v2 = d2["traits"].get(tkey, 50)
        # هەندێک تایبەتمەندی لە دایک، هەندێکی تر لە باوک
        child_traits[tkey] = int(random.uniform(min(v1,v2) * 0.9, max(v1,v2) * 1.1))
        child_traits[tkey] = max(10, min(100, child_traits[tkey]))

    # میوتەیشن — %20 بونوسی تایبەت
    mut_key = random.choice([t[2] for t in _DNA_TRAITS])
    child_traits[mut_key] = min(100, child_traits[mut_key] + random.randint(5, 20))

    DNA_DATA[child_uid] = {
        "name": child_name, "traits": child_traits,
        "xp_bonus": 0, "mixes": 0,
        "child_of": [uid1, uid2], "mixed_with": []
    }

    # نوێکردنەوەی دایک و باوک
    d1["mixes"] = d1.get("mixes", 0) + 1
    d2["mixes"] = d2.get("mixes", 0) + 1
    d1.setdefault("mixed_with", []).append(uid2)
    d2.setdefault("mixed_with", []).append(uid1)

    # پاداشت
    for uid_r in [uid1, uid2]:
        add_coins(int(uid_r), 50)
    _save_dna()

    child = DNA_DATA[child_uid]
    pers_icon, pers_desc = _dna_personality(child_traits)
    total = sum(child_traits.values())
    grade = "S" if total >= 560 else "A" if total >= 490 else "B" if total >= 420 else "C"

    mut_name = next(t[1] for t in _DNA_TRAITS if t[2] == mut_key)
    await _safe_edit(query, f"<tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> <b>مووجودی نوێ دروست بوو!</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"👨‍👩‍👦 ناو: <b>{child_name}</b>\n"
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> کەسایەتی: <b>{pers_icon}</b> — {pers_desc}\n"
        f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> پلە: <b>{grade}</b>  |  کۆ: {total}/800\n\n"
        f"{_TSP} میوتەیشن: <b>{mut_name}</b> بووە تووندتر!\n\n"
        f"{_TMN} هەر دووتان +50{_TCN} وەرگرتن!")

@guarded
async def dnatop_cmd(update: Update, context: CallbackContext):
    if not DNA_DATA:
        await update.message.reply_text("<tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> هێشتا هیچ DNA تۆمارنەکراوە!\n/dna بنووسە بۆ دەستپێکردن.", parse_mode="HTML")
        return
    scored = [(sum(d["traits"].values()) + d.get("xp_bonus",0),
               d["name"], _dna_personality(d["traits"])[0])
              for d in DNA_DATA.values() if "child_of" not in d or not d["child_of"]]
    scored.sort(reverse=True)
    medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"]
    lines = ["<tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> <b>باشترین DNAکان</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"]
    for i,(total,name,pers) in enumerate(scored[:10]):
        m = medals[i] if i<3 else f"{i+1}."
        lines.append(f"{m} {name} — {pers} ({total}pt)")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")


