        role = clan.get("roles",{}).get(uid,"member")
        if role != "leader":
            await answered("❌" + " تەنها سەرۆک شەڕ دەکات!", show_alert=True); return

        btns = []
        for ecid, ec in enemies[:5]:
            ep = _clan_power(ec)
            btns.append([_ebtn(f"{ec['name']} [{ec.get('tag','?')}] — هێز:{ep}", f"clan:war_confirm:{clan_id}:{ecid}", emoji_id="5382170054311841219", api_kwargs={"style": "success"})])
        btns.append([_ebtn("گەڕانەوە", f"clan:back:{clan_id}", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
        my_power = _clan_power(clan)
        # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX v34: answered() پێویستە
        await answered()
