# FIX [BUG-9,10]: EQ_SESSIONS/EQ_FILE ئێستا لە main.py دادەنرێن — دوبارەکردنەوە لابرا
# تەنها داتا بار دەکەین بۆ ناو stub ی main.py
try:
    with open(_hdata_path(EQ_FILE), "r", encoding="utf-8") as _eqf:
        EQ_SESSIONS.update(json.load(_eqf))
except Exception as _load_err:
    logger.debug("ℹ️ بارکردنی داتا: فایل هێشتا دروست نەبووە (ئاسایییە): %s", _load_err)

@guarded
async def eq_cmd(update: Update, context: CallbackContext):
    user = update.effective_user
    uid  = str(user.id)
    kb = InlineKeyboardMarkup([[
        _ebtn("دەستپێبکە!", f"eq:start:{uid}", emoji_id="5264874622012126052", api_kwargs={"style": "success"}),
        _ebtn("لابردن", f"eq:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
    ]])
    await update.message.reply_text(
        "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>تاقیکردنەوەی زیرەکیی سۆزداری (EQ)</b>\n"
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        "زیرەکیی سۆزداری (Emotional Intelligence) یەکێکە لە گەورەترین و گرنگترین تواناکانی مرۆڤ — "
        "توێژینەوە زانستییەکان سەلماندوویانە کە EQ لە گەیشتن بە سەرکەوتنی ڕاستەقینەی ژیاندا، "
        "زۆر لە IQ (زیرەکیی مێشکی) گرنگترە!\n\n"
        "ئەم تاقیکردنەوەیە ٤ ڕەهەندی سەرەکیی زیرەکیی سۆزداریت دەپێوێت:\n\n"
        "<tg-emoji emoji-id=\"5258274739041883702\">🔍</tg-emoji> <b>خۆناسی (Self-Awareness)</b> — توانای تێگەیشتن لە هەستەکانی خۆت و کاریگەرییان.\n"
        f"{_TLT} <b>خۆبەڕێوەبردن (Self-Management)</b> — توانای کۆنتڕۆڵکردن و ئاڕاستەکردنی هەستەکانت.\n"
        "<tg-emoji emoji-id=\"6030665018851203489\">💞</tg-emoji> <b>هاوسۆزی (Empathy)</b> — توانای تێگەیشتن لە هەستی کەسانی تر و هاوخەمی بۆیان.\n"
        "<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> <b>بەڕێوەبردنی پەیوەندییەکان (Relationship Management)</b> — لێهاتوویی لە کارکردن و گونجان لەگەڵ دەوروبەر.\n\n"
        f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>{len(EQ_QUESTIONS)} پرسیار</b> — تکایە بەوپەڕی ڕاستگۆییەوە وەڵام بدەرەوە!\n"
        "<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> هیچ وەڵامێکی هەڵە بوونی نییە — تەنیا وێنەیەکی ڕاستەقینەی هەستەکانی خۆت دەرببڕە.",
        parse_mode="HTML", reply_markup=kb,
    )

async def eq_callback(update: Update, context: CallbackContext):
    query   = update.callback_query
    answered = _make_answerer(update.callback_query)
    clicker = str(query.from_user.id)
    parts   = query.data.split(":")
    action  = parts[1]
    uid     = parts[2] if len(parts) > 2 else clicker

    if action not in ("view",) and uid != clicker:
        try: await answered("🔒 ئەم تێستە هی تۆ نییە! /eq بنووسە", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی EQ؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"eq:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"eq:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        sess = EQ_SESSIONS.get(uid) or EQ_SESSIONS.get(str(uid))
        if not sess:
            await answered("⚠️ تاقیکردنەوەکە نەدۆزرایەوە.", show_alert=True); return
        q = EQ_QUESTIONS[sess["order"][sess["q_idx"]]]
        await _safe_edit(query, _eq_make_txt(q, sess["q_idx"], len(EQ_QUESTIONS)), reply_markup=_make_likert_kb("eq", uid, sess["q_idx"], len(EQ_QUESTIONS))); return
    if action == "cancel":
        EQ_SESSIONS.pop(uid, None); _save_eq()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        try: await query.edit_message_text(_TGX + " تێستەکە هەڵوەشایەوە.", parse_mode="HTML")
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        return

    if action in ("start", "restart"):
        EQ_SESSIONS[uid] = {
            "q_idx": 0,
            "scores": {"SE": 0, "SM": 0, "SO": 0, "RS": 0}, "ans_log": [],
            "order":  random.sample(range(len(EQ_QUESTIONS)), len(EQ_QUESTIONS)),
            "chat_id": query.message.chat_id,
        }; _save_eq()
        sess = EQ_SESSIONS.get(uid)
        if not sess:
            try: await query.edit_message_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> /eq بنووسە.", parse_mode="HTML")
            except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
            return
        q = EQ_QUESTIONS[sess["order"][0]]
        await _safe_edit(query, _eq_make_txt(q, 0, len(EQ_QUESTIONS)), reply_markup=_make_likert_kb("eq", uid, 0, len(EQ_QUESTIONS))); return

    if action == "back":
        sess = EQ_SESSIONS.get(uid)
        if not sess or sess["q_idx"] <= 0:
            await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True); return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["scores"][last["t"]] = max(0, sess["scores"].get(last["t"], 0) - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        q = EQ_QUESTIONS[sess["order"][sess["q_idx"]]]
        await _safe_edit(query, _eq_make_txt(q, sess["q_idx"], len(EQ_QUESTIONS)), reply_markup=_make_likert_kb("eq", uid, sess["q_idx"], len(EQ_QUESTIONS))); return
    if action == "ans":
        sess = EQ_SESSIONS.get(uid)
        if not sess:
            await answered(); return
        val = int(parts[3]) if len(parts) > 3 else 3
        if sess["q_idx"] < len(EQ_QUESTIONS):
            q = EQ_QUESTIONS[sess["order"][sess["q_idx"]]]
            sess["scores"][q["t"]] = sess["scores"].get(q["t"], 0) + val
            sess.setdefault("ans_log", []).append({"t": q["t"], "val": val})
            sess["q_idx"] += 1
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]

        if sess["q_idx"] >= len(EQ_QUESTIONS):
            sc  = sess["scores"]
            tot = sum(sc.values()) or 1
            max_per_dim = 25 * 5  # 25 پرسیار × ٥ نمرەی زیاتر

            # نمرەی گشتی EQ (لە ١٠٠)
            eq_total = int(sum(sc.values()) / (len(sc) * max_per_dim) * 100)

            # باشترین و لاوازترین
            top  = max(sc, key=lambda k: sc[k])
            weak = min(sc, key=lambda k: sc[k])
            r_top  = EQ_RESULTS[top]
            r_weak = EQ_RESULTS[weak]

            # ئاست
            if eq_total >= 75:
                eq_level = "<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> زیرەکی هەستیت نایابە"
                eq_msg   = ("تۆ خاوەنی زیرەکییەکی سۆزداریی دەگمەنیت. تۆ نەک تەنها لە ململانێ لەگەڵ خۆت و "
                            "ژیان ڕزگارت بووە، بەڵکو بوویتەتە ڕێپیشاندەر بۆ کەسانی تریش. گەورەترین تەحەدا "
                            "بۆ تۆ ئەوەیە کە چۆن ئەم هاوسەنگییە لە کاتە هەرە سەختەکاندا بپارێزیت.")
            elif eq_total >= 50:
                eq_level = f"{_TDM} زیرەکی هەستیت بەرزە"
                eq_msg   = ("تۆ لەسەر ڕێگەیەکی دروستیت. بەشێکی زۆری ژیانت لەژێر کۆنترۆڵدایە، بەڵام هێشتا "
                            "هەندێک خاڵی تاریک هەن کە پێویستیان بە ڕووناکی هەیە. زیرەکیی سۆزداری وەک "
                            "ماسولکە وایە، هەرقەندە زیاتر ڕاهێنانی پێ بکەیت، بەهێزتر دەبێت.")
            else:
                eq_level = "<tg-emoji emoji-id=\"5424974746355799852\">🌱</tg-emoji> زیرەکی هەستیت لە گەشەکردنیدایە"
                eq_msg   = ("ئەم ئەنجامە کۆتایی ڕێگەکە نییە، بەڵکو زەنگێکی ئاگادارکردنەوەیە. تۆ وزەیەکی "
                            "زۆرت لە دەست دەچێت بەهۆی ململانێ ناوەکییەکان و کێشە کۆمەڵایەتییەکانت. "
                            "فێربوونی زیرەکیی سۆزداری دەبێتە کلیلی ئەو دەرگایانەی کە ساڵانێکە لە "
                            "ڕووتدا داخراون. لە ئەمڕۆوە دەست پێ بکە بە ناسینی هەستەکانت.")

            # بارچارت
            bars = ""
            for k, r in EQ_RESULTS.items():
                pct   = int(sc[k] / max_per_dim * 100)
                filled = pct // 10
                bars += f"{r['emoji']} {r['short']:9} [{'█'*filled}{'░'*(10-filled)}] {pct}%\n"

            # بەرز/نزم هەر پایە دیاری بکە
            threshold = max_per_dim * 0.6  # ٦٠٪ بریتیە لە بەرز
            dim_texts = []
            for dim_key in ["SE", "SM", "SO", "RS"]:
                r = EQ_RESULTS[dim_key]
                level_text = r["high"] if sc[dim_key] >= threshold else r["low"]
                dim_texts.append(
                    f"{r['emoji']} <b>{r['name']}</b> — <i>{r['title']}</i>\n"
                    f"{level_text}"
                )

            txt = (
                "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>ئەنجامی زیرەکی هەستی (EQ)</b>\n"
                "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"{_TCH} <b>نمرەی گشتی EQ تۆ: {eq_total}/100</b>\n"
                f"<b>{eq_level}</b>\n\n"
                f"<i>{eq_msg}</i>\n\n"
                "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
                f"<code>{bars}</code>\n"
                "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                + "\n\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n".join(dim_texts)
            )

            EQ_SESSIONS.pop(uid, None); _save_eq()
            save_test_result(int(uid), "eq", {
                "score": eq_total, "top": top, "weak": weak,
                "name": r_top["name"], "emoji": r_top["emoji"], "scores": sc
            })
            await _safe_edit(query, txt, reply_markup=InlineKeyboardMarkup([[
                    _ebtn("دووبارە", f"eq:restart:{uid}", emoji_id="5353025084845994828", api_kwargs={"style": "success"})
                ]]))
        else:
            q = EQ_QUESTIONS[sess["order"][sess["q_idx"]]]
            await _safe_edit(query, _eq_make_txt(q, sess["q_idx"], len(EQ_QUESTIONS)), reply_markup=_make_likert_kb("eq", uid, sess["q_idx"], len(EQ_QUESTIONS)))


