@guarded
async def hsp_cmd(update: Update, context: CallbackContext):
    uid = str(update.effective_user.id)
    kb = InlineKeyboardMarkup([[
        _ebtn("دەستپێبکە!", f"hsp:start:{uid}", api_kwargs={"icon_custom_emoji_id": "6026321200597176575", "style": "success"}),
        _ebtn("لابردن", f"hsp:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
    ]])
    await update.message.reply_text(
        "<tg-emoji emoji-id=\"6026321200597176575\">🌿</tg-emoji> <b>تێستی کەسایەتییە زۆر هەستیارەکان (HSP)</b>\n"
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        "ئەم تێستە لەلایەن <b>دکتۆر ئێلین ئایرۆن</b>ەوە دروستکراوە — دەروونناسی ئەمریکی کە "
        "داهێنەری چەمکی «کەسایەتییە زۆر هەستیارەکان» (Highly Sensitive Person) بووە.\n\n"
        f"{_TCH} <b>ئایستاتیستیک:</b> نزیکەی <b>١٥-٢٠٪</b> لە مرۆڤانی جیهان لەم گرووپەداین.\n\n"
        "<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> <b>تێبینی گرنگ:</b>\n"
        "HSP بوون نەخۆشی یان لاوازی نییە — بەڵکو جۆرێکی جیاوازی پڕۆسێسکردنی زانیاریە کە "
        "لەگەڵ توانایە دەگمەنەکانەوە دێت: داهێنانی بەرز، هاوسۆزیی قووڵ، و تێگەیشتنی ئەوەی "
        "کەسانی تر لێی بێئاگان.\n\n"
        f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>{len(HSP_QUESTIONS)} پرسیار</b>\n"
        "وەڵامەکان: زۆر / بەڵێ / نازانم / کەمێک / هیچ",
        parse_mode="HTML", reply_markup=kb,
    )

async def hsp_callback(update: Update, context: CallbackContext):
    query   = update.callback_query
    answered = _make_answerer(update.callback_query)
    clicker = str(query.from_user.id)
    parts   = query.data.split(":")
    action  = parts[1]
    uid     = parts[2] if len(parts) > 2 else clicker

    if action not in ("view",) and uid != clicker:
        try: await answered("🔒 ئەم تێستە هی تۆ نییە! /hsp بنووسە", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "confirmcancel":
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئایا دڵنیایت لە هەڵوەشاندنەوەی تاقیکردنەوەی HSP؟</b>\n\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> هەموو پێشکەوتنەکەت لەدەست دەچێت.\n"
            "<tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> پێویستە لە سەرەتاوە دەست پێبکەیتەوە.", reply_markup=InlineKeyboardMarkup([
                [_ebtn("بەڵێ، هەڵیوەشێنەوە", f"hsp:cancel:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "danger"})],
                [_ebtn("نەخێر، بەردەوام بە", f"hsp:resume:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]
            ]))
        return
    if action == "resume":
        sess = HSP_SESSIONS.get(uid) or HSP_SESSIONS.get(str(uid))
        if not sess:
            await answered("⚠️ تاقیکردنەوەکە نەدۆزرایەوە.", show_alert=True); return
        await _safe_edit(query, _hsp_make_txt(sess["q_idx"], len(HSP_QUESTIONS)), reply_markup=_hsp_make_kb(uid, sess["q_idx"], len(HSP_QUESTIONS))); return
    if action == "cancel":
        HSP_SESSIONS.pop(uid, None); _save_hsp()
        try: await answered()
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        try: await query.edit_message_text(_TGX + " تێستەکە هەڵوەشایەوە.", parse_mode="HTML")
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        return

    if action in ("start", "restart"):
        HSP_SESSIONS[uid] = {
            "q_idx": 0, "total_score": 0, "ans_log": [],
            "order": list(range(len(HSP_QUESTIONS))),
            "chat_id": query.message.chat_id,
        }; _save_hsp()
        await _safe_edit(query, _hsp_make_txt(0, len(HSP_QUESTIONS)), reply_markup=_hsp_make_kb(uid, 0, len(HSP_QUESTIONS))); return

    if action == "back":
        sess = HSP_SESSIONS.get(uid)
        if not sess or sess["q_idx"] <= 0:
            try: await answered("⬅️ پرسیاری پێشووت نییە!", show_alert=True)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return
        log = sess.get("ans_log", [])
        if log:
            last = log.pop()
            sess["total_score"] = max(0, sess["total_score"] - last["val"])
        sess["q_idx"] = max(0, sess["q_idx"] - 1)
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed back save]
        await _safe_edit(query, _hsp_make_txt(sess["q_idx"], len(HSP_QUESTIONS)), reply_markup=_hsp_make_kb(uid, sess["q_idx"], len(HSP_QUESTIONS))); return

    if action == "ans":
        sess = HSP_SESSIONS.get(uid)
        if not sess:
            await answered(); return
        val = int(parts[3]) if len(parts) > 3 else 2
        if sess["q_idx"] < len(HSP_QUESTIONS):
            sess["total_score"] += val
            sess.setdefault("ans_log", []).append({"val": val})
            sess["q_idx"] += 1
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> [removed per-click save — پاشەکەوت لە کۆتاییدا]

        if sess["q_idx"] >= len(HSP_QUESTIONS):
            score     = sess["total_score"]
            max_score = len(HSP_QUESTIONS) * 5   # ١٣٥
            pct       = int(score / max_score * 100)
            filled    = pct // 10
            bar       = "█" * filled + "░" * (10 - filled)

            if score >= 94:
                level    = "<tg-emoji emoji-id=\"5287519334569097506\">🌊</tg-emoji> زۆر هەستیار (HSP)"
                level_en = "Highly Sensitive Person"
                desc     = ("تۆ بە تەواوی لە گرووپی کەسایەتییە زۆر هەستیارەکاندایت. ئەمە مانای ئەوەیە "
                            "مێشکت زانیارییەکان ١٠ ئەوەندەی کەسێکی ئاسایی پڕۆسێس دەکات. تۆ وەک "
                            "خاوەن ڕادارێکی زۆر بەهێز وایت کە هەموو لەرەلەرێکی جیهان دەگریت. ڕەنگە "
                            "زۆرجار هەست بە ماندوێتی بکەیت، بەڵام ئەمە بەهایەکی گەورەی هەیە؛ تۆ "
                            "دەتوانیت ئەو جوانی و قووڵییە ببینیت کە زۆربەی خەڵک لێی بێئاگان.")
                advice   = ("پارێزگاری لە وزەت بکە: ساتەکانی بێدەنگ پێویستن، نەک ئیختیاری. "
                            "هاوڕێیانت بناسێنە بۆ ئەم تایبەتمەندییەت — تێگەیشتنیان کاریگەریی زۆری هەیە. "
                            "خەستەکانی HSP: داهێنانی بەرز، هاوسۆزی، و دیتنی جوانی لە شوێنی ناچاوەڕوانکراو.")
                emoji_lv = "<tg-emoji emoji-id=\"5287519334569097506\">🌊</tg-emoji>"
            elif score >= 50:
                level    = "<tg-emoji emoji-id=\"6026321200597176575\">🌿</tg-emoji> مامناوەند"
                level_en = "Middle Range"
                desc     = ("تۆ خاوەنی هەستیارییەکی تەندروستیت. هەندێک لە خەسڵەتەکانی HSPت تێدایە، "
                            "بەڵام ناهێڵیت بە تەواوی کۆنترۆڵی ژیانت بکەن. تۆ دەتوانیت لەگەڵ ژینگەی "
                            "جەنجاڵدا ڕا بێیت، بەڵام هێشتا پێویستت بە ساتەکانی بێدەنگی هەیە بۆ ئەوەی "
                            "وزەی خۆت نوێ بکەیتەوە.")
                advice   = ("گوێ لە نیشانەکانی جەستەت بگرە — کاتێک هەست بە ماندوویی دەکەیت "
                            "بەشێوەیەکی نائاسایی، ئەمە ئاگادارکردنەوەیەکە. هاوسەنگی نێوان "
                            "کات لەگەڵ خەڵک و کاتی تەنهایی بۆ تۆ گرینگە.")
                emoji_lv = "<tg-emoji emoji-id=\"6026321200597176575\">🌿</tg-emoji>"
            else:
                level    = "🪨 کەم هەستیار"
                level_en = "Low Sensitivity"
                desc     = ("تۆ خاوەنی قەڵغانێکی دەماریی زۆر بەهێزیت. کارتێکەرە دەرەکییەکان بە ئاسانی "
                            "ناتشڵەژێنن. ئەمە یارمەتیت دەدات لە دۆخە پڕ فشارەکاندا وەک بەرد سەقامگیر "
                            "بیت. ڕەنگە هەندێک جار تێبینی ئەو وردەکارییە سۆزدارییانە نەکەیت کە کەسانی "
                            "تر پێی سەرسامن، بەڵام لە بەرامبەردا جیهان بۆ تۆ شوێنێکی کەمتر ماندووکەرە.")
                advice   = ("ئاگا بە لەو کەسانە بکە کە لە دەوروبەرتدان — ڕەنگە هەستیارتر لەت بن. "
                            "هاوسۆزیکردن لەگەڵ HSPیەکان لەناو ژیانتدا دەتوانێت پەیوەندییەکانت "
                            "قووڵتر بکات.")
                emoji_lv = "🪨"

            txt = (
                "<tg-emoji emoji-id=\"6026321200597176575\">🌿</tg-emoji> <b>ئەنجامی تێستی HSP</b>\n"
                "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"{emoji_lv} <b>{level}</b>\n"
                f"<i>{level_en}</i>\n\n"
                f"{_TCH} نمرەت: <b>{score}/{max_score}</b>\n"
                f"<code>[{bar}] {pct}%</code>\n\n"
                "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"{desc}\n\n"
                f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> <b>ئامۆژگاری:</b>\n{advice}\n\n"
                "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
                "<i><tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> ئەم تێستە لەلایەن دکتۆر ئێلین ئایرۆن — یەکەم کەسێک کە لە ١٩٩١دا "
                "HSP بوون وەک تایبەتمەندییەک پێناسەی کرد — دروستکراوە.</i>"
            )

            HSP_SESSIONS.pop(uid, None); _save_hsp()
            save_test_result(int(uid), "hsp", {
                "score": score, "max": max_score, "pct": pct,
                "level": level, "emoji": emoji_lv,
            })
            await _safe_edit(query, txt, reply_markup=InlineKeyboardMarkup([[
                    _ebtn("دووبارە", f"hsp:restart:{uid}", emoji_id="5353025084845994828", api_kwargs={"style": "success"})
                ]]))
        else:
            await _safe_edit(query, _hsp_make_txt(sess["q_idx"], len(HSP_QUESTIONS)), reply_markup=_hsp_make_kb(uid, sess["q_idx"], len(HSP_QUESTIONS)))

async def warn_cmd(update: Update, context: CallbackContext):
    """فەرمانی /warn — ئاگاداریکردنەوەی بەکارهێنەر"""
    chat = update.effective_chat
    user = update.effective_user
    if not user: return
    msg = update.effective_message
    if not msg or not msg.reply_to_message:
        await msg.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تکایە پەیامی ئەو کەسە reply بکە کە دەتەوێ ئاگاداری بکەیتەوە.", parse_mode="HTML")
        return
    # چەکی ئادمین بوون
    member = await chat.get_member(user.id)
    if member.status not in ("administrator", "creator"):
        await msg.reply_text(_TGX + " تەنها ئادمینەکان دەتوانن ئاگادارکردنەوە بدەن.", parse_mode="HTML")

        return
    target = msg.reply_to_message.from_user
    if not target or target.is_bot:
        await msg.reply_text(_TGX + " ناتوانیت بۆتێک ئاگادار بکەیتەوە.", parse_mode="HTML")

        return
    reason = " ".join(context.args) if context.args else "هۆکاری دیاری نەکراو"
    cid = str(chat.id)
    uid = str(target.id)
    if cid not in WARNINGS_DATA:
        WARNINGS_DATA[cid] = {}
    if uid not in WARNINGS_DATA[cid]:
        WARNINGS_DATA[cid][uid] = []
    warn_entry = {
        "by": user.id,
        "reason": reason,
        "time": datetime.datetime.now().isoformat()
    }
    WARNINGS_DATA[cid][uid].append(warn_entry)
    _save_warnings()
    warn_count = len(WARNINGS_DATA[cid][uid])
    name = target.first_name or "بەکارهێنەر"
    text = (
        f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئاگاداریکردنەوە بۆ {name}</b>\n\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هۆکار: <i>{reason}</i>\n"
        f"<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> ژمارەی ئاگاداریەکان: <b>{warn_count}/3</b>\n"
        f"👮 لەلایەن: {user.first_name}"
    )
    if warn_count >= 3:
        text += "\n\n<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> <b>٣ ئاگاداری — بەکارهێنەر ڕاپچێندرا!</b>"
        try:
            await chat.ban_member(target.id)
            await asyncio.sleep(1)
            await chat.unban_member(target.id)  # unban بۆ ئەوەی بتوانێت دووبارە بێتەوە
        except Exception as e:
            text += f"\n<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> نەتوانرا بانی بکرێت: {_html_escape(str(e))}"
        WARNINGS_DATA[cid][uid] = []
        _save_warnings()
    await msg.reply_text(text, parse_mode="HTML")

async def warnings_cmd(update: Update, context: CallbackContext):
    """فەرمانی /warnings — بینینی ئاگاداریەکانی بەکارهێنەر"""
    chat = update.effective_chat
    msg = update.effective_message
    if not msg: return
    target = None
    if msg.reply_to_message and msg.reply_to_message.from_user:
        target = msg.reply_to_message.from_user
    elif context.args:
        try:
            target_id = int(context.args[0])
            target = await context.bot.get_chat(target_id)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    if not target:
        await msg.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تکایە پەیامی کەسێک reply بکە یان ID بنووسە.", parse_mode="HTML")
        return
    cid = str(chat.id)
    uid = str(target.id)
    warns = WARNS.get(cid, {}).get(uid, [])
    if not warns:
        await msg.reply_text(f"{_TCK} {_html_escape(target.first_name)} هیچ ئاگاداریکردنەوەیەکی نییە.", parse_mode="HTML")
        return
    text = f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> <b>ئاگاداریەکانی {_html_escape(target.first_name)}</b>\n\n"
    for i, w in enumerate(warns, 1):
        text += f"{i}. {w['reason']} — <i>{w['time'][:10]}</i>\n"
    text += f"\n<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> کۆ: <b>{len(warns)}/{MAX_WARNS}</b>"
    await msg.reply_text(text, parse_mode="HTML")

async def clearwarns_cmd(update: Update, context: CallbackContext):
    """فەرمانی /clearwarns — سڕینەوەی ئاگاداریەکان"""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    member = await chat.get_member(user.id)
    if member.status not in ("administrator", "creator"):
        await msg.reply_text(_TGX + " تەنها ئادمینەکان.", parse_mode="HTML")

        return
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        await msg.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تکایە پەیامی کەسێک reply بکە.", parse_mode="HTML")
        return
    target = msg.reply_to_message.from_user
    cid = str(chat.id)
    uid = str(target.id)
    if cid in WARNS and uid in WARNS[cid]:
        WARNS[cid][uid] = []
        _save_warns()
    await msg.reply_text(f"{_TCK} هەموو ئاگاداریەکانی {_html_escape(target.first_name)} سڕایەوە.", parse_mode="HTML")



# ═════════════════════════
# <tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> سیستەمی یاسای گرووپ (Rules System)
# ═════════════════════════
RULES_FILE = "group_rules.json"
RULES_DATA = load_data(RULES_FILE, {})

async def setrules_cmd(update: Update, context: CallbackContext):
    """فەرمانی /setrules — دانانی یاسای گرووپ"""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    member = await chat.get_member(user.id)
    if member.status not in ("administrator", "creator"):
        await msg.reply_text(_TGX + " تەنها ئادمینەکان.", parse_mode="HTML")

        return
    if not context.args:
        await msg.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بەکارهێنان: /setrules <یاساکان>\n\nبۆ نمونە:\n/setrules ١. ڕێزگرتن\n٢. بەبێ سپام\n٣. کوردی بنووسە", parse_mode="HTML")
        return
    rules_text = " ".join(context.args)
    RULES_DATA[str(chat.id)] = {
        "text": rules_text,
        "set_by": user.id,
        "set_at": datetime.datetime.now().isoformat()
    }
    _save_rules()
    await msg.reply_text(f"{_TCK} یاسای گرووپ بە سەرکەوتوویی دانرا!", parse_mode="HTML")

async def rules_cmd(update: Update, context: CallbackContext):
    """فەرمانی /rules — بینینی یاسای گرووپ"""
    chat = update.effective_chat
    msg = update.effective_message
    if not msg: return
    cid = str(chat.id)
    if cid not in RULES_DATA:
        await msg.reply_text("<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> هێشتا هیچ یاسایەک دانەنراوە. ئادمینەکان دەتوانن /setrules بەکاربهێنن.", parse_mode="HTML")
        return
    rules = RULES_DATA[cid]
    text = (
        f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>یاسای گرووپی {_html_escape(chat.title)}</b>\n\n"
        f"{rules['text']}\n\n"
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> دانراوە: {rules['set_at'][:10]}"
    )
    await msg.reply_text(text, parse_mode="HTML")


