# 🎭 سیستەمی VIBE — ئێستا چی دەکەیت؟
# ═════════════════════════════════════════════════════════════
#
#  /vibe          → دووگمەی هەڵبژاردنی چالاکی
#  /vibe [تێکست] → یەکسەر دانان
#  /vibes         → لیستی گرووپ (کێ چی دەکات)
#
#  • ١٠ چالاکی ئامادە + تایبەتی
#  • کارتی جوان کاتی mention
#  • Auto-expire پاش ٨ ساعات
#  • پاشکەوتکردن لە JSON
# ═════════════════════════════════════════════════════════════

VIBE_FILE = "vibe_data.json"

def _vload() -> dict:
    raw = load_data(VIBE_FILE, {})
    return {int(k): v for k, v in raw.items()}

def _vsave():
    save_data({str(k): v for k, v in VIBE_DATA.items()}, VIBE_FILE)

VIBE_DATA: dict = _vload()

_VIBES = {
    "game":    ("<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji>", "یاری دەکات"),
    "read":    ("<tg-emoji emoji-id=\"5445275347366989283\">📚</tg-emoji>", "دەیخوێنێت"),
    "rest":    ("<tg-emoji emoji-id=\"5316743172519378979\">😴</tg-emoji>", "ئاستراحەت"),
    "music":   ("<tg-emoji emoji-id=\"5397756121261840824\">🎵</tg-emoji>", "گوێی مۆزیک دەگرێت"),
    "code":    ("<tg-emoji emoji-id=\"5449820535162675988\">💻</tg-emoji>", "کۆدی دەنووسێت"),
    "study":   ("<tg-emoji emoji-id=\"5211151105194467156\">🎓</tg-emoji>", "خوێندن بۆ تاقیکردنەوە"),
    "eat":     ("🍽️", "نان دەخوات"),
    "watch":   ("🍿", "فیلم دەبینێت"),
    "work":    ("<tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji>", "کار دەکات"),
    "gym":     ("<tg-emoji emoji-id=\"5471936197943106990\">💪</tg-emoji>", "ووەرزش دەکات"),
    "custom":  ("<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>", ""),
}

_VIBE_EXPIRE = 8 * 3600  # 8 کاتژمێر

def _vibe_expired(info: dict) -> bool:
    try:
        elapsed = (datetime.datetime.now() - datetime.datetime.fromisoformat(info["time"])).total_seconds()
        return elapsed > _VIBE_EXPIRE
    except Exception:
        return True

def _fmt_dur(secs: int) -> str:
    if secs < 60:   return f"{secs} چرکە"
    if secs < 3600: m = secs//60;  return f"{m} خولەک"
    h = secs//3600; m = (secs%3600)//60
    return f"{h} کاتژمێر" + (f" و {m} خولەک" if m else "")

def _vibe_keyboard(uid: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [
            _ebtn("یاری",    f"vb:s:{uid}:game", emoji_id="5381825232862483894", api_kwargs={"style": "primary"}),
            _ebtn("خوێندن",  f"vb:s:{uid}:read", emoji_id="5445275347366989283", api_kwargs={"style": "primary"}),
            _ebtn(" ئاستراحەت", f"vb:s:{uid}:rest", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5316743172519378979"),
        ],
        [
            _ebtn("مۆزیک",   f"vb:s:{uid}:music", emoji_id="5397756121261840824", api_kwargs={"style": "primary"}),
            _ebtn("کۆد",     f"vb:s:{uid}:code", emoji_id="5449820535162675988", api_kwargs={"style": "primary"}),
            _ebtn(" خوێندن",  f"vb:s:{uid}:study",  api_kwargs={"style":"primary"}, icon_custom_emoji_id="5211151105194467156"),
        ],
        [
            _ebtn("🍽️ نان",     f"vb:s:{uid}:eat",    api_kwargs={"style": "primary"}),
            _ebtn("🍿 فیلم",    f"vb:s:{uid}:watch",  api_kwargs={"style": "primary"}),
            _ebtn("کار",     f"vb:s:{uid}:work", emoji_id="5431499171045581032", api_kwargs={"style": "primary"}),
        ],
        [
            _ebtn("ووەرزش",  f"vb:s:{uid}:gym", emoji_id="5471936197943106990", api_kwargs={"style": "primary"}),
            _ebtn("تایبەتی", f"vb:s:{uid}:custom", emoji_id="5397686620101055828", api_kwargs={"style": "primary"}),
        ],
        [
            _ebtn("پاکردنەوەی ڤایب", f"vb:clr:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
        ],
    ])

def _vibe_card(name: str, info: dict) -> str:
    """کارتی جوانی ڤایب"""
    em, lbl = _VIBES.get(info.get("key","custom"), ("<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",""))
    custom   = info.get("custom","")
    activity = custom if custom else lbl
    elapsed  = int((datetime.datetime.now() - datetime.datetime.fromisoformat(info["time"])).total_seconds())
    remain   = max(0, _VIBE_EXPIRE - elapsed)
    bar_fill = int((elapsed / _VIBE_EXPIRE) * 10)
    bar      = "█" * bar_fill + "░" * (10 - bar_fill)
    return (
        f"{em} <b>{name}</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> ئێستا: <b>{activity}</b>\n"
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> لەوەتەی: <b>{_fmt_dur(elapsed)}</b>\n"
        f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> ماوە: <b>{_fmt_dur(remain)}</b>\n"
        f"[{bar}]"
    )

@guarded
async def vibe_cmd(update: Update, context: CallbackContext):
    user = update.effective_user
    msg  = update.effective_message
    if not user or not msg: return
    uid  = str(user.id)
    name = _html_escape(user.first_name or "بەکارهێنەر")

    # پاکردنەوەی ڤایبی کۆن ئەگەر بەسەرچووبوو
    if user.id in VIBE_DATA and _vibe_expired(VIBE_DATA[user.id]):
        VIBE_DATA.pop(user.id)

    # ئەگەر ئارگیومێنت هاتبوو — یەکسەر دادەنرێت
    if context.args:
        custom_text = " ".join(context.args)[:60]
        VIBE_DATA[user.id] = {
            "key":    "custom",
            "custom": _html_escape(custom_text),
            "time":   datetime.datetime.now().isoformat(),
            "name":   name,
        }
        _vsave()
        await msg.reply_text(
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> <b>{name}</b> — ڤایبی نوێت دانرا!\n\n"
            f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> <b>{_html_escape(custom_text)}</b>\n"
            f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> ٨ کاتژمێر بەردەوامە",
            parse_mode="HTML"
        )
        return

    # ئەگەر پێشتر ڤایبی هەیە — نیشان بدە + هەڵبژاردن
    if user.id in VIBE_DATA:
        info = VIBE_DATA[user.id]
        em, lbl = _VIBES.get(info.get("key","custom"), ("<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",""))
        activity = info.get("custom","") or lbl
        kb = InlineKeyboardMarkup([
            [_ebtn("گۆڕینی ڤایب", f"vb:change:{uid}", emoji_id="5310278924616356636", api_kwargs={"style": "primary"})],
            [_ebtn("پاکردنەوە",   f"vb:clr:{uid}",    emoji_id="6271611232457855630", api_kwargs={"style": "danger"})],
        ])
        await msg.reply_text(
            f"{em} ڤایبی ئێستات: <b>{activity}</b>\n"
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> لەوەتەی: <b>{_fmt_dur(int((datetime.datetime.now()-datetime.datetime.fromisoformat(info['time'])).total_seconds()))}</b>",
            parse_mode="HTML"
        )
        return

    # نیشاندانی مینیو
    await msg.reply_text(
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> <b>{name}</b>، ئێستا چی دەکەیت؟",
        reply_markup=_vibe_keyboard(uid),
        parse_mode="HTML"
    )

async def vibe_callback(update: Update, context: CallbackContext):
    q       = update.callback_query
    ans     = _make_answerer(q)
    parts   = q.data.split(":")          # vb:s/clr/change:uid[:key]
    action  = parts[1]
    uid     = parts[2] if len(parts) > 2 else str(q.from_user.id)

    if str(uid) != str(q.from_user.id):
        await ans("<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> ئەم دووگمەیە بۆ تۆ نییە!", show_alert=True); return

    uid_int = int(uid)
    name    = _html_escape(q.from_user.first_name or "بەکارهێنەر")

    if action == "clr":
        await ans()
        VIBE_DATA.pop(uid_int, None); _vsave()
        await _safe_edit(q, f"{_TGX} ڤایبت پاکدرایەوە.")
        return

    if action == "change":
        await ans()
        await _safe_edit(q, f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> <b>{name}</b>، ئێستا چی دەکەیت؟", reply_markup=_vibe_keyboard(uid))
        return

    if action == "s":   # set
        key = parts[3] if len(parts) > 3 else "custom"
        if key == "custom":
            await ans()
            context.user_data["vibe_waiting"] = True
            await _safe_edit(q, "<tg-emoji emoji-id=\"5397686620101055828\">✏️</tg-emoji> ڤایبی تایبەتەکەت بنووسە <i>(زیاتر لە ٦٠ پیت نەبێت)</i>:")
            return
        await ans()
        em, lbl = _VIBES.get(key, ("<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",""))
        VIBE_DATA[uid_int] = {
            "key":    key,
            "custom": "",
            "time":   datetime.datetime.now().isoformat(),
            "name":   name,
        }
        _vsave()
        await _safe_edit(
            q,
            f"{em} <b>{name}</b> ئێستا <b>{lbl}</b>!\n"
            f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> ٨ کاتژمێر بەردەوامە — گرووپەکەت دەیبینێت کاتێک mention دەکرێیت."
        )

@guarded
async def vibes_cmd(update: Update, context: CallbackContext):
    """فەرمانی /vibes — لیستی ڤایبی ئەندامانی چالاک"""
    msg     = update.effective_message
    chat_id = update.effective_chat.id if update.effective_chat else None
    if not msg or not chat_id: return

    # پاکردنەوەی بەسەرچووەکان
    for k in list(VIBE_DATA.keys()):
        if _vibe_expired(VIBE_DATA[k]):
            VIBE_DATA.pop(k)
    _vsave()

    if not VIBE_DATA:
        await msg.reply_text(
            "<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> هیچکەس ئێستا ڤایبی چالاکی نییە!\n"
            "بەکاربهێنە: /vibe",
            parse_mode="HTML"
        )
        return

    lines = ""
    for info in sorted(VIBE_DATA.values(), key=lambda x: x["time"], reverse=True):
        em, lbl  = _VIBES.get(info.get("key","custom"), ("<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",""))
        activity = info.get("custom","") or lbl
        uname    = info.get("name","؟")
        elapsed  = int((datetime.datetime.now()-datetime.datetime.fromisoformat(info["time"])).total_seconds())
        lines   += f"{em} <b>{uname}</b> — {activity} <i>({_fmt_dur(elapsed)} لەمەوبەر)</i>\n"

    await msg.reply_text(
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> <b>ڤایبی گرووپ</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"{lines}\n"
        f"<i>ڤایب پاش ٨ کاتژمێر خودکار لادەچێت</i>",
        parse_mode="HTML"
    )

async def _check_vibe_mentions(update: Update, context: CallbackContext):
    """کاتی mention — نیشاندانی کارتی ڤایب"""
    msg  = update.effective_message
    user = update.effective_user
    if not msg or not user: return

    # چاوەڕوانی ڤایبی تایبەتی custom
    if context.user_data.get("vibe_waiting"):
        txt = (msg.text or "").strip()
        if txt and not txt.startswith("/"):
            context.user_data.pop("vibe_waiting", None)
            name = _html_escape(user.first_name or "بەکارهێنەر")
            custom_text = _html_escape(txt[:60])
            VIBE_DATA[user.id] = {
                "key":    "custom",
                "custom": custom_text,
                "time":   datetime.datetime.now().isoformat(),
                "name":   name,
            }
            _vsave()
            await msg.reply_text(
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> <b>{name}</b> — ڤایبی نوێت دانرا!\n\n"
                f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> <b>{custom_text}</b>\n"
                f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> ٨ کاتژمێر بەردەوامە",
                parse_mode="HTML"
            )
            return

    # پاکردنەوەی بەسەرچووەکان
    for k in list(VIBE_DATA.keys()):
        if _vibe_expired(VIBE_DATA[k]):
            VIBE_DATA.pop(k)

    # ئەگەر reply بۆ کەسی بووی ڤایب
    if msg.reply_to_message and msg.reply_to_message.from_user:
        ruser = msg.reply_to_message.from_user
        if ruser.id in VIBE_DATA:
            rname = _html_escape(ruser.first_name or "بەکارهێنەر")
            await msg.reply_text(
                _vibe_card(rname, VIBE_DATA[ruser.id]),
                parse_mode="HTML"
            )

    _vsave()



