# <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> سیستەمی ڕێپیوتەیشن (Reputation System)
# ═════════════════════════
REP_FILE = "reputation.json"
REP_DATA = load_data(REP_FILE, {})
REP_COOLDOWN: dict = {}  # {user_id: last_rep_time}

async def rep_cmd(update: Update, context: CallbackContext):
    """فەرمانی /rep — خاڵی ڕێپیوتەیشن بدە بە کەسێک"""
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        # بینینی ڕێپی خۆت
        uid = str(user.id)
        rep = REP_DATA.get(uid, {"pos": 0, "neg": 0})
        total = rep["pos"] - rep["neg"]
        await msg.reply_text(
            f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> <b>ڕێپیوتەیشنی {_html_escape(user.first_name)}</b>\n\n"
            f"<tg-emoji emoji-id=\"5438383058728296995\">👍</tg-emoji> ئەرێنی: {rep['pos']}\n"
            f"👎 نەرێنی: {rep['neg']}\n"
            f"{_TCH} کۆ: <b>{total:+d}</b>",
            parse_mode="HTML"
        )
        return
    target = msg.reply_to_message.from_user
    if target.id == user.id:
        await msg.reply_text(_TGX + " ناتوانیت خاڵ بۆ خۆت بدەیت!", parse_mode="HTML")

        return
    if target.is_bot:
        await msg.reply_text(_TGX + " ناتوانیت خاڵ بۆ بۆت بدەیت!", parse_mode="HTML")

        return
    # cooldown — هەر ١٢ کاتژمێر یەکجار
    now = datetime.datetime.now()
    key = f"{user.id}_{target.id}"
    if key in REP_COOLDOWN:
        diff = (now - REP_COOLDOWN[key]).total_seconds()
        if diff < 43200:
            remaining = int((43200 - diff) / 3600)
            await msg.reply_text(f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> دەبێت {remaining} کاتژمێری تر چاوەڕوان بکەیت.", parse_mode="HTML")
            return
    # +rep یان -rep
    rep_type = "pos"
    if context.args and context.args[0] in ("-", "neg", "negative", "-1"):
        rep_type = "neg"
    uid = str(target.id)
    if uid not in REP_DATA:
        REP_DATA[uid] = {"pos": 0, "neg": 0}
    REP_DATA[uid][rep_type] += 1
    REP_COOLDOWN[key] = now
    _save_rep()
    total = REP_DATA[uid]["pos"] - REP_DATA[uid]["neg"]
    emoji = "<tg-emoji emoji-id=\"5438383058728296995\">👍</tg-emoji>" if rep_type == "pos" else "👎"
    await msg.reply_text(
        f"{emoji} <b>{_html_escape(user.first_name)}</b> خاڵی {'ئەرێنی' if rep_type == 'pos' else 'نەرێنی'} دا بە "
        f"<b>{_html_escape(target.first_name)}</b>\n{_TCH} ڕێپیوتەیشنی ئێستا: <b>{total:+d}</b>",
        parse_mode="HTML"
    )

async def toprep_cmd(update: Update, context: CallbackContext):
    """فەرمانی /toprep — لیستی باڵاترین ڕێپیوتەیشن"""
    msg = update.effective_message
    if not msg: return
    if not REP_DATA:
        await msg.reply_text(f"{_TCH} هێشتا هیچ ڕێپیوتەیشنێک نییە.", parse_mode="HTML")

        return
    sorted_rep = sorted(
        REP_DATA.items(),
        key=lambda x: x[1].get("pos", 0) - x[1].get("neg", 0),
        reverse=True
    )[:10]
    text = "<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> <b>لیستی باڵاترین ڕێپیوتەیشن</b>\n\n"
    medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"]
    for i, (uid, data) in enumerate(sorted_rep):
        total = data["pos"] - data["neg"]
        medal = medals[i] if i < 3 else f"{i+1}."
        try:
            chat_member = await context.bot.get_chat(int(uid))
            name = chat_member.first_name or uid
        except Exception:
            name = f"User {uid}"
        text += f"{medal} <b>{name}</b> — {total:+d} <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>\n"
    await msg.reply_text(text, parse_mode="HTML")


