# {_TCH} سیستەمی ڕاپرسی پڕۆفیشناڵ (Advanced Poll System)
# ═════════════════════════
POLL_DATA: dict = {}  # {poll_id: {...}}

async def modlog_cmd(update: Update, context: CallbackContext):
    """فەرمانی /modlog — بینینی تۆمارەکانی ئادمین"""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    member = await chat.get_member(user.id)
    if member.status not in ("administrator", "creator"):
        await msg.reply_text(_TGX + " تەنها ئادمینەکان.", parse_mode="HTML")

        return
    cid = str(chat.id)
    logs = MODLOG_DATA.get(cid, [])
    if not logs:
        await msg.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هیچ تۆمارێک نییە.", parse_mode="HTML")
        return
