# ═════════════════════════
# 🔇 سیستەمی بێدەنگکردن (Mute System)
# ═════════════════════════

async def mute_cmd(update: Update, context: CallbackContext):
    """فەرمانی /mute — بێدەنگکردنی بەکارهێنەر"""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    member = await chat.get_member(user.id)
    if member.status not in ("administrator", "creator"):
        await msg.reply_text(_TGX + " تەنها ئادمینەکان.", parse_mode="HTML")

        return
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        await msg.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تکایە پەیامی کەسێک reply بکە.", parse_mode="HTML")
        return
    target = msg.reply_to_message.from_user
    if target.is_bot:
        await msg.reply_text(_TGX + " ناتوانیت بۆتێک بێدەنگ بکەیت.", parse_mode="HTML")

        return
    # ── parse ماوە — پشتیوانی لە: 10m, 2h, 1d, "10 m", "2 h" ──────────────
    duration = 3600   # بنەڕەت: ١ کاتژمێر
    duration_text = "١ کاتژمێر"
    if context.args:
        import re as _re_mute
        # تێکەڵکردنی args — پشتیوانی لە "10m" و "10 m" هەردووکیان
        _raw = "".join(context.args).strip().lower()
        _m = _re_mute.match(r"^(\d+)\s*([mhd]|خولەک|کاتژمێر|ڕۆژ)?$", _raw)
        if _m:
            val  = int(_m.group(1))
            unit = (_m.group(2) or "m").strip()
            if unit in ("h", "کاتژمێر"):
                duration = val * 3600
                duration_text = f"{val} کاتژمێر"
            elif unit in ("d", "ڕۆژ"):
                duration = val * 86400
                duration_text = f"{val} ڕۆژ"
            else:   # m یان هیچ
                duration = val * 60
                duration_text = f"{val} خولەک"
    # ✅ FIX: UTC بەکاربێنە — Telegram UTC دەوێت نەک کاتی ناوخۆ
    until = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=duration)
    try:
        await chat.restrict_member(
            target.id,
            permissions=ChatPermissions(can_send_messages=False),
            until_date=until
        )
        _add_modlog(chat.id, "MUTE", user.id, target.id, duration_text)
        await msg.reply_text(
            f"<tg-emoji emoji-id=\"5379904450473273365\">🔇</tg-emoji> <b>{_html_escape(target.first_name)}</b> میوتکرا بۆ <b>{duration_text}</b>",
            parse_mode="HTML"
        )
    except Exception as e:
        await msg.reply_text(f"{_TGX} نەتوانرا بێدەنگ بکرێت: {_html_escape(str(e))}", parse_mode="HTML")

async def unmute_cmd(update: Update, context: CallbackContext):
    """فەرمانی /unmute — لابردنی بێدەنگ"""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    member = await chat.get_member(user.id)
    if member.status not in ("administrator", "creator"):
        await msg.reply_text(_TGX + " تەنها ئادمینەکان.", parse_mode="HTML")

        return
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        await msg.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تکایە پەیامی کەسێک reply بکە.", parse_mode="HTML")
        return
    target = msg.reply_to_message.from_user
    try:
        await chat.restrict_member(
            target.id,
            permissions=ChatPermissions(
                can_send_messages=True,
                can_send_audios=True,
                can_send_documents=True,
                can_send_photos=True,
                can_send_videos=True,
                can_send_video_notes=True,
                can_send_voice_notes=True,
                can_send_polls=True,
                can_send_other_messages=True,
                can_add_web_page_previews=True,
                can_change_info=False,
                can_invite_users=True,
                can_pin_messages=False,
            )
        )
        _add_modlog(chat.id, "UNMUTE", user.id, target.id)
        await msg.reply_text(f"<tg-emoji emoji-id=\"5438230772072878815\">🔊</tg-emoji> <b>{_html_escape(target.first_name)}</b> میوتی لادرا.", parse_mode="HTML")
    except Exception as e:
        await msg.reply_text(f"{_TGX} هەڵە: {_html_escape(str(e))}", parse_mode="HTML")



