@guarded
async def health_cmd(update: Update, context: CallbackContext):
    """فەرمانی تەندروستی — ئاماری تەندروستی بەکارهێنەر"""
    
    uid = update.effective_user.id
    ud = get_user_data(uid)
    name = _html_escape(update.effective_user.first_name or "بەکارهێنەر")
    
    level = ud.get("level", 1)
    xp = ud.get("xp", 0)
    coins = ud.get("coins", 0)
    messages = ud.get("messages", 0)
    games_played = ud.get("games_played", 0)
    games_won = ud.get("games_won", 0)
    tests_done = len(ud.get("test_results", {}))
    streak = ud.get("daily_streak", 0)
    
    health_score = 0
    factors = []
    
    if messages >= 1000:
        health_score += 25; factors.append("<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> چالاکی: بەرز")
    elif messages >= 100:
        health_score += 15; factors.append("<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> چالاکی: مامناوەند")
    else:
        health_score += 5; factors.append("<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> چالاکی: نزم")
    
    if games_played >= 50:
        health_score += 25; factors.append("<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> یاری: بەرز")
    elif games_played >= 10:
        health_score += 15; factors.append("<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> یاری: مامناوەند")
    else:
        health_score += 5; factors.append("<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> یاری: نزم")
    
    if tests_done >= 5:
        health_score += 25; factors.append("<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> تێست: بەرز")
    elif tests_done >= 2:
        health_score += 15; factors.append("<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> تێست: مامناوەند")
    else:
        health_score += 5; factors.append("<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> تێست: نزم")
    
    if streak >= 7:
        health_score += 25; factors.append("<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> بەردەوامی: بەرز")
    elif streak >= 3:
        health_score += 15; factors.append("<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> بەردەوامی: مامناوەند")
