            cpu_count = psutil.cpu_count()
            mem_text = f"<tg-emoji emoji-id=\"5462956611033117422\">💾</tg-emoji> RAM: {mem.used/(1024**3):.1f}/{mem.total/(1024**3):.1f} GB ({mem.percent}%)"
