# <tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> سیستەمی ئامارەکانی گرووپ (Group Analytics)
# ═════════════════════════
GROUP_ANALYTICS: dict = {}  # {chat_id: {date: {user_id: msg_count}}}

async def _track_analytics(update: Update, context: CallbackContext):  # noqa: ASYNC100 — PTB job queue requires coroutine
    """شوێنپێگرتنی پەیامەکان بۆ ئامار — GROUP_ANALYTICS (٧ ڕۆژ)
    تێبینی: _track_group_msg (WEEKLY_STATS) پێشتر لە سەرەوەی handle_all_messages دەخوێنرێت
    """
    msg = update.effective_message
    user = update.effective_user
    chat = update.effective_chat
    if not msg or not chat: return
    if chat.type == "private": return
    # بۆتەکان نەژمێرێت
    if user and user.is_bot: return
    cid = str(chat.id)
    today = _dt_today()
    if cid not in GROUP_ANALYTICS:
        GROUP_ANALYTICS[cid] = {}
    if today not in GROUP_ANALYTICS[cid]:
        GROUP_ANALYTICS[cid][today] = {}
        dates = sorted(GROUP_ANALYTICS[cid].keys())
        while len(dates) > 7:
            del GROUP_ANALYTICS[cid][dates.pop(0)]
    # sender_chat (چەناڵ لە discussion) یان ئەکاونتی ئاسایی
    if hasattr(msg, 'sender_chat') and msg.sender_chat:
        uid = str(msg.sender_chat.id)
    elif user:
        uid = str(user.id)
    else:
        return
    GROUP_ANALYTICS[cid][today][uid] = GROUP_ANALYTICS[cid][today].get(uid, 0) + 1

async def analytics_cmd(update: Update, context: CallbackContext):
    """فەرمانی /analytics — ئامارەکانی گرووپ"""
    chat = update.effective_chat
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    member = await chat.get_member(user.id)
    if member.status not in ("administrator", "creator"):
        await msg.reply_text(_TGX + " تەنها ئادمینەکان.", parse_mode="HTML")

        return
    cid = str(chat.id)
    if cid not in GROUP_ANALYTICS:
        await msg.reply_text(f"{_TCH} هێشتا داتایەک نییە.", parse_mode="HTML")

        return
    today = _dt_today()
    today_data = GROUP_ANALYTICS[cid].get(today, {})
    total_today = sum(today_data.values())
    total_users = len(today_data)
    # تاپ ٥ بەکارهێنەر
    sorted_users = sorted(today_data.items(), key=lambda x: x[1], reverse=True)[:5]
    text = (
        f"<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> <b>ئامارەکانی ئەمڕۆ — {_html_escape(chat.title)}</b>\n\n"
        f"<tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> کۆی پەیامەکان: <b>{total_today}</b>\n"
        f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> بەکارهێنەری چالاک: <b>{total_users}</b>\n\n"
        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>تاپ ٥ چالاک:</b>\n"
    )
    medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>", "4️⃣", "5️⃣"]
    for i, (uid, count) in enumerate(sorted_users):
        try:
            u = await context.bot.get_chat(int(uid))
            name = u.first_name or uid
        except Exception:
            name = f"User {uid}"
        text += f"  {medals[i]} {name}: {count} پەیام\n"
    # ئامارەکانی ٧ ڕۆژ
    week_total = sum(
        sum(d.values()) for d in GROUP_ANALYTICS[cid].values()
    )
    text += f"\n<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> کۆی ٧ ڕۆژی ڕابردوو: <b>{week_total}</b> پەیام"
    await msg.reply_text(text, parse_mode="HTML")


