# <tg-emoji emoji-id=\"5458676908050883036\">🎫</tg-emoji> سیستەمی تیکەت (Ticket/Report System)
# ═════════════════════════
TICKETS_DATA: dict = {}  # {ticket_id: {...}}

async def report_cmd(update: Update, context: CallbackContext):
    """فەرمانی /report — ڕاپۆرتکردنی کەسێک"""
    user = update.effective_user
    chat = update.effective_chat
    msg = update.effective_message
    if not msg or not user: return
    if not msg.reply_to_message or not msg.reply_to_message.from_user:
        await msg.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تکایە پەیامی کەسێک reply بکە بۆ ڕاپۆرت.", parse_mode="HTML")
        return
    target = msg.reply_to_message.from_user
    reason = " ".join(context.args) if context.args else "ڕاپۆرت بەبێ هۆکار"
    ticket_id = str(uuid4())[:6].upper()
    TICKETS_DATA[ticket_id] = {
        "reporter": user.id,
        "reporter_name": user.first_name,
        "target": target.id,
        "target_name": target.first_name,
        "reason": reason,
        "chat_id": chat.id,
        "time": datetime.datetime.now().isoformat(),
        "status": "open"
    }
    # ئاگادارکردنەوەی ئادمینەکان
    text = (
        f"<tg-emoji emoji-id=\"5458676908050883036\">🎫</tg-emoji> <b>ڕاپۆرتی نوێ #{ticket_id}</b>\n\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> ڕاپۆرتکەر: {_html_escape(user.first_name)}\n"
        f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> ئامانج: {_html_escape(target.first_name)}\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هۆکار: {reason}\n"
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> کات: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}"
    )
    await msg.reply_text(text, parse_mode="HTML")
    # ئاگاداری ئادمینەکان لە پرایڤەت
    try:
        admins = await chat.get_administrators()
        for admin in admins:
            if not admin.user.is_bot:
                try:
                    await context.bot.send_message(
                        admin.user.id,
                        f"<tg-emoji emoji-id=\"5823259308665607384\">🚨</tg-emoji> <b>ڕاپۆرتی نوێ لە {_html_escape(chat.title)}</b>\n\n{text}",
                        parse_mode="HTML"
                    )
                except Exception as _exc:
                    logger.debug("Suppressed Exception: %s", _exc)
    except Exception as _exc:
        logger.debug("Suppressed Exception: %s", _exc)
