# 🌐 سیستەمی وەرگێڕان (Translation Helper)
# ═════════════════════════

async def translate_cmd(update: Update, context: CallbackContext):
    """فەرمانی /tr — وەرگێڕانی تێکست"""
    msg = update.effective_message
    if not msg: return
    text_to_translate = ""
    target_lang = "en"
    _VALID = {"en","ar","ku","tr","fa","fr","de","es","ru","zh","ja","it"}
    if msg.reply_to_message and (msg.reply_to_message.text or msg.reply_to_message.caption):
        text_to_translate = (msg.reply_to_message.text or msg.reply_to_message.caption or "").strip()
        if context.args:
            target_lang = context.args[0].lower()
    elif context.args and len(context.args) >= 2:
        target_lang = context.args[0].lower()
        text_to_translate = " ".join(context.args[1:])
    else:
        await msg.reply_text(
            "<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> <b>وەرگێڕان</b>\n\n"
            "بەکارهێنان:\n"
            "1️⃣ ریپڵی پەیام + <code>/tr en</code>\n"
            "2️⃣ <code>/tr en سڵاو جیهان</code>\n\n"
            "زمانەکان: <code>en ar ku fa tr de fr es ru zh ja it</code>",
            parse_mode="HTML"
        )
        return
    if target_lang not in _VALID:
        target_lang = "en"
    await _do_translate(msg.reply_text, target_lang, text_to_translate)



