# <tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> سیستەمی یادکەرەوەی پڕۆفیشناڵ (Enhanced Reminder)
# ═════════════════════════

async def quickremind_cmd(update: Update, context: CallbackContext):
    """فەرمانی /qremind — یادکەرەوەی خێرا"""
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    if not context.args or len(context.args) < 2:
        await msg.reply_text(
            f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادکەرەوەی خێرا</b>\n\n"
            "بەکارهێنان: /qremind <خولەک> <تێکست>\n\n"
            "بۆ نمونە:\n"
            "/qremind 30 کۆبوونەوە\n"
            "/qremind 60 نان بخۆ",
            parse_mode="HTML"
        )
        return
    try:
        minutes = int(context.args[0])
        if minutes < 1 or minutes > 1440:
            await msg.reply_text(_TGX + " ماوە دەبێت لە ١ تا ١٤٤٠ خولەک بێت.", parse_mode="HTML")

            return
        reminder_text = " ".join(context.args[1:])
        await msg.reply_text(
            f"{_TCK} یادکەرەوە دانرا بۆ <b>{minutes}</b> خولەک دواتر:\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> {reminder_text}",
            parse_mode="HTML"
        )
        # شیدولکردن
        context.job_queue.run_once(
            _qremind_fire,
            when=minutes * 60,
            data={
                "chat_id": msg.chat_id,
                "user_id": user.id,
                "user_name": user.first_name,
                "text": reminder_text
            },
            name=f"qremind_{user.id}_{uuid4().hex[:6]}"
        )
    except ValueError:
        await msg.reply_text(_TGX + " تکایە ژمارەی خولەک بنووسە.", parse_mode="HTML")

async def _qremind_fire(context: CallbackContext):
    """فایەرکردنی یادکەرەوە"""
    data = context.job.data
    text = (
        f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> <b>یادکەرەوە!</b>\n\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> {data['user_name']}\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> {data['text']}"
    )
    await context.bot.send_message(data["chat_id"], text, parse_mode="HTML")


