# <tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> سیستەمی لیستی کارەکان (Todo List)
# ═════════════════════════
TODO_FILE = "todo_data.json"
TODO_DATA = load_data(TODO_FILE, {})

async def todo_cmd(update: Update, context: CallbackContext):
    """فەرمانی /todo — بەڕێوەبردنی لیستی کارەکان"""
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    uid = str(user.id)
    if uid not in TODO_DATA:
        TODO_DATA[uid] = []
    if not context.args:
        # نیشاندانی لیست
        if not TODO_DATA[uid]:
            await msg.reply_text("<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> لیستی کارەکانت بەتاڵە!\n\n/todo add <کار> — زیادکردن\n/todo done <ژمارە> — تەواوکردن", parse_mode="HTML")
            return
        text = f"<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> <b>لیستی کارەکانی {_html_escape(user.first_name)}</b>\n\n"
        for i, item in enumerate(TODO_DATA[uid], 1):
            status = f"{_TCK}" if item.get("done") else f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
            text += f"{status} {i}. {item['text']}\n"
        text += "\n/todo add <کار> — زیادکردن\n/todo done <ژمارە> — تەواوکردن\n/todo del <ژمارە> — سڕینەوە"
        await msg.reply_text(text, parse_mode="HTML")
        return
    action = context.args[0].lower()
    if action == "add" and len(context.args) > 1:
        task_text = " ".join(context.args[1:])
        TODO_DATA[uid].append({"text": task_text, "done": False, "added": datetime.datetime.now().isoformat()})
        _save_todo()
        await msg.reply_text(f"{_TCK} زیادکرا: {task_text}", parse_mode="HTML")

    elif action == "done" and len(context.args) > 1:
        try:
            idx = int(context.args[1]) - 1
            if 0 <= idx < len(TODO_DATA[uid]):
                TODO_DATA[uid][idx]["done"] = True
                _save_todo()
                await msg.reply_text(f"{_TCK} تەواو کرا: {TODO_DATA[uid][idx]['text']}", parse_mode="HTML")

            else:
                await msg.reply_text(_TGX + " ژمارەی نادروست.", parse_mode="HTML")

        except ValueError:
            await msg.reply_text(_TGX + " تکایە ژمارە بنووسە.", parse_mode="HTML")

    elif action == "del" and len(context.args) > 1:
        try:
            idx = int(context.args[1]) - 1
            if 0 <= idx < len(TODO_DATA[uid]):
                removed = TODO_DATA[uid].pop(idx)
                _save_todo()
                await msg.reply_text(f"<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> سڕایەوە: {removed['text']}", parse_mode="HTML")
            else:
                await msg.reply_text(_TGX + " ژمارەی نادروست.", parse_mode="HTML")

        except ValueError:
            await msg.reply_text(_TGX + " تکایە ژمارە بنووسە.", parse_mode="HTML")

    elif action == "clear":
        TODO_DATA[uid] = []
        _save_todo()
        await msg.reply_text("<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> هەموو کارەکان سڕانەوە.", parse_mode="HTML")
    else:
        await msg.reply_text(_TGX + " بەکارهێنان: /todo [add|done|del|clear] <...>", parse_mode="HTML")



