# <tg-emoji emoji-id=\"5395487321967596182\">🏷</tg-emoji>️ سیستەمی تاگکردن (Notes/Tag System)
# ═════════════════════════

async def save_cmd(update: Update, context: CallbackContext):
    """فەرمانی /save — پاشەکەوتکردنی تێبینی"""
    user = update.effective_user
    chat = update.effective_chat
    msg = update.effective_message
    if not msg or not user: return
    if not context.args:
        await msg.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بەکارهێنان: /save <ناو> <تێکست>\nیان reply بکە + /save <ناو>", parse_mode="HTML")
        return
    tag_name = context.args[0].lower()
    cid = str(chat.id)
    if cid not in NOTES:
        NOTES[cid] = {}
    if msg.reply_to_message:
        content = msg.reply_to_message.text or msg.reply_to_message.caption or ""
        NOTES[cid][tag_name] = {"text": content, "by": user.id, "time": datetime.datetime.now().isoformat()}
    elif len(context.args) > 1:
        content = " ".join(context.args[1:])
        NOTES[cid][tag_name] = {"text": content, "by": user.id, "time": datetime.datetime.now().isoformat()}
    else:
        await msg.reply_text(_TGX + " تکایە تێکستێک بنووسە یان reply بکە.", parse_mode="HTML")

        return
    save_notes()
    await msg.reply_text(f"{_TCK} تێبینی <code>#{tag_name}</code> پاشەکەوت کرا!", parse_mode="HTML")

async def get_cmd(update: Update, context: CallbackContext):
    """فەرمانی /get — بینینی تێبینی"""
    chat = update.effective_chat
    msg = update.effective_message
    if not msg: return
    if not context.args:
        await msg.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بەکارهێنان: /get <ناو>", parse_mode="HTML")
        return
    tag_name = context.args[0].lower()
    cid = str(chat.id)
    note = NOTES.get(cid, {}).get(tag_name)
    if not note:
        await msg.reply_text(f"{_TGX} تێبینی <code>#{tag_name}</code> نەدۆزرایەوە.", parse_mode="HTML")
        return
    await msg.reply_text(f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <b>#{tag_name}</b>\n\n{note['text']}", parse_mode="HTML")

async def notes_cmd(update: Update, context: CallbackContext):
    """فەرمانی /notes — لیستی تێبینییەکان"""
    chat = update.effective_chat
    msg = update.effective_message
    if not msg: return
    cid = str(chat.id)
    chat_notes = NOTES.get(cid, {})
    if not chat_notes:
        await msg.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> هیچ تێبینییەک نییە لەم گرووپە.", parse_mode="HTML")
        return
    text = f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <b>تێبینییەکانی {_html_escape(chat.title)}</b>\n\n"
    for name in sorted(chat_notes.keys()):
        text += f"  <tg-emoji emoji-id=\"5231070734016607712\">🔹</tg-emoji> <code>#{name}</code>\n"
    text += f"\n{_TCH} کۆ: {len(chat_notes)} تێبینی\n/get <ناو> بۆ بینین"
    await msg.reply_text(text, parse_mode="HTML")



