async def escape_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5235545969679935681\">🏃</tg-emoji> /escape — ئەسکەیپ ڕووم"""
    uid = update.effective_user.id
    if has_active_game(uid):
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە! /resetgame", parse_mode="HTML")
        return
    
    room = random.choice(_ESCAPE_ROOMS)
    gd = {"room_name": room["name"], "rooms": room["rooms"], "current": 0, "lives": 3, "clues_used": 0}
    set_active_game(uid, "escape", gd)
    
    await _show_escape_room(uid, gd, update=update)

async def _show_escape_room(uid, gd, update=None, query=None):
    current = gd["rooms"][gd["current"]]
    lives_display = "<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️" * gd["lives"] + "<tg-emoji emoji-id=\"5465384878168102994\">🖤</tg-emoji>" * (3 - gd["lives"])
    
    kb = []
    for i, (label, _) in enumerate(current["choices"]):
        kb.append([_ebtn(label, f"esc:choice:{uid}:{i}", api_kwargs={"style": "primary"})])
    if current.get("clue"):
        kb.append([_ebtn("سەرنج", f"esc:clue:{uid}", emoji_id="5258500400918587241", api_kwargs={"style": "primary"})])
    
    text = (
        f"<tg-emoji emoji-id=\"5235545969679935681\">🏃</tg-emoji> <b>{gd['room_name']}</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ ژیان: {lives_display}\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> ژوور: {gd['current'] + 1}/{len(gd['rooms'])}\n\n"
        f"<tg-emoji emoji-id=\"5472411062412254753\">📖</tg-emoji> {current['desc']}\n\n"
        f"👇 هەڵبژاردنەکەت چییە؟"
    )
    
    markup = InlineKeyboardMarkup(kb)
    if query:
        await _safe_edit(query, text, reply_markup=markup)
    elif update:
        await update.message.reply_text(text, parse_mode="HTML", reply_markup=markup)

async def escape_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    
    parts = query.data.split(":")
    if len(parts) < 3: return
    action = parts[1]
    target_uid = int(parts[2])
    uid = query.from_user.id
    
    if uid != target_uid:
        await answered("❌" + " ئەمە یاری تۆ نییە!", show_alert=True)
        return
    
    game = get_active_game(uid)
    if not game or game.get("type") != "escape":
        await answered("❌" + " یارییەکەت تەواو بووە!", show_alert=True)
        return
    
    gd = game["data"]
    current_room = gd["rooms"][gd["current"]]
    
    if action == "clue":
        if current_room.get("clue"):
            gd["clues_used"] += 1
            await answered(current_room["clue"], show_alert=True)
        return
    
    if action == "choice":
        choice_idx = int(parts[3])
        _, result = current_room["choices"][choice_idx]
        
        if result == "random":
            result = random.choice(["right", "wrong"])
        
        if result == "right":
            gd["current"] += 1
            
            if gd["current"] >= len(gd["rooms"]):
                # Escaped!
                remove_active_game(uid)
                bonus = gd["lives"] * 15
                coins = 30 + bonus
                add_coins(uid, coins, "escape_win", "ئەسکەیپ ڕووم")
                add_points(uid, 20)
                ud = get_user_data(uid)
                ud["games_played"] = ud.get("games_played", 0) + 1
                ud["games_won"] = ud.get("games_won", 0) + 1
                save_users()
                await _safe_edit(query, f"<tg-emoji emoji-id=\"5235545969679935681\">🏃</tg-emoji> <b>دەرچویت!</b> <tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji>\n"
                    f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                    f"{_TCK} {gd['room_name']} تەواو کرد!\n"
                    f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ ژیانی ماوە: {gd['lives']}\n"
                    f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> سەرنج بەکارهێنراو: {gd['clues_used']}\n\n"
                    f"{_TMN} +{coins} دراو  |  <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> +20 XP")
                return
            
            update_game_data(uid, gd)
            await _show_escape_room(uid, gd, query=query)
        
        elif result == "wrong":
            gd["lives"] -= 1
            
            if gd["lives"] <= 0:
                remove_active_game(uid)
                ud = get_user_data(uid)
                ud["games_played"] = ud.get("games_played", 0) + 1
                ud["games_lost"] = ud.get("games_lost", 0) + 1
                save_users()
                await _safe_edit(query, f"<tg-emoji emoji-id=\"5235545969679935681\">🏃</tg-emoji> <b>نەتوانی دەربچیت!</b> <tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji>\n"
                    f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                    f"{_TGX} {gd['room_name']}\n"
                    f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> لە ژووری {gd['current'] + 1} وەستایت\n\n"
                    f"<tg-emoji emoji-id=\"5471936197943106990\">💪</tg-emoji> دووبارە تاقی بکەرەوە بە /escape")
                return
            
            update_game_data(uid, gd)
            await answered("❌" + " هەڵەیە! ژیانت کەم بوو!", show_alert=True)
            await _show_escape_room(uid, gd, query=query)

async def escape_from_query(query, context):
    uid = query.from_user.id
    if has_active_game(uid):
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە! /resetgame")
        return
    fake_upd = _GFakeUpd(query)
    await escape_cmd(fake_upd, context)



