@guarded
async def quests_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> /quests — ئامانجە هەفتانەکان"""
    uid = str(update.effective_user.id)
    
    if uid not in ADV_GAMES["quests"]:
        # ٣ قەستی ڕاندۆم بدەرێ
        chosen = random.sample(QUEST_TEMPLATES, 3)
        ADV_GAMES["quests"][uid] = {
            "active": [{**q, "progress": 0, "started": datetime.datetime.now().isoformat(), "completed": False} for q in chosen],
            "completed_total": 0,
            "last_refresh": datetime.datetime.now().isoformat(),
        }
        save_adv_games()
    
    quest_data = ADV_GAMES["quests"][uid]
    
    # چێکی ڕیفرێش هەفتانە
    try:
        last_ref = datetime.datetime.fromisoformat(quest_data["last_refresh"])
        if (datetime.datetime.now() - last_ref).days >= 7:
            chosen = random.sample(QUEST_TEMPLATES, 3)
            quest_data["active"] = [{**q, "progress": 0, "started": datetime.datetime.now().isoformat(), "completed": False} for q in chosen]
            quest_data["last_refresh"] = datetime.datetime.now().isoformat()
            save_adv_games()
    except Exception as _exc:
        logger.debug("Suppressed Exception: %s", _exc)
    text = (
        "<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>ئامانجەکانت</b>\n"
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TCH} کۆی تەواوکراو: {quest_data.get('completed_total', 0)}\n\n"
    )
    
    buttons = []
    for i, q in enumerate(quest_data["active"]):
        pct = min(100, int(q["progress"] / q["target"] * 100))
        bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
        status = f"{_TCK}" if q["completed"] else "<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji>"
        text += (
            f"{status} <b>{q['name']}</b>\n"
            f"   [{bar}] {pct}% ({q['progress']}/{q['target']})\n"
            f"   {_TCN} {q['reward_coins']} + {_TSP} {q['reward_xp']} XP\n\n"
        )
        if q["completed"] and not q.get("claimed"):
            buttons.append([_ebtn(f"وەرگرتنی خەڵات — {q['name'][:20]}", f"qst:claim:{i}", api_kwargs={"icon_custom_emoji_id": "5381873589899267194", "style": "success"})])
    
    buttons.append([_ebtn("ڕیفرێش (هەفتانە)", "qst:refresh", emoji_id="5353025084845994828", api_kwargs={"style": "primary"})])
    buttons.append([_ebtn("گەڕانەوە", "menu:games", emoji_id="5381825232862483894", api_kwargs={"style": "primary"})])
    
    await update.message.reply_text(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(buttons))

async def quest_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    parts = query.data.split(":")
    action = parts[1] if len(parts) > 1 else ""
    uid = str(query.from_user.id)
    
    if action == "claim":
        idx = int(parts[2]) if len(parts) > 2 else -1
        qdata = ADV_GAMES["quests"].get(uid)
        if not qdata or idx < 0 or idx >= len(qdata["active"]):
            await answered("❌" + " نەدۆزرایەوە", show_alert=True)
            return
        q = qdata["active"][idx]
        if not q["completed"] or q.get("claimed"):
            await answered("❌" + " ئامادە نییە", show_alert=True)
            return
        q["claimed"] = True
        qdata["completed_total"] = qdata.get("completed_total", 0) + 1
        add_coins(query.from_user.id, q["reward_coins"], "quest", q["id"])
        add_points(query.from_user.id, q["reward_xp"])
        save_adv_games()
        await answered(f"🎁 +{q['reward_coins']}🪙 +{q['reward_xp']}XP!", show_alert=True)
        return
    
    if action == "refresh":
        qdata = ADV_GAMES["quests"].get(uid)
        if qdata:
            try:
                last_ref = datetime.datetime.fromisoformat(qdata["last_refresh"])
                if (datetime.datetime.now() - last_ref).days < 7:
                    await answered("⏰ هەفتەی داهاتوو ڕیفرێش دەکرێت!", show_alert=True)
                    return
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            chosen = random.sample(QUEST_TEMPLATES, 3)
            qdata["active"] = [{**q, "progress": 0, "started": datetime.datetime.now().isoformat(), "completed": False} for q in chosen]
            qdata["last_refresh"] = datetime.datetime.now().isoformat()
            save_adv_games()
            await answered("🔄 قەستەکان نوێ کرانەوە!", show_alert=True)
        return


