# ── دانان و دەرهێنان بە نووسینی ڕاستەوخۆ ──

@guarded
async def deposit_cmd(update: Update, context: CallbackContext):
    """/deposit <بڕ> — دانانی کۆین لە بانک"""
    args = context.args
    if not args or not args[0].isdigit():
        await update.message.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <code>/deposit 1000</code>", parse_mode="HTML")
        return
    amount = int(args[0])
    if amount < 10:
        await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> لانیکەم 10 {_TCN}", parse_mode="HTML")

        return
    uid_int = update.effective_user.id
    user_data = get_user_data(uid_int)
    if user_data.get("coins", 0) < amount:
        await update.message.reply_text(_TGX + " کۆینت بەس نییە!", parse_mode="HTML")

        return
    async with _get_bank_lock(uid_int):
        acc = _get_bank_account(uid_int)
        add_coins(uid_int, -amount, "bank", "deposit")
        acc["balance"] += amount
        acc["total_deposited"] = acc.get("total_deposited", 0) + amount
        _bank_add_transaction(acc, "پاشەکەوت", amount)
        _bank_update_vip(acc)
        _save_bank()
    await update.message.reply_text(
        f"{_TCK} <b>{amount:,} {_TCN}</b> دانرا لە بانکدا.\n<tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> باڵانس: <b>{acc.get('balance', 0):,}</b> {_TCN}",
        parse_mode="HTML"
    )

@guarded
async def withdraw_cmd(update: Update, context: CallbackContext):
    """/withdraw <بڕ> — دەرهێنانی کۆین لە بانک"""
    args = context.args
    if not args or not args[0].isdigit():
        await update.message.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <code>/withdraw 1000</code>", parse_mode="HTML")
        return
    amount = int(args[0])
    uid_int = update.effective_user.id
    async with _get_bank_lock(uid_int):
        acc = _get_bank_account(uid_int)
        if acc["balance"] < amount:
            await update.message.reply_text(f"{_TGX} تەنها {acc.get('balance', 0):,} {_TCN} لە بانکداتە!", parse_mode="HTML")

            return
        acc["balance"] -= amount
        acc["total_withdrawn"] = acc.get("total_withdrawn", 0) + amount
        add_coins(uid_int, amount, "bank", "withdraw")
        _bank_add_transaction(acc, "بردنەوە", amount)
        _bank_update_vip(acc)
        _save_bank()
    await update.message.reply_text(
        f"{_TCK} <b>{amount:,} {_TCN}</b> دەرهێنرا.\n{_TMN} جزدان: <b>{get_user_data(uid_int).get('coins',0):,}</b> {_TCN}",
        parse_mode="HTML"
    )

@guarded
async def autodeposit_cmd(update: Update, context: CallbackContext):
    """/autodeposit — بینین/گۆڕینی ئاستی ئۆتۆ-دیپۆزیت"""
    global _AUTO_DEPOSIT_THRESHOLD, _AUTO_DEPOSIT_KEEP
    uid  = update.effective_user.id
    args = context.args

    # بێ ئارگومێنت — نیشانی ئاستی ئێستا
    if not args:
        b   = _bank_get(uid)
        ud  = get_user_data(uid)
        w   = ud.get("coins", 0)
        text = (
            f"<tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> <b>ئۆتۆ-دیپۆزیتی بانک</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"{_TCH} ئاستی ئێستا: <b>{_AUTO_DEPOSIT_THRESHOLD:,} {_TCN}</b>\n"
            f"<tg-emoji emoji-id=\"5462956611033117422\">💾</tg-emoji> ماوە لە جزدان: <b>{_AUTO_DEPOSIT_KEEP:,} {_TCN}</b>\n"
            f"{_TCH} دابەشکردن: ٨٠٪ پاشەکەوت / ٢٠٪ Savings\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> جزدانی ئێستا: <b>{w:,} {_TCN}</b>\n\n"
            f"بۆ گۆڕینی threshold:\n"
            f"<code>/autodeposit 500000</code> — ئاستی نوێ دیاری بکە\n"
            f"<code>/autodeposit off</code>   — ئۆتۆ-دیپۆزیت کوژاندنەوە"
        )
        await update.message.reply_text(text, parse_mode="HTML")
        return

    arg = args[0].lower()

    # کوژاندنەوە
    if arg in ("of", "0", "کوژاندنەوە"):
        _AUTO_DEPOSIT_THRESHOLD = _AUTO_DEPOSIT_DISABLED  # sentinel — عملاً بەتاڵ
        await update.message.reply_text(
            f"{_TCK} ئۆتۆ-دیپۆزیت کوژاندرایەوە.\n"
            "دیسانەوە چالاکی بکە: <code>/autodeposit 1000000</code>",
            parse_mode="HTML"
        )
        return

    # گۆڕینی threshold
    if not arg.isdigit():
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ژمارەیەک بنووسە، نمونە: <code>/autodeposit 500000</code>", parse_mode="HTML")
        return

    new_thresh = int(arg)
    if new_thresh < 50_000:
        await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> لانیکەم 50,000 {_TCN} بنووسە.", parse_mode="HTML")

        return
    if new_thresh > 500_000_000:
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> زۆر زیادە — زیاتر لە 500,000,000 نابێت.", parse_mode="HTML")
        return

    _AUTO_DEPOSIT_THRESHOLD = new_thresh
    _AUTO_DEPOSIT_KEEP      = max(10_000, new_thresh // 20)  # ٥٪ی threshold لە جزدان دەمێنێتەوە

    await update.message.reply_text(
        f"{_TCK} <b>ئۆتۆ-دیپۆزیت نوێ کرایەوە</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TCH} ئاستی نوێ: <b>{new_thresh:,} {_TCN}</b>\n"
        f"<tg-emoji emoji-id=\"5462956611033117422\">💾</tg-emoji> ماوە لە جزدان: <b>{_AUTO_DEPOSIT_KEEP:,} {_TCN}</b>\n"
        f"کاتێک جزدانت گەیشت بە ئەم ئاستەیەوە،\n"
        f"ئۆتۆماتیک ٨٠٪ بۆ پاشەکەوت و ٢٠٪ بۆ Savings دەچێت.",
        parse_mode="HTML"
    )

@guarded
async def transfer_cmd(update: Update, context: CallbackContext):
    """/transfer <بڕ> یان /transfer <ئایدی> <بڕ> — گواستنەوەی کۆین بۆ کەسێکی تر"""
    args       = context.args or []   # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: context.args=None کاتی callback دووگمە
    sender_id  = update.effective_user.id
    receiver_id = None
    rname       = None
    amount_str  = None

    # ── شێوازی ١: reply + بڕ ──
    if update.message.reply_to_message:
        receiver_id = update.message.reply_to_message.from_user.id
        rname       = update.message.reply_to_message.from_user.first_name
        amount_str  = args[0] if args else None

    # ── شێوازی ٢: /transfer [USER_ID] [BRR] ──
    elif len(args) >= 2:
        try:
            receiver_id = int(args[0])
        except ValueError:
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ئایدی هەڵەیە!\n"
                f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> شێوازەکان:\n"
                f"١. reply بکە: <code>/transfer 500</code>\n"
                f"٢. ئایدی: <code>/transfer 123456789 500</code>",
                parse_mode="HTML")
            return
        rname      = str(receiver_id)
        amount_str = args[1]

    # ── هیچ شێوازێک نییە ──
    else:
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> <b>گواستنەوەی کۆین</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> شێوازەکان:\n"
            f"١. reply بکە بۆ کەسێک: <code>/transfer 500</code>\n"
            f"٢. ئایدی بنووسە: <code>/transfer 123456789 500</code>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> لانیکەم ١٠ {_TCN}",
            parse_mode="HTML")
        return

    # ── پشکنینی بڕ ──
    if not amount_str or not str(amount_str).isdigit():
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> بڕ دروست نییە!\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> نموونە: <code>/transfer 500</code>",
            parse_mode="HTML")
        return

    amount = int(amount_str)
    if amount < 10:
        await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> لانیکەم 10 {_TCN}", parse_mode="HTML")
        return

    if sender_id == receiver_id:
        await update.message.reply_text(_TGX + " ناتوانیت بۆ خۆت بنێریت!", parse_mode="HTML")
        return

    lock = _get_transfer_lock(sender_id)
    async with lock:
        sender_acc = _get_bank_account(sender_id)
        if sender_acc["balance"] < amount:
            await update.message.reply_text(
                f"{_TGX} باڵانسی بانکت بەس نییە!\n"
                f"<tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> باڵانسی ئێستات: <b>{sender_acc['balance']:,} {_TCN}</b>",
                parse_mode="HTML")
            return
        receiver_acc = _get_bank_account(receiver_id)
        fee = max(int(amount * 0.02), 1)  # 2% کرێی گواستنەوە
        net = amount - fee
        sender_acc["balance"]   -= amount
        receiver_acc["balance"] += net
        # fee بنێرە بۆ خزینەی باج — ناپەیدا نەبێت
        TAX_TREASURY["total"] = TAX_TREASURY.get("total", 0) + fee
        TAX_TREASURY.setdefault("history", []).append({
            "uid": str(sender_id), "amount": fee, "reason": "transfer_fee",
            "time": datetime.datetime.now().isoformat(),
        })
        if len(TAX_TREASURY["history"]) > 500:
            TAX_TREASURY["history"] = TAX_TREASURY["history"][-500:]
        _save_tax()
        _bank_log_tx(sender_id, "transfer_out", amount, f"→ {receiver_id}")
        _bank_log_tx(receiver_id, "transfer_in", net,    f"← {sender_id}")
        # FIX: save_bank() لادرا — _bank_log_tx() خۆی _save_bank() دەکات

    # ── ناوی وەرگر: USERS cache پێشتر هەیە ──
    if rname == str(receiver_id):
        cached = USERS.get(str(receiver_id), {})
        rname = cached.get("nickname") or cached.get("name") or str(receiver_id)

    await update.message.reply_text(
        f"{_TCK} <b>{amount:,} {_TCN}</b> نێردرا بۆ <b>{_html_escape(rname)}</b>\n"
        f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> کرێ: {fee:,} {_TCN} | وەرگیراو: {net:,} {_TCN}",
        parse_mode="HTML"
    )

@guarded
async def loan_cmd(update: Update, context: CallbackContext):
    """/loan <بڕ> — قەرز لە بانک (v4 یەکگرتوو)"""
    uid_int = update.effective_user.id
    b = _bank_get(uid_int)
    # ئەگەر قەرزی پێشوو هەبێت
    if b["loan"] > 0:
        await update.message.reply_text(
            f"{_TGX} ئێستا قەرزت هەیە: {b.get('loan', 0):,} {_TCN}\n"
            f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> دوای: {b['loan_due'] or '—'}\n"
            f"تکایە یەکەم قەرزەکەت بدەوە بە /repay",
            parse_mode="HTML"
        )
        return
    args = context.args
    if not args or not args[0].isdigit():
        vip = b.get("vip_level", 0)
        max_loan = max(1000, int(b["balance"] * BANK_LOAN_RATIO)) + (vip * 25000)
        credit = b["credit_score"]
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5445353829304387411\">💳</tg-emoji> <b>قەرزی بانک</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <code>/loan 5000</code>\n"
            f"• نمرەی متمانە: {credit}/200\n"
            f"• زۆرترین قەرز: {max_loan:,} {_TCN}\n"
            f"• ماوە: {BANK_LOAN_DAYS} ڕۆژ",
            parse_mode="HTML"
        )
        return
    amount = int(args[0])
    vip = b.get("vip_level", 0)
    max_loan = max(1000, int(b["balance"] * BANK_LOAN_RATIO)) + (vip * 25000)
    if amount > max_loan:
        await update.message.reply_text(f"{_TGX} زۆرترین قەرز: {max_loan:,} {_TCN}\n<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> زیاتر پاشەکەوت بکە بۆ قەرزی زیاتر!", parse_mode="HTML")

        return
    if amount < 100:
        await update.message.reply_text(f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> لانیکەم 100 {_TCN}", parse_mode="HTML")

        return
    if b["credit_score"] < 30:
        await update.message.reply_text(_TGX + " نمرەی متمانەت کەمە! (لانیکەم ٣٠ پێویستە)", parse_mode="HTML")

        return
    loan_rate = _bank_get_loan_rate(b)
    due_date = (datetime.date.today() + datetime.timedelta(days=BANK_LOAN_DAYS)).isoformat()
    async with _get_bank_lock(uid_int):
        b["loan"] = amount
        b["loan_due"] = due_date
        b["loan_interest"] = loan_rate
        add_coins(uid_int, amount, "قەرز", "←بانک")
        _bank_add_transaction(b, "قەرز", amount, f"سوود={int(loan_rate*100)}%")
        _save_bank()
    total_repay = int(amount * (1 + loan_rate))
    await update.message.reply_text(
        f"{_TCK} <b>قەرز وەرگیرا!</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TMN} بڕ: {amount:,} {_TCN}\n"
        f"{_TCH} سوود: {int(loan_rate*100)}%\n"
        f"<tg-emoji emoji-id=\"5445353829304387411\">💳</tg-emoji> گەڕاندنەوە: {total_repay:,} {_TCN}\n"
        f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> دوای {BANK_LOAN_DAYS} ڕۆژ ({due_date})",
        parse_mode="HTML"
    )

@guarded
async def repay_cmd(update: Update, context: CallbackContext):
    """/repay — قەرز دانەوە (v4 یەکگرتوو)"""
    uid_int = update.effective_user.id
    b = _bank_get(uid_int)
    if b["loan"] <= 0:
        await update.message.reply_text(f"{_TCK} هیچ قەرزێکت نییە!", parse_mode="HTML")

        return
    loan_rate = b.get("loan_interest", 0.20)
    total = int(b["loan"] * (1 + loan_rate))
    ud = get_user_data(uid_int)
    wallet = ud.get("coins", 0)
    bank_bal = b["balance"]
    # ئەوەڵ لە جزدان هەوڵبدە
    if wallet >= total:
        async with _get_bank_lock(uid_int):
            add_coins(uid_int, -total, "قەرز_دانەوە", "→بانک")
            b["loan"] = 0
            b["loan_due"] = None
            b["credit_score"] = min(200, b["credit_score"] + 10)
            _bank_add_transaction(b, "قەرز_دانەوە", total, "لە جزدان")
            _bank_update_vip(b)
            _save_bank()
        await update.message.reply_text(
            f"{_TCK} قەرزەکەت دایتەوە! ({total:,} {_TCN} لە جزدان)\n"
            f"<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> نمرەی متمانە: {b['credit_score']}/200",
            parse_mode="HTML")
        return
    # جزدان + بانک
    if wallet + bank_bal >= total:
        async with _get_bank_lock(uid_int):
            need_from_bank = total - wallet
            if wallet > 0:
                add_coins(uid_int, -wallet, "قەرز_دانەوە", "→بانک(جزدان)")
            b["balance"] -= need_from_bank
            b["loan"] = 0
            b["loan_due"] = None
            b["credit_score"] = min(200, b["credit_score"] + 10)
            _bank_add_transaction(b, "قەرز_دانەوە", total, "جزدان+بانک")
            _bank_update_vip(b)
            _save_bank()
        await update.message.reply_text(
            f"{_TCK} قەرزەکەت دایتەوە! ({total:,} {_TCN})\n"
            f"<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> نمرەی متمانە: {b['credit_score']}/200",
            parse_mode="HTML")
        return
    await update.message.reply_text(
        f"{_TGX} {total:,} {_TCN} پێویستە بۆ گەڕاندنەوەی قەرز.\n"
        f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> جزدان: {wallet:,} | <tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> بانک: {bank_bal:,}\n"
        f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> کۆی هەردووکیان بەس نییە!",
        parse_mode="HTML")

async def bank_callback(update: Update, context: CallbackContext):
    """{_TCK} [UNIFIED v5] Callback بۆ بانک — هەردوو ^bank: و ^bnk: پاتێرن handle دەکات"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    uid_int = query.from_user.id
    uid = str(uid_int)
    parts = query.data.split(":")
    prefix = parts[0]  # "bank" یان "bnk"
    action = parts[1] if len(parts) > 1 else ""

    # ── bank:deposit:{uid} / bank:withdraw:{uid} — دووگمەکانی v4 ──
    if prefix == "bank" and action == "deposit":
        b = _bank_get(uid_int)
        ud = get_user_data(uid_int)
        wallet = ud.get("coins", 0)
        # دووگمەکانی بڕی خێرا + دووگمەی بڕی دلخواز
        amounts = [500, 1000, 5000]
        btns = []
        for a in amounts:
            if wallet >= a:
                btns.append(_ebtn(f"{a:,}", f"bank:dep_do:{uid_int}:{a}", emoji_id="5379827763832203150", api_kwargs={"style": "danger"}))
        if wallet > 0:
            btns_row2 = [_ebtn(f"هەمووی ({wallet:,})", f"bank:dep_do:{uid_int}:all", emoji_id="5990147899403539264", api_kwargs={"style": "danger"})]
        else:
            btns_row2 = []
        kb_rows = []
        if btns:
            kb_rows.append(btns[:3])
        if btns_row2:
            kb_rows.append(btns_row2)
        kb_rows.append([_ebtn("بڕی دلخواز بنووسە", f"bank:dep_custom:{uid_int}", api_kwargs={"icon_custom_emoji_id": "5397686620101055828", "style": "danger"})])
        kb_rows.append([_ebtn("گەڕانەوە", "run:bank", emoji_id="5352759161945867747", api_kwargs={"style": "danger"})])
        await _safe_edit(query,
            f"<tg-emoji emoji-id=\"5397966712098297802\">💵</tg-emoji> <b>پاشەکەوتکردن</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> جزدان: <b>{wallet:,} {_TCN}</b>\n"
            f"{_TMN} پاشەکەوت: <b>{b.get('balance', 0):,} {_TCN}</b>\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> بڕێک هەڵبژێرە یان بڕی دلخوازت بنووسە:",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(kb_rows))
        return

    if prefix == "bank" and action == "withdraw":
        b = _bank_get(uid_int)
        balance = b["balance"]
        amounts = [500, 1000, 5000]
        btns = []
        for a in amounts:
            if balance >= a:
                btns.append(_ebtn(f"{a:,}", f"bank:wit_do:{uid_int}:{a}", emoji_id="5379827763832203150", api_kwargs={"style": "danger"}))
        if balance > 0:
            btns_row2 = [_ebtn(f"هەمووی ({balance:,})", f"bank:wit_do:{uid_int}:all", emoji_id="5983168981274465534", api_kwargs={"style": "danger"})]
        else:
            btns_row2 = []
        kb_rows = []
        if btns:
            kb_rows.append(btns[:3])
        if btns_row2:
            kb_rows.append(btns_row2)
        kb_rows.append([_ebtn("بڕی دلخواز بنووسە", f"bank:wit_custom:{uid_int}", api_kwargs={"icon_custom_emoji_id": "5397686620101055828", "style": "danger"})])
        kb_rows.append([_ebtn("گەڕانەوە", "run:bank", emoji_id="5352759161945867747", api_kwargs={"style": "danger"})])
        await _safe_edit(query,
            f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> <b>ڕاکێشانی پارە</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"{_TMN} پاشەکەوت: <b>{balance:,} {_TCN}</b>\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> بڕێک هەڵبژێرە یان بڕی دلخوازت بنووسە:",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(kb_rows))
        return

    # ── bank:dep_do:{uid}:{amount} — پاشەکەوتی ڕاستەوخۆ ──
    if prefix == "bank" and action == "dep_do":
        target_uid = int(parts[2]) if len(parts) > 2 else uid_int
        if target_uid != uid_int:
            await answered("❌" + " ئەم دووگمەیە بۆ تۆ نییە!", show_alert=True); return
        _raw_amt = parts[3] if len(parts) > 3 else "0"
