@guarded
async def stock_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> /stock — بۆرسەی ئابووری"""
    args = context.args or []
    if not args:
        text = "<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> <b>بۆرسەی کوردستان</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        for sym, s in STOCK_DATA["stocks"].items():
            arrow = "<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji>" if s["change"] >= 0 else "<tg-emoji emoji-id=\"5393589131106359852\">📉</tg-emoji>"
            text += f"{arrow} <b>{sym}</b> — {s['name']}\n   {_TMN} {s.get('price', 0):,} {_TCN} ({s['change']:+.1f}%)\n\n"
        text += (
            "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            "<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> فەرمانەکان:\n"
            "<code>/stock buy KRD 10</code> — کڕین\n"
            "<code>/stock sell KRD 5</code> — فرۆشتن\n"
            "<code>/stock chart BTC</code> — چارت\n"
            "<code>/portfolio</code> — پۆرتفۆلیۆ"
        )
        await update.message.reply_text(text, parse_mode="HTML")
        return

    action = args[0].lower()
    uid = str(update.effective_user.id)

    if action == "chart" and len(args) >= 2:
        sym = args[1].upper()
        stock = STOCK_DATA["stocks"].get(sym)
        if not stock:
            await update.message.reply_text(f"{_TGX} سهامی {sym} نەدۆزرایەوە.", parse_mode="HTML")

            return
        chart = _stock_chart(stock["history"])
        await update.message.reply_text(
            f"{_TCH} <b>چارتی {sym} — {stock['name']}</b>\n\n<pre>{chart}</pre>\n\n"
            f"{_TMN} نرخ: {stock.get('price', 0):,} {_TCN} ({stock['change']:+.1f}%)",
            parse_mode="HTML"
        )
        return

    if action in ("buy", "sell") and len(args) >= 3:
        sym = args[1].upper()
        if not args[2].isdigit():
            await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ژمارەی سهام بنووسە.", parse_mode="HTML")
            return
        qty = int(args[2])
        stock = STOCK_DATA["stocks"].get(sym)
        if not stock:
            await update.message.reply_text(f"{_TGX} سهامی {sym} نەدۆزرایەوە.", parse_mode="HTML")

            return
        if qty < 1 or qty > 1000:
            await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ١ تا ١٠٠٠ دانە.", parse_mode="HTML")
            return

        total_cost = stock["price"] * qty
        if uid not in STOCK_DATA["portfolios"]:
            STOCK_DATA["portfolios"][uid] = {}

        if action == "buy":
            acc = _get_bank_account(update.effective_user.id)
            wallet = get_user_data(update.effective_user.id).get("coins", 0)
            total_money = acc["balance"] + wallet
            if total_money < total_cost:
                await update.message.reply_text(f"{_TGX} {total_cost:,} {_TCN} پێویستە! (بانک+جزدان = {total_money:,})", parse_mode="HTML")

                return
            # لە بانک یەکەم
            if acc["balance"] >= total_cost:
                acc["balance"] -= total_cost
            else:
                need = total_cost - acc["balance"]
                acc["balance"] = 0
                add_coins(update.effective_user.id, -need, "stock", "buy")
            save_bank()
            STOCK_DATA["portfolios"][uid][sym] = STOCK_DATA["portfolios"][uid].get(sym, 0) + qty
            save_stocks()
            await update.message.reply_text(
                f"{_TCK} <b>{qty}x {sym}</b> کڕدرا!\n{_TMN} کۆی: {total_cost:,} {_TCN}\n{_TCH} نرخی یەکە: {stock.get('price', 0):,} {_TCN}",
                parse_mode="HTML"
            )
        else:  # sell
            owned = STOCK_DATA["portfolios"][uid].get(sym, 0)
            if owned < qty:
                await update.message.reply_text(f"{_TGX} تەنها {owned} دانەت هەیە لە {sym}!", parse_mode="HTML")

                return
            STOCK_DATA["portfolios"][uid][sym] -= qty
            if STOCK_DATA["portfolios"][uid][sym] <= 0:
                del STOCK_DATA["portfolios"][uid][sym]
            acc = _get_bank_account(update.effective_user.id)
            acc["balance"] += total_cost
            save_bank()
            save_stocks()
            await update.message.reply_text(
                f"{_TCK} <b>{qty}x {sym}</b> فرۆشرا!\n{_TMN} وەرگیراو: {total_cost:,} {_TCN}",
                parse_mode="HTML"
            )

@guarded
async def portfolio_cmd(update: Update, context: CallbackContext):
    """/portfolio — پۆرتفۆلیۆی وەبەرهێنان"""
    uid = str(update.effective_user.id)
