@guarded
async def buy_cmd(update: Update, context: CallbackContext):
    """/buy <ناو> — کڕینی شتومەک"""
    args = " ".join(context.args) if context.args else ""
    if not args:
        await update.message.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <code>/buy شمشێر</code>", parse_mode="HTML")
        return
    uid = str(update.effective_user.id)
    found = None
    for name, item in DEFAULT_SHOP_ITEMS.items():
        if args in name or args.lower() in name.lower():
            found = (name, item)
            break
    if not found:
        await update.message.reply_text(_TGX + " شتومەک نەدۆزرایەوە!", parse_mode="HTML")

        return
    name, item = found
    user_data = get_user_data(update.effective_user.id)
    wallet = user_data.get("coins", 0)
    acc = _get_bank_account(update.effective_user.id)
    total = wallet + acc["balance"]
    if total < item["price"]:
        await update.message.reply_text(f"{_TGX} {item.get('price', 0):,} {_TCN} پێویستە!", parse_mode="HTML")

        return
    if wallet >= item["price"]:
        add_coins(update.effective_user.id, -item["price"], "shop", "buy")
    else:
        add_coins(update.effective_user.id, -wallet, "shop", "buy_wallet")
        acc["balance"] -= (item["price"] - wallet)
        save_bank()
    if uid not in SHOP_DATA["user_items"]:
        SHOP_DATA["user_items"][uid] = []
    SHOP_DATA["user_items"][uid].append({
        "name": name, "type": item["type"], "bonus": item["bonus"],
        "bought": datetime.datetime.now().isoformat()
    })
    save_shop()
    await update.message.reply_text(f"{_TCK} {name} کڕدرا! ({item.get('price', 0):,} {_TCN})\n<tg-emoji emoji-id=\"5463172695132745432\">📦</tg-emoji> <code>/inventory</code> بکە بۆ بینینی شتومەکەکانت", parse_mode="HTML")

