@guarded
async def sell_market_cmd(update: Update, context: CallbackContext):
    """/sell <ناو> <نرخ> — فرۆشتن لە بازاڕی ئازاد"""
    args = context.args or []
    if len(args) < 2 or not args[-1].isdigit():
        await update.message.reply_text("<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <code>/sell شمشێر 600</code>", parse_mode="HTML")
        return
    uid = str(update.effective_user.id)
    price = int(args[-1])
    item_name = " ".join(args[:-1])
    items = SHOP_DATA["user_items"].get(uid, [])
    found_idx = None
    for i, it in enumerate(items):
        if item_name in it["name"] or item_name.lower() in it["name"].lower():
            found_idx = i
            break
    if found_idx is None:
        await update.message.reply_text(_TGX + " ئەم شتومەکەت نییە!", parse_mode="HTML")

        return
    removed = items.pop(found_idx)
    SHOP_DATA["market"].append({
        "seller_id": uid, "seller_name": update.effective_user.first_name,
        "item": removed, "price": price, "listed": datetime.datetime.now().isoformat()
    })
    # max 100 listing
    SHOP_DATA["market"] = SHOP_DATA["market"][-100:]
    save_shop()
    await update.message.reply_text(f"{_TCK} {removed['name']} خرایە بازاڕ بە {price:,} {_TCN}!", parse_mode="HTML")

