async def skill_callback(update: Update, context: CallbackContext):
    """callback بۆ بەکارهێنانی شارەزایی"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    uid = query.from_user.id
    parts = query.data.split(":")
    sk_name = parts[1] if len(parts) > 1 else ""
    
    ud = get_user_data(uid)
    skills = ud.get("skills", {})
    sk = skills.get(sk_name)
    if not sk:
        try:
            await _safe_edit(query, _TGX + " ئەم شارەزایییە بوونی نییە!")
        except Exception as _e:
            logger.debug("Suppressed: %s", _e)
        return
    
    # Check cooldown
    last_used = sk.get("last_used", 0)
    now_ts = datetime.datetime.now().timestamp()
    cd = sk.get("cooldown", 60)
    remaining = max(0, int(cd - (now_ts - last_used)))
    
    if remaining > 0:
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> FIX: answered() بەکاردەهێنین نەک query.answer() ڕاستەوخۆ — double-answer پێشگیری
        await answered(f"⏰ {remaining} چرکە مابوو تا شارەزاییەکە ئامادەبێت!", show_alert=True)
        return
    
    # Use the skill
    sk["last_used"] = now_ts
    sk["uses"] = sk.get("uses", 0) + 1
    save_user_data(uid, ud)
    
    try:
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5379884861127432488\">🌀</tg-emoji> شارەزایی <b>{sk_name}</b> بەکارهات! {_TCK}")
    except Exception as _e:
        logger.debug("Suppressed: %s", _e)


# ══════════════════════════════════════════════════════
# ── /ar — گفتوگۆی ڕاستەوخۆ لەگەڵ Groq AI ──
# ══════════════════════════════════════════════════════

def _ar_groq_send(history: list, text: str) -> tuple:
    """
    blocking call — لە thread pool ئەجرا دەکرێت.
    Groq REST API — OpenAI-compatible، بەبێ پاکێجی زیادە.
    history فۆرماتی: [{"role": "user"|"assistant", "content": "..."}, ...]
    returns: (reply_text, updated_history)
    """
    import requests as _req
    new_history = history + [{"role": "user", "content": text}]
    messages = [{"role": "system", "content": _GROQ_SYSTEM}] + new_history
    payload = {
        "model": _GROQ_MODEL,
        "messages": messages,
        "temperature": 0.8,
        "max_tokens": 2048,
    }
    resp = _req.post(
        _GROQ_API_URL,
        headers={
            "Authorization": f"Bearer {_GROQ_API_KEY}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=30,
    )
    if not resp.ok:
        logger.error("Groq REST error %s: %s", resp.status_code, resp.text[:500])
        resp.raise_for_status()
    data   = resp.json()
    reply  = data["choices"][0]["message"]["content"]
    updated = new_history + [{"role": "assistant", "content": reply}]
    return reply, updated


@guarded
async def ar_cmd(update: Update, context: CallbackContext):
    """
    بەکارهێنان: /ar سڵاو، چۆنیت؟
    """
    user = update.effective_user
    uid  = str(user.id)

    if not context.args:
        kb = InlineKeyboardMarkup([[
            _ebtn("<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> سڕینەوەی مێژوو", f"ar_reset:{uid}",
                  emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
        ]])
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> <b>زیرەکی دەستکرد — Groq AI</b>\n\n"
            "بۆ دەستپێکردن بنووسە:\n"
            "<code>/ar سڵاو، چۆنیت؟</code>\n\n"
            "<i>مێژووی گفتوگۆکەت پارێزراوە تا کاتێک سڕیتەوە.</i>",
            parse_mode="HTML",
            reply_markup=kb,
            do_quote=True,
        )
        return

    prompt = " ".join(context.args).strip()

    if uid not in _AR_SESSIONS:
        _AR_SESSIONS[uid] = []   # لیستی مێژووی گفتوگۆ

    await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="typing")

    try:
        reply_text, updated_history = await asyncio.get_running_loop().run_in_executor(
            _THREAD_POOL, _ar_groq_send, _AR_SESSIONS[uid], prompt
        )
        _AR_SESSIONS[uid] = updated_history   # مێژوو نوێ دەکرێتەوە
        await update.message.reply_text(reply_text, do_quote=True)

    except Exception as exc:
        err_str = str(exc)
        if "429" in err_str or "rate_limit" in err_str.lower():
            # ── Rate limit: سێشن نەسڕێتەوە — مێژوو پارێزراوە ──
            import re as _re
            wait_match = _re.search(r"try again in ([\d.]+)s", err_str)
            wait_msg   = f" چاوەڕوانی <b>{float(wait_match.group(1)):.0f}</b> چرکە بکە." if wait_match else ""
            logger.warning("ar_cmd rate-limit: %s", exc)
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> داواکارییەکەت زۆر خێرا بوو."
                + wait_msg + "\n<i>مێژووی گفتوگۆکەت پارێزراوە.</i>",
                parse_mode="HTML",
                do_quote=True,
            )
        else:
            # ── هەڵەی تر: سێشن پاک دەکرێتەوە ──
            _AR_SESSIONS.pop(uid, None)
            logger.error("ar_cmd Groq error: %s", exc)
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> هەڵەیەک ڕوویدا، سێشنەکەت نوێکرایەوە.\n"
                "تکایە دووبارە تاقی بکەرەوە.",
                parse_mode="HTML",
                do_quote=True,
            )


