# مێژووی گفتوگۆ: uid → list[{"role": "user"|"assistant", "content": "..."}]
_MAVERICK_SESSIONS: dict = {}


def _maverick_send(history: list, text: str) -> tuple:
    """
    blocking call — لە thread pool ئەجرا دەکرێت.
    SambaNova REST API بە key rotation + retry-after + backoff.
    returns: (reply_text, updated_history)
    """
    return _samba_request(
        system        = _MAVERICK_SYSTEM,
        history       = history,
        user_text     = text,
        model         = _MAVERICK_MODEL,
        preferred_key = _MAVERICK_API_KEY,
    )


@guarded
async def gpt_cmd(update: Update, context: CallbackContext):
    """
    بەکارهێنان: /gpt پرسیارەکەت  |  /Q پرسیارەکەت  (alias)
    گفتوگۆی قووڵ — مێژووی گفتوگۆ پارێزراوە
    """
    user = update.effective_user
    uid  = str(user.id)

    # ئەگەر تەنیا /gpt نووسرا بەبێ تێکست
    if not context.args:
        kb = InlineKeyboardMarkup([[
            _ebtn("<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> سڕینەوەی مێژوو", f"gpt_reset:{uid}",
                  emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
        ]])
        await update.message.reply_text(
            f"{_TCH} <b>زیرەکی دەستکرد</b>\n\n"
            "بۆ دەستپێکردن بنووسە:\n"
            "<code>/gpt سڵاو، چۆنیت؟</code>\n\n"
            "<i>مێژووی گفتوگۆکەت پارێزراوە تا کاتێک سڕیتەوە.</i>",
            parse_mode="HTML",
            reply_markup=kb,
            do_quote=True,
        )
        return

    prompt = " ".join(context.args).strip()

    # سێشن دروست بکە ئەگەر نەبوو
    if uid not in _MAVERICK_SESSIONS:
        _MAVERICK_SESSIONS[uid] = []

    # نیشاندانی typing
    await context.bot.send_chat_action(
        chat_id=update.effective_chat.id, action="typing"
    )

    try:
        reply_text, updated_history = await asyncio.get_running_loop().run_in_executor(
            _THREAD_POOL, _maverick_send, _MAVERICK_SESSIONS[uid], prompt
        )
        _MAVERICK_SESSIONS[uid] = updated_history

        try:
            await update.message.reply_text(
                reply_text,
                parse_mode="HTML",
                do_quote=True,
            )
        except Exception:
            # ئەگەر HTML هەڵەی ئەنالایز بوو، بەبێ فۆرمات بنێرە
            await update.message.reply_text(
                reply_text,
                do_quote=True,
            )

    except Exception as exc:
        err_str = str(exc)
        # Rate limit
        if "429" in err_str or "rate_limit" in err_str.lower():
            import re as _re
            wait_match = _re.search(r"try again in ([\d.]+)s", err_str)
            wait_msg   = (
                f" چاوەڕوانی <b>{float(wait_match.group(1)):.0f}</b> چرکە بکە."
                if wait_match else ""
            )
            logger.warning("gpt_cmd rate-limit: %s", exc)
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> داواکارییەکەت زۆر خێرا بوو." + wait_msg +
                "\n<i>مێژووی گفتوگۆکەت پارێزراوە.</i>",
                parse_mode="HTML",
                do_quote=True,
            )

        # Timeout
        elif "timeout" in err_str.lower() or "timed out" in err_str.lower():
            logger.warning("gpt_cmd timeout: %s", exc)
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> وەڵام درەنگ کرد. تکایە دووبارە تاقی بکەرەوە.",
                do_quote=True,
            )

        # هەڵەی تر — سێشن سڕینەوە
        else:
            _MAVERICK_SESSIONS.pop(uid, None)
            logger.error("gpt_cmd error: %s", exc)
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> هەڵەیەک ڕوویدا، سێشنەکەت نوێکرایەوە.\n"
                "تکایە دووبارە تاقی بکەرەوە.",
                parse_mode="HTML",
                do_quote=True,
            )


