def _samba_blocking_call(session_key: str, system: str, model: str, text: str, api_key: str = _SAMBA_API_KEY_Q) -> tuple:
    """
    blocking HTTP call — لە thread pool ئەجرا دەکرێت.
    SambaNova REST API بە key rotation + retry-after + backoff.
    returns: (reply_text, updated_history)
    """
    history = _SAMBA_SESSIONS.get(session_key, [])
    return _samba_request(
        system        = system,
        history       = history,
        user_text     = text,
        model         = model,
        preferred_key = api_key,
    )


def _sanitize_philosopher_html(text: str) -> str:
    """
    پاکسازی وەڵامەکانی فەیلەسوف بۆتەکان پێش ناردن بۆ Telegram HTML.

    مۆدێلەکان زانیارییان هەیە تاگی نەپشتیوانیکراو بنووسن (<p>, <div>, <br>, ...)
    یان تاگی داخستنی سەرگەردان (</b> بێ <b>ی تۆپیکخستن).
    Telegram کاتێک تاگێکی نادروست ببینێت, parse_mode='HTML' ئیشنادەکات و
    تاگەکان وەک تێکستی خاو دەردەکەون.

    ئەم فکنشنە:
      ١. تاگی نەپشتیوانیکراو دەسڕێتەوە
      ٢. تاگی داخستنی سەرگەردان دەسڕێتەوە
      ٣. ماراکساشنی ئاخستنی دووبارە پاکدەکاتەوە
    """
    import re as _re

    # تاگی Telegram HTML-ی پشتیوانیکراو
    _ALLOWED = {"b", "i", "u", "s", "code", "pre", "a", "tg-emoji", "tg-spoiler"}

    # ١) تاگی قەدەغە بەتەواوی دەسڕێتەوە (opening + closing + self-closing)
    _FORBIDDEN_RE = _re.compile(
        r"</?(?:p|div|span|br|h[1-6]|ul|ol|li|em|strong|hr|img|table|tr|td|th)"
        r"(?:\s[^>]*)?\s*/?>",
        _re.IGNORECASE,
    )
    text = _FORBIDDEN_RE.sub("", text)

    # ٢) شمارکردنی تاگی کراوەی مۆڵەتدراو بۆ دەستنیشانکردنی سەرگەردانەکان
    open_tags: dict[str, int] = {}
    for m in _re.finditer(r"<([a-zA-Z][a-zA-Z0-9-]*)(?:\s[^>]*)?>", text):
        tag = m.group(1).lower()
        if tag in _ALLOWED:
            open_tags[tag] = open_tags.get(tag, 0) + 1

    # ٣) تاگی داخستنی کە هیچ تاگی کراوەکەی نییە دەسڕێتەوە
    def _drop_stray_close(m: _re.Match) -> str:
        tag = m.group(1).lower()
        if tag not in _ALLOWED:
            return ""
        if open_tags.get(tag, 0) <= 0:
            return ""   # سەرگەردانە
        open_tags[tag] -= 1
        return m.group(0)

    text = _re.sub(r"</([a-zA-Z][a-zA-Z0-9-]*)>", _drop_stray_close, text)

    # ٤) گۆڕینی Markdown بۆ Telegram HTML
    # **text** → <b>text</b>
    text = _re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", text, flags=_re.DOTALL)
    # *text* → <i>text</i>  (تەنها ئەگەر دووبارە نەبوو)
    text = _re.sub(r"(?<![\*])\*(?!\*)(.+?)(?<!\*)\*(?![\*])", r"<i>\1</i>", text, flags=_re.DOTALL)
    # _text_ → <i>text</i>
    text = _re.sub(r"(?<![_])_(?!_)(.+?)(?<!_)_(?![_])", r"<i>\1</i>", text)
    # `text` → <code>text</code>
    text = _re.sub(r"`([^`]+)`", r"<code>\1</code>", text)

    # ٥) پاکردنەوەی خاڵکردنی دووبارەی ئاخستنی (newline > 2)
    text = _re.sub(r"\n{3,}", "\n\n", text)

    return text.strip()


async def get_samba_response(
    user_id: str,
    text: str,
    system_prompt: str,
    session_key: str,
    model: str = _SAMBA_MODEL_Q,
    api_key: str = _SAMBA_API_KEY_Q,
) -> str:
    """
    ئەسینکڕۆن — مێژووی چات بەڕێوەدەبات و وەڵام دەگەڕێنێتەوە.
    session_key جیاوازە بۆ هەر فەرمانێک (/q → uid_q, /jungai → uid_jung).
    """
    reply, updated = await asyncio.get_running_loop().run_in_executor(
        _THREAD_POOL,
        _samba_blocking_call,
        session_key, system_prompt, model, text, api_key,
    )
    _SAMBA_SESSIONS[session_key] = updated
    return reply


def _samba_handle_exc(exc: Exception, cmd: str, uid: str, session_key: str) -> str:
    """هەڵەکان شیکاری بکە و پەیامی گونجاو برگەڕێنەوە (لابردنی کۆد دووبارە)."""
    import re as _re
    # ⚡ ١) SambaRateLimitError ـی structured (هەموو کلیلەکان exhausted)
    if isinstance(exc, SambaRateLimitError):
        wait_s = exc.wait_seconds
        if wait_s < 60:
            wait_str = f"<b>{wait_s:.0f}</b> چرکە"
        else:
            wait_str = f"<b>{wait_s/60:.1f}</b> خولەک"
        logger.warning("%s rate-limit (all keys): wait=%.1fs source=%s",
                       cmd, wait_s, exc.source)
        return (
            "<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> "
            f"سێرڤەری AI ئێستا قەرەباڵغە. تکایە دوای {wait_str} دووبارە تاقی بکەرەوە."
            "\n<i>مێژووی گفتوگۆکەت پارێزراوە.</i>"
        )
    err = str(exc)
    # ⚡ ٢) ٤٢٩ ـی موجوود (بۆ پاراستن بۆ هەر هەڵەیەکی نا-structured)
    if "429" in err or "rate_limit" in err.lower():
        m = _re.search(r"try again in ([\d.]+)s", err)
        wait = f" چاوەڕوانی <b>{float(m.group(1)):.0f}</b> چرکە بکە." if m else ""
        logger.warning("%s rate-limit: %s", cmd, exc)
        return (
            "<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> "
            "داواکارییەکەت زۆر خێرا بوو." + wait +
            "\n<i>مێژووی گفتوگۆکەت پارێزراوە.</i>"
        )
    # ⏳ ٣) Timeout
    if "timeout" in err.lower() or "timed out" in err.lower():
        logger.warning("%s timeout: %s", cmd, exc)
        return "<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> وەڵام درەنگ کرد. تکایە دووبارە تاقی بکەرەوە."
    # ❌ ٤) هەڵەی نەناسراو — سێشن سڕینەوە
    _SAMBA_SESSIONS.pop(session_key, None)
    logger.error("%s SambaNova error: %s", cmd, exc)
    return (
        "<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> "
        "هەڵەیەک ڕوویدا، سێشنەکەت نوێکرایەوە.\nتکایە دووبارە تاقی بکەرەوە."
    )


