@guarded
async def q_cmd(update: Update, context: CallbackContext):
    """/q — یاریدەدەری گشتگیر کوردی"""
    user = update.effective_user
    uid  = str(user.id)
    session_key = f"{uid}_q"

    if not context.args:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> "
            "<b>یاریدەدەری گشتگیر</b>\n\n"
            "بۆ دەستپێکردن بنووسە:\n"
            "<code>/q سڵاو، چۆنیت؟</code>\n\n"
            "سڕینەوەی مێژوو: <code>/q_reset</code>\n"
            "<i>مێژووی گفتوگۆکەت پارێزراوە تا کاتێک سڕیتەوە.</i>",
            parse_mode="HTML",
            reply_markup=kb,
            do_quote=True,
        )
        return

    prompt = " ".join(context.args).strip()
    _Q_SYSTEM = "تۆ یاریدەدەرێکی کوردی سۆرانی زیرەک و هاوکاریت."

    await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="typing")
    try:
        reply_text = await get_samba_response(uid, prompt, _Q_SYSTEM, session_key, model=_SAMBA_MODEL_Q, api_key=_SAMBA_API_KEY_Q)
        try:
            await update.message.reply_text(reply_text, parse_mode="HTML", do_quote=True)
        except Exception:
            await update.message.reply_text(reply_text, do_quote=True)
    except Exception as exc:
        msg = _samba_handle_exc(exc, "q_cmd", uid, session_key)
        await update.message.reply_text(msg, parse_mode="HTML", do_quote=True)

@guarded
async def q_reset_cmd(update: Update, context: CallbackContext):
    """سڕینەوەی مێژووی /q و /jungai بۆ بەکارهێنەرەکە"""
    uid = str(update.effective_user.id)
    _SAMBA_SESSIONS.pop(f"{uid}_q",          None)
    _SAMBA_SESSIONS.pop(f"{uid}_jung",        None)
    _SAMBA_SESSIONS.pop(f"{uid}_freud",       None)
    _SAMBA_SESSIONS.pop(f"{uid}_nietzsche",   None)
    _SAMBA_SESSIONS.pop(f"{uid}_socrates",    None)
    await update.message.reply_text(
        "<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> مێژووی گفتوگۆکەت سڕایەوە. گفتوگۆیەکی نوێ دەستپێدەکات.",
        do_quote=True,
    )
async def q_reset_callback(update: Update, context: CallbackContext):
    """callback دووگمەی سڕینەوەی /q"""
    query      = update.callback_query
    answered   = _make_answerer(query)
    caller_uid = str(query.from_user.id)
    uid_target = query.data.split(":")[1] if ":" in query.data else ""

    if uid_target != caller_uid:
        await answered("❌ تەنها خۆت دەتوانیت مێژووی خۆت بسڕیتەوە.", show_alert=True)
        return

    await answered()
    _SAMBA_SESSIONS.pop(f"{caller_uid}_q",          None)
    _SAMBA_SESSIONS.pop(f"{caller_uid}_jung",        None)
    _SAMBA_SESSIONS.pop(f"{caller_uid}_freud",       None)
    _SAMBA_SESSIONS.pop(f"{caller_uid}_nietzsche",   None)
    _SAMBA_SESSIONS.pop(f"{caller_uid}_socrates",    None)
    try:
        await query.edit_message_text(
            "<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> "
            "مێژووی گفتوگۆ سڕایەوە.\n"
            "بە <code>/q</code> دەستی نوێ پێبکە.",
            parse_mode="HTML",
        )
    except Exception as _e:
        logger.debug("q_reset_callback edit failed: %s", _e)


