@guarded
async def jungai_cmd(update: Update, context: CallbackContext):
    """/jungai — پزیشکی دەروونی یۆنگیان"""
    user = update.effective_user
    uid  = str(user.id)
    session_key = f"{uid}_jung"
    kb = None  # default
    if not context.args:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5264874622012126052\">🧠</tg-emoji> "
            "<b>پزیشکی دەروونی یۆنگ</b>\n\n"
            "بۆ دەستپێکردن بنووسە:\n"
            "<code>/jungai خەونێکم دیتم...</code>\n\n"
                        "<i>مێژووی گفتوگۆکەت پارێزراوە تا کاتێک سڕیتەوە.</i>",
            parse_mode="HTML",
            do_quote=True,
        )
        return

    prompt = " ".join(context.args).strip()

    await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="typing")
    try:
        reply_text = await get_samba_response(uid, prompt, _JUNG_SYSTEM, session_key, model=_SAMBA_MODEL_JUNG, api_key=_SAMBA_API_KEY_JUNG)
        reply_text = _sanitize_philosopher_html(reply_text)
        try:
            await update.message.reply_text(reply_text, parse_mode="HTML", do_quote=True)
        except Exception:
            await update.message.reply_text(reply_text, do_quote=True)
    except Exception as exc:
        msg = _samba_handle_exc(exc, "jungai_cmd", uid, session_key)
        await update.message.reply_text(msg, parse_mode="HTML", do_quote=True)



